  function productDevelopmentHomeFeaturePageHtml() {
    const sku = getProductDevelopmentCurrentSku();
    const featureEntries = productDevelopmentHomeFeatureEntries();
    if (state.homeFeatureEditMode) {
      return '<div class="pfh-home-feature-page pfh-home-feature-page-product">' + productDevelopmentHomeFeatureEditHtml(featureEntries) + '</div>';
    }
    const byId = new Map(featureEntries.map((entry) => [entry.id, entry]));
    const groups = getProductDevelopmentFeatureGroups();
    const commonEntries = groups.common.map((id) => byId.get(id)).filter(Boolean);
    const secondaryEntries = groups.more.map((id) => byId.get(id)).filter(Boolean);
    const primary = commonEntries[0] || null;
    const quickEntries = commonEntries.slice(1);
    const productMeta = sku ? '当前 SKU：' + sku : '请先在设计任务中打开一个 SKU';
    return '<div class="pfh-home-feature-page pfh-home-feature-page-product">' +
      '<div class="pfh-home-feature-layout">' + (primary ? homeFeatureEntryHtml(primary, 'pfh-home-entry-primary') : '<div class="pfh-home-feature-empty">暂无开发入口</div>') + '<div class="pfh-home-quick-grid">' + quickEntries.map((entry) => homeFeatureEntryHtml(entry, 'pfh-home-entry-quick')).join('') + '</div></div>' +
      '<div class="pfh-home-secondary-label">其他开发功能 · ' + escapeHtml(productMeta) + '</div><div class="pfh-home-secondary-grid">' + secondaryEntries.map((entry) => homeFeatureEntryHtml(entry, 'pfh-home-entry-secondary')).join('') + '</div>' +
      '</div>';
  }

  function playProductDevelopmentHomeFeatureRailAnimation(track, nextIsProduct, hasModeChange) {
    if (!track || !hasModeChange) return;
    track.classList.remove('is-to-product', 'is-to-daily');
    const previousAnimation = track.__pfhHomeFeatureRailAnimation;
    if (previousAnimation && typeof previousAnimation.cancel === 'function') {
      try { previousAnimation.cancel(); } catch (_) {}
    }
    track.__pfhHomeFeatureRailAnimation = null;
    const dragStartTransform = String(track.__pfhHomeFeatureRailStartTransform || '').trim();
    track.__pfhHomeFeatureRailStartTransform = '';
    const from = dragStartTransform || (nextIsProduct ? 'translateX(0)' : 'translateX(-100%)');
    const to = nextIsProduct ? 'translateX(-100%)' : 'translateX(0)';
    const easing = 'cubic-bezier(.25, 1.2, .35, 1)';
    if (typeof track.animate === 'function') {
      if (dragStartTransform) track.style.removeProperty('transform');
      const animation = track.animate(
        [{ transform: from }, { transform: to }],
        { duration: 620, easing, fill: 'both' },
      );
      track.__pfhHomeFeatureRailAnimation = animation;
      const cleanup = () => {
        if (track.__pfhHomeFeatureRailAnimation !== animation) return;
        track.__pfhHomeFeatureRailAnimation = null;
        if (dragStartTransform) track.style.removeProperty('transform');
        try { animation.cancel(); } catch (_) {}
      };
      animation.onfinish = cleanup;
      animation.oncancel = cleanup;
      return;
    }
    track.style.setProperty('transition', 'none');
    track.style.setProperty('transform', from);
    void track.offsetWidth;
    track.style.setProperty('transition', 'transform .62s cubic-bezier(.25, 1.2, .35, 1)');
    track.style.setProperty('transform', to);
    window.setTimeout(() => {
      if (!track.isConnected) return;
      track.style.removeProperty('transform');
      track.style.removeProperty('transition');
    }, 700);
  }

  function updateProductDevelopmentHomeModeDom(mode) {
    const next = normalizeProductDevelopmentWorkMode(mode);
    const panel = document.getElementById(PANEL_ID);
    const track = panel && panel.querySelector('.pfh-home-feature-track');
    if (!track) return false;
    const nextIsProduct = next === 'product-development';
    const wasProduct = track.classList.contains('is-product-development');
    const hasModeChange = wasProduct !== nextIsProduct;
    track.style.setProperty('transition', 'none');
    track.classList.toggle('is-product-development', nextIsProduct);
    track.classList.toggle('is-daily', !nextIsProduct);
    void track.offsetWidth;
    track.style.removeProperty('transition');
    playProductDevelopmentHomeFeatureRailAnimation(track, nextIsProduct, hasModeChange);
    const title = panel.querySelector('[data-work-mode-title]');
    if (title) title.textContent = nextIsProduct ? '开发功能' : '常用功能';
    const actions = panel.querySelector('.pfh-home-feature-actions');
    if (actions) actions.innerHTML = nextIsProduct
      ? '<span>可自定义开发入口</span><button type="button" data-action="home-feature-edit-toggle">编辑</button>'
      : '<span>可自定义常用入口</span><button type="button" data-action="home-feature-edit-toggle">编辑</button>';
    panel.classList.toggle('is-product-development', nextIsProduct);
    panel.querySelectorAll('.pfh-work-mode-switch button[data-work-mode]').forEach((button) => {
      button.classList.toggle('is-active', button.getAttribute('data-work-mode') === next);
    });
    return true;
  }

  function homeFeatureEditGroupHtml(label, description, entries, group) {
    const cards = entries.length
      ? entries.map((entry) => homeFeatureEntryHtml(entry, 'pfh-home-entry-edit', { editing: true, group })).join('')
      : '<div class="pfh-home-feature-dropzone">把功能卡片拖到这里</div>';
    return '<section class="pfh-home-feature-edit-group" data-home-feature-group="' + escapeHtml(group) + '">' +
      '<header><b>' + escapeHtml(label) + '</b><small>' + escapeHtml(description) + '</small></header>' +
      '<div class="pfh-home-feature-edit-list">' + cards + '</div>' +
      '</section>';
  }

  function homeGreetingMinutes(value) {
    const parts = String(value || '').split(':');
    if (parts.length !== 2) return -1;
    const hours = Number(parts[0]);
    const minutes = Number(parts[1]);
    return Number.isInteger(hours) && hours >= 0 && hours < 24 && Number.isInteger(minutes) && minutes >= 0 && minutes < 60
      ? hours * 60 + minutes
      : -1;
  }

  function homeGreetingMatches(item, minutesNow) {
    if (!item || !item.enabled) return false;
    const start = homeGreetingMinutes(item.startTime);
    const end = homeGreetingMinutes(item.endTime);
    if (start < 0 || end < 0) return false;
    if (start === end) return true;
    return start < end ? minutesNow >= start && minutesNow < end : minutesNow >= start || minutesNow < end;
  }

  function currentHomeGreeting(now) {
    const date = now instanceof Date ? now : new Date();
    const minutesNow = date.getHours() * 60 + date.getMinutes();
    const configured = (Array.isArray(state.homeGreetings) ? state.homeGreetings : [])
      .map(normalizeHomeGreetingItem)
      .filter(Boolean)
      .sort((a, b) => a.sortOrder - b.sortOrder || a.greetingId.localeCompare(b.greetingId));
    return configured.find((item) => homeGreetingMatches(item, minutesNow))
      || DEFAULT_HOME_GREETINGS.find((item) => homeGreetingMatches(item, minutesNow))
      || DEFAULT_HOME_GREETINGS[0];
  }

  function homeViewHtml(statusText) {
    if (state.workMode === 'product-development' && state.productDevelopmentView !== 'home') return productDevelopmentViewHtml(statusText);
    const period = Number(state.homeChartPeriod) === 30 ? 30 : 7;
    const stats = homeDashboardStats(period);
    const chart = homeChartGeometry(stats.values);
    const now = new Date();
    const weekNames = ['星期日', '星期一', '星期二', '星期三', '星期四', '星期五', '星期六'];
    const greeting = currentHomeGreeting(now);
    const dateText = (now.getMonth() + 1) + '月' + now.getDate() + '日 ' + weekNames[now.getDay()];
    const delta = stats.today - stats.yesterday;
    const deltaPercent = stats.yesterday ? Math.round(Math.abs(delta) / stats.yesterday * 100) : 0;
    const compareClass = delta > 0 ? ' is-up' : (delta < 0 ? ' is-down' : '');
    const compareBadge = delta > 0 ? '↗ ' + deltaPercent + '%' : (delta < 0 ? '↘ ' + deltaPercent + '%' : '持平');
    const compareText = stats.yesterday ? '比昨天' + (delta > 0 ? '多 ' + delta : (delta < 0 ? '少 ' + Math.abs(delta) : '相同')) + ' 个' : '昨日暂无新任务';
    const homeFeatureEntries = getHomeFeatureEntries();
    const homeFeatureById = new Map(homeFeatureEntries.map((entry) => [entry.id, entry]));
    const homeFeatureGroups = getHomeFeatureGroups();
    const commonEntries = homeFeatureGroups.common.map((id) => homeFeatureById.get(id)).filter(Boolean);
    const secondaryEntries = homeFeatureGroups.more.map((id) => homeFeatureById.get(id)).filter(Boolean);
    const primary = commonEntries[0] || null;
    const quickEntries = commonEntries.slice(1);
    const isProductDevelopment = state.workMode === 'product-development';
    const featureEditActions = '<div class="pfh-home-feature-actions">' +
      (isProductDevelopment
        ? (state.homeFeatureEditMode ? '<span>拖动卡片调整位置</span><button type="button" data-action="home-feature-edit-toggle" class="is-done">完成</button>' : '<span>可自定义开发入口</span><button type="button" data-action="home-feature-edit-toggle">编辑</button>')
        : (state.homeFeatureEditMode ? '<span>拖动卡片调整位置</span><button type="button" data-action="home-feature-edit-toggle" class="is-done">完成</button>' : '<span>可自定义常用入口</span><button type="button" data-action="home-feature-edit-toggle">编辑</button>')) +
      '</div>';
    const dailyFeaturePage = '<div class="pfh-home-feature-page pfh-home-feature-page-daily">' +
      (state.homeFeatureEditMode
        ? '<div class="pfh-home-feature-edit-groups">' + homeFeatureEditGroupHtml('常用功能', '上面区域会优先展示', commonEntries, 'common') + homeFeatureEditGroupHtml('更多功能', '不常用入口放在这里', secondaryEntries, 'more') + '</div>'
        : '<div class="pfh-home-feature-layout">' + (primary ? homeFeatureEntryHtml(primary, 'pfh-home-entry-primary') : '<div class="pfh-home-feature-empty">暂无常用入口</div>') + '<div class="pfh-home-quick-grid">' + quickEntries.map((entry) => homeFeatureEntryHtml(entry, 'pfh-home-entry-quick')).join('') + '</div></div><div class="pfh-home-secondary-label">更多功能</div><div class="pfh-home-secondary-grid">' + secondaryEntries.map((entry) => homeFeatureEntryHtml(entry, 'pfh-home-entry-secondary')).join('') + '</div>') +
      '</div>';
    const featureTrackClass = 'pfh-home-feature-track ' + (isProductDevelopment ? 'is-product-development' : 'is-daily') + (state.homeModeTransition ? ' is-' + escapeHtml(state.homeModeTransition) : '');
    const chartSummary = '近 ' + period + ' 日共新分配 ' + stats.total + ' 个任务';
    const status = statusText || greeting.subtitle || '常用功能与今日进度集中在这里';
    const modeSwitch = productDevelopmentModeSwitchHtml();
    return '<div class="pfh-detail-scroll pfh-home-scroll"><section class="pfh-home-dashboard">' +
      '<header class="pfh-home-welcome"><div><h2>' + escapeHtml(greeting.title) + '</h2><p>' + escapeHtml(dateText) + ' · ' + escapeHtml(status) + '</p></div>' + modeSwitch + '</header>' +
      '<div class="pfh-home-analytics">' +
        '<article class="pfh-home-metric"><small>今日新分配</small><div><strong>' + stats.today + '</strong><span>个任务</span></div><p class="pfh-home-compare' + compareClass + '"><b>' + escapeHtml(compareBadge) + '</b><span>' + escapeHtml(compareText) + '</span></p><footer><span><small>昨日</small><b>' + stats.yesterday + '</b></span><span><small>今日已定稿</small><b>' + stats.finalizedToday + '</b></span><span><small>完成率</small><b>' + (stats.today ? stats.completionRate + '%' : '--') + '</b></span></footer></article>' +
        '<article class="pfh-home-chart"><header><div><h3>新任务趋势</h3><p>' + escapeHtml(chartSummary) + '</p></div><div class="pfh-home-period-tabs"><button type="button" data-action="home-chart-period" data-period="7" class="' + (period === 7 ? 'is-active' : '') + '">7日</button><button type="button" data-action="home-chart-period" data-period="30" class="' + (period === 30 ? 'is-active' : '') + '">30日</button></div></header><div class="pfh-home-chart-canvas"><div class="pfh-home-chart-plot"><svg viewBox="0 0 620 130" preserveAspectRatio="none" role="img" aria-label="新任务趋势图"><defs><linearGradient id="pfh-home-chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="var(--pfh-theme-primary)" stop-opacity=".25"></stop><stop offset="1" stop-color="var(--pfh-theme-primary)" stop-opacity="0"></stop></linearGradient></defs><line x1="0" y1="26" x2="620" y2="26"></line><line x1="0" y1="68" x2="620" y2="68"></line><line x1="0" y1="110" x2="620" y2="110"></line><path class="pfh-home-chart-area" d="' + chart.area + '"></path><path class="pfh-home-chart-line" d="' + chart.line + '"></path></svg><div class="pfh-home-chart-points">' + homeChartPointsHtml(stats, chart) + '</div><div class="pfh-home-chart-tooltip" role="status"><strong></strong><span></span></div></div><div class="pfh-home-chart-labels">' + homeChartLabelsHtml(stats.days, period) + '</div></div></article>' +
      '</div>' +
      '<div class="pfh-home-lower">' +
        '<section class="pfh-home-panel pfh-home-feature-panel' + (state.homeFeatureEditMode ? ' is-editing' : '') + (isProductDevelopment ? ' is-product-development' : '') + '"><div class="pfh-home-panel-title"><h3 data-work-mode-title>' + (isProductDevelopment ? '开发功能' : '常用功能') + '</h3>' + featureEditActions + '</div>' +
          '<div class="pfh-home-feature-viewport"><div class="' + featureTrackClass + '">' + dailyFeaturePage + productDevelopmentHomeFeaturePageHtml() + '</div></div>' +
          '</section>' +
        homeTaskPanelHtml() +
      '</div>' +
      '</section></div>';
  }

  function normalizeToolsActiveTool(value) {
    const tool = String(value || '').trim().toLowerCase();
    if (tool === 'code' || tool === 'copywriting') return tool;
    return 'unit';
  }

  function unitConverterToolPanelHtml() {
    const result = convertCmInputToInches(state.cmConverterInput);
    return '<section class="pfh-mini-tool-card pfh-tools-panel"><div class="pfh-tools-panel-head"><small>UNIT CONVERTER</small><h3>厘米换算英寸</h3><p>支持单个数值或多个尺寸，例如 3.3 × 3.3 × 12.6。</p></div><label>厘米（cm）</label><textarea class="pfh-unit-converter-input" placeholder="例如：3.3 × 3.3 × 12.6">' + escapeHtml(state.cmConverterInput || '') + '</textarea>' +
      '<div class="pfh-mini-tool-result"><span>英寸（inch）</span><strong class="pfh-unit-converter-result">' + escapeHtml(result || '等待输入') + '</strong></div>' +
      '<div class="pfh-mini-tool-actions"><button type="button" data-action="unit-converter-clear">清空</button><button type="button" data-action="unit-converter-copy"' + (result ? '' : ' disabled') + '>复制结果</button></div></section>';
  }

  function codeFormatterToolPanelHtml() {
    const result = formatSearchCodes(state.codeFormatterInput);
    return '<section class="pfh-mini-tool-card pfh-tools-panel"><div class="pfh-tools-panel-head"><small>CODE FORMATTER</small><h3>编码格式化</h3><p>把多个编码整理为文件搜索格式，支持空格、换行或逗号分隔。</p></div><label>编码</label><textarea class="pfh-code-formatter-input" placeholder="粘贴多个编码，可用空格、换行或逗号分隔">' + escapeHtml(state.codeFormatterInput || '') + '</textarea>' +
      '<div class="pfh-mini-tool-result"><span>输出格式</span><strong class="pfh-code-formatter-result">' + escapeHtml(result || 'ext:zip|ext:xlsx 编码1|编码2') + '</strong></div>' +
      '<div class="pfh-mini-tool-actions"><button type="button" data-action="code-formatter-clear">清空</button><button type="button" data-action="code-formatter-copy"' + (result ? '' : ' disabled') + '>复制结果</button></div></section>';
  }

  const SUPPLEMENT_FACTS_PAGE_WIDTH = 595.25;
  const SUPPLEMENT_FACTS_PAGE_HEIGHT = 841.85;
  const SUPPLEMENT_FACTS_OUTER_LEFT = 53.88;
  const SUPPLEMENT_FACTS_OUTER_TOP = 71.88;
  const SUPPLEMENT_FACTS_OUTER_WIDTH = 484.68;
  const SUPPLEMENT_FACTS_BASE_HEIGHT = 361.08;
  const SUPPLEMENT_FACTS_ROW_HEIGHT = 30.84;
  const SUPPLEMENT_FACTS_BASE_FINAL_THICK = 400.08;
  const SUPPLEMENT_FACTS_BASE_FOOTER = 413.22;
  const SUPPLEMENT_FACTS_BODY_FONT = 10.812;
  const SUPPLEMENT_FACTS_TITLE_FONT = 24.45;
  const SUPPLEMENT_FACTS_NAME_X = 68.51;
  const SUPPLEMENT_FACTS_AMOUNT_X = 465.66;
  const SUPPLEMENT_FACTS_DAILY_VALUE_X = 524.94;
  let supplementFactsMeasureCanvas = null;

  function supplementFactsTextWidth(value, fontSize, bold) {
    const text = String(value || '');
    if (!text) return 0;
    try {
      if (!supplementFactsMeasureCanvas) supplementFactsMeasureCanvas = document.createElement('canvas');
      const context = supplementFactsMeasureCanvas.getContext('2d');
      if (context) {
        context.font = (bold ? '700 ' : '400 ') + fontSize + 'px Arial';
        return context.measureText(text).width;
      }
    } catch (error) {
      // Fall back to a conservative estimate when canvas is unavailable.
    }
    return text.length * fontSize * 0.55;
  }

  function fitSupplementFactsIngredient(value, amount) {
    const name = String(value || '').trim();
    const amountWidth = supplementFactsTextWidth(amount, SUPPLEMENT_FACTS_BODY_FONT, false);
    const availableWidth = Math.max(120, Math.min(
      350,
      SUPPLEMENT_FACTS_AMOUNT_X - SUPPLEMENT_FACTS_NAME_X - amountWidth - 8
    ));
    let fontSize = SUPPLEMENT_FACTS_BODY_FONT;
    while (fontSize > 6.6 && supplementFactsTextWidth(name, fontSize, false) > availableWidth) fontSize -= 0.2;
    let text = name;
    if (supplementFactsTextWidth(text, fontSize, false) > availableWidth) {
      while (text.length > 4 && supplementFactsTextWidth(text + '...', fontSize, false) > availableWidth) text = text.slice(0, -1);
      text = text.trim() + '...';
    }
    return { text, fontSize };
  }

  function supplementFactsSvgText(x, top, value, options) {
    const config = options || {};
    const fontSize = Number(config.fontSize || SUPPLEMENT_FACTS_BODY_FONT);
    const baseline = top + fontSize * 0.79;
    const anchor = config.anchor ? ' text-anchor="' + config.anchor + '"' : '';
    const weight = config.bold ? ' font-weight="700"' : '';
    return '<text x="' + Number(x).toFixed(2) + '" y="' + baseline.toFixed(2) + '" font-size="' + fontSize.toFixed(3) + '"' + anchor + weight + '>' + escapeHtml(value) + '</text>';
  }

  function renderSupplementFactsSvg(value) {
    const draft = normalizeSupplementFactsDraft(value);
    const rows = Array.isArray(draft.rows) && draft.rows.length
      ? draft.rows
      : [{ name: '', amount: '', dailyValue: '' }];
    const delta = (rows.length - 8) * SUPPLEMENT_FACTS_ROW_HEIGHT;
    const outerHeight = SUPPLEMENT_FACTS_BASE_HEIGHT + delta;
    const finalThickTop = SUPPLEMENT_FACTS_BASE_FINAL_THICK + delta;
    const footerTop = SUPPLEMENT_FACTS_BASE_FOOTER + delta;
    const line = (x, top, width, height) => '<rect x="' + Number(x).toFixed(2) + '" y="' + Number(top).toFixed(2) + '" width="' + Number(width).toFixed(2) + '" height="' + Number(height).toFixed(2) + '" fill="#000"></rect>';
    const parts = [
      '<svg class="pfh-supplement-facts-svg" xmlns="http://www.w3.org/2000/svg" width="' + SUPPLEMENT_FACTS_PAGE_WIDTH + '" height="' + SUPPLEMENT_FACTS_PAGE_HEIGHT + '" viewBox="0 0 ' + SUPPLEMENT_FACTS_PAGE_WIDTH + ' ' + SUPPLEMENT_FACTS_PAGE_HEIGHT + '" role="img" aria-label="Supplement Facts" shape-rendering="geometricPrecision">',
      '<rect x="' + SUPPLEMENT_FACTS_OUTER_LEFT + '" y="' + SUPPLEMENT_FACTS_OUTER_TOP + '" width="' + SUPPLEMENT_FACTS_OUTER_WIDTH + '" height="' + outerHeight.toFixed(2) + '" fill="#fff" stroke="#000" stroke-width="0.6"></rect>',
      '<g font-family="Arial, Helvetica, sans-serif" fill="#000">',
      supplementFactsSvgText(70.45, 80.42, draft.title, { fontSize: SUPPLEMENT_FACTS_TITLE_FONT, bold: true }),
      supplementFactsSvgText(70.45, 104.08, 'Serving Size ' + draft.servingSize),
      supplementFactsSvgText(70.45, 116.91, 'Serving Per Container ' + draft.servingsPerContainer),
      line(65.76, 129.84, 460.92, 1.8),
      supplementFactsSvgText(68.51, 139.58, 'Amount Per Serving', { bold: true }),
      supplementFactsSvgText(445.08, 139.58, '% Daily Value', { bold: true }),
      line(66.36, 153.96, 459.72, 0.6),
    ];
    rows.forEach((row, index) => {
      const top = 166.02 + index * SUPPLEMENT_FACTS_ROW_HEIGHT;
      const fit = fitSupplementFactsIngredient(row.name, row.amount);
      if (index < rows.length - 1) parts.push(line(66.36, 184.80 + index * SUPPLEMENT_FACTS_ROW_HEIGHT, 459.72, 0.6));
      parts.push(supplementFactsSvgText(SUPPLEMENT_FACTS_NAME_X, top, fit.text, { fontSize: fit.fontSize }));
      parts.push(supplementFactsSvgText(SUPPLEMENT_FACTS_AMOUNT_X, top, row.amount, { anchor: 'end' }));
      parts.push(supplementFactsSvgText(SUPPLEMENT_FACTS_DAILY_VALUE_X, top, row.dailyValue || '**', { anchor: 'end' }));
    });
    parts.push(line(65.76, finalThickTop, 460.92, 1.8));
    if (draft.showFooter) parts.push(supplementFactsSvgText(68.51, footerTop, '**Daily Value not established.'));
    parts.push('</g></svg>');
    return parts.join('');
  }

  function supplementFactsVisibleRows(draft) {
    return Array.isArray(draft.rows) && draft.rows.length
      ? draft.rows
      : [{ name: '', amount: '', dailyValue: '**' }];
  }

  function supplementFactsFieldHtml(key, label, value, placeholder) {
    return '<label class="pfh-supplement-facts-field"><span>' + label + '</span><input type="text" data-supplement-facts-state="' + key + '" value="' + escapeHtml(value) + '" placeholder="' + escapeHtml(placeholder || '') + '" spellcheck="false"></label>';
  }

  function supplementFactsToolPanelHtml() {
    const draft = normalizeSupplementFactsDraft(state.supplementFactsDraft);
    state.supplementFactsDraft = draft;
    const rows = supplementFactsVisibleRows(draft);
    const rowMarkup = rows.map((row, index) => '<div class="pfh-supplement-facts-row"><input type="text" data-supplement-facts-row-index="' + index + '" data-supplement-facts-row-field="name" value="' + escapeHtml(row.name) + '" placeholder="Vitamin B6 (as ...)" spellcheck="false"><input type="text" data-supplement-facts-row-index="' + index + '" data-supplement-facts-row-field="amount" value="' + escapeHtml(row.amount) + '" placeholder="10 mg" spellcheck="false"><input type="text" data-supplement-facts-row-index="' + index + '" data-supplement-facts-row-field="dailyValue" value="' + escapeHtml(row.dailyValue) + '" placeholder="**" spellcheck="false"><button type="button" data-action="supplement-facts-remove-row" data-index="' + index + '" aria-label="删除这一行">×</button></div>').join('');
    return '<section class="pfh-mini-tool-card pfh-tools-panel pfh-supplement-facts-tool"><div class="pfh-supplement-facts-head"><div><small>SUPPLEMENT FACTS</small><h3>成分表 PDF</h3><p>填写标签字段后，按参考文件的 A4 版式预览并打印保存。</p></div><span class="pfh-supplement-facts-chip">A4</span></div><div class="pfh-supplement-facts-layout"><div class="pfh-supplement-facts-editor">' +
      '<div class="pfh-supplement-facts-fields">' + supplementFactsFieldHtml('title', '标题', draft.title, 'Supplement Facts') + supplementFactsFieldHtml('servingSize', 'Serving Size', draft.servingSize, '2 Capsules') + supplementFactsFieldHtml('servingsPerContainer', 'Serving Per Container', draft.servingsPerContainer, '30') + supplementFactsFieldHtml('filename', 'PDF 文件名', draft.filename, 'supplement-facts.pdf') + '</div>' +
      '<div class="pfh-supplement-facts-section-title"><strong>成分行</strong><span>最多 18 行</span></div><div class="pfh-supplement-facts-row-head"><span>成分名称</span><span>每份含量</span><span>% DV</span><span></span></div><div class="pfh-supplement-facts-rows">' + rowMarkup + '</div><button type="button" class="pfh-supplement-facts-add" data-action="supplement-facts-add-row">＋ 添加成分行</button>' +
      '<div class="pfh-supplement-facts-editor-footer"><label class="pfh-supplement-facts-check"><input type="checkbox" data-supplement-facts-state="showFooter"' + (draft.showFooter ? ' checked' : '') + '><span>显示 “**Daily Value not established.”</span></label><div class="pfh-mini-tool-actions"><button type="button" data-action="supplement-facts-load-sample">载入示例</button><button type="button" class="is-primary" data-action="supplement-facts-print">打印 / 保存 PDF</button></div></div></div>' +
      '<div class="pfh-supplement-facts-preview-card"><div class="pfh-supplement-facts-preview-head"><div><strong>实时预览</strong><span>打印时选择“另存为 PDF”</span></div><span>595 × 842 pt</span></div><div class="pfh-supplement-facts-preview">' + renderSupplementFactsSvg(draft) + '</div></div></div></section>';
  }

  function renderSupplementFactsPreviewInline() {
    const panel = ensurePanel();
    const preview = panel.querySelector('.pfh-supplement-facts-preview');
    if (preview) preview.innerHTML = renderSupplementFactsSvg(state.supplementFactsDraft);
  }

  function supplementFactsFilename(value) {
    let filename = String(value || '').trim().replace(/[\\/:*?"<>|]+/g, '-');
    if (!filename) filename = 'supplement-facts.pdf';
    if (!/\.pdf$/i.test(filename)) filename += '.pdf';
    return filename;
  }

  function getSupplementFactsExportDraft() {
    const draft = normalizeSupplementFactsDraft(state.supplementFactsDraft);
    const rows = draft.rows.filter((row) => row.name || row.amount || (row.dailyValue && row.dailyValue !== '**'));
    if (!rows.length) {
      showToast('请至少填写一行成分');
      return null;
    }
    if (rows.length > 18) {
      showToast('单页最多支持 18 行成分');
      return null;
    }
    for (let index = 0; index < rows.length; index += 1) {
      if (!rows[index].name) {
        showToast('第 ' + (index + 1) + ' 行缺少成分名称');
        return null;
      }
      if (!rows[index].amount) {
        showToast('第 ' + (index + 1) + ' 行缺少每份含量');
        return null;
      }
    }
    return {
      ...draft,
      filename: supplementFactsFilename(draft.filename),
      rows: rows.map((row) => ({ ...row, dailyValue: row.dailyValue || '**' })),
    };
  }

  function printSupplementFactsPdf() {
    const draft = getSupplementFactsExportDraft();
    if (!draft) return;
    const popup = window.open('', '_blank', 'width=900,height=900,scrollbars=yes');
    if (!popup) {
      showToast('打印窗口被浏览器拦截，请允许弹出窗口后重试');
      return;
    }
    const title = escapeHtml(draft.filename);
    popup.document.open();
    popup.document.write('<!doctype html><html lang="en"><head><meta charset="utf-8"><title>' + title + '</title><style>@page{size:A4;margin:0}html,body{margin:0;padding:0;width:595.25pt;min-height:841.85pt;background:#fff}body{overflow:hidden}.pfh-supplement-facts-svg{display:block;width:595.25pt;height:841.85pt;background:#fff}</style></head><body>' + renderSupplementFactsSvg(draft) + '</body></html>');
    popup.document.close();
    popup.focus();
    window.setTimeout(() => {
      try { popup.print(); } catch (error) { showToast('打印窗口已打开，请手动选择打印或另存为 PDF'); }
    }, 450);
    showToast('已打开打印窗口，请选择“另存为 PDF”');
  }

  function toolsViewHtml() {
    const activeTool = normalizeToolsActiveTool(state.toolsActiveTool);
    state.toolsActiveTool = activeTool;
    const navItems = [
      ['unit', 'calculator', '厘米换算英寸'],
      ['code', 'tag', '编码格式化'],
      ['copywriting', 'sparkle', '批量文案补全'],
    ];
    const content = activeTool === 'unit'
      ? unitConverterToolPanelHtml()
      : (activeTool === 'code' ? codeFormatterToolPanelHtml() : toyCopywritingBatchCardHtml());
    const nav = navItems.map((item) => '<button type="button" data-action="tools-select" data-tool="' + item[0] + '" class="' + (item[0] === activeTool ? 'is-active' : '') + '" aria-current="' + (item[0] === activeTool ? 'page' : 'false') + '">' + iconHtml(item[1]) + '<span>' + item[2] + '</span></button>').join('');
    return '<div class="pfh-detail-scroll"><section class="pfh-mini-tool-page pfh-tools-page">' +
      '<div class="pfh-mini-tool-head pfh-tools-head"><button type="button" class="pfh-upload-back" data-action="home-back" aria-label="返回主页">' + iconHtml('backArrow') + '</button><div><small>QUICK TOOLS</small><h2>小工具</h2><p>厘米换算、编码格式化和批量玩具文案补全，统一在这里切换。</p></div></div>' +
      '<div class="pfh-tools-workbench"><aside class="pfh-tools-sidebar"><div class="pfh-tools-sidebar-head"><small>TOOLS</small><strong>工具列表</strong></div><nav class="pfh-tools-nav" aria-label="小工具列表">' + nav + '</nav></aside><main class="pfh-tools-content">' + content + '</main></div>' +
      '</section></div>';
  }

  function toyCopywritingBatchCardHtml() {
    const queueIsActive = state.toyCopywritingBatchRunning || state.toyCopywritingApplyRunning;
    const queue = queueIsActive
      ? (state.toyCopywritingBatchQueue || loadToyCopywritingBatchQueue())
      : loadToyCopywritingBatchQueue();
    state.toyCopywritingBatchQueue = queue;
    const stats = getToyCopywritingBatchStats(queue);
    const running = Boolean(state.toyCopywritingBatchRunning);
    const applying = Boolean(state.toyCopywritingApplyRunning);
    const downloadReviewing = applying && isToyCopywritingDownloadOnlyMode(state.toyCopywritingApplyMode);
    const locked = running || applying;
    const canStart = !locked && queue.some((entry) => entry.status === 'pending' || entry.status === 'error');
    const canApply = !locked && queue.some((entry) => {
      return (entry.status === 'success' || entry.status === 'noop') && entry.applyStatus !== 'submitted';
    });
    const progressText = state.toyCopywritingBatchStatus || (running
      ? '正在先读取新品开发全部项目状态，再按状态进入设计任务或商品管理补全文案并生成图片，请保持 PLM 页面登录状态。'
      : '输入 SKU 后，系统会自动识别玩具并只补全缺失的中英文文案字段。');
    return '<section class="pfh-mini-tool-card pfh-tools-panel pfh-toy-copywriting-batch-page">' +
      '<div class="pfh-toy-copywriting-batch-head"><small>TOY COPYWRITING</small><h3>批量智能玩具文案补全</h3><p>只需输入 SKU，自动逐个补全并保存 PLM 草稿。</p></div>' +
      '<div class="pfh-toy-copywriting-batch-card pfh-toy-copywriting-batch-form"><label>SKU 编码</label><textarea class="pfh-toy-copywriting-batch-input" placeholder="例如：SKU00047214\nSKU00047213\nSKU00047212">' + escapeHtml(state.toyCopywritingBatchInput || '') + '</textarea><p class="pfh-toy-copywriting-batch-hint">支持每行一个，也支持空格、逗号或直接粘贴一串文本；重复编码会自动合并。非玩具、基础卖点缺失或保存失败的编码会停在失败列表中。</p><div class="pfh-mini-tool-actions"><button type="button" data-action="toy-copywriting-batch-clear-input">清空</button><button type="button" data-action="toy-copywriting-batch-add">加入文案队列</button></div></div>' +
      '<div class="pfh-toy-copywriting-batch-card"><div class="pfh-toy-copywriting-batch-summary"><strong>文案补全队列</strong><span>共 ' + stats.total + ' 个 · 已完成 ' + stats.done + ' 个 · 待处理 ' + stats.pending + ' 个 · 失败 ' + stats.error + ' 个</span></div><div class="pfh-toy-copywriting-batch-queue">' + getToyCopywritingBatchRowsHtml(queue, locked) + '</div><p class="pfh-toy-copywriting-batch-progress">' + escapeHtml(progressText) + '</p><div class="pfh-mini-tool-actions pfh-toy-copywriting-batch-actions"><button type="button" data-action="toy-copywriting-batch-start"' + (canStart ? '' : ' disabled') + '>' + (running ? '正在补全…' : '开始补全文案') + '</button><button type="button" data-action="toy-copywriting-batch-pause"' + (running ? '' : ' disabled') + '>暂停</button><button type="button" data-action="toy-copywriting-batch-apply"' + (canApply ? '' : ' disabled') + '>' + (applying && !downloadReviewing ? '正在全部应用并提审…' : '批量全部应用并提审') + '</button><button type="button" data-action="toy-copywriting-batch-download-review" title="通过生图 API 查询并按主图、详情图顺序下载，不全部应用、不提审"' + (canApply ? '' : ' disabled') + '>' + (downloadReviewing ? '正在下载生图…' : '下载全部主图和详情图') + '</button><button type="button" data-action="toy-copywriting-batch-clear-completed"' + (stats.done && !locked ? '' : ' disabled') + '>清除已完成</button></div></div>' +
      '</section>';
  }

  function batchExcelViewHtml() {
    const queue = loadExcelBatchQueue();
    state.batchExcelQueue = queue;
    const stats = getExcelBatchQueueStats(queue);
    const mode = state.batchExcelMode === 'merge' ? 'merge' : 'separate';
    const running = Boolean(state.batchExcelWorkerRunning);
    const downloading = Boolean(state.batchExcelDownloadRunning);
    const modeDisabled = running || downloading ? ' disabled' : '';
    const canDownload = stats.generatable > 0 && !running && !downloading;
    const progressText = state.batchExcelStatus || (running ? '正在按顺序补全缓存，请保持 PLM 页面登录状态。' : '数据不完整也可生成；缺失字段会留空，缺少产品图时不插入图片。');
    return '<div class="pfh-detail-scroll"><section class="pfh-mini-tool-page pfh-batch-excel-page">' +
      '<div class="pfh-mini-tool-head pfh-batch-excel-head"><button type="button" class="pfh-upload-back" data-action="home-back" aria-label="返回主页">' + iconHtml('backArrow') + '</button><div><small>BATCH EXCEL</small><h2>批量生成 Excel</h2><p>输入多个 SKU，补全资料后按需要分别下载或合并下载。</p></div></div>' +
      '<div class="pfh-batch-excel-top"><div class="pfh-mini-tool-card pfh-batch-excel-card pfh-batch-excel-form"><label>SKU 编码</label><textarea class="pfh-batch-excel-input" placeholder="例如：SKU00046398\nSKU00046397\nSKU00046396\nSKU00046395">' + escapeHtml(state.batchExcelInput || '') + '</textarea><p class="pfh-batch-excel-hint">每行一个或直接粘贴一串编码，重复 SKU 会自动合并。</p><div class="pfh-mini-tool-actions"><button type="button" data-action="batch-excel-clear-input">清空</button><button type="button" data-action="batch-excel-add">加入补全队列</button></div></div><div class="pfh-mini-tool-card pfh-batch-excel-card pfh-batch-excel-mode-card"><div class="pfh-batch-excel-mode-head"><strong>导出方式</strong><span>下载前可随时切换</span></div><div class="pfh-batch-excel-mode"><button type="button" data-action="batch-excel-mode" data-mode="separate" class="pfh-batch-excel-mode-option is-separate' + (mode === 'separate' ? ' is-active' : '') + '" aria-pressed="' + (mode === 'separate' ? 'true' : 'false') + '"' + modeDisabled + '>' + iconHtml('download') + '<span><b>分别下载</b><small>每个 SKU 一个文件</small></span></button><button type="button" data-action="batch-excel-mode" data-mode="merge" class="pfh-batch-excel-mode-option is-merge' + (mode === 'merge' ? ' is-active' : '') + '" aria-pressed="' + (mode === 'merge' ? 'true' : 'false') + '"' + modeDisabled + '>' + iconHtml('batchExcel') + '<span><b>合并下载</b><small>合成一个工作簿</small></span></button></div><p class="pfh-batch-excel-mode-hint">分别下载方便逐个发送；合并下载适合一次性整理。</p></div></div>' +
      '<div class="pfh-mini-tool-card pfh-batch-excel-card pfh-batch-excel-queue-card"><div class="pfh-batch-excel-summary"><div><strong>补全与下载队列</strong><small>上下滑动浏览全部任务</small></div><span>共 ' + stats.total + ' 个 · 完整 ' + stats.ready + ' 个 · 可生成 ' + stats.partial + ' 个</span></div><div class="pfh-batch-excel-queue">' + getExcelBatchQueueRowsHtml(queue, running || downloading) + '</div><div class="pfh-batch-excel-footer"><p class="pfh-batch-excel-progress">' + escapeHtml(progressText) + '</p><div class="pfh-mini-tool-actions pfh-batch-excel-actions"><button type="button" class="is-prepare" data-action="batch-excel-prepare"' + (running || downloading || !queue.length ? ' disabled' : '') + '>' + (running ? '<i class="pfh-loading-dots" aria-hidden="true"><i></i><i></i><i></i></i>' : iconHtml('refresh')) + (running ? '正在补全…' : '补全数据') + '</button><button type="button" class="is-download" data-action="batch-excel-download"' + (canDownload ? '' : ' disabled') + '>' + (downloading ? '<i class="pfh-loading-dots" aria-hidden="true"><i></i><i></i><i></i></i>' : iconHtml('download')) + (mode === 'merge' ? '合并下载 Excel' : '分别下载 Excel') + '</button><button type="button" class="is-clear" data-action="batch-excel-clear-completed"' + (stats.downloaded ? '' : ' disabled') + '>清除已下载</button></div></div></div>' +
      '</section></div>';
  }

  function getExcelBatchQueueStats(queue) {
    const items = Array.isArray(queue) ? queue : [];
    return items.reduce((stats, entry) => {
      const snapshot = getExcelBatchCacheSnapshot(entry.sku);
      if (entry.status === 'downloaded') stats.downloaded += 1;
      const generatable = entry.status !== 'preparing';
      if (generatable) stats.generatable += 1;
      if (!snapshot.missing.length && generatable && entry.status !== 'error') stats.ready += 1;
      else if (generatable) stats.partial += 1;
      else stats.pending += 1;
      stats.total += 1;
      return stats;
    }, { total: 0, ready: 0, partial: 0, pending: 0, generatable: 0, downloaded: 0 });
  }

  function getExcelBatchQueueRowsHtml(queue, locked) {
    if (!Array.isArray(queue) || !queue.length) return '<div class="pfh-batch-excel-empty">还没有编码。先粘贴 SKU，再加入补全队列。</div>';
    return queue.map((entry) => {
      const snapshot = getExcelBatchCacheSnapshot(entry.sku);
      const missing = snapshot.missing;
      const status = getExcelBatchEntryStatus(entry, missing);
      const statusClass = status.kind === 'ready' ? 'is-ready' : (status.kind === 'error' ? 'is-error' : 'is-pending');
      const title = snapshot.data.name || snapshot.data.englishName || '未读取产品名称';
      const detail = status.kind === 'ready'
        ? (entry.status === 'downloaded' ? '已生成文件，可再次下载' : '缓存字段完整，等待下载')
        : (status.text + (missing.length ? '：' + missing.join('、') : '') + (entry.error ? ' / ' + entry.error : ''));
      const retry = !locked && status.kind !== 'ready' ? '<button type="button" data-action="batch-excel-retry" data-sku="' + escapeHtml(entry.sku) + '" title="重新补全">↻</button>' : '';
      return '<div class="pfh-batch-excel-row"><div class="pfh-batch-excel-row-main"><b>' + escapeHtml(entry.sku) + '</b><small title="' + escapeHtml(title + ' / ' + detail) + '">' + escapeHtml(title + ' · ' + detail) + '</small></div><span class="pfh-batch-excel-status ' + statusClass + '">' + escapeHtml(status.text) + '</span>' + retry + '<button type="button" data-action="batch-excel-remove" data-sku="' + escapeHtml(entry.sku) + '" title="移除">×</button></div>';
    }).join('');
  }

  function getExcelBatchEntryStatus(entry, missing) {
    const current = String(entry && entry.status || 'pending');
    if (current === 'preparing') return { kind: 'pending', text: '补全中' };
    if (current === 'error') return { kind: 'error', text: '补全失败，可生成' };
    if (current === 'downloaded') return { kind: 'ready', text: '已下载' };
    if (!missing.length) return { kind: 'ready', text: '缓存完整' };
    if (current === 'partial') return { kind: 'pending', text: '数据不完整，可生成' };
    return { kind: 'pending', text: '待补全，可生成' };
  }

  function getToyCopywritingBatchStats(queue) {
    return (Array.isArray(queue) ? queue : []).reduce((stats, entry) => {
      const status = String(entry && entry.status || 'pending');
      stats.total += 1;
      if (status === 'success' || status === 'noop') stats.done += 1;
      else if (status === 'error') stats.error += 1;
      else stats.pending += 1;
      return stats;
    }, { total: 0, done: 0, pending: 0, error: 0 });
  }

  function getToyCopywritingBatchEntryStatus(entry) {
    const status = String(entry && entry.status || 'pending');
    const applyStatus = String(entry && entry.applyStatus || '');
    const downloadOnly = isToyCopywritingDownloadOnlyMode(entry && entry.applyMode);
    if (applyStatus === 'applying') return { kind: 'running', text: downloadOnly ? '下载生图中' : '应用中' };
    if (applyStatus === 'applied') return { kind: 'running', text: downloadOnly ? '下载完成' : '应用完成，提审中' };
    if (applyStatus === 'downloaded') return { kind: 'done', text: '已下载生图' };
    if (applyStatus === 'submitted') return { kind: 'done', text: '已提审' };
    if (applyStatus === 'error' && (status === 'success' || status === 'noop')) {
      return { kind: 'error', text: downloadOnly ? '下载生图失败' : '应用失败' };
    }
    if (status === 'processing') return { kind: 'running', text: '补全中' };
    if (status === 'success') return { kind: 'done', text: '已完成' };
    if (status === 'noop') return { kind: 'done', text: '无需补充' };
    if (status === 'error') return { kind: 'error', text: '补全失败' };
    return { kind: 'pending', text: '待处理' };
  }

  function getToyCopywritingBatchRowsHtml(queue, locked) {
    if (!Array.isArray(queue) || !queue.length) return '<div class="pfh-toy-copywriting-batch-empty">还没有编码。先粘贴 SKU，再加入文案队列。</div>';
    return queue.map((entry) => {
      const status = getToyCopywritingBatchEntryStatus(entry);
      const data = normalizeData(loadData(entry.sku) || {});
      const title = entry.name || data.name || '等待读取产品名称';
      const generatedImages = Number(entry.generatedImages) || 0;
      const submitted = entry.applyStatus === 'submitted';
      const downloaded = entry.applyStatus === 'downloaded';
      const detail = downloaded
        ? '主图/详情图已下载（未全部应用，未提审）'
        : submitted
        ? (entry.applyMode === 'download-review' ? '主图/详情图已下载并提审（未全部应用）' : '主图/详情图已全部应用并提审')
        : (entry.status === 'success'
          ? (/已生成/.test(entry.step || '')
            ? entry.step
            : '已补充 ' + (Number(entry.filledCount) || 0) + ' 个字段并保存草稿' + (generatedImages ? '，主图/详情图请求已触发' : '')) + (entry.applyError ? ' / ' + entry.applyError : '')
          : (entry.status === 'noop' ? '现有文案已完整' + (entry.applyError ? ' / ' + entry.applyError : '') : (entry.error || entry.step || '等待处理')));
      const retry = !locked && entry.status === 'error' ? '<button type="button" data-action="toy-copywriting-batch-retry" data-sku="' + escapeHtml(entry.sku) + '" title="重新补全">↻</button>' : '';
      const remove = !locked ? '<button type="button" data-action="toy-copywriting-batch-remove" data-sku="' + escapeHtml(entry.sku) + '" title="移除">×</button>' : '';
      return '<div class="pfh-toy-copywriting-batch-row"><div class="pfh-toy-copywriting-batch-row-main"><b>' + escapeHtml(entry.sku) + '</b><small title="' + escapeHtml(title + ' / ' + detail) + '">' + escapeHtml(title + ' · ' + detail) + '</small></div><span class="pfh-toy-copywriting-batch-status is-' + status.kind + '">' + escapeHtml(status.text) + '</span>' + retry + remove + '</div>';
    }).join('');
  }

  function extractToyCopywritingBatchSkus(value) {
    const seen = new Set();
    return extractSearchCodes(value).filter((item) => /^SKU\d+$/i.test(item)).map((item) => String(item).toUpperCase()).filter((sku) => {
      if (seen.has(sku)) return false;
      seen.add(sku);
      return true;
    });
  }

  function addToyCopywritingBatchItems(value) {
    const skus = extractToyCopywritingBatchSkus(value);
    if (!skus.length) {
      showToast('没有找到有效 SKU，请检查编码格式');
      return;
    }
    const existing = new Map(loadToyCopywritingBatchQueue().map((entry) => [entry.sku, entry]));
    const now = Date.now();
    skus.forEach((sku, index) => {
      const previous = existing.get(sku);
      const data = normalizeData(loadData(sku) || {});
      existing.set(sku, {
        ...(previous || {}),
        id: previous && previous.id || 'toy-copywriting-' + sku + '-' + now + '-' + index,
        sku,
        name: data.name || previous && previous.name || '',
        status: 'pending',
        step: '等待打开设计任务编辑入口',
        error: '',
        filledCount: 0,
        generatedImages: 0,
        applyStatus: '',
        applyError: '',
        projectStatus: data.projectStatus || previous && previous.projectStatus || '',
        projectRowId: data.projectRowId || previous && previous.projectRowId || '',
        createdAt: previous && previous.createdAt || now,
        updatedAt: now,
      });
    });
    state.toyCopywritingBatchInput = '';
    state.toyCopywritingBatchStatus = '已加入 ' + skus.length + ' 个 SKU，等待补全文案';
    saveToyCopywritingBatchQueue(Array.from(existing.values()));
    renderShell();
    showToast(state.toyCopywritingBatchStatus);
  }

  function updateToyCopywritingBatchEntry(sku, patch) {
    const normalizedSku = String(sku || '').trim().toUpperCase();
    const queue = Array.isArray(state.toyCopywritingBatchQueue) ? state.toyCopywritingBatchQueue : loadToyCopywritingBatchQueue();
    const next = queue.map((entry) => entry.sku === normalizedSku ? { ...entry, ...(patch || {}), updatedAt: Date.now() } : entry);
    saveToyCopywritingBatchQueue(next);
    return next.find((entry) => entry.sku === normalizedSku) || null;
  }

  function removeToyCopywritingBatchItem(sku) {
    if (state.toyCopywritingBatchRunning) {
      showToast('当前队列正在处理，请先暂停后再移除');
      return;
    }
    const normalizedSku = String(sku || '').trim().toUpperCase();
    saveToyCopywritingBatchQueue(loadToyCopywritingBatchQueue().filter((entry) => entry.sku !== normalizedSku));
    renderShell();
  }

  function retryToyCopywritingBatchItem(sku) {
    if (state.toyCopywritingBatchRunning) return;
    const normalizedSku = String(sku || '').trim().toUpperCase();
    if (!loadToyCopywritingBatchQueue().some((entry) => entry.sku === normalizedSku)) return;
    updateToyCopywritingBatchEntry(normalizedSku, { status: 'pending', step: '等待重新补全', error: '', filledCount: 0 });
    renderShell();
  }

  function clearCompletedToyCopywritingBatch() {
    if (state.toyCopywritingBatchRunning) return;
    saveToyCopywritingBatchQueue(loadToyCopywritingBatchQueue().filter((entry) => entry.status !== 'success' && entry.status !== 'noop'));
    state.toyCopywritingBatchStatus = '已清除已完成项目';
    renderShell();
  }

  function pauseToyCopywritingBatch() {
    if (!state.toyCopywritingBatchRunning) return;
    state.toyCopywritingBatchRunning = false;
    const currentSku = state.toyCopywritingBatchCurrentSku;
    if (currentSku) updateToyCopywritingBatchEntry(currentSku, { status: 'pending', step: '已暂停，等待继续', error: '' });
    state.toyCopywritingBatchCurrentSku = '';
    state.toyCopywritingBatchStatus = '已暂停，已完成项目保留在队列中';
    saveToyCopywritingBatchQueue(state.toyCopywritingBatchQueue);
    renderShell();
  }

  async function startToyCopywritingBatch() {
    if (state.toyCopywritingBatchRunning || state.toyCopywritingApplyRunning) return;
    state.toyCopywritingBatchQueue = loadToyCopywritingBatchQueue();
    const pending = state.toyCopywritingBatchQueue.filter((entry) => entry.status === 'pending' || entry.status === 'error');
    if (!pending.length) {
      state.toyCopywritingBatchStatus = state.toyCopywritingBatchQueue.length ? '当前队列没有待处理项目' : '队列暂为空';
      renderShell();
      return;
    }
    state.toyCopywritingBatchRunning = true;
    state.toyCopywritingBatchStatus = '开始批量补全文案';
    saveToyCopywritingBatchQueue(state.toyCopywritingBatchQueue);
    renderShell();
    try {
      await processToyCopywritingBatch();
    } catch (error) {
      state.toyCopywritingBatchRunning = false;
      state.toyCopywritingBatchCurrentSku = '';
      state.toyCopywritingBatchStatus = '批量处理异常：' + formatErrorMessage(error);
      renderShell();
    }
  }

  async function processToyCopywritingBatch() {
    const queue = state.toyCopywritingBatchQueue || [];
    const routeMap = await prepareToyCopywritingBatchRoutes(queue.filter((entry) => entry.status === 'pending' || entry.status === 'error'));
    for (const entry of queue) {
      if (!state.toyCopywritingBatchRunning) break;
      if (entry.status !== 'pending' && entry.status !== 'error') continue;
      const sku = entry.sku;
      state.toyCopywritingBatchCurrentSku = sku;
      updateToyCopywritingBatchEntry(sku, { status: 'processing', step: '正在按项目状态打开对应编辑入口', error: '' });
      let drawer = null;
      try {
        const cached = normalizeData(loadData(sku) || (state.index || []).find((item) => item.sku === sku) || { sku });
        drawer = await openToyCopywritingBatchDrawer(sku, cached, routeMap.get(sku));
        const data = getPageToyCopywritingData(drawer, sku);
        if (!isToyCopywritingProduct(data)) throw new Error('当前编码未识别为玩具，已跳过');
        updateToyCopywritingBatchEntry(sku, { name: data.name || cached.name || '', step: '正在补全中英文缺失字段' });
        const filledCount = await fillToyCopywriting({ data, fromPage: true, throwOnError: true });
        const imageResult = await generateToyImagesForBatch(drawer, sku);
        const generatedImages = imageResult.completed;
        const imageStep = imageResult.triggered === 2
          ? '文案已保存，主图和详情图生成请求已触发'
          : (imageResult.triggered
            ? '已有图片保留，其余图片生成请求已触发'
            : 'PLM 中主图和详情图均已生成');
        updateToyCopywritingBatchEntry(sku, {
          status: filledCount || generatedImages ? 'success' : 'noop',
          step: imageStep,
          error: '',
          filledCount: filledCount || 0,
          generatedImages,
        });
      } catch (error) {
        const message = formatErrorMessage(error) || '文案补全失败';
        updateToyCopywritingBatchEntry(sku, { status: 'error', step: '处理失败', error: message });
        addLog('error', '批量玩具文案补充失败', sku + ' | ' + message);
      } finally {
        if (drawer || getToyCopywritingDrawerForSku(sku) || getProjectDrawerForSku(sku)) {
          await closeToyCopywritingDrawerForSku(sku).catch(() => {});
        }
        state.toyCopywritingBatchCurrentSku = '';
        saveToyCopywritingBatchQueue(state.toyCopywritingBatchQueue);
        if (state.toyCopywritingBatchRunning) {
          state.toyCopywritingBatchStatus = '已处理 ' + sku + '，继续下一个编码';
          renderShell();
        }
      }
    }
    if (state.toyCopywritingBatchRunning) {
      state.toyCopywritingBatchRunning = false;
      state.toyCopywritingBatchStatus = '批量文案补全完成';
      state.toyCopywritingBatchCurrentSku = '';
      saveToyCopywritingBatchQueue(state.toyCopywritingBatchQueue);
      renderShell();
      showToast('批量玩具文案补全完成');
    }
  }

  async function prepareToyCopywritingBatchRoutes(entries) {
    const skus = Array.from(new Set((entries || []).map((entry) => String(entry && entry.sku || '').trim().toUpperCase()).filter(Boolean)));
    const routes = new Map();
    if (!skus.length) return routes;
    const projectSkus = [];
    skus.forEach((sku) => {
      const cached = normalizeData(loadData(sku) || (state.index || []).find((item) => item && item.sku === sku) || {});
      const isManual = Boolean(cached.skuListSource === 'manual-code' || cached.manualSkuAddedAt || cached.manualSkuAddedAtMs);
      const projectStatus = compactText(cached.projectStatus || '');
      const route = {
        projectStatus: isManual ? '' : projectStatus,
        projectRowId: String(cached.projectRowId || cached.projectId || ''),
        completed: isManual || /已完成/.test(projectStatus),
      };
      routes.set(sku, route);
      if (isManual) {
        updateToyCopywritingBatchEntry(sku, {
          projectStatus: '',
          projectRowId: '',
          step: '手动添加 SKU，准备从商品管理打开',
        });
      } else {
        projectSkus.push(sku);
      }
    });
    if (!projectSkus.length) return routes;
    if (!(await ensureNewProductProjectPage())) throw new Error('未能进入新品开发页面读取项目状态');
    if (!(await ensureProjectAllTab())) throw new Error('未能切换到新品开发「全部」页签读取项目状态');
    const input = findInputByPlaceholder('搜索商品编码');
    const button = findButtonByText('查询');
    if (!input || !button) throw new Error('未找到新品开发「全部」页签的商品编码搜索框');
    updateToyCopywritingBatchEntry(projectSkus[0], { step: '正在新品开发「全部」中批量读取项目状态' });
    setNativeInputValue(input, projectSkus.join(' '));
    clickElement(button);
    const loaded = await waitFor(() => {
      if (isProjectResultLoading()) return '';
      const rows = collectProjectAllListRows().filter((row) => projectSkus.includes(row.sku));
      return rows.length || hasProjectResultEmptyState() ? rows : '';
    }, 20000, 180);
    if (!loaded && !hasProjectResultEmptyState()) throw new Error('新品开发「全部」项目状态加载超时');
    await expandProjectResultPageSize(projectSkus.length);
    await wait(350);
    const rowMap = new Map(collectProjectAllListRows().filter((row) => projectSkus.includes(row.sku)).map((row) => [row.sku, row]));
    projectSkus.forEach((sku) => {
      const row = rowMap.get(sku);
      const cached = normalizeData(loadData(sku) || {});
      const projectStatus = compactText(row && row.projectStatus || cached.projectStatus || '');
      const route = {
        projectStatus,
        projectRowId: row && row.rowId || cached.projectRowId || '',
        completed: /已完成/.test(projectStatus),
      };
      routes.set(sku, route);
      updateToyCopywritingBatchEntry(sku, {
        projectStatus,
        projectRowId: route.projectRowId || undefined,
        step: route.completed ? '项目已完成，准备从商品管理打开' : '项目未完成，准备从设计任务打开',
      });
    });
    return routes;
  }

  function getToyImageSectionState(drawer, label) {
    if (!drawer) return null;
    const expectedLabel = compactText(label);
    const expectedButton = compactText('AI一键生成');
    const buttons = Array.from(drawer.querySelectorAll('button, a, [role="button"], span.startBtn'))
      .filter(isVisibleElement)
      .filter((button) => compactText(button.innerText || button.textContent) === expectedButton);
    for (const button of buttons) {
      let current = button.parentElement;
      for (let depth = 0; current && current !== drawer && depth < 10; depth += 1, current = current.parentElement) {
        const text = compactText(getVisibleText(current));
        if (!text.includes(expectedLabel)) continue;
        const media = Array.from(current.querySelectorAll('img'))
          .map((img) => img.currentSrc || img.src || img.alt || 'img')
          .join('|');
        return {
          button,
          signature: [text, media, button.className || '', button.disabled ? 'disabled' : 'ready'].join('|'),
        };
      }
    }
    return null;
  }

  function isToyImageButtonBusy(button) {
    if (!button) return false;
    const text = compactText(button.innerText || button.textContent);
    const className = String(button.className || '');
    const html = String(button.innerHTML || '');
    return Boolean(
      button.disabled
      || button.getAttribute('aria-disabled') === 'true'
      || button.getAttribute('aria-busy') === 'true'
      || /\bloading\b|ant-btn-loading|ant-btn-disabled|ant-spin/.test(className + ' ' + html)
      || button.querySelector('.ant-spin, [aria-busy="true"]')
      || /生成中|处理中|上传中|排队中/.test(text)
    );
  }

  async function clickToyImageAiGenerate(drawer, sku, label) {
    const currentDrawer = getToyCopywritingDrawerForSku(sku) || drawer;
    if (isToyImageAlreadyGenerated(currentDrawer, label)) return false;
    const before = getToyImageSectionState(currentDrawer, label);
    if (!before || !before.button) throw new Error('未找到' + label + '的 AI一键生成按钮');
    if (!isActionButtonReady(before.button)) throw new Error(label + ' AI一键生成按钮不可用');
    const beforeText = compactText(before.button.innerText || before.button.textContent);
    clickElement(before.button);
    const started = await waitFor(() => {
      const liveDrawer = getToyCopywritingDrawerForSku(sku) || drawer;
      const current = getToyImageSectionState(liveDrawer, label);
      if (!current) {
        const buttonText = compactText(before.button.innerText || before.button.textContent);
        return !document.body.contains(before.button) || !isVisibleElement(before.button) || buttonText !== beforeText ? before : '';
      }
      return isToyImageButtonBusy(current.button) || current.signature !== before.signature ? current : '';
    }, 5000, 100);
    if (!started) throw new Error(label + ' AI一键生成未进入加载态');
    return true;
  }

  async function generateToyImagesForBatch(drawer, sku) {
    let triggered = 0;
    let completed = 0;
    for (const label of ['主图', '详情图']) {
      const currentDrawer = getToyCopywritingDrawerForSku(sku) || drawer;
      if (isToyImageAlreadyGenerated(currentDrawer, label)) {
        updateToyCopywritingBatchEntry(sku, { step: label + '已生成，继续检查下一项' });
        completed += 1;
        continue;
      }
      updateToyCopywritingBatchEntry(sku, { step: '正在点击' + label + ' AI一键生成' });
      if (await clickToyImageAiGenerate(currentDrawer, sku, label)) triggered += 1;
      completed += 1;
    }
    return { triggered, completed };
  }

  function getToyGeneratedImageSection(drawer, label) {
    if (!drawer) return null;
    const expected = compactText(label);
    return Array.from(drawer.querySelectorAll('.ant-form-item'))
      .filter(isVisibleElement)
      .find((item) => {
        const labelNode = item.querySelector('.ant-form-item-label, label');
        const text = compactText(labelNode && (labelNode.innerText || labelNode.textContent)).replace(/[*：:]/g, '');
        return text.startsWith(expected) && /已生成|点击查看|AI(?:一键|重新)生成/.test(getVisibleText(item));
      }) || null;
  }

  function isToyImageAlreadyGenerated(drawer, label) {
    const section = getToyGeneratedImageSection(drawer, label);
    return Boolean(
      section
      && getVisibleText(section).includes('已生成')
      && findToyGeneratedImageAction(section, '点击查看')
    );
  }

  function findToyGeneratedImageAction(scope, text) {
    if (!scope) return null;
    const expected = compactText(text).replace(/\s+/g, '');
    return Array.from(scope.querySelectorAll('button, a, [role="button"], span'))
      .filter(isVisibleElement)
      .filter(isActionButtonReady)
      .find((element) => compactText(element.innerText || element.textContent).replace(/\s+/g, '') === expected) || null;
  }

  function getToyImagePreviewContainer() {
    const applyActions = Array.from(document.querySelectorAll('button, a, [role="button"], span'))
      .filter(isVisibleElement)
      .filter((element) => compactText(element.innerText || element.textContent).replace(/\s+/g, '') === '全部应用');
    for (const action of applyActions) {
      const modal = action.closest('.ant-modal, .ant-drawer-open, [role="dialog"], .ant-image-preview-wrap');
      if (modal && getVisibleText(modal).includes('下载图片')) return modal;
      let fallback = null;
      let current = action.parentElement;
      for (let depth = 0; current && current !== document.body && depth < 14; depth += 1, current = current.parentElement) {
        const text = getVisibleText(current);
        if (!text.includes('下载图片') || !text.includes('全部应用')) continue;
        fallback = current;
        if (findDrawerCloseButton(current)) return current;
      }
      if (fallback) return fallback;
    }
    return null;
  }

  async function closeToyImagePreviewIfPresent() {
    const preview = getToyImagePreviewContainer();
    if (!preview) return true;
    const close = findDrawerCloseButton(preview)
      || findToyGeneratedImageAction(preview, '关闭');
    if (!close) throw new Error('未找到生成图片预览关闭按钮');
    clickElement(close);
    return Boolean(await waitFor(() => {
      return !document.body.contains(preview) || !isVisibleElement(preview) || !getToyImagePreviewContainer();
    }, 10000, 100));
  }

  async function applyToyGeneratedImage(drawer, sku, label, options) {
    const opts = options || {};
    const section = await waitFor(() => {
      const liveDrawer = getToyCopywritingDrawerForSku(sku) || drawer;
      const current = getToyGeneratedImageSection(liveDrawer, label);
      return current && findToyGeneratedImageAction(current, '点击查看') ? current : null;
    }, 300000, 1000);
    if (!section) throw new Error(label + '等待生成完成超时');
    const view = findToyGeneratedImageAction(section, '点击查看');
    if (!view) throw new Error(label + '未找到「点击查看」');
    clickElement(view);
    const preview = await waitFor(() => getToyImagePreviewContainer(), 15000, 150);
    if (!preview) throw new Error(label + '生成图片预览未打开');

    const download = findToyGeneratedImageAction(preview, '下载图片');
    if (!download) throw new Error(label + '未找到「下载图片」');
    clickElement(download);
    const directUse = await waitFor(() => findToyGeneratedImageAction(document.body, '直接使用'), 2500, 100);
    if (directUse) {
      clickElement(directUse);
      const submitDownload = await waitFor(() => findToyGeneratedImageAction(document.body, '提交并下载'), 5000, 100);
      if (!submitDownload) throw new Error(label + '评价后未找到「提交并下载」');
      clickElement(submitDownload);
      const downloadSubmitted = await waitFor(() => {
        return !findToyGeneratedImageAction(document.body, '提交并下载');
      }, 15000, 100);
      if (!downloadSubmitted) throw new Error(label + '「提交并下载」未完成');
    }

    const livePreview = await waitFor(() => getToyImagePreviewContainer(), 10000, 100);
    if (!livePreview) throw new Error(label + '下载后图片预览已意外关闭');
    if (opts.skipApply) {
      if (!(await closeToyImagePreviewIfPresent())) throw new Error(label + '图片预览未关闭');
      return true;
    }
    const applyAll = findToyGeneratedImageAction(livePreview, '全部应用');
    if (!applyAll) throw new Error(label + '未找到「全部应用」');
    await waitFor(() => !/应用成功/.test(getPlmNoticeText()), 5000, 100);
    clickElement(applyAll);
    const applied = await waitFor(() => /应用成功/.test(getPlmNoticeText()), 45000, 100);
    if (!applied) throw new Error(label + '点击全部应用后未收到「应用成功」');
    if (!(await closeToyImagePreviewIfPresent())) throw new Error(label + '图片预览未关闭');
    return true;
  }

  function isToyCopywritingDownloadOnlyMode(mode) {
    return mode === 'download' || mode === 'download-review';
  }

  function ensureToyCopywritingLedgerRecord(sku, entry, dateKey) {
    const normalizedSku = String(sku || '').trim().toUpperCase();
    const normalizedDate = normalizeLedgerDate(dateKey) || getTodayKey();
    const existing = findLedgerRecord(normalizedSku, normalizedDate);
    if (existing) return existing;
    const cached = normalizeData(loadData(normalizedSku) || { sku: normalizedSku });
    const data = {
      ...cached,
      sku: normalizedSku,
      name: cached.name || String(entry && entry.name || '').trim(),
    };
    return upsertDailyLedgerFromData(data, { date: normalizedDate, isToy: true });
  }

  async function queryToyGeneratedImagesForDownload(sku, entry) {
    const normalizedSku = String(sku || '').trim().toUpperCase();
    const dateKey = getTodayKey();
    ensureToyCopywritingLedgerRecord(normalizedSku, entry, dateKey);
    for (let attempt = 0; attempt < LEDGER_AI_IMAGE_MAX_POLLS; attempt += 1) {
      const result = await queryLedgerAiImageStatus(normalizedSku, dateKey, {
        openViewer: false,
        reopenViewerOnUpdate: false,
        poll: false,
      });
      const record = findLedgerRecord(normalizedSku, dateKey);
      const status = normalizeLedgerAiImageStatus(record && record.aiImageStatus, record && record.aiImageMessage);
      const mainCount = normalizeLedgerAiImageItems(record && record.aiMainImages, 12).length;
      const detailCount = normalizeLedgerAiImageItems(record && record.aiDetailImages, 20).length;
      if (status === 'success' && (mainCount || detailCount)) return record;
      if (['error', 'task-error', 'result-missing', 'empty', 'needs-copywriting', 'needs-sku-image', 'needs-prerequisites'].includes(status)) {
        const message = String(record && record.aiImageMessage || (result && result.aiImageMessage) || '未返回可下载的生图结果').trim();
        throw new Error('生图后台查询失败：' + message);
      }
      updateToyCopywritingBatchEntry(normalizedSku, { step: '后台查询生图结果中（第 ' + (attempt + 1) + ' 次）' });
      state.toyCopywritingBatchStatus = normalizedSku + '：后台查询生图结果中（第 ' + (attempt + 1) + ' 次）';
      renderShell();
      if (attempt + 1 < LEDGER_AI_IMAGE_MAX_POLLS) await wait(LEDGER_AI_IMAGE_POLL_DELAY_MS);
    }
    throw new Error('生图后台查询超时，暂未返回主图和详情图');
  }

  async function downloadToyGeneratedImagesForBatch(sku, entry) {
    const normalizedSku = String(sku || '').trim().toUpperCase();
    const dateKey = getTodayKey();
    updateToyCopywritingBatchEntry(normalizedSku, { step: '正在通过后台服务查询已生成图片' });
    state.toyCopywritingBatchStatus = normalizedSku + '：正在通过后台服务查询已生成图片';
    renderShell();
    const record = await queryToyGeneratedImagesForDownload(normalizedSku, entry);
    const downloadKinds = [
      { kind: 'main', label: '主图', count: normalizeLedgerAiImageItems(record.aiMainImages, 12).length },
      { kind: 'detail', label: '详情图', count: normalizeLedgerAiImageItems(record.aiDetailImages, 20).length },
    ];
    const missing = downloadKinds.filter((item) => !item.count).map((item) => item.label);
    if (missing.length) throw new Error('生图后台未返回' + missing.join('、') + '，无法完成全部下载');
    for (const item of downloadKinds) {
      updateToyCopywritingBatchEntry(normalizedSku, { step: '正在下载全部' + item.label + '（' + item.count + ' 张）' });
      state.toyCopywritingBatchStatus = normalizedSku + '：正在下载全部' + item.label + '（' + item.count + ' 张）';
      renderShell();
      if (!(await downloadLedgerAiImageZip(normalizedSku, dateKey, item.kind))) {
        throw new Error('下载全部' + item.label + '失败');
      }
    }
    return downloadKinds;
  }

  async function startToyCopywritingApplyBatch(options) {
    const opts = options || {};
    const skipApply = Boolean(opts.skipApply);
    const actionLabel = skipApply ? '批量下载生成图片' : '批量全部应用并提审';
    const applyMode = skipApply ? 'download' : 'apply';
    if (state.toyCopywritingBatchRunning || state.toyCopywritingApplyRunning) return;
    state.toyCopywritingBatchQueue = loadToyCopywritingBatchQueue();
    const eligible = state.toyCopywritingBatchQueue.filter((entry) => {
      return (entry.status === 'success' || entry.status === 'noop') && entry.applyStatus !== 'submitted';
    });
    if (!eligible.length) {
      state.toyCopywritingBatchStatus = '没有等待' + actionLabel + '的已完成产品';
      renderShell();
      return;
    }
    state.toyCopywritingApplyRunning = true;
    state.toyCopywritingApplyMode = applyMode;
    state.toyCopywritingBatchStatus = '开始' + actionLabel;
    renderShell();
    let routeMap = new Map();
    if (!skipApply) {
      try {
        routeMap = await prepareToyCopywritingBatchRoutes(eligible);
      } catch (error) {
        state.toyCopywritingApplyRunning = false;
        state.toyCopywritingApplyMode = '';
        state.toyCopywritingBatchStatus = actionLabel + '前读取项目状态失败：' + formatErrorMessage(error);
        addLog('error', '玩具生成图片：读取项目状态失败', formatErrorMessage(error));
        renderShell();
        return;
      }
    }
    for (const entry of eligible) {
      const sku = entry.sku;
      let drawer = null;
      state.toyCopywritingApplyCurrentSku = sku;
      updateToyCopywritingBatchEntry(sku, { applyStatus: 'applying', applyMode, applyError: '', step: '正在打开设计资料' });
      state.toyCopywritingBatchStatus = sku + '：正在打开设计资料';
      renderShell();
      try {
        const cached = normalizeData(loadData(sku) || (state.index || []).find((item) => item.sku === sku) || { sku });
        if (skipApply) {
          await downloadToyGeneratedImagesForBatch(sku, cached);
          updateToyCopywritingBatchEntry(sku, {
            applyStatus: 'downloaded',
            applyMode: 'download',
            applyError: '',
            step: '主图和详情图已下载（未全部应用，未提审）',
          });
          addLog('success', '玩具生成图片下载成功（未提审）', sku);
        } else {
          drawer = await openToyCopywritingBatchDrawer(sku, cached, routeMap.get(sku));
          for (const label of ['主图', '详情图']) {
            updateToyCopywritingBatchEntry(sku, { step: '正在处理' + label + '生成图片' });
            state.toyCopywritingBatchStatus = sku + '：正在下载' + label + '并全部应用';
            renderShell();
            await applyToyGeneratedImage(drawer, sku, label, { skipApply: false });
          }
          updateToyCopywritingBatchEntry(sku, { applyStatus: 'applied', applyMode, step: '主图和详情图已全部应用，正在提审' });
          state.toyCopywritingBatchStatus = sku + '：正在提审';
          renderShell();
          await submitProductReview();
          await closeTopProductDrawer({ skipDraftSave: true, allowReviewResultModal: true });
          updateToyCopywritingBatchEntry(sku, {
            applyStatus: 'submitted',
            applyMode,
            applyError: '',
            step: '主图和详情图已全部应用并提审',
          });
          addLog('success', '玩具生成图片' + actionLabel + '成功', sku);
        }
      } catch (error) {
        const message = formatErrorMessage(error) || actionLabel + '失败';
        updateToyCopywritingBatchEntry(sku, { applyStatus: 'error', applyMode, applyError: message, step: actionLabel + '失败' });
        addLog('error', '玩具生成图片' + actionLabel + '失败', sku + ' | ' + message);
        await closeToyImagePreviewIfPresent().catch(() => {});
        await closeToyCopywritingDrawerForSku(sku).catch(() => {});
      } finally {
        state.toyCopywritingApplyCurrentSku = '';
        state.toyCopywritingBatchStatus = '已处理 ' + sku + '，继续下一个编码';
        renderShell();
      }
    }
    state.toyCopywritingApplyRunning = false;
    state.toyCopywritingApplyCurrentSku = '';
    state.toyCopywritingApplyMode = '';
    state.toyCopywritingBatchStatus = actionLabel + '完成';
    renderShell();
    showToast(actionLabel + '完成');
  }

  async function openToyCopywritingBatchDrawer(sku, seed, route) {
    const existingCopywritingDrawer = getToyCopywritingDrawerForSku(sku);
    if (existingCopywritingDrawer) return existingCopywritingDrawer;
    const existingEditDrawer = getProductEditDrawerForSku(sku);
    if (existingEditDrawer) {
      updateToyCopywritingBatchEntry(sku, { step: '正在进入玩具文案编辑页' });
      return ensureToyCopywritingDrawerFromProductEdit(sku);
    }
    const currentDrawer = getToyCopywritingDrawerForSku('') || getProjectDrawer();
    const currentSku = currentDrawer && getProjectDrawerHeaderSku(currentDrawer);
    if (currentDrawer && currentSku !== sku) await closeToyCopywritingDrawerForSku(currentSku).catch(() => {});
    const openFromProductManagement = async (step) => {
      updateToyCopywritingBatchEntry(sku, { step: step || '项目未找到设计任务编辑入口，正在商品管理中搜索编码' });
      await ensureProductManagementPageInPlace();
      await searchProductManagementSku(sku);
      await openProductEditDrawer(sku);
      return ensureToyCopywritingDrawerFromProductEdit(sku);
    };
    if (route && route.completed) {
      return openFromProductManagement('项目已完成，正在商品管理中搜索编码');
    }
    if (!(await ensureNewProductProjectPage())) {
      addLog('info', '批量玩具文案：未能打开新品开发，改用商品管理', sku);
      return openFromProductManagement('新品开发不可用，正在商品管理中搜索编码');
    }
    if (!(await ensureDesignTaskTab())) {
      addLog('info', '批量玩具文案：未能进入设计任务，改用商品管理', sku);
      return openFromProductManagement('设计任务不可用，正在商品管理中搜索编码');
    }
    let rowId = route && route.projectRowId || seed && (seed.projectRowId || seed.projectId) || '';
    if (!rowId || !findOperationButtonByRowId(rowId, '编辑')) rowId = await queryDesignTaskRowIdBySku(sku);
    if (!rowId) {
      addLog('info', '批量玩具文案：设计任务未找到编辑入口，改用商品管理', sku);
      return openFromProductManagement();
    }
    if (!(await clickProjectEditByRowId(rowId, sku))) {
      addLog('info', '批量玩具文案：设计任务编辑抽屉未打开，改用商品管理', sku);
      await closeToyCopywritingDrawerForSku(sku).catch(() => {});
      return openFromProductManagement();
    }
    cacheProjectRowId(sku, rowId);
    const drawer = await waitFor(() => getToyCopywritingDrawerForSku(sku), 15000, 150);
    if (!drawer) throw new Error('编辑抽屉未加载');
    updateToyCopywritingBatchEntry(sku, { step: '正在进入玩具文案编辑页' });
    return advanceToyCopywritingDrawerToFields(drawer, sku);
  }

  async function ensureToyCopywritingDrawerFromProductEdit(sku) {
    let drawer = await waitFor(() => getToyCopywritingDrawerForSku(sku), 8000, 150);
    if (!drawer) {
      await enterProductEditSecondStep(sku);
      drawer = await waitFor(() => getToyCopywritingDrawerForSku(sku), 30000, 150);
    }
    if (!drawer) throw new Error('商品管理编辑页未加载出玩具文案字段');
    return advanceToyCopywritingDrawerToFields(drawer, sku);
  }

  function convertCmInputToInches(value) {
    const numbers = String(value || '').match(/-?\d+(?:\.\d+)?/g) || [];
    if (!numbers.length) return '';
    return numbers.map((item) => formatToolNumber(Number(item) * CM_TO_INCH)).join(' × ') + ' inch';
  }

  function formatToolNumber(value) {
    if (!Number.isFinite(value)) return '';
    return value.toFixed(2);
  }

  function extractSearchCodes(value) {
    const text = String(value || '').replace(/^\s*ext:zip\|ext:xlsx\s*/i, '');
    const matched = text.match(/\b(?:SKU|MTL)\d+\b/gi);
    const raw = matched && matched.length ? matched : text.split(/[\s,，;；、|/\\]+/).filter(Boolean);
    const seen = new Set();
    return raw.map((item) => String(item).trim().toUpperCase()).filter((item) => {
      if (!item || seen.has(item)) return false;
      seen.add(item);
      return true;
    });
  }

  function formatSearchCodes(value) {
    const codes = extractSearchCodes(value);
    return codes.length ? 'ext:zip|ext:xlsx ' + codes.join('|') : '';
  }

  function getActiveSizeImageData() {
    const source = state.sizeImageCustomData || state.data || (state.selectedSku ? loadData(state.selectedSku) : null);
    return source ? normalizeData(source) : null;
  }

  function getActiveSizeImageSku() {
    const data = getActiveSizeImageData();
    return data && data.sku ? String(data.sku) : '';
  }

  function formatSizeImageCustomDimensionText(value, fallbackNums) {
    const text = String(value || '').trim();
    if (text) return text;
    const nums = Array.isArray(fallbackNums) ? fallbackNums.map(Number).filter((item) => Number.isFinite(item) && item > 0) : [];
    return nums.length ? nums.map(formatSizeImageNumber).join(' × ') + ' cm' : '';
  }

  function getSizeImageCustomDraft(data) {
    const source = data && data.sku ? data : {};
    const sku = source.sku || '';
    const session = sku ? ensureSizeImageSession(sku) : null;
    const remarks = getSizeImageRemarks(source);
    const labelSpecs = getLabelSizeImageSpecs(source);
    const firstLabel = labelSpecs[0] || null;
    const customFlatKind = source.sizeImageCustomFlatKind === 'label' || source.sizeImageCustomFlatKind === 'print'
      ? source.sizeImageCustomFlatKind
      : (firstLabel && firstLabel.kind === 'label' ? 'label' : 'print');
    return {
      sku,
      brand: source.brand || '',
      name: source.name || '',
      packageTitle: source.sizeImageCustomPackageTitle || source.packageSizeLabel || '纸盒',
      packageSizeText: formatSizeImageCustomDimensionText(source.packageSizeText, source.packageNums),
      packageCode: source.packageCode || '',
      flatKind: customFlatKind,
      flatTitle: source.sizeImageCustomFlatTitle || source.printSizeLabel || (customFlatKind === 'label' ? '标签' : '印刷'),
      flatSizeText: source.printSizeText || '',
      flatCode: source.printCode || '',
      cartonRemark: source.sizeImageCustomCartonRemark || (session && session.cartonRemarkText) || remarks.carton || '',
      flatRemark: source.sizeImageCustomFlatRemark || (session && firstLabel && session.labelRemarkTexts[firstLabel.key]) || remarks.label || '',
      includeRemark: !session || session.includeRemark !== false,
      includeRoundArc: !session || session.includeRoundArc !== false,
      includeBatchNumber: !session || session.includeBatchNumber !== false,
    };
  }

  function sizeImageCustomInput(key, label, value, placeholder, wide) {
    return '<label class="pfh-size-image-custom-field' + (wide ? ' is-wide' : '') + '"><span>' + escapeHtml(label) + '</span><input type="text" data-size-image-custom-key="' + escapeHtml(key) + '" value="' + escapeHtml(value || '') + '" placeholder="' + escapeHtml(placeholder || '') + '"></label>';
  }

  function sizeImageCustomModalHtml() {
    if (!state.sizeImageCustomOpen) return '';
    const draft = state.sizeImageCustomDraft || getSizeImageCustomDraft(getActiveSizeImageData());
    const selectedLabel = draft.flatKind === 'label' ? ' selected' : '';
    const selectedPrint = draft.flatKind === 'print' ? ' selected' : '';
    return '<div class="pfh-size-image-custom-layer" data-action="size-image-custom-close">' +
      '<div class="pfh-size-image-custom-modal" role="dialog" aria-modal="true" aria-label="自定义尺寸图">' +
        '<div class="pfh-size-image-custom-head"><div><h3>自定义尺寸图</h3><p>不依赖 PLM 缓存，填写后上传底图即可生成尺寸图。</p></div><button type="button" class="pfh-size-image-custom-close" data-action="size-image-custom-close" aria-label="关闭">×</button></div>' +
        '<div class="pfh-size-image-custom-form">' +
          '<section class="pfh-size-image-custom-section"><strong class="pfh-size-image-custom-section-title">基础信息</strong><div class="pfh-size-image-custom-grid">' +
            sizeImageCustomInput('sku', 'SKU（必填）', draft.sku, '例如 SKU00050446') +
            sizeImageCustomInput('brand', '品牌', draft.brand, '可不填') +
            sizeImageCustomInput('name', '商品名称', draft.name, '可不填', true) +
          '</div></section>' +
          '<section class="pfh-size-image-custom-section"><strong class="pfh-size-image-custom-section-title">纸盒信息</strong><div class="pfh-size-image-custom-grid">' +
            sizeImageCustomInput('packageTitle', '纸盒标题', draft.packageTitle, '纸盒') +
            sizeImageCustomInput('packageCode', '纸盒物料编码', draft.packageCode, '可不填') +
            sizeImageCustomInput('packageSizeText', '纸盒尺寸（长×宽×高）', draft.packageSizeText, '例如 5.2×5.2×4.6cm', true) +
          '</div><p class="pfh-size-image-custom-hint">支持 3 个尺寸；多页纸盒可填写 5 个尺寸，例如 5.2×5.2×4.6×5.2×5.2cm。纸盒尺寸可留空，只生成标签/印刷图。</p></section>' +
          '<section class="pfh-size-image-custom-section"><strong class="pfh-size-image-custom-section-title">标签 / 印刷信息</strong><div class="pfh-size-image-custom-grid">' +
            '<label class="pfh-size-image-custom-field"><span>平面图类型</span><select data-size-image-custom-key="flatKind"><option value="label"' + selectedLabel + '>标签</option><option value="print"' + selectedPrint + '>印刷</option></select></label>' +
            sizeImageCustomInput('flatTitle', '标签 / 印刷标题', draft.flatTitle, '例如 标签、印刷') +
            sizeImageCustomInput('flatCode', '标签 / 印刷物料编码', draft.flatCode, '可不填') +
            sizeImageCustomInput('flatSizeText', '平面图尺寸（宽×高）', draft.flatSizeText, '例如 10×2.3cm', true) +
          '</div><p class="pfh-size-image-custom-hint">可填写多个宽×高尺寸，用分号隔开；纸盒、标签、印刷至少填写一组有效尺寸。</p></section>' +
          '<section class="pfh-size-image-custom-section"><strong class="pfh-size-image-custom-section-title">标题备注与生成选项</strong><div class="pfh-size-image-custom-grid">' +
            sizeImageCustomInput('cartonRemark', '纸盒备注', draft.cartonRemark, '例如 多页、内卡') +
            sizeImageCustomInput('flatRemark', '标签 / 印刷备注', draft.flatRemark, '例如 透明、加粘') +
          '</div><div class="pfh-size-image-custom-checks"><label><input type="checkbox" data-size-image-custom-key="includeRemark"' + (draft.includeRemark ? ' checked' : '') + '>生成标题备注</label><label><input type="checkbox" data-size-image-custom-key="includeRoundArc"' + (draft.includeRoundArc ? ' checked' : '') + '>标签圆弧</label><label><input type="checkbox" data-size-image-custom-key="includeBatchNumber"' + (draft.includeBatchNumber ? ' checked' : '') + '>批次号</label></div></section>' +
        '</div>' +
        '<div class="pfh-size-image-custom-foot"><button type="button" class="is-secondary" data-action="size-image-custom-close">取消</button><button type="button" class="is-primary" data-action="size-image-custom-save">保存并继续</button></div>' +
      '</div>' +
    '</div>';
  }

  function openSizeImageCustomEditor() {
    state.sizeImageCustomDraft = getSizeImageCustomDraft(getActiveSizeImageData());
    state.sizeImageCustomOpen = true;
    expandPanel();
    renderShell();
    window.setTimeout(() => {
      const input = ensurePanel().querySelector('[data-size-image-custom-key="sku"]');
      if (input) input.focus();
    }, 0);
  }

  function closeSizeImageCustomEditor() {
    state.sizeImageCustomOpen = false;
    state.sizeImageCustomDraft = null;
    renderShell();
  }

  function readSizeImageCustomField(panel, key) {
    const input = panel && panel.querySelector('[data-size-image-custom-key="' + key + '"]');
    return input ? String(input.value || '').trim() : '';
  }

  function saveSizeImageCustomConfig() {
    const panel = ensurePanel();
    const sku = readSizeImageCustomField(panel, 'sku');
    const packageSizeText = readSizeImageCustomField(panel, 'packageSizeText');
    const flatSizeText = readSizeImageCustomField(panel, 'flatSizeText');
    const flatKind = readSizeImageCustomField(panel, 'flatKind') === 'label' ? 'label' : 'print';
    const packageTitle = readSizeImageCustomField(panel, 'packageTitle') || '纸盒';
    const flatTitle = readSizeImageCustomField(panel, 'flatTitle') || (flatKind === 'label' ? '标签' : '印刷');
    if (!sku) {
      showToast('请填写 SKU');
      const input = panel.querySelector('[data-size-image-custom-key="sku"]');
      if (input) input.focus();
      return;
    }
    const customData = normalizeData({
      sku,
      brand: readSizeImageCustomField(panel, 'brand'),
      name: readSizeImageCustomField(panel, 'name'),
      packageSizeLabel: packageTitle,
      packageSizeText,
      packageCode: readSizeImageCustomField(panel, 'packageCode'),
      printSizeLabel: flatTitle,
      printSizeText: flatSizeText,
      printRawText: flatTitle,
      printCode: readSizeImageCustomField(panel, 'flatCode'),
      materialDimensionUnitIssues: { package: null, print: null },
      isCustomSizeImage: true,
      sizeImageCustomFlatKind: flatKind,
      sizeImageCustomPackageTitle: packageTitle,
      sizeImageCustomFlatTitle: flatTitle,
      sizeImageCustomCartonRemark: readSizeImageCustomField(panel, 'cartonRemark'),
      sizeImageCustomFlatRemark: readSizeImageCustomField(panel, 'flatRemark'),
    });
    const cartonSpec = getSizeImageSpec(customData);
    const labelSpecs = getLabelSizeImageSpecs(customData);
    if (packageSizeText && !cartonSpec && !isPrintedBagPackageDimensionData(customData)) {
      showToast('纸盒尺寸格式不正确，请填写 3 个或 5 个数字');
      return;
    }
    if (flatSizeText && !labelSpecs.length) {
      showToast('标签 / 印刷尺寸格式不正确，请填写宽×高');
      return;
    }
    if (!cartonSpec && !labelSpecs.length) {
      showToast('纸盒或标签 / 印刷至少填写一组有效尺寸');
      return;
    }
    state.sizeImageCustomData = customData;
    state.sizeImageCustomDraft = null;
    state.sizeImageCustomOpen = false;
    delete state.sizeImageSessions[customData.sku];
    const session = ensureSizeImageSession(customData.sku);
    session.includeRemark = Boolean(panel.querySelector('[data-size-image-custom-key="includeRemark"]')?.checked);
    session.includeRoundArc = Boolean(panel.querySelector('[data-size-image-custom-key="includeRoundArc"]')?.checked);
    session.includeBatchNumber = Boolean(panel.querySelector('[data-size-image-custom-key="includeBatchNumber"]')?.checked);
    session.cartonRemarkText = customData.sizeImageCustomCartonRemark || '';
    if (labelSpecs[0]) session.labelRemarkTexts[labelSpecs[0].key] = customData.sizeImageCustomFlatRemark || '';
    state.view = 'sizeImage';
    state.copywritingMode = false;
    expandPanel();
    renderShell();
    showToast('自定义尺寸已保存，请上传纸盒或标签底图');
  }

  function sizeImageViewHtml() {
    const data = getActiveSizeImageData();
    if (!data || !data.sku) {
      return '<div class="pfh-detail-scroll pfh-size-image-scroll">' + detailViewTabsHtml('sizeImage') + '<section class="pfh-size-image-page"><div class="pfh-size-image-empty"><strong>选择一个 SKU 或自定义尺寸</strong><p>缓存中没有 SKU 时，也可以直接填写 SKU、尺寸、标题和备注，再上传底图生成尺寸图。</p><button type="button" class="pfh-size-image-custom-button" data-action="size-image-custom-open">自定义尺寸图</button></div></section>' + sizeImageCustomModalHtml() + '</div>';
    }
    const cartonSpec = getSizeImageSpec(data);
    const labelSpecs = getLabelSizeImageSpecs(data);
    const labelSpec = labelSpecs[0] || null;
    const session = ensureSizeImageSession(data.sku);
    migrateLegacySizeImageResult(session, labelSpec);
    const transparentLabel = hasTransparentSizeImageLabel(data, labelSpecs);
    if (transparentLabel) {
      session.includeRoundArc = false;
      session.includeBatchNumber = false;
    }
    const transparentOptionAttrs = transparentLabel ? ' disabled title="\u900f\u660e\u6807\u7b7e\u5df2\u81ea\u52a8\u53d6\u6d88\u8be5\u9009\u9879"' : '';
    const busy = state.sizeImageBusySku === data.sku;
    const cartonDimension = cartonSpec ? [cartonSpec.length, cartonSpec.width, cartonSpec.height].concat(cartonSpec.extraWidths || []).map(formatSizeImageNumber).join(' \u00d7 ') + ' cm' : '';
    const labelDimensions = labelSpecs.map((spec) => (spec.kind === 'print' ? '\u5370\u5237' : '\u6807\u7b7e') + ' ' + formatSizeImageNumber(spec.width) + ' \u00d7 ' + formatSizeImageNumber(spec.height) + ' cm');
    const dimensionText = [cartonDimension ? '\u7eb8\u76d2 ' + cartonDimension : ''].concat(labelDimensions).filter(Boolean).join(' / ') || '\u5c3a\u5bf8\u4e0d\u53ef\u7528';
    const flatResultCount = labelSpecs.filter((spec) => session.flatResults[spec.key] && session.flatResults[spec.key].dataUrl).length;
    const resultCount = Number(Boolean(session.cartonResultDataUrl)) + flatResultCount;
    const canRegenerate = Boolean(session.cartonFile || Object.keys(session.flatFiles).length);
    const status = busy
      ? '<div class="pfh-size-image-status is-processing"><i></i><span>' + escapeHtml(session.processingStep || '\u6b63\u5728\u8bfb\u53d6\u56fe\u7247...') + '</span><em></em></div>'
      : session.error
      ? '<div class="pfh-size-image-status is-error">' + escapeHtml(session.error) + '</div>'
      : (resultCount ? '<div class="pfh-size-image-status is-ready">\u5df2\u751f\u6210 ' + resultCount + ' \u4e2a 3000 \u00d7 3000 JPG\u3002</div>' : '');
    const previewCard = (type, url, detail) => {
      const label = type === 'label' ? '\u6807\u7b7e' : (type === 'print' ? '\u5370\u5237' : '\u7eb8\u76d2');
      return url
        ? '<div class="pfh-size-image-preview"><span class="pfh-size-image-preview-type">' + label + (detail ? ' ' + escapeHtml(detail) : '') + '\u9884\u89c8</span><img src="' + url + '" alt="' + escapeHtml(data.sku + ' ' + label + '\u5c3a\u5bf8\u56fe') + '"></div>'
        : '<div class="pfh-size-image-placeholder is-compact">' + iconHtml(type === 'carton' ? 'box' : 'tag') + '<strong>\u6682\u65e0' + label + (detail ? ' ' + escapeHtml(detail) : '') + '\u9884\u89c8</strong><span>\u53ef\u540c\u65f6\u62d6\u5165\u591a\u5f20\u56fe\u7247</span></div>';
    };
    const flatPreviews = labelSpecs.map((spec) => {
      const result = session.flatResults[spec.key];
      const detail = formatSizeImageNumber(spec.width) + '\u00d7' + formatSizeImageNumber(spec.height) + 'cm';
      return previewCard(spec.kind, result && result.dataUrl, detail);
    }).join('');
    const preview = '<div class="pfh-size-image-preview-grid">' + (cartonSpec ? previewCard('carton', session.cartonResultDataUrl) : '') + flatPreviews + '</div>';
    const disabled = (cartonSpec || labelSpec) && !busy ? '' : ' disabled';
    const remarks = getSizeImageRemarks(data);
    if (typeof session.cartonRemarkText !== 'string') session.cartonRemarkText = remarks.carton || '';
    labelSpecs.forEach((spec) => {
      if (typeof session.labelRemarkTexts[spec.key] !== 'string') session.labelRemarkTexts[spec.key] = spec.remark || remarks.label || '';
    });
    const remarkInputs = [
      cartonSpec ? '<label><span>\u7eb8\u76d2</span><input type="text" class="pfh-size-image-remark-text" data-size-image-type="carton" value="' + escapeHtml(session.cartonRemarkText) + '" placeholder="\u7eb8\u76d2\u6807\u9898\u5907\u6ce8"></label>' : '',
      ...labelSpecs.map((spec) => {
        const flatLabel = spec.kind === 'print' ? '\u5370\u5237' : '\u6807\u7b7e';
        const detail = formatSizeImageNumber(spec.width) + '\u00d7' + formatSizeImageNumber(spec.height);
        return '<label><span>' + flatLabel + ' ' + detail + '</span><input type="text" class="pfh-size-image-remark-text" data-size-image-type="label" data-size-image-key="' + escapeHtml(spec.key) + '" value="' + escapeHtml(session.labelRemarkTexts[spec.key]) + '" placeholder="' + flatLabel + '\u6807\u9898\u5907\u6ce8"></label>';
      }),
    ].filter(Boolean).join('');
    const pendingMatch = session.pendingLabelMatches.length ? '<div class="pfh-size-image-match-list"><strong>\u8bf7\u9009\u62e9\u56fe\u7247\u5bf9\u5e94\u7684\u5c3a\u5bf8</strong>' + session.pendingLabelMatches.map((pending) => '<div><span>' + escapeHtml(pending.file.name || '\u5f85\u5339\u914d\u56fe\u7247') + '</span><select class="pfh-size-image-match-select" data-pending-id="' + escapeHtml(pending.id) + '">' + labelSpecs.map((spec) => '<option value="' + escapeHtml(spec.key) + '">' + escapeHtml((spec.kind === 'print' ? '\u5370\u5237 ' : '\u6807\u7b7e ') + formatSizeImageNumber(spec.width) + ' \u00d7 ' + formatSizeImageNumber(spec.height) + ' cm') + '</option>').join('') + '</select><button type="button" data-action="size-image-confirm-match" data-pending-id="' + escapeHtml(pending.id) + '">\u786e\u8ba4\u751f\u6210</button></div>').join('') + '</div>' : '';
    return '<div class="pfh-detail-scroll pfh-size-image-scroll">' + detailViewTabsHtml('sizeImage') + '<section class="pfh-size-image-page">' +
      '<header class="pfh-size-image-hero"><div class="pfh-size-image-hero-media">' + productThumbHtml(data) + '</div><div class="pfh-size-image-hero-copy"><small>SIZE IMAGE</small><h3>' + escapeHtml(data.sku) + ' \u5c3a\u5bf8\u56fe</h3><p>' + escapeHtml([data.brand, data.name].filter(Boolean).join(' ') || (data.isCustomSizeImage ? '自定义数据' : '\u9009\u4e2d\u4ea7\u54c1')) + '</p></div><div class="pfh-size-image-hero-actions"><button type="button" class="pfh-size-image-custom-button" data-action="size-image-custom-open">自定义尺寸图</button></div></header>' +
      (!(cartonSpec || labelSpec) ? '<div class="pfh-size-image-status is-error">' + escapeHtml(getSizeImageSpecError(data)) + '</div>' : '') +
      '<div class="pfh-size-image-workspace' + (busy ? ' is-busy' : '') + '"><div class="pfh-size-image-controls">' +
        '<div class="pfh-size-image-spec"><span>\u5df2\u8bfb\u53d6\u89c4\u683c</span><b>' + escapeHtml(dimensionText) + '</b><small>\u7eb8\u76d2\u6309\u5200\u6a21\u8f6e\u5ed3\u8bc6\u522b\uff1b\u6807\u7b7e\u548c\u5370\u5237\u6309\u5bbd\u9ad8\u6bd4\u4f8b\u8bc6\u522b\u3002</small></div>' +
        '<div class="pfh-size-image-remark-editor"><span>\u6807\u9898\u5907\u6ce8</span><div>' + remarkInputs + '</div></div>' +
        '<div class="pfh-size-image-options">' + (labelSpecs.some((spec) => spec.kind === 'label') ? '<label><input type="checkbox" class="pfh-size-image-round-arc-input"' + (session.includeRoundArc === false ? '' : ' checked') + transparentOptionAttrs + '><span>\u6807\u7b7e\u5706\u5f27</span></label>' : '') + '<label><input type="checkbox" class="pfh-size-image-batch-number-input"' + (session.includeBatchNumber === false ? '' : ' checked') + transparentOptionAttrs + '><span>\u6279\u6b21\u53f7</span></label></div>' +
        '<button type="button" class="pfh-size-image-drop' + (busy ? ' is-processing' : '') + '" data-action="size-image-pick"' + disabled + '>' + (busy ? '<i class="pfh-loading-scan" aria-hidden="true"></i>' : iconHtml('upload')) + '<strong>' + (busy ? escapeHtml(session.processingStep || '\u6b63\u5728\u5206\u6790\u5e76\u751f\u6210...') : '\u70b9\u51fb\u9009\u62e9\u6216\u62d6\u5165\u56fe\u7247') + '</strong><span>' + (busy ? '\u8bf7\u7a0d\u5019\uff0c\u5927\u5c3a\u5bf8\u56fe\u7247\u9700\u8981\u51e0\u79d2\u5904\u7406\u65f6\u95f4\u3002' : '\u9f20\u6807\u505c\u5728\u8fd9\u91cc\u53ef\u76f4\u63a5 Ctrl+V \u7c98\u8d34\u56fe\u7247\u3002\u7eb8\u76d2\u7528\u900f\u660e PNG\uff0c\u6807\u7b7e/\u5370\u5237\u652f\u6301 PNG / JPG\u3002') + '</span></button>' +
        (session.fileName ? '<p class="pfh-size-image-file">\u6700\u8fd1\u8bfb\u53d6\uff1a' + escapeHtml(session.fileName) + '</p>' : '') +
        '<div class="pfh-size-image-actions"><button type="button" class="is-secondary" data-action="size-image-regenerate"' + (canRegenerate && !busy ? '' : ' disabled') + '>' + iconHtml('refresh') + '\u91cd\u65b0\u751f\u6210</button><button type="button" class="is-primary" data-action="size-image-save-all"' + (resultCount && !busy ? '' : ' disabled') + '>' + iconHtml('download') + '\u53e6\u5b58\u5c3a\u5bf8\u56fe JPG</button></div>' +
        pendingMatch + '<input type="file" class="pfh-size-image-file-input" accept="image/png,image/jpeg,.png,.jpg,.jpeg" multiple>' + status +
      '</div>' + preview + '</div>' +
    '</section>' + sizeImageCustomModalHtml() + '</div>';
  }

  function ensureSizeImageSession(sku) {
    if (!state.sizeImageSessions[sku]) state.sizeImageSessions[sku] = { includeRemark: true, includeRoundArc: true, includeBatchNumber: true };
    if (typeof state.sizeImageSessions[sku].includeRemark !== 'boolean') state.sizeImageSessions[sku].includeRemark = true;
    if (typeof state.sizeImageSessions[sku].includeRoundArc !== 'boolean') state.sizeImageSessions[sku].includeRoundArc = true;
    if (typeof state.sizeImageSessions[sku].includeBatchNumber !== 'boolean') state.sizeImageSessions[sku].includeBatchNumber = true;
    if (!state.sizeImageSessions[sku].flatResults || typeof state.sizeImageSessions[sku].flatResults !== 'object') state.sizeImageSessions[sku].flatResults = {};
    if (!state.sizeImageSessions[sku].flatFiles || typeof state.sizeImageSessions[sku].flatFiles !== 'object') state.sizeImageSessions[sku].flatFiles = {};
    if (!state.sizeImageSessions[sku].labelRemarkTexts || typeof state.sizeImageSessions[sku].labelRemarkTexts !== 'object') state.sizeImageSessions[sku].labelRemarkTexts = {};
    if (!Array.isArray(state.sizeImageSessions[sku].pendingLabelMatches)) state.sizeImageSessions[sku].pendingLabelMatches = [];
    return state.sizeImageSessions[sku];
  }

  function migrateLegacySizeImageResult(session, firstSpec) {
    if (!session || !firstSpec) return;
    if (session.labelResultDataUrl && !session.flatResults[firstSpec.key]) {
      session.flatResults[firstSpec.key] = { dataUrl: session.labelResultDataUrl, kind: session.labelResultKind || firstSpec.kind };
    }
    if (session.labelFile && !session.flatFiles[firstSpec.key]) session.flatFiles[firstSpec.key] = session.labelFile;
    if (typeof session.labelRemarkText === 'string' && typeof session.labelRemarkTexts[firstSpec.key] !== 'string') session.labelRemarkTexts[firstSpec.key] = session.labelRemarkText;
  }

  function getSizeImageSpec(data) {
    // A manually entered carton size may not have the derived material label.
    // The dimensions themselves are sufficient to identify the size-image input.
    if (!data || getMaterialDimensionUnitIssue(data, 'package') || isPrintedBagPackageDimensionData(data)) return null;
    const sourceNums = Array.isArray(data.packageNums) && data.packageNums.length
      ? data.packageNums
      : parseDimension(data.packageSizeText, 3);
    const nums = Array.isArray(sourceNums) ? sourceNums.map(Number) : [];
    if (![3, 5].includes(nums.length) || nums.some((value) => !Number.isFinite(value) || value <= 0)) return null;
    return { length: nums[0], width: nums[1], height: nums[2], extraWidths: nums.slice(3) };
  }

  function getSizeImageSpecError(data) {
    if (Array.isArray(data && data.packageNums) && data.packageNums.length > 3) return '\u591a\u9875\u7eb8\u76d2\u9700\u8981\u201c\u957f X \u5bbd X \u9ad8 X \u7b2c\u4e94\u9762\u5bbd X \u7b2c\u516d\u9762\u5bbd\u201d\u5171 5 \u4e2a\u5c3a\u5bf8\u3002';
    return '\u672a\u627e\u5230\u53ef\u7528\u7684\u7eb8\u76d2\u3001\u6807\u7b7e\u6216\u5370\u5237\u5c3a\u5bf8\uff0c\u8bf7\u5148\u5237\u65b0 PLM \u7f13\u5b58\u3002';
  }

  function isPrintedBagSizeImageData(data) {
    if (data && data.isPrintedBagOuterPackage) return true;
    const source = [
      data && data.printRawText,
      data && data.printSizeLabel,
      data && data.packageSizeLabel,
    ].filter(Boolean).join(' ');
    return /(?:\u5370\u5237\u81ea\u7acb\u888b|\u81ea\u7acb\u5370\u5237\u888b|\u81ea\u7acb\u888b|\u5370\u5237\u888b|\u5305\u88c5\u888b|\u94dd\u7b94\u888b|\u81ea\u5c01\u888b|\u8f6f\u888b|\u888b\u5b50|\u888b\/\u819c\u7c7b)/.test(source);
  }

  function isPrintedBagPackageDimensionData(data) {
    if (data && data.isPrintedBagOuterPackage) return true;
    const packageLabel = String(data && data.packageSizeLabel || '').trim();
    const printLabel = String(data && data.printSizeLabel || '').trim();
    const label = [packageLabel, printLabel].filter(Boolean).join(' ');
    if (!label) return false;
    if (/(?:\u7eb8\u76d2|\u5f69\u76d2|\u7eb8\u7bb1|\u5305\u88c5\u76d2|\u5916\u76d2)/.test(packageLabel)) return false;
    return /(?:\u5370\u5237\u81ea\u7acb\u888b|\u81ea\u7acb\u5370\u5237\u888b|\u81ea\u7acb\u888b|\u5370\u5237\u888b|\u5305\u88c5\u888b|\u94dd\u7b94\u888b|\u81ea\u5c01\u888b|\u888b\/\u819c\u7c7b|\u8f6f\u888b|\u888b\u5b50)/.test(label)
      && !/(?:\u7eb8\u76d2|\u5f69\u76d2|\u7eb8\u7bb1|\u5305\u88c5\u76d2|\u5916\u76d2)/.test(packageLabel);
  }

  function getPrintedBagFlatDimensionPair(data) {
    // Printed self-standing bags may be stored as width x gusset x height;
    // naming and flat-image matching use only the two visible dimensions.
    if (!data || !isPrintedBagSizeImageData(data)) return null;
    const sources = [data.printSizeText, data.packageSizeText, data.printRawText];
    const pattern = /\d+(?:\.\d+)?\s*[xX\u00d7*]\s*\d+(?:\.\d+)?(?:\s*[xX\u00d7*]\s*\d+(?:\.\d+)?){0,3}\s*(?:cm|mm)?/i;
    for (const source of sources) {
      const match = String(source || '').match(pattern);
      if (!match) continue;
      const numbers = (match[0].match(/\d+(?:\.\d+)?/g) || []).map(Number);
      if (numbers.length < 2) continue;
      const divisor = /mm/i.test(match[0]) ? 10 : 1;
      const pair = numbers.length >= 3 ? [numbers[0], numbers[2]] : [numbers[0], numbers[1]];
      const result = pair.map((value) => value / divisor);
      if (result.every((value) => Number.isFinite(value) && value > 0)) return result;
    }
    return null;
  }

  function getLabelSizeImageSpecs(data) {
    // printSizeLabel is derived from the PLM material name and may be absent
    // in older/manual cache records. A valid width x height is enough here.
    if (!data) return [];
    if (getMaterialDimensionUnitIssue(data, 'print')) return [];
    const labels = String(data.printSizeLabel || '').split(/\s*[\uff1b;]\s*/).filter(Boolean);
    const codes = String(data.printCode || '').split(/\s*[\uff1b;]\s*/).filter(Boolean);
    const printedBag = isPrintedBagSizeImageData(data);
    const rawPrintLabel = /\u6807\u7b7e/.test(String(data.printRawText || '')) ? '\u6807\u7b7e' : '';
    const dimensions = [];
    const printedBagPair = printedBag ? getPrintedBagFlatDimensionPair(data) : null;
    const pattern = /(\d+(?:\.\d+)?)\s*[xX\u00d7*]\s*(\d+(?:\.\d+)?)\s*(cm|mm)?/ig;
    if (printedBagPair) {
      dimensions.push({ width: printedBagPair[0], height: printedBagPair[1] });
    } else {
      let match;
      while ((match = pattern.exec(String(data.printSizeText || '')))) {
        const divisor = String(match[3] || '').toLowerCase() === 'mm' ? 10 : 1;
        const width = Number(match[1]) / divisor;
        const height = Number(match[2]) / divisor;
        if (Number.isFinite(width) && Number.isFinite(height) && width > 0 && height > 0) dimensions.push({ width, height });
      }
    }
    const fallbackLabel = labels[0] || rawPrintLabel || (printedBag ? compactText(data.packageSizeLabel || '\u5370\u5237\u81ea\u7acb\u888b') : '');
    const fallbackCode = codes[0] || (printedBag ? compactText(data.packageCode || '') : '');
    return dimensions.map((dimension, index) => {
      const labelText = labels[index] || fallbackLabel;
      const customKind = data.sizeImageCustomFlatKind === 'label' || data.sizeImageCustomFlatKind === 'print' ? data.sizeImageCustomFlatKind : '';
      const kind = customKind || (/\u6807\u7b7e/.test([labelText, data.printSizeLabel, data.printRawText].filter(Boolean).join(' ')) && !data.isTubePrint ? 'label' : 'print');
      return {
        width: dimension.width,
        height: dimension.height,
        kind,
        index,
        key: 'flat-' + index + '-' + formatSizeImageNumber(dimension.width) + 'x' + formatSizeImageNumber(dimension.height),
        code: codes[index] || fallbackCode,
        labelText,
        remark: collectSizeImageRemark(labelText, []),
        printedBag: kind === 'print' && printedBag,
      };
    });
  }

  function getLabelSizeImageSpec(data) {
    return getLabelSizeImageSpecs(data)[0] || null;
  }

  function isDoubleSidedPrintedBagSizeImage(spec, geometry) {
    return Boolean(spec && spec.kind === 'print' && spec.printedBag && geometry && Number(geometry.panelCount) > 1);
  }

  function collectSizeImageRemark(label, extra) {
    const values = [];
    const source = String(label || '');
    let match;
    const pattern = /[\uff08(]([^\uff09)]+)[\uff09)]/g;
    while ((match = pattern.exec(source))) {
      const value = cleanCopywritingLine(match[1]);
      if (value && !/\d+(?:\.\d+)?\s*[xX\u00d7*]/.test(value)) values.push(value);
    }
    ['\u5185\u5361', '\u900f\u660e', '\u52a0\u7c98'].forEach((keyword) => {
      if (!source.includes(keyword) || values.some((value) => value.includes(keyword))) return;
      const sourceIndex = source.indexOf(keyword);
      const insertAt = values.findIndex((value) => source.indexOf(value) > sourceIndex);
      if (insertAt >= 0) values.splice(insertAt, 0, keyword);
      else values.push(keyword);
    });
    (extra || []).forEach((value) => { if (value) values.push(value); });
    return Array.from(new Set(values)).join(' ');
  }

  function getSizeImageRemarks(data) {
    return {
      carton: (data && data.sizeImageCustomCartonRemark) || collectSizeImageRemark(data && data.packageSizeLabel, [data && data.hasInnerCard ? '\u5185\u5361' : '']),
      label: (data && data.sizeImageCustomFlatRemark) || collectSizeImageRemark(data && data.printSizeLabel, []),
    };
  }

  function isTransparentSizeImageLabel(data, spec) {
    if (!spec || spec.kind !== 'label') return false;
    const source = [
      data && data.printSizeLabel,
      data && data.printRawText,
      data && data.printSizeText,
      spec.labelText,
      spec.remark,
    ].filter(Boolean).join(' ');
    return /\u900f\u660e/.test(source) && !/(?:\u4e0d\u900f\u660e|\u975e\u900f\u660e)/.test(source);
  }

  function hasTransparentSizeImageLabel(data, specs) {
    return (Array.isArray(specs) ? specs : []).some((spec) => isTransparentSizeImageLabel(data, spec));
  }

  function formatSizeImageNumber(value) {
    return trimNumber(Number(value));
  }

  function yieldSizeImageUi() {
    return new Promise((resolve) => window.requestAnimationFrame(() => window.setTimeout(resolve, 0)));
  }

  function createSizeImageCanvas(width, height) {
    if (typeof document !== 'undefined' && document.createElement) {
      const canvas = document.createElement('canvas');
      canvas.width = width;
      canvas.height = height;
      return canvas;
    }
    if (typeof OffscreenCanvas === 'function') return new OffscreenCanvas(width, height);
    throw new Error('当前环境不支持 Canvas');
  }

  function getSizeImageSourceDimensions(image) {
    const width = Number(image && (image.naturalWidth || image.width));
    const height = Number(image && (image.naturalHeight || image.height));
    if (!(width > 0) || !(height > 0)) throw new Error('无法读取图片尺寸');
    return { width, height };
  }

  async function setSizeImageProcessingStep(session, text) {
    session.processingStep = text;
    const panel = document.getElementById(PANEL_ID);
    const strong = panel && panel.querySelector('.pfh-size-image-drop.is-processing strong');
    const status = panel && panel.querySelector('.pfh-size-image-status.is-processing span');
    if (strong) strong.textContent = text;
    if (status) status.textContent = text;
    await yieldSizeImageUi();
  }

  async function processSizeImageFile(file, preferredType, silent) {
    const data = getActiveSizeImageData();
    const cartonSpec = getSizeImageSpec(data);
    const labelSpecs = getLabelSizeImageSpecs(data);
    if (!data || !data.sku || !(cartonSpec || labelSpecs.length)) {
      showToast(data ? getSizeImageSpecError(data) : '\u8bf7\u5148\u9009\u62e9 SKU');
      return;
    }
    if (!file || !/\.(?:png|jpe?g)$/i.test(file.name || '') || (file.type && !/^image\/(?:png|jpeg)$/.test(file.type))) {
      const invalidSession = ensureSizeImageSession(data.sku);
      invalidSession.fileName = file && file.name || '';
      invalidSession.error = '\u8bf7\u9009\u62e9 PNG \u6216 JPG \u56fe\u7247\uff1b\u7eb8\u76d2\u5fc5\u987b\u4f7f\u7528\u900f\u660e PNG\u3002';
      renderShell();
      return;
    }
    const sku = data.sku;
    const session = ensureSizeImageSession(sku);
    migrateLegacySizeImageResult(session, labelSpecs[0]);
    state.sizeImageBusySku = sku;
    session.fileName = file.name;
    session.error = '';
    session.processingStep = '\u6b63\u5728\u8bfb\u53d6 ' + file.name;
    if (!silent) renderShell();
    if (!silent) await yieldSizeImageUi();
    const sourceUrl = URL.createObjectURL(file);
    try {
      await setSizeImageProcessingStep(session, '\u6b63\u5728\u8bc6\u522b\u7eb8\u76d2\u6216\u6807\u7b7e...');
      const preferredLabelKey = String(preferredType || '').startsWith('label:') ? String(preferredType).slice(6) : '';
      const productImageAsset = labelSpecs.some((spec) => spec.printedBag)
        ? await loadSizeImageProductImage(data)
        : null;
      const workerResult = await runSizeImageWorker(file, preferredType, cartonSpec, labelSpecs, data, session, productImageAsset && productImageAsset.dataUrl);
      if (workerResult) {
        if (workerResult.status === 'pending') {
          const pendingId = 'pending-' + Date.now() + '-' + Math.random().toString(36).slice(2, 7);
          session.pendingLabelMatches = session.pendingLabelMatches.filter((item) => item.file !== file);
          session.pendingLabelMatches.push({ id: pendingId, file });
          session.error = '';
          if (!silent) showToast('\u4e24\u4e2a\u5c3a\u5bf8\u6bd4\u4f8b\u592a\u63a5\u8fd1\uff0c\u8bf7\u624b\u52a8\u9009\u62e9\u5bf9\u5e94\u5c3a\u5bf8');
          return 'pending';
        }
        const workerMatchedLabelSpec = workerResult.detectedType === 'label'
          ? labelSpecs.find((spec) => spec.key === workerResult.matchedLabelKey) || null
          : null;
        if (workerResult.detectedType === 'label' && !workerMatchedLabelSpec) {
          throw new Error('\u9009\u62e9\u7684\u6807\u7b7e\u5c3a\u5bf8\u5df2\u5931\u6548\uff0c\u8bf7\u91cd\u65b0\u9009\u62e9\u3002');
        }
        await setSizeImageProcessingStep(session, '\u8bc6\u522b\u5b8c\u6210\uff0c\u6b63\u5728\u56de\u586b Worker \u751f\u6210\u7684 3000 \u00d7 3000 JPG...');
        if (workerResult.transparent) {
          session.includeRoundArc = false;
          session.includeBatchNumber = false;
        }
        if (workerResult.detectedType === 'carton') {
          session.cartonResultDataUrl = workerResult.dataUrl;
          session.cartonFile = file;
        } else {
          const spec = workerMatchedLabelSpec;
          session.flatResults[spec.key] = { dataUrl: workerResult.dataUrl, kind: spec.kind, code: spec.code };
          session.flatFiles[spec.key] = file;
          session.pendingLabelMatches = session.pendingLabelMatches.filter((item) => item.file !== file);
          if (labelSpecs.length === 1) {
            session.labelResultDataUrl = workerResult.dataUrl;
            session.labelResultKind = spec.kind;
            session.labelFile = file;
          }
        }
        session.error = '';
        if (!data.isCustomSizeImage) {
          if (workerResult.detectedType === 'carton') {
            updateDailyLedgerForSku(sku, { boxFileState: 'done', boxFileDone: true }, getTodayKey());
          } else {
            updateDailyLedgerForSku(sku, { labelFileState: 'done', labelFileDone: true }, getTodayKey());
          }
        }
        recordSizeImageUsage(true);
        if (!silent) showToast('\u5df2\u81ea\u52a8\u8bc6\u522b\u4e3a' + (workerResult.detectedType === 'carton' ? '\u7eb8\u76d2' : (workerMatchedLabelSpec.kind === 'print' ? '\u5370\u5237' : '\u6807\u7b7e')) + '\u5e76\u751f\u6210\u5c3a\u5bf8\u56fe');
        return true;
      }
      const image = await loadSizeImageSource(sourceUrl);
      let detectedType = preferredType === 'carton' ? 'carton' : (preferredType === 'label' || preferredLabelKey ? 'label' : '');
      let matchedLabelSpec = null;
      let geometry = null;
      let cartonError = null;
      if ((!detectedType || detectedType === 'carton') && cartonSpec && /\.png$/i.test(file.name || '')) {
        try {
          geometry = analyzeSizeImageGeometry(image, cartonSpec);
          detectedType = 'carton';
        } catch (error) {
          cartonError = error;
          if (preferredType === 'carton') throw error;
        }
      }
      if (!detectedType || detectedType === 'label') {
        if (!labelSpecs.length) throw cartonError || new Error('\u5f53\u524d SKU \u6ca1\u6709\u53ef\u7528\u7684\u6807\u7b7e\u5c3a\u5bf8\u3002');
        if (preferredLabelKey) {
          matchedLabelSpec = labelSpecs.find((spec) => spec.key === preferredLabelKey) || null;
          if (!matchedLabelSpec) throw new Error('\u9009\u62e9\u7684\u6807\u7b7e\u5c3a\u5bf8\u5df2\u5931\u6548\uff0c\u8bf7\u91cd\u65b0\u9009\u62e9\u3002');
          geometry = analyzeLabelSizeImageGeometry(image, matchedLabelSpec, true);
        } else {
          const matches = labelSpecs.map((spec) => {
            try {
              return { spec, geometry: analyzeLabelSizeImageGeometry(image, spec) };
            } catch (_) {
              return null;
            }
          }).filter(Boolean).sort((a, b) => a.geometry.matchDelta - b.geometry.matchDelta);
          if (!matches.length && labelSpecs.length === 1) throw new Error('\u56fe\u7247\u6bd4\u4f8b\u4e0e PLM \u4e2d\u7684\u6807\u7b7e\u6216\u5370\u5237\u5c3a\u5bf8\u4e0d\u5339\u914d\u3002');
          const first = matches[0];
          const second = matches[1];
          const confident = first && (!second || second.geometry.matchDelta - first.geometry.matchDelta >= 0.012);
          if (!confident) {
            const pendingId = 'pending-' + Date.now() + '-' + Math.random().toString(36).slice(2, 7);
            session.pendingLabelMatches = session.pendingLabelMatches.filter((item) => item.file !== file);
            session.pendingLabelMatches.push({ id: pendingId, file });
            session.error = '';
            if (!silent) showToast('\u4e24\u4e2a\u5c3a\u5bf8\u6bd4\u4f8b\u592a\u63a5\u8fd1\uff0c\u8bf7\u624b\u52a8\u9009\u62e9\u5bf9\u5e94\u5c3a\u5bf8');
            return 'pending';
          }
          matchedLabelSpec = first.spec;
          geometry = first.geometry;
        }
        detectedType = 'label';
      }
      await setSizeImageProcessingStep(session, '\u8bc6\u522b\u5b8c\u6210\uff0c\u6b63\u5728\u7ed8\u5236 3000 \u00d7 3000 JPG...');
      if (detectedType === 'label' && isTransparentSizeImageLabel(data, matchedLabelSpec)) {
        session.includeRoundArc = false;
        session.includeBatchNumber = false;
      }
      if (detectedType === 'carton') {
        session.cartonResultDataUrl = generateSizeImageJpeg(image, geometry, cartonSpec, data, session.includeRemark, session.includeRoundArc, session.cartonRemarkText);
        session.cartonFile = file;
      } else {
        const customRemark = session.labelRemarkTexts[matchedLabelSpec.key];
        const dataUrl = generateLabelSizeImageJpeg(
          image,
          geometry,
          matchedLabelSpec,
          data,
          session.includeRemark,
          session.includeRoundArc,
          session.includeBatchNumber,
          customRemark,
          productImageAsset && productImageAsset.image ? { productImage: productImageAsset.image } : undefined,
        );
        session.flatResults[matchedLabelSpec.key] = { dataUrl, kind: matchedLabelSpec.kind, code: matchedLabelSpec.code };
        session.flatFiles[matchedLabelSpec.key] = file;
        session.pendingLabelMatches = session.pendingLabelMatches.filter((item) => item.file !== file);
        if (labelSpecs.length === 1) {
          session.labelResultDataUrl = dataUrl;
          session.labelResultKind = matchedLabelSpec.kind;
          session.labelFile = file;
        }
      }
      session.error = '';
      if (!data.isCustomSizeImage) {
        if (detectedType === 'carton') {
          updateDailyLedgerForSku(sku, { boxFileState: 'done', boxFileDone: true }, getTodayKey());
        } else {
          updateDailyLedgerForSku(sku, { labelFileState: 'done', labelFileDone: true }, getTodayKey());
        }
      }
      recordSizeImageUsage(true);
      if (!silent) showToast('\u5df2\u81ea\u52a8\u8bc6\u522b\u4e3a' + (detectedType === 'carton' ? '\u7eb8\u76d2' : (matchedLabelSpec.kind === 'print' ? '\u5370\u5237' : '\u6807\u7b7e')) + '\u5e76\u751f\u6210\u5c3a\u5bf8\u56fe');
      return true;
    } catch (error) {
      session.error = formatSizeImageError(error);
      recordSizeImageUsage(false);
      return false;
    } finally {
      URL.revokeObjectURL(sourceUrl);
      if (!silent) {
        if (state.sizeImageBusySku === sku) state.sizeImageBusySku = '';
        session.processingStep = '';
        if (state.view === 'sizeImage') renderShell();
      }
    }
  }

  function loadSizeImageSource(url) {
    return new Promise((resolve, reject) => {
      const image = new Image();
      image.onload = () => resolve(image);
      image.onerror = () => reject(new Error('\u65e0\u6cd5\u8bfb\u53d6\u56fe\u7247\uff0c\u6587\u4ef6\u53ef\u80fd\u5df2\u635f\u574f\u3002'));
      image.src = url;
    });
  }

  async function loadSizeImageProductImage(data) {
    const source = getProductThumbUrl(data) || [
      data && data.skuImageUrl,
      data && data.skuImageFallbackUrl,
      data && data.productListImageUrl,
      data && data.productListImageFallbackUrl,
    ].map((value) => String(value || '').trim()).find((value) => value && !/^data:image\//i.test(value)) || '';
    if (!source) return null;
    const fallback = data && (
      data.skuImageFallbackUrl
      || data.productListImageFallbackUrl
      || data.skuImageUrl
      || data.productListImageUrl
      || source
    );
    try {
      const imageInfo = /^data:image\//i.test(source)
        ? { dataUrl: source }
        : await fetchImageForExcel(source, fallback).catch(() => null);
      if (!imageInfo || !imageInfo.dataUrl) return null;
      return { dataUrl: imageInfo.dataUrl, image: await loadSizeImageSource(imageInfo.dataUrl) };
    } catch (error) {
      console.warn('PLM floating helper printed bag product image load failed:', error);
      return null;
    }
  }

  async function processSizeImageFiles(files, options) {
    const items = Array.from(files || []).filter(Boolean);
    if (!items.length) return;
    const sku = getActiveSizeImageSku();
    const session = sku && ensureSizeImageSession(sku);
    if (session) {
      state.sizeImageBusySku = sku;
      session.error = '';
      session.fileName = items.map((file) => file.name).join(' / ');
      session.processingStep = '\u6b63\u5728\u8bfb\u53d6 ' + items.length + ' \u5f20\u56fe\u7247...';
      if (state.view === 'sizeImage') renderShell();
      await yieldSizeImageUi();
    }
    let generated = false;
    for (const file of items) generated = (await processSizeImageFile(file, '', true)) === true || generated;
    if (state.sizeImageBusySku === sku) state.sizeImageBusySku = '';
    if (session) session.processingStep = '';
    if (session && !session.error) {
      const flatCount = Object.values(session.flatResults).filter((item) => item && item.dataUrl).length;
      const names = [session.cartonResultDataUrl ? '\u7eb8\u76d2' : '', flatCount ? flatCount + '\u4e2a\u6807\u7b7e/\u5370\u5237' : ''].filter(Boolean).join('\u548c');
      if (names) showToast('\u5df2\u751f\u6210' + names + '\u5c3a\u5bf8\u56fe');
      else if (session.pendingLabelMatches.length) showToast('\u8bf7\u624b\u52a8\u9009\u62e9\u56fe\u7247\u5bf9\u5e94\u7684\u6807\u7b7e\u5c3a\u5bf8');
    }
    if (state.view === 'sizeImage') renderShell();
    if (generated && options && options.focusSave) focusGeneratedAssetSaveButton('size-image-save-all', 'sizeImage');
  }

  function analyzeSizeImageGeometry(image, spec) {
    const maxSide = 1800;
    const source = getSizeImageSourceDimensions(image);
    const ratio = Math.min(1, maxSide / Math.max(source.width, source.height));
    const width = Math.max(1, Math.round(source.width * ratio));
    const height = Math.max(1, Math.round(source.height * ratio));
    const canvas = createSizeImageCanvas(width, height);
    const context = canvas.getContext('2d', { willReadFrequently: true });
    context.drawImage(image, 0, 0, width, height);
    const pixels = context.getImageData(0, 0, width, height).data;
    const rows = new Array(height);
    let transparentPixels = 0;
    let opaquePixels = 0;
    for (let y = 0; y < height; y += 1) {
      let count = 0;
      let left = width;
      let right = -1;
      for (let x = 0; x < width; x += 1) {
        const alpha = pixels[(y * width + x) * 4 + 3];
        if (alpha <= 12) transparentPixels += 1;
        if (alpha >= 220) opaquePixels += 1;
        if (alpha >= 220) {
          count += 1;
          if (left === width) left = x;
          right = x;
        }
      }
      rows[y] = { count, left, right };
    }
    const totalPixels = width * height;
    if (transparentPixels < totalPixels * 0.03 || opaquePixels < totalPixels * 0.05) {
      throw new Error('\u56fe\u7247\u6ca1\u6709\u53ef\u9760\u7684\u900f\u660e\u8f6e\u5ed3\uff0c\u8bf7\u5728 Photoshop \u4e2d\u4fdd\u7559\u900f\u660e\u80cc\u666f\u540e\u5bfc\u51fa PNG\u3002');
    }
    const maxRow = rows.reduce((max, row) => Math.max(max, row.count), 0);
    const threshold = maxRow * 0.92;
    let bestStart = -1;
    let bestEnd = -1;
    let start = -1;
    for (let y = 0; y <= height; y += 1) {
      const active = y < height && rows[y].count >= threshold;
      if (active && start < 0) start = y;
      if (!active && start >= 0) {
        if (bestStart < 0 || y - start > bestEnd - bestStart) {
          bestStart = start;
          bestEnd = y;
        }
        start = -1;
      }
    }
    if (bestStart < 0 || bestEnd - bestStart < 20) throw new Error('\u65e0\u6cd5\u5b9a\u4f4d\u8fde\u7eed\u7684\u7eb8\u76d2\u4e3b\u4f53\u3002');
    const sampleRows = rows.slice(bestStart, bestEnd).filter((row) => row.count >= threshold);
    const bodyLeft = Math.min(...sampleRows.map((row) => row.left));
    const bodyRight = Math.max(...sampleRows.map((row) => row.right + 1));
    const bodyWidth = bodyRight - bodyLeft;
    const bodyHeight = bestEnd - bestStart;
    const physicalBodyWidth = getCartonBodyWidths(spec).reduce((sum, value) => sum + value, 0);
    const scaleX = bodyWidth / physicalBodyWidth;
    const scaleY = bodyHeight / spec.height;
    const scaleDelta = Math.abs(scaleX - scaleY) / Math.max(scaleX, scaleY);
    if (scaleDelta > 0.045) throw new Error('\u7eb8\u76d2\u4e3b\u4f53\u6bd4\u4f8b\u4e0e PLM \u5c3a\u5bf8\u4e0d\u4e00\u81f4\uff0c\u8bf7\u786e\u8ba4 SKU \u548c\u5bfc\u51fa\u56fe\u662f\u5426\u5339\u914d\u3002');
    const topRect = {
      x: bodyLeft + spec.width * scaleX,
      y: bestStart - spec.width * scaleY,
      width: spec.length * scaleX,
      height: spec.width * scaleY,
    };
    const bottomRect = {
      x: bodyLeft + (2 * spec.width + spec.length) * scaleX,
      y: bestEnd,
      width: spec.length * scaleX,
      height: spec.width * scaleY,
    };
    if (topRect.y < -2 || bottomRect.y + bottomRect.height > height + 2) throw new Error('\u9876\u76d6\u6216\u5e95\u76d6\u4e0d\u5b8c\u6574\uff0c\u8bf7\u5bfc\u51fa\u5305\u542b\u5b8c\u6574\u7eb8\u76d2\u8f6e\u5ed3\u7684 PNG\u3002');
    const coverage = (rect) => {
      const x0 = Math.max(0, Math.round(rect.x));
      const y0 = Math.max(0, Math.round(rect.y));
      const x1 = Math.min(width, Math.round(rect.x + rect.width));
      const y1 = Math.min(height, Math.round(rect.y + rect.height));
      let hits = 0;
      let samples = 0;
      const step = Math.max(1, Math.floor(Math.min(rect.width, rect.height) / 90));
      for (let y = y0; y < y1; y += step) {
        for (let x = x0; x < x1; x += step) {
          samples += 1;
          if (pixels[(y * width + x) * 4 + 3] > 12) hits += 1;
        }
      }
      return samples ? hits / samples : 0;
    };
    const bodyCoverage = coverage({ x: bodyLeft, y: bestStart, width: bodyWidth, height: bodyHeight });
    if (bodyCoverage < 0.94 || coverage(topRect) < 0.82 || coverage(bottomRect) < 0.82) {
      throw new Error('\u900f\u660e\u8f6e\u5ed3\u4e0d\u7b26\u5408\u201c\u8fde\u7eed\u4e3b\u4f53 + \u7b2c\u4e8c\u9762\u9876\u76d6 + \u7b2c\u56db\u9762\u5e95\u76d6\u201d\u7ed3\u6784\u3002');
    }
    return {
      bodyLeft: bodyLeft * source.width / width,
      bodyTop: bestStart * source.height / height,
      pixelsPerCmX: scaleX * source.width / width,
      pixelsPerCmY: scaleY * source.height / height,
    };
  }

  function matchFlatSizeImageRatio(sourceRatio, spec) {
    const panelCounts = spec && spec.printedBag ? [1, 2] : [1];
    const candidates = [];
    panelCounts.forEach((panelCount) => {
      const expectedRatio = spec.width * panelCount / spec.height;
      candidates.push({
        panelCount,
        rotated: false,
        matchDelta: Math.abs(sourceRatio - expectedRatio) / expectedRatio,
      });
      candidates.push({
        panelCount,
        rotated: true,
        matchDelta: Math.abs((1 / sourceRatio) - expectedRatio) / expectedRatio,
      });
    });
    return candidates.sort((a, b) => a.matchDelta - b.matchDelta)[0];
  }

  function analyzeLabelSizeImageGeometry(image, spec, allowMismatch) {
    const maxSide = 1600;
    const source = getSizeImageSourceDimensions(image);
    const ratio = Math.min(1, maxSide / Math.max(source.width, source.height));
    const width = Math.max(1, Math.round(source.width * ratio));
    const height = Math.max(1, Math.round(source.height * ratio));
    const canvas = createSizeImageCanvas(width, height);
    const context = canvas.getContext('2d', { willReadFrequently: true });
    context.drawImage(image, 0, 0, width, height);
    const pixels = context.getImageData(0, 0, width, height).data;
    let left = width;
    let top = height;
    let right = -1;
    let bottom = -1;
    let transparent = 0;
    for (let y = 0; y < height; y += 1) {
      for (let x = 0; x < width; x += 1) {
        const alpha = pixels[(y * width + x) * 4 + 3];
        if (alpha <= 12) transparent += 1;
        if (alpha > 12) {
          left = Math.min(left, x);
          top = Math.min(top, y);
          right = Math.max(right, x);
          bottom = Math.max(bottom, y);
        }
      }
    }
    const useAlphaBounds = transparent > width * height * 0.02 && right >= left && bottom >= top;
    if (!useAlphaBounds) {
      left = 0;
      top = 0;
      right = width - 1;
      bottom = height - 1;
    }
    const cropWidth = right - left + 1;
    const cropHeight = bottom - top + 1;
    const sourceRatio = cropWidth / cropHeight;
    const ratioMatch = matchFlatSizeImageRatio(sourceRatio, spec);
    if (!allowMismatch && ratioMatch.matchDelta > 0.065) {
      throw new Error('\u56fe\u7247\u6bd4\u4f8b\u4e0e PLM \u6807\u7b7e\u5c3a\u5bf8 ' + formatSizeImageNumber(spec.width) + ' \u00d7 ' + formatSizeImageNumber(spec.height) + ' cm \u4e0d\u5339\u914d\u3002');
    }
    return {
      cropX: left * source.width / width,
      cropY: top * source.height / height,
      cropWidth: cropWidth * source.width / width,
      cropHeight: cropHeight * source.height / height,
      rotated: ratioMatch.rotated,
      panelCount: ratioMatch.panelCount,
      matchDelta: ratioMatch.matchDelta,
    };
  }

  function generateSizeImageJpeg(image, geometry, spec, data, includeRemark, includeRoundArc, customRemark, renderOptions) {
    const canvas = createSizeImageCanvas(3000, 3000);
    const context = canvas.getContext('2d');
    context.fillStyle = '#ffffff';
    context.fillRect(0, 0, canvas.width, canvas.height);
    context.textBaseline = 'top';
    context.fillStyle = '#000000';
    context.font = '700 88px "Microsoft YaHei", "PingFang SC", sans-serif';
    const titleText = renderOptions && renderOptions.titleText || getSizeImageTitle('carton', data, includeRemark, includeRoundArc, customRemark);
    context.fillText(titleText, 505, 140);
    context.font = '78px "Microsoft YaHei", "PingFang SC", sans-serif';
    const extraSizeText = (spec.extraWidths || []).map((value) => 'X' + formatSizeImageNumber(value)).join('');
    context.fillText('\u89c4\u683c\u5c3a\u5bf8\uff1a\u957f' + formatSizeImageNumber(spec.length) + 'X\u5bbd' + formatSizeImageNumber(spec.width) + 'X\u9ad8' + formatSizeImageNumber(spec.height) + extraSizeText + 'CM', 505, 260);
    context.fillStyle = '#ee1410';
    context.font = '76px "Microsoft YaHei", "PingFang SC", sans-serif';
    context.fillText('(\u751f\u4ea7\u65e5\u671f+\u622a\u6b62\u65e5\u671f+\u6279\u6b21\u53f7)', 505, 370);

    const bodyWidths = getCartonBodyWidths(spec);
    const physicalWidth = bodyWidths.reduce((sum, value) => sum + value, 0);
    const physicalHeight = spec.height + 2 * spec.width;
    const cartonAspect = physicalWidth / physicalHeight;
    const widthLimit = clamp(1600 + ((cartonAspect - 0.72) / 0.38) * 450, 1600, 2050);
    const drawScale = Math.min(widthLimit / physicalWidth, 2020 / physicalHeight);
    const artWidth = physicalWidth * drawScale;
    const artHeight = physicalHeight * drawScale;
    const artX = Math.round((3000 - artWidth) / 2);
    const artY = clamp(Math.round((3000 - artHeight) / 2), 650, 900);
    const bodyTop = artY + spec.width * drawScale;
    const bodyBottom = bodyTop + spec.height * drawScale;
    context.save();
    context.beginPath();
    context.rect(artX + spec.width * drawScale, artY, spec.length * drawScale, spec.width * drawScale);
    context.rect(artX, bodyTop, physicalWidth * drawScale, spec.height * drawScale);
    context.rect(artX + (2 * spec.width + spec.length) * drawScale, bodyBottom, spec.length * drawScale, spec.width * drawScale);
    context.clip();
    context.imageSmoothingEnabled = true;
    context.imageSmoothingQuality = 'high';
    const imageX = artX - geometry.bodyLeft / geometry.pixelsPerCmX * drawScale;
    const imageY = bodyTop - geometry.bodyTop / geometry.pixelsPerCmY * drawScale;
    const source = getSizeImageSourceDimensions(image);
    context.drawImage(image, imageX, imageY, source.width / geometry.pixelsPerCmX * drawScale, source.height / geometry.pixelsPerCmY * drawScale);
    context.restore();
    traceCartonSizeImageOutline(context, artX, artY, drawScale, spec);
    context.strokeStyle = '#000000';
    context.lineWidth = 1;
    context.stroke();

    context.strokeStyle = '#ee1410';
    context.fillStyle = '#ee1410';
    context.lineWidth = 4;
    const tick = 28;
    const heightX = artX - 48;
    drawSizeImageLine(context, heightX, bodyTop, heightX, bodyBottom);
    drawSizeImageLine(context, heightX - tick, bodyTop, heightX + tick, bodyTop);
    drawSizeImageLine(context, heightX - tick, bodyBottom, heightX + tick, bodyBottom);
    context.save();
    context.translate(heightX - 112, (bodyTop + bodyBottom) / 2);
    context.rotate(-Math.PI / 2);
    context.font = '66px "Microsoft YaHei", "PingFang SC", sans-serif';
    context.textAlign = 'center';
    context.fillText(formatSizeImageNumber(spec.height) + 'cm', 0, 0);
    context.restore();

    const bottomY = bodyBottom + 48;
    const firstEnd = artX + spec.width * drawScale;
    const secondEnd = firstEnd + spec.length * drawScale;
    drawSizeImageLine(context, artX, bottomY, secondEnd, bottomY);
    [artX, firstEnd, secondEnd].forEach((x) => drawSizeImageLine(context, x, bottomY - tick, x, bottomY + tick));
    context.font = '66px "Microsoft YaHei", "PingFang SC", sans-serif';
    context.textAlign = 'center';
    context.fillText(formatSizeImageNumber(spec.width) + 'cm', (artX + firstEnd) / 2, bottomY + 34);
    context.fillText(formatSizeImageNumber(spec.length) + 'cm', (firstEnd + secondEnd) / 2, bottomY + 34);
    if (bodyWidths.length > 4) {
      const extraStart = artX + bodyWidths.slice(0, 4).reduce((sum, value) => sum + value, 0) * drawScale;
      const extraLineY = bodyTop - 48;
      let cursorX = extraStart;
      drawSizeImageLine(context, extraStart, extraLineY, artX + artWidth, extraLineY);
      drawSizeImageLine(context, extraStart, extraLineY - tick, extraStart, extraLineY + tick);
      bodyWidths.slice(4).forEach((width) => {
        const nextX = cursorX + width * drawScale;
        drawSizeImageLine(context, nextX, extraLineY - tick, nextX, extraLineY + tick);
        context.fillText(formatSizeImageNumber(width) + 'cm', (cursorX + nextX) / 2, extraLineY - 102);
        cursorX = nextX;
      });
    }
    return renderOptions && renderOptions.returnCanvas ? canvas : canvas.toDataURL('image/jpeg', 0.96);
  }

  function getCartonBodyWidths(spec) {
    return [spec.width, spec.length, spec.width, spec.length].concat(Array.isArray(spec.extraWidths) ? spec.extraWidths : []);
  }

  function traceCartonSizeImageOutline(context, artX, artY, scale, spec) {
    const width = spec.width;
    const length = spec.length;
    const bodyTop = artY + width * scale;
    const bodyBottom = bodyTop + spec.height * scale;
    const flapBottom = bodyBottom + width * scale;
    context.beginPath();
    context.moveTo(artX, bodyTop);
    context.lineTo(artX + width * scale, bodyTop);
    context.lineTo(artX + width * scale, artY);
    context.lineTo(artX + (width + length) * scale, artY);
    context.lineTo(artX + (width + length) * scale, bodyTop);
    const bodyWidth = getCartonBodyWidths(spec).reduce((sum, value) => sum + value, 0);
    context.lineTo(artX + bodyWidth * scale, bodyTop);
    context.lineTo(artX + bodyWidth * scale, bodyBottom);
    context.lineTo(artX + 2 * (width + length) * scale, bodyBottom);
    context.lineTo(artX + 2 * (width + length) * scale, flapBottom);
    context.lineTo(artX + (2 * width + length) * scale, flapBottom);
    context.lineTo(artX + (2 * width + length) * scale, bodyBottom);
    context.lineTo(artX, bodyBottom);
    context.closePath();
  }

  function drawSizeImageContained(context, image, x, y, width, height) {
    if (!context || !image || !(width > 0) || !(height > 0)) return;
    const source = getSizeImageSourceDimensions(image);
    const scale = Math.min(width / source.width, height / source.height);
    const drawWidth = source.width * scale;
    const drawHeight = source.height * scale;
    context.drawImage(image, x + (width - drawWidth) / 2, y + (height - drawHeight) / 2, drawWidth, drawHeight);
  }

  function drawPrintedBagSealDimension(context, artX, artY, drawScale) {
    const sealWidth = Math.max(24, 0.5 * drawScale);
    const lineY = artY - 58;
    const tick = 28;
    context.save();
    context.strokeStyle = '#ee1410';
    context.fillStyle = '#ee1410';
    context.lineWidth = 4;
    context.font = '66px "Microsoft YaHei", "PingFang SC", sans-serif';
    context.textAlign = 'left';
    context.textBaseline = 'top';
    context.fillText('\u5c01\u8fb90.5cm', Math.max(100, artX - 190), lineY - 106);
    drawSizeImageLine(context, artX, lineY, artX + sealWidth, lineY);
    drawSizeImageLine(context, artX, lineY - tick, artX, lineY + tick);
    drawSizeImageLine(context, artX + sealWidth, lineY - tick, artX + sealWidth, lineY + tick);
    context.restore();
  }

  function generateLabelSizeImageJpeg(image, geometry, spec, data, includeRemark, includeRoundArc, includeBatchNumber, customRemark, renderOptions) {
    const canvas = createSizeImageCanvas(3000, 3000);
    const context = canvas.getContext('2d');
    context.fillStyle = '#ffffff';
    context.fillRect(0, 0, canvas.width, canvas.height);
    context.textBaseline = 'top';
    context.fillStyle = '#000000';
    context.font = '700 88px "Microsoft YaHei", "PingFang SC", sans-serif';
    const titleText = renderOptions && renderOptions.titleText || getSizeImageTitle(spec.kind === 'print' ? 'print' : 'label', data, includeRemark, includeRoundArc, customRemark);
    context.fillText(titleText, 505, 140);
    const titleRight = 505 + context.measureText(titleText).width;
    context.font = '78px "Microsoft YaHei", "PingFang SC", sans-serif';
    const panelCount = Math.max(1, Number(geometry.panelCount) || 1);
    const artworkWidth = spec.width * panelCount;
    const doubleSidedPrintedBag = isDoubleSidedPrintedBagSizeImage(spec, geometry);
    const sizeText = doubleSidedPrintedBag
      ? '\u89c4\u683c\u5c3a\u5bf8\uff1a\u5bbd' + formatSizeImageNumber(spec.width) + 'X\u9ad8' + formatSizeImageNumber(spec.height) + 'CM'
      : panelCount > 1
      ? '\u89c4\u683c\u5c3a\u5bf8\uff1a\u5355\u9762\u5bbd' + formatSizeImageNumber(spec.width) + 'X\u9ad8' + formatSizeImageNumber(spec.height) + 'CM\uff08\u53cc\u9762\u5c55\u5f00\u5bbd' + formatSizeImageNumber(artworkWidth) + 'CM\uff09'
      : '\u89c4\u683c\u5c3a\u5bf8\uff1a\u5bbd' + formatSizeImageNumber(spec.width) + 'X\u9ad8' + formatSizeImageNumber(spec.height) + 'CM';
    context.fillText(sizeText, 505, 260);
    const sizeTextRight = 505 + context.measureText(sizeText).width;
    let batchTextRight = 469;
    if (includeBatchNumber) {
      context.fillStyle = '#ee1410';
      context.font = '76px "Microsoft YaHei", "PingFang SC", sans-serif';
      const batchNote = renderOptions && renderOptions.batchNoteText || (shouldUseFullLabelDateRemark(data) ? '\uff08\u751f\u4ea7\u65e5\u671f+\u622a\u6b62\u65e5\u671f+\u6279\u6b21\u53f7\uff09' : '\uff08\u6279\u6b21\u53f7\uff09');
      context.fillText(batchNote, 469, 370);
      batchTextRight = 469 + context.measureText(batchNote).width;
    }
    if (doubleSidedPrintedBag && renderOptions && renderOptions.productImage) {
      const effectImageX = Math.max(1800, Math.max(titleRight, sizeTextRight, batchTextRight) + 52);
      const effectImageRight = 2860;
      const effectImageWidth = effectImageRight - effectImageX;
      if (effectImageWidth >= 260) {
        drawSizeImageContained(context, renderOptions.productImage, effectImageX, 42, effectImageWidth, 620);
      }
    }

    const drawScale = Math.min(2050 / artworkWidth, 1550 / spec.height);
    const artWidth = artworkWidth * drawScale;
    const artHeight = spec.height * drawScale;
    const artX = Math.round((3000 - artWidth) / 2);
    const artY = clamp(Math.round((3000 - artHeight) / 2), 760, 1200);
    if (doubleSidedPrintedBag) drawPrintedBagSealDimension(context, artX, artY, drawScale);
    const cornerRadius = spec.kind === 'label' && includeRoundArc ? Math.min(18, Math.max(6, drawScale * 0.08)) : 0;
    context.save();
    context.beginPath();
    if (cornerRadius) traceSizeImageRoundedRect(context, artX, artY, artWidth, artHeight, cornerRadius);
    else context.rect(artX, artY, artWidth, artHeight);
    context.clip();
    context.imageSmoothingEnabled = true;
    context.imageSmoothingQuality = 'high';
    if (geometry.rotated) {
      context.translate(artX + artWidth / 2, artY + artHeight / 2);
      context.rotate(-Math.PI / 2);
      context.drawImage(image, geometry.cropX, geometry.cropY, geometry.cropWidth, geometry.cropHeight, -artHeight / 2, -artWidth / 2, artHeight, artWidth);
    } else {
      context.drawImage(image, geometry.cropX, geometry.cropY, geometry.cropWidth, geometry.cropHeight, artX, artY, artWidth, artHeight);
    }
    context.restore();
    context.strokeStyle = '#000000';
    context.lineWidth = 1;
    if (cornerRadius) {
      context.beginPath();
      traceSizeImageRoundedRect(context, artX + 0.5, artY + 0.5, artWidth - 1, artHeight - 1, Math.max(0, cornerRadius - 0.5));
      context.stroke();
    } else {
      context.strokeRect(artX + 0.5, artY + 0.5, artWidth - 1, artHeight - 1);
    }

    context.strokeStyle = '#ee1410';
    context.fillStyle = '#ee1410';
    context.lineWidth = 4;
    const tick = 28;
    const heightX = artX - 48;
    drawSizeImageLine(context, heightX, artY, heightX, artY + artHeight);
    drawSizeImageLine(context, heightX - tick, artY, heightX + tick, artY);
    drawSizeImageLine(context, heightX - tick, artY + artHeight, heightX + tick, artY + artHeight);
    context.save();
    context.translate(heightX - 112, artY + artHeight / 2);
    context.rotate(-Math.PI / 2);
    context.font = '66px "Microsoft YaHei", "PingFang SC", sans-serif';
    context.textAlign = 'center';
    context.fillText(formatSizeImageNumber(spec.height) + 'cm', 0, 0);
    context.restore();
    const bottomY = artY + artHeight + 48;
    drawSizeImageLine(context, artX, bottomY, artX + artWidth, bottomY);
    drawSizeImageLine(context, artX, bottomY - tick, artX, bottomY + tick);
    drawSizeImageLine(context, artX + artWidth, bottomY - tick, artX + artWidth, bottomY + tick);
    context.font = '66px "Microsoft YaHei", "PingFang SC", sans-serif';
    context.textAlign = 'center';
    if (panelCount > 1) {
      for (let panelIndex = 1; panelIndex < panelCount; panelIndex += 1) {
        const dividerX = artX + artWidth * panelIndex / panelCount;
        context.save();
        context.strokeStyle = 'rgba(238, 20, 16, 0.65)';
        context.setLineDash([18, 14]);
        drawSizeImageLine(context, dividerX, artY, dividerX, artY + artHeight);
        context.restore();
        drawSizeImageLine(context, dividerX, bottomY - tick, dividerX, bottomY + tick);
      }
      for (let panelIndex = 0; panelIndex < panelCount; panelIndex += 1) {
        context.fillText(formatSizeImageNumber(spec.width) + 'cm', artX + artWidth * (panelIndex + 0.5) / panelCount, bottomY + 34);
      }
    } else {
      context.fillText(formatSizeImageNumber(spec.width) + 'cm', artX + artWidth / 2, bottomY + 34);
    }
    return renderOptions && renderOptions.returnCanvas ? canvas : canvas.toDataURL('image/jpeg', 0.96);
  }

  let sizeImageWorkerSource = '';

  function getSizeImageWorkerSource() {
    if (sizeImageWorkerSource) return sizeImageWorkerSource;
    const pureFunctions = [
      'const clamp = ' + clamp.toString() + ';',
      'const trimNumber = ' + trimNumber.toString() + ';',
      'const formatSizeImageNumber = ' + formatSizeImageNumber.toString() + ';',
      createSizeImageCanvas,
      getSizeImageSourceDimensions,
      getCartonBodyWidths,
      drawSizeImageLine,
      isDoubleSidedPrintedBagSizeImage,
      drawSizeImageContained,
      drawPrintedBagSealDimension,
      traceSizeImageRoundedRect,
      traceCartonSizeImageOutline,
      matchFlatSizeImageRatio,
      analyzeSizeImageGeometry,
      analyzeLabelSizeImageGeometry,
      generateSizeImageJpeg,
      generateLabelSizeImageJpeg,
    ].map((item) => typeof item === 'string' ? item : item.toString()).join('\n');
    sizeImageWorkerSource = `'use strict';
${pureFunctions}

async function canvasToBlob(canvas) {
  if (!canvas || typeof canvas.convertToBlob !== 'function') throw new Error('当前浏览器不支持 Worker 图片导出');
  return canvas.convertToBlob({ type: 'image/jpeg', quality: .96 });
}

self.onmessage = async function(event) {
  const payload = event.data || {};
  let image = null;
  let productImage = null;
  try {
    if (typeof OffscreenCanvas !== 'function' || typeof createImageBitmap !== 'function') throw new Error('当前浏览器不支持 Worker 尺寸图生成');
    image = await createImageBitmap(payload.file);
    const cartonSpec = payload.cartonSpec || null;
    const labelSpecs = Array.isArray(payload.labelSpecs) ? payload.labelSpecs : [];
    if (payload.productImageDataUrl && labelSpecs.some((spec) => spec && spec.printedBag)) {
      const productImageResponse = await fetch(payload.productImageDataUrl);
      if (!productImageResponse.ok) throw new Error('产品效果图读取失败');
      productImage = await createImageBitmap(await productImageResponse.blob());
    }
    const preferredType = String(payload.preferredType || '');
    const preferredLabelKey = preferredType.startsWith('label:') ? preferredType.slice(6) : '';
    const isPng = String(payload.fileName || '').toLowerCase().endsWith('.png') || payload.fileType === 'image/png';
    let detectedType = preferredType === 'carton' ? 'carton' : (preferredType === 'label' || preferredLabelKey ? 'label' : '');
    let geometry = null;
    let matchedLabelSpec = null;
    let cartonError = null;
    if ((!detectedType || detectedType === 'carton') && cartonSpec && isPng) {
      try {
        geometry = analyzeSizeImageGeometry(image, cartonSpec);
        detectedType = 'carton';
      } catch (error) {
        cartonError = error;
        if (preferredType === 'carton') throw error;
      }
    }
    if (!detectedType || detectedType === 'label') {
      if (!labelSpecs.length) throw cartonError || new Error('当前 SKU 没有可用的标签尺寸');
      if (preferredLabelKey) {
        matchedLabelSpec = labelSpecs.find((spec) => spec.key === preferredLabelKey) || null;
        if (!matchedLabelSpec) throw new Error('选择的标签尺寸已失效，请重新选择');
        geometry = analyzeLabelSizeImageGeometry(image, matchedLabelSpec, true);
      } else {
        const matches = labelSpecs.map((spec) => {
          try { return { spec, geometry: analyzeLabelSizeImageGeometry(image, spec) }; } catch (_) { return null; }
        }).filter(Boolean).sort((a, b) => a.geometry.matchDelta - b.geometry.matchDelta);
        if (!matches.length && labelSpecs.length === 1) throw new Error('图片比例与 PLM 中的标签或印刷尺寸不匹配');
        const first = matches[0];
        const second = matches[1];
        const confident = first && (!second || second.geometry.matchDelta - first.geometry.matchDelta >= .012);
        if (!confident) {
          self.postMessage({ ok: true, status: 'pending', matches: matches.map((item) => ({ key: item.spec.key, matchDelta: item.geometry.matchDelta })) });
          return;
        }
        matchedLabelSpec = first.spec;
        geometry = first.geometry;
      }
      detectedType = 'label';
    }
    const key = detectedType === 'carton' ? 'carton' : matchedLabelSpec.key;
    const transparent = detectedType === 'label' && Array.isArray(payload.transparentLabelKeys) && payload.transparentLabelKeys.includes(key);
    const renderOptions = detectedType === 'carton'
      ? ((payload.renderMeta && payload.renderMeta.carton) || {})
      : ((payload.renderMeta && payload.renderMeta.labels && payload.renderMeta.labels[key]) || {});
    if (detectedType === 'label' && isDoubleSidedPrintedBagSizeImage(matchedLabelSpec, geometry) && productImage) {
      renderOptions.productImage = productImage;
    }
    const includeRoundArc = transparent ? false : Boolean(payload.includeRoundArc);
    const includeBatchNumber = transparent ? false : Boolean(payload.includeBatchNumber);
    const canvas = detectedType === 'carton'
      ? generateSizeImageJpeg(image, geometry, cartonSpec, {}, Boolean(payload.includeRemark), includeRoundArc, payload.cartonRemarkText || '', { ...renderOptions, returnCanvas: true })
      : generateLabelSizeImageJpeg(image, geometry, matchedLabelSpec, {}, Boolean(payload.includeRemark), includeRoundArc, includeBatchNumber, payload.labelRemarkText || '', { ...renderOptions, returnCanvas: true });
    const blob = await canvasToBlob(canvas);
    self.postMessage({ ok: true, status: 'ready', detectedType, matchedLabelKey: matchedLabelSpec ? matchedLabelSpec.key : '', geometry, transparent, blob });
  } catch (error) {
    self.postMessage({ ok: false, error: String(error && error.message || error || '尺寸图生成失败') });
  } finally {
    if (image && typeof image.close === 'function') image.close();
    if (productImage && typeof productImage.close === 'function') productImage.close();
  }
};`;
    return sizeImageWorkerSource;
  }

  function sizeImageBlobToDataUrl(blob) {
    return new Promise((resolve, reject) => {
      if (!blob) { reject(new Error('Worker 未返回尺寸图')); return; }
      const reader = new FileReader();
      reader.onload = () => resolve(String(reader.result || ''));
      reader.onerror = () => reject(new Error('尺寸图结果读取失败'));
      reader.readAsDataURL(blob);
    });
  }

  async function runSizeImageWorker(file, preferredType, cartonSpec, labelSpecs, data, session, productImageDataUrl) {
    const canUseWorker = typeof Worker === 'function'
      && typeof Blob === 'function'
      && typeof OffscreenCanvas === 'function'
      && typeof createImageBitmap === 'function'
      && typeof URL !== 'undefined'
      && typeof URL.createObjectURL === 'function';
    if (!canUseWorker) return null;
    const transparentLabelKeys = labelSpecs.filter((spec) => isTransparentSizeImageLabel(data, spec)).map((spec) => spec.key);
    const renderMeta = { carton: null, labels: {} };
    if (cartonSpec) {
      renderMeta.carton = { titleText: getSizeImageTitle('carton', data, session.includeRemark, session.includeRoundArc, session.cartonRemarkText) };
    }
    labelSpecs.forEach((spec) => {
      const transparent = transparentLabelKeys.includes(spec.key);
      const includeRoundArc = transparent ? false : session.includeRoundArc;
      const includeBatchNumber = transparent ? false : session.includeBatchNumber;
      renderMeta.labels[spec.key] = {
        titleText: getSizeImageTitle(spec.kind === 'print' ? 'print' : 'label', data, session.includeRemark, includeRoundArc, session.labelRemarkTexts[spec.key]),
        batchNoteText: includeBatchNumber ? (shouldUseFullLabelDateRemark(data) ? '\uff08\u751f\u4ea7\u65e5\u671f+\u622a\u6b62\u65e5\u671f+\u6279\u6b21\u53f7\uff09' : '\uff08\u6279\u6b21\u53f7\uff09') : '',
      };
    });
    let worker = null;
    let sourceUrl = '';
    try {
      sourceUrl = URL.createObjectURL(new Blob([getSizeImageWorkerSource()], { type: 'application/javascript' }));
      worker = new Worker(sourceUrl);
      const result = await new Promise((resolve, reject) => {
        let settled = false;
        const finish = (callback, value) => {
          if (settled) return;
          settled = true;
          callback(value);
        };
        worker.onmessage = (event) => {
          const payload = event && event.data || {};
          if (!payload.ok) finish(reject, new Error(payload.error || '尺寸图 Worker 失败'));
          else finish(resolve, payload);
        };
        worker.onerror = (event) => finish(reject, new Error(event && event.message || '尺寸图 Worker 启动失败'));
        worker.postMessage({
          file,
          fileName: file.name || '',
          fileType: file.type || '',
          preferredType,
          cartonSpec,
          labelSpecs,
          includeRemark: session.includeRemark,
          includeRoundArc: session.includeRoundArc,
          includeBatchNumber: session.includeBatchNumber,
          cartonRemarkText: session.cartonRemarkText || '',
          labelRemarkText: '',
          transparentLabelKeys,
          productImageDataUrl: productImageDataUrl || '',
          renderMeta,
        });
      });
      if (result.status === 'pending') return { worker: true, status: 'pending', matches: result.matches || [] };
      return {
        worker: true,
        status: 'ready',
        detectedType: result.detectedType,
        matchedLabelKey: result.matchedLabelKey || '',
        geometry: result.geometry,
        transparent: Boolean(result.transparent),
        dataUrl: await sizeImageBlobToDataUrl(result.blob),
      };
    } catch (_) {
      return null;
    } finally {
      if (worker) worker.terminate();
      if (sourceUrl) URL.revokeObjectURL(sourceUrl);
    }
  }

  function shouldUseFullLabelDateRemark(data) {
    const brand = String(data && data.brand || '').trim().toUpperCase();
    const flatSpec = getLabelSizeImageSpec(data);
    return ['DOCTEAT', 'GOOGEER', 'BUSHAID'].some((name) => brand.includes(name)) && !getSizeImageSpec(data) && Boolean(flatSpec && flatSpec.kind === 'label');
  }

  function getSizeImageTitle(type, data, includeRemark, includeRoundArc, customRemark) {
    const customBase = type === 'carton'
      ? String(data && data.sizeImageCustomPackageTitle || '').trim()
      : String(data && data.sizeImageCustomFlatTitle || '').trim();
    const base = customBase || (type === 'label' ? '\u6807\u7b7e' : (type === 'print' ? '\u5370\u5237' : '\u7eb8\u76d2'));
    if (!includeRemark) return base;
    const remarks = getSizeImageRemarks(data);
    const sourceRemark = typeof customRemark === 'string' ? customRemark.trim() : (type === 'carton' ? remarks.carton : remarks.label);
    const roundArcRemark = type === 'label' && includeRoundArc && !String(sourceRemark || '').includes('\u5706\u5f27') ? '\u5706\u5f27' : '';
    const remark = [sourceRemark, roundArcRemark].filter(Boolean).join(' ');
    return remark ? base + '\uff08' + remark + '\uff09' : base;
  }

  function traceSizeImageRoundedRect(context, x, y, width, height, radius) {
    const r = Math.max(0, Math.min(Number(radius) || 0, width / 2, height / 2));
    context.moveTo(x + r, y);
    context.lineTo(x + width - r, y);
    context.quadraticCurveTo(x + width, y, x + width, y + r);
    context.lineTo(x + width, y + height - r);
    context.quadraticCurveTo(x + width, y + height, x + width - r, y + height);
    context.lineTo(x + r, y + height);
    context.quadraticCurveTo(x, y + height, x, y + height - r);
    context.lineTo(x, y + r);
    context.quadraticCurveTo(x, y, x + r, y);
    context.closePath();
  }

  function drawSizeImageLine(context, x1, y1, x2, y2) {
    context.beginPath();
    context.moveTo(Math.round(x1), Math.round(y1));
    context.lineTo(Math.round(x2), Math.round(y2));
    context.stroke();
  }

  function formatSizeImageError(error) {
    const message = String(error && error.message || error || '').trim();
    return message || '\u65e0\u6cd5\u8bc6\u522b\u7eb8\u76d2\u3001\u6807\u7b7e\u6216\u5370\u5237\uff0c\u8bf7\u68c0\u67e5\u56fe\u7247\u4e0e PLM \u5c3a\u5bf8\u662f\u5426\u5339\u914d\u3002';
  }

  function confirmSizeImageFolderPermission() {
    if (typeof window.confirm !== 'function') return true;
    return window.confirm('即将选择尺寸图保存文件夹。\n如果随后出现“允许此网站修改文件？”提示，请点击“允许”，否则尺寸图无法批量写入。\n\n点击“确定”继续，点击“取消”停止。');
  }

  async function saveCurrentSizeImagesToFolder() {
    const sku = getActiveSizeImageSku();
    const session = sku && state.sizeImageSessions[sku];
    const currentData = getActiveSizeImageData();
    const flatSpecs = getLabelSizeImageSpecs(currentData);
    if (session) migrateLegacySizeImageResult(session, flatSpecs[0]);
    const flatFiles = session ? flatSpecs.map((spec) => {
      const result = session.flatResults[spec.key];
      if (!result || !result.dataUrl) return null;
      const flatLabel = (result.kind || spec.kind) === 'print' ? '\u5370\u5237' : '\u6807\u7b7e';
      const materialCode = namingCodes(result.code || spec.code)[0] || compactText(result.code || spec.code || '') || sku;
      return { name: sanitizeDownloadFileName(flatLabel + materialCode + '.jpg'), dataUrl: result.dataUrl };
    }).filter(Boolean) : [];
    const cartonCode = namingCodes(currentData.packageCode)[0] || compactText(currentData.packageCode || '') || sku;
    const files = session ? [
      session.cartonResultDataUrl ? { name: sanitizeDownloadFileName('\u7eb8\u76d2' + cartonCode + '.jpg'), dataUrl: session.cartonResultDataUrl } : null,
      ...flatFiles,
    ].filter(Boolean) : [];
    if (!files.length) {
      showToast('\u8bf7\u5148\u751f\u6210\u7eb8\u76d2\u3001\u6807\u7b7e\u6216\u5370\u5237\u5c3a\u5bf8\u56fe');
      return;
    }
    if (typeof saveImageFiles === 'function' && getDirectoryPicker() && !confirmSizeImageFolderPermission()) return;
    if (typeof saveImageFiles === 'function') {
      try {
        const result = await saveImageFiles(files);
        if (result && result.cancelled) return;
        if (result && result.mode === 'unsupported') {
          showToast('\u5f53\u524d\u6d4f\u89c8\u5668\u4e0d\u652f\u6301\u53e6\u5b58\u4e3a\uff0c\u8bf7\u4f7f\u7528\u6700\u65b0\u7248 Chrome \u6216 Edge');
          return;
        }
        showToast('\u5df2\u4fdd\u5b58 ' + files.length + ' \u4e2a\u5c3a\u5bf8\u56fe JPG');
      } catch (error) {
        if (error && error.name === 'AbortError') return;
        console.warn('PLM floating helper size image folder save failed:', error);
        showToast('\u4fdd\u5b58\u5931\u8d25\uff1a' + formatErrorMessage(error));
      }
      return;
    }
    const picker = getSaveFilePicker();
    if (!picker) {
      showToast('\u5f53\u524d\u6d4f\u89c8\u5668\u4e0d\u652f\u6301\u53e6\u5b58\u4e3a\uff0c\u8bf7\u4f7f\u7528\u6700\u65b0\u7248 Chrome');
      return;
    }
    try {
      for (const file of files) {
        const handle = await picker({
          suggestedName: file.name,
          types: [{ description: 'JPEG Image', accept: { 'image/jpeg': ['.jpg', '.jpeg'] } }],
        });
        const writable = await handle.createWritable();
        await writable.write(await (await fetch(file.dataUrl)).blob());
        await writable.close();
      }
      showToast('\u5df2\u4fdd\u5b58 ' + files.length + ' \u4e2a\u5c3a\u5bf8\u56fe JPG');
    } catch (error) {
      if (error && error.name === 'AbortError') return;
      console.warn('PLM floating helper size image folder save failed:', error);
      showToast('\u4fdd\u5b58\u5931\u8d25\uff1a' + formatErrorMessage(error));
    }
  }

  async function regenerateCurrentSizeImages() {
    const sku = getActiveSizeImageSku();
    const session = sku && ensureSizeImageSession(sku);
    if (!session) return;
    if (state.sizeImageBusySku === sku) return;
    const data = getActiveSizeImageData();
    const flatSpecs = getLabelSizeImageSpecs(data);
    migrateLegacySizeImageResult(session, flatSpecs[0]);
    const sources = [
      session.cartonFile ? { file: session.cartonFile, type: 'carton' } : null,
      ...flatSpecs.map((spec) => session.flatFiles[spec.key] ? { file: session.flatFiles[spec.key], type: 'label:' + spec.key } : null),
    ].filter(Boolean);
    if (!sources.length) {
      showToast('\u8bf7\u5148\u5bfc\u5165\u7eb8\u76d2\u3001\u6807\u7b7e\u6216\u5370\u5237\u56fe\u7247');
      return;
    }
    state.sizeImageBusySku = sku;
    session.error = '';
    session.processingStep = '\u6b63\u5728\u6309\u6700\u65b0\u9009\u9879\u91cd\u65b0\u751f\u6210...';
    if (state.view === 'sizeImage') renderShell();
    await yieldSizeImageUi();
    try {
      const errors = [];
      for (const source of sources) {
        await processSizeImageFile(source.file, source.type, true);
        if (session.error) errors.push(session.error);
      }
      session.error = errors.join('\n');
      if (!errors.length) showToast('\u5df2\u6309\u6700\u65b0\u9009\u9879\u91cd\u65b0\u751f\u6210\u5c3a\u5bf8\u56fe');
    } finally {
      if (state.sizeImageBusySku === sku) state.sizeImageBusySku = '';
      session.processingStep = '';
      if (state.view === 'sizeImage') renderShell();
    }
  }

  async function confirmPendingSizeImageMatch(pendingId) {
    const sku = getActiveSizeImageSku();
    const session = sku && ensureSizeImageSession(sku);
    if (!session || state.sizeImageBusySku === sku) return;
    const pending = session.pendingLabelMatches.find((item) => item.id === pendingId);
    const panel = document.getElementById(PANEL_ID);
    const select = panel && panel.querySelector('.pfh-size-image-match-select[data-pending-id="' + cssEscape(pendingId) + '"]');
    const specKey = select && select.value;
    if (!pending || !specKey) {
      showToast('\u8bf7\u9009\u62e9\u56fe\u7247\u5bf9\u5e94\u7684\u5c3a\u5bf8');
      return;
    }
    await processSizeImageFile(pending.file, 'label:' + specKey, false);
  }

  function getLedgerPerformanceKind(record) {
    if (record && record.status === '作废') return 'void';
    if (record && record.performanceType === 'extension') return 'extension';
    const designType = String(record && record.designType || '').replace(/\s+/g, '');
    return /(?:换|无)(?:logo|标识|商标)/i.test(designType) ? 'logo' : 'design';
  }

  function getLedgerToySeriesKey(record) {
    if (!record || record.status === '作废' || record.performanceGroupId || record.performanceType === 'extension' || isLedgerSeriesExcluded(record)) return '';
    const cached = normalizeData(loadData(record.sku) || {});
    const toyData = { ...cached, brand: record.brand || cached.brand || '', name: record.name || cached.name || '', isToy: record.isToy };
    // Reuse the smart toy-copywriting classification as well: it includes PLM
    // category fields that are not present in the dimension-only toy check.
    if (!record.isToy && !isToyDimensionProduct(toyData) && !isToyCopywritingProduct(toyData)) return '';
    const name = cleanName(record.name || cached.name || '').replace(/\s+/g, ' ').trim();
    const match = name.match(/^(.+?)[\-－–—_](?:\s*.+)$/);
    const root = cleanName(match ? match[1] : '').replace(/\s+/g, ' ').trim();
    return root.length >= 3 ? root : '';
  }

  function getLedgerSkuSortValue(sku) {
    const match = String(sku || '').match(/(\d+)/);
    return match ? Number(match[1]) : Number.MAX_SAFE_INTEGER;
  }

  function getLedgerSeriesGroupId(seriesKey, part) {
    let hash = 0;
    for (let index = 0; index < seriesKey.length; index += 1) hash = ((hash * 31) + seriesKey.charCodeAt(index)) >>> 0;
    return 'auto-series-' + hash.toString(36) + '-' + String(part);
  }

  function getLedgerAutomaticSeriesGroups(records) {
    const bySeries = new Map();
    (records || []).forEach((record) => {
      const seriesKey = getLedgerToySeriesKey(record);
      if (!seriesKey) return;
      if (!bySeries.has(seriesKey)) bySeries.set(seriesKey, []);
      bySeries.get(seriesKey).push(record);
    });
    const groups = [];
    bySeries.forEach((items, seriesKey) => {
      if (items.length < 2) return;
      items.sort((a, b) => getLedgerSkuSortValue(a.sku) - getLedgerSkuSortValue(b.sku) || String(a.sku || '').localeCompare(String(b.sku || '')));
      for (let offset = 0, part = 1; offset < items.length; offset += 5, part += 1) {
        const members = items.slice(offset, offset + 5);
        groups.push({
          id: getLedgerSeriesGroupId(seriesKey, part),
          source: 'auto-series',
          seriesKey,
          kind: 'series',
          points: 1,
          records: members,
          recordKeys: members.map(getLedgerSelectionKey),
          skus: members.map((record) => String(record.sku || '')).filter(Boolean),
        });
      }
    });
    return groups;
  }

  function getLedgerManualSeriesGroupId(groupId, part) {
    const source = String(groupId || '');
    let hash = 0;
    for (let index = 0; index < source.length; index += 1) hash = ((hash * 31) + source.charCodeAt(index)) >>> 0;
    return 'manual-series-' + hash.toString(36) + '-' + String(part);
  }

  function getLedgerManualSeriesGroups(records) {
    const byGroup = new Map();
    (records || []).forEach((record) => {
      const groupId = String(record && record.performanceGroupId || '').trim();
      const isLegacyManualGroup = /^performance-manual-/.test(groupId);
      if (!groupId || (record.performanceGroupMode !== 'series' && !isLegacyManualGroup)) return;
      if (!byGroup.has(groupId)) byGroup.set(groupId, []);
      byGroup.get(groupId).push(record);
    });
    const groups = [];
    byGroup.forEach((items, groupId) => {
      items.sort((a, b) => getLedgerSkuSortValue(a.sku) - getLedgerSkuSortValue(b.sku) || String(a.sku || '').localeCompare(String(b.sku || '')));
      for (let offset = 0, part = 1; offset < items.length; offset += 5, part += 1) {
        const members = items.slice(offset, offset + 5);
        groups.push({
          id: getLedgerManualSeriesGroupId(groupId, part),
          source: 'manual-series',
          seriesKey: '手动按编码',
          kind: 'series',
          points: 1,
          records: members,
          recordKeys: members.map(getLedgerSelectionKey),
          skus: members.map((record) => String(record.sku || '')).filter(Boolean),
        });
      }
    });
    return groups;
  }

  function summarizeLedgerPerformance(records) {
    const summary = { design: 0, logo: 0, void: 0, extension: 0, series: 0, mergedGroups: 0, autoSeriesGroups: 0, groups: [], total: 0 };
    const units = new Map();
    const weight = { extension: 3, void: 5, logo: 10, design: 14 };
    const manualSeriesGroups = getLedgerManualSeriesGroups(records);
    const automaticGroups = getLedgerAutomaticSeriesGroups(records);
    const groupedRecordKeys = new Set(manualSeriesGroups.concat(automaticGroups).flatMap((group) => group.recordKeys));
    (records || []).forEach((record, index) => {
      if (groupedRecordKeys.has(getLedgerSelectionKey(record))) return;
      const groupId = String(record && record.performanceGroupId || '').trim();
      const unitKey = groupId ? 'group:' + groupId : 'record:' + getLedgerSelectionKey(record) + ':' + index;
      const kind = getLedgerPerformanceKind(record);
      const current = units.get(unitKey);
      if (!current) units.set(unitKey, { kind, count: 1, grouped: Boolean(groupId), groupId, records: [record] });
      else {
        current.count += 1;
        current.records.push(record);
        if (weight[kind] > weight[current.kind]) current.kind = kind;
      }
    });
    units.forEach((unit) => {
      summary[unit.kind] += 1;
      if (unit.grouped && unit.count > 1) {
        summary.mergedGroups += 1;
        summary.groups.push({
          id: unit.groupId,
          source: 'manual',
          kind: unit.kind,
          points: weight[unit.kind] / 10,
          recordKeys: unit.records.map(getLedgerSelectionKey),
          skus: unit.records.map((record) => String(record && record.sku || '')).filter(Boolean),
        });
      }
    });
    manualSeriesGroups.forEach((group) => {
      summary.series += 1;
      summary.groups.push(group);
    });
    automaticGroups.forEach((group) => {
      summary.series += 1;
      summary.autoSeriesGroups += 1;
      summary.groups.push(group);
    });
    summary.total = (summary.design * 14 + summary.logo * 10 + summary.void * 5 + summary.extension * 3) / 10 + summary.series;
    return summary;
  }

  function formatLedgerPerformance(value) {
    const number = Math.round((Number(value) || 0) * 10) / 10;
    return Number.isInteger(number) ? String(number) : number.toFixed(1);
  }

  function getLedgerTodayPerformanceSummary() {
    const todayKey = getTodayKey();
    const records = getLedgerRecordsForMonth('finalized', getMonthKeyFromDateKey(todayKey))
      .filter((record) => getLedgerFinalizedDate(record) === todayKey);
    return { summary: summarizeLedgerPerformance(records), count: records.length };
  }

  function ledgerPerformanceHtml(summary, todayValue) {
    const value = summary || summarizeLedgerPerformance([]);
    const today = todayValue || getLedgerTodayPerformanceSummary();
    const breakdown = '设计 ' + value.design + ' × 1.4 · 换/无 Logo ' + value.logo + ' × 1 · 作废 ' + value.void + ' × 0.5 · 延伸 ' + value.extension + ' × 0.3 · 系列编组 ' + value.series + ' × 1（每 5 个）';
    const kindLabels = { design: '设计 1.4 分', logo: '换/无 Logo 1 分', void: '作废 0.5 分', extension: '延伸 0.3 分' };
    const groups = Array.isArray(value.groups) ? value.groups : [];
    const groupHtml = groups.length
      ? '<details class="pfh-ledger-merge-groups"><summary>绩效分组 ' + escapeHtml(String(groups.length)) + ' 组，点击展开组合明细</summary><div class="pfh-ledger-merge-list">' +
        groups.map((group) => {
          const isSeriesGroup = group.source === 'auto-series' || group.source === 'manual-series';
          const seriesLabel = group.source === 'manual-series' ? '手动系列' : '玩具系列';
          const title = isSeriesGroup
            ? getLedgerPerformanceGroupLabel(group, groups) + ' · ' + seriesLabel + ' 1 分 · ' + String((group.skus || []).length) + ' 个'
            : getLedgerPerformanceGroupLabel(group, groups) + ' · ' + (kindLabels[group.kind] || '');
          return '<button type="button" class="pfh-ledger-merge-group" data-action="ledger-highlight-performance-group" data-group-id="' + escapeHtml(group.id) + '" title="高亮这一组的产品卡片"><b>' + escapeHtml(title) + '</b><span>' + escapeHtml((group.seriesKey ? group.seriesKey + '：' : '') + (group.skus || []).join(' + ')) + '</span></button>';
        }).join('') +
        '</div></details>'
      : '';
    return '<div class="pfh-ledger-performance" aria-live="polite"><div class="pfh-ledger-performance-scores"><div class="pfh-ledger-performance-summary is-today"><div><span>当天绩效</span><small>今天已定稿 ' + escapeHtml(String(today.count || 0)) + ' 条</small></div><strong>' + escapeHtml(formatLedgerPerformance(today.summary && today.summary.total)) + '</strong></div><div class="pfh-ledger-performance-summary"><div><span>当月总绩效</span><small>' + escapeHtml(breakdown) + '</small></div><strong>' + escapeHtml(formatLedgerPerformance(value.total)) + '</strong></div></div>' + groupHtml + '</div>';
  }

  function refreshLedgerPerformanceSummary() {
    if (state.view !== 'ledger' || state.ledgerView !== 'finalized') return;
    const panel = document.getElementById(PANEL_ID);
    const current = panel && panel.querySelector('.pfh-ledger-performance');
    if (!current) return;
    const records = getLedgerRecordsForMonth('finalized', getCurrentLedgerMonth());
    current.outerHTML = ledgerPerformanceHtml(summarizeLedgerPerformance(records), getLedgerTodayPerformanceSummary());
  }

  function getLedgerPerformanceGroupLabel(group, groups) {
    const source = group && (group.source === 'auto-series' || group.source === 'manual-series') ? group.source : 'manual';
    const position = (groups || []).filter((item) => {
      const itemSource = item && (item.source === 'auto-series' || item.source === 'manual-series') ? item.source : 'manual';
      return itemSource === source;
    }).indexOf(group) + 1;
    return source === 'auto-series' ? '自动系列 ' + position : (source === 'manual-series' ? '手动系列 ' + position : '合并组 ' + position);
  }

  function getLedgerPerformanceGroupMaps(summary) {
    const labels = new Map();
    const recordGroupIds = new Map();
    const groups = summary && summary.groups || [];
    groups.forEach((group) => {
      const label = getLedgerPerformanceGroupLabel(group, groups);
      labels.set(group.id, label);
      (group.recordKeys || []).forEach((key) => recordGroupIds.set(key, group.id));
    });
    return { labels, recordGroupIds };
  }

  function isLedgerSeriesExcluded(record) {
    const sku = String(record && record.sku || '').trim().toUpperCase();
    return Boolean(record && record.seriesExcluded) || Boolean(sku && state.ledgerSeriesExcludedSkus && state.ledgerSeriesExcludedSkus.has(sku));
  }

  function highlightLedgerPerformanceGroup(groupId) {
    const id = String(groupId || '').trim();
    const panel = document.getElementById(PANEL_ID);
    if (!id || !panel) return;
    const cards = Array.from(panel.querySelectorAll('.pfh-ledger-item[data-performance-group-id="' + cssEscape(id) + '"]'));
    panel.querySelectorAll('.pfh-ledger-item.is-group-highlighted').forEach((card) => card.classList.remove('is-group-highlighted'));
    if (!cards.length) {
      showToast('当前列表中没有找到这一组合并产品');
      return;
    }
    cards.forEach((card) => card.classList.add('is-group-highlighted'));
    cards[0].scrollIntoView({ behavior: 'smooth', block: 'center', inline: 'nearest' });
    window.clearTimeout(state.ledgerGroupHighlightTimer);
    state.ledgerGroupHighlightTimer = window.setTimeout(() => {
      cards.forEach((card) => card.classList.remove('is-group-highlighted'));
      state.ledgerGroupHighlightTimer = 0;
    }, 2600);
    showToast('已高亮这一组的 ' + cards.length + ' 个产品');
  }

  function ledgerPerformanceMergeButtonHtml(records, selectedKeys) {
    const selected = selectedKeys instanceof Set ? selectedKeys : new Set(selectedKeys || []);
    const selectedRecords = (records || []).filter((record) => selected.has(getLedgerSelectionKey(record)));
    const selectedGroupId = String(selectedRecords[0] && selectedRecords[0].performanceGroupId || '');
    const canUnmerge = Boolean(selectedGroupId) && selectedRecords.every((record) => String(record.performanceGroupId || '') === selectedGroupId);
    const disabled = !canUnmerge && selectedRecords.length < 2;
    return '<span class="pfh-ledger-performance-merge-actions" style="display:contents">' +
      '<button type="button" class="pfh-ledger-performance-merge" data-action="' + (canUnmerge ? 'ledger-performance-unmerge' : 'ledger-performance-merge') + '" title="' + (canUnmerge ? '取消选中编码的绩效合并' : '将选中的多个编码合并为一个绩效单位') + '"' + (disabled ? ' disabled' : '') + '>' + (canUnmerge ? '取消合并' : '合并绩效') + '</button>' +
      '<button type="button" class="pfh-ledger-performance-merge" data-action="ledger-performance-group-open" title="不看产品名，按输入的 SKU 编码直接编组">按编码编组</button>' +
      '</span>';
  }

  function refreshLedgerPerformanceMergeButton() {
    if (state.view !== 'ledger' || state.ledgerView !== 'finalized') return;
    const panel = document.getElementById(PANEL_ID);
    const current = panel && panel.querySelector('.pfh-ledger-performance-merge-actions');
    if (!current) return;
    const records = getLedgerRecordsForMonth('finalized', getCurrentLedgerMonth());
    current.outerHTML = ledgerPerformanceMergeButtonHtml(records, new Set(state.ledgerSelectedKeys || []));
  }

  function getLedgerPerformanceGroupInputSummary(value) {
    const rawSkus = extractManualSkuCodes(value);
    const requested = rawSkus.slice(0, LEDGER_PERFORMANCE_GROUP_MAX_ITEMS);
    const records = getLedgerRecordsForMonth('finalized', getCurrentLedgerMonth());
    const bySku = new Map();
    records.forEach((record) => {
      const sku = getLedgerSkuKey(record && record.sku);
      if (sku && !bySku.has(sku)) bySku.set(sku, record);
    });
    const matched = [];
    const missing = [];
    requested.forEach((sku) => {
      const record = bySku.get(getLedgerSkuKey(sku));
      if (record) matched.push(record);
      else missing.push(sku);
    });
    return { requested, matched, missing, truncated: rawSkus.length > requested.length };
  }

  function ledgerPerformanceGroupPreviewText(summary) {
    const value = summary || { requested: [], matched: [], missing: [], truncated: false };
    if (!value.requested.length) return '等待输入 SKU 编码';
    let text = '已识别 ' + value.requested.length + ' 个，当前月份已定稿匹配 ' + value.matched.length + ' 个';
    if (value.missing.length) text += '，未找到 ' + value.missing.length + ' 个';
    if (value.truncated) text += '（最多处理 ' + LEDGER_PERFORMANCE_GROUP_MAX_ITEMS + ' 个）';
    return text;
  }

  function refreshLedgerPerformanceGroupPreview(layer) {
    if (!layer) return;
    const input = layer.querySelector('.pfh-ledger-performance-group-input');
    const summary = getLedgerPerformanceGroupInputSummary(input ? input.value : state.ledgerPerformanceGroupInput);
    const summaryNode = layer.querySelector('[data-ledger-performance-group-summary]');
    const detailNode = layer.querySelector('[data-ledger-performance-group-detail]');
    const submit = layer.querySelector('[data-action="ledger-performance-group-submit"]');
    if (summaryNode) summaryNode.textContent = ledgerPerformanceGroupPreviewText(summary);
    if (detailNode) {
      detailNode.textContent = summary.missing.length
        ? '未找到：' + summary.missing.join('、')
        : (summary.matched.length ? '将按编码归为同一个绩效单位，不读取产品名。' : '只匹配当前月份已定稿记录，产品名称不参与判断。');
      detailNode.title = summary.missing.join('、');
    }
    if (submit) submit.disabled = summary.matched.length < 2;
  }

  function ledgerPerformanceGroupModalHtml() {
    if (!state.ledgerPerformanceGroupOpen) return '';
    const summary = getLedgerPerformanceGroupInputSummary(state.ledgerPerformanceGroupInput);
    const status = state.ledgerPerformanceGroupStatus || '按当前月份已定稿记录匹配；系列名称不规则也可以直接编组。';
    return '<div class="pfh-ledger-time-modal pfh-ledger-performance-group-modal" data-action="ledger-performance-group-close" role="dialog" aria-modal="true" aria-label="按编码编组">' +
      '<div class="pfh-ledger-time-card" style="width:min(100%,520px)!important;max-height:calc(100% - 8px)!important;overflow:auto!important;">' +
        '<div class="pfh-ledger-time-head"><div><b>按编码编组</b><span>' + escapeHtml(getCurrentLedgerMonth()) + ' · 不依赖产品名称规则</span></div><button type="button" data-action="ledger-performance-group-close" aria-label="关闭">×</button></div>' +
        '<div class="pfh-ledger-performance-group-fields" style="display:flex!important;flex-direction:column!important;gap:8px!important;margin:16px 0 10px!important;">' +
          '<label style="display:grid!important;gap:6px!important;color:#73708d;font-size:11px;">产品编码（每行一个，也支持空格、逗号、分号）<textarea class="pfh-ledger-performance-group-input" rows="8" placeholder="例如：SKU00046398\nSKU00046397\nSKU00046396" style="width:100%;min-height:170px;resize:vertical;padding:10px;border:1px solid rgba(167,139,250,.32);border-radius:10px;outline:0;background:#fff;color:#30285e;font:inherit;font-size:12px;line-height:1.5;">' + escapeHtml(state.ledgerPerformanceGroupInput || '') + '</textarea></label>' +
          '<div style="display:grid;gap:4px;padding:8px 10px;border-radius:10px;background:rgba(240,237,255,.72);color:#6f6690;font-size:10px;line-height:1.45;"><strong data-ledger-performance-group-summary style="color:#5e36cc;font-size:11px;">' + escapeHtml(ledgerPerformanceGroupPreviewText(summary)) + '</strong><small data-ledger-performance-group-detail title="' + escapeHtml(summary.missing.join('、')) + '">' + escapeHtml(summary.missing.length ? '未找到：' + summary.missing.join('、') : (summary.matched.length ? '将按编码归为同一个绩效单位，不读取产品名。' : '只匹配当前月份已定稿记录，产品名称不参与判断。')) + '</small></div>' +
          '<p data-ledger-performance-group-status title="' + escapeHtml(status) + '" style="margin:0;color:#8d8aa8;font-size:10px;line-height:1.45;">' + escapeHtml(status) + '</p>' +
        '</div>' +
        '<div class="pfh-ledger-time-actions"><button type="button" data-action="ledger-performance-group-close">取消</button><button type="button" class="is-primary" data-action="ledger-performance-group-submit"' + (summary.matched.length < 2 ? ' disabled' : '') + '>确定编组</button></div>' +
      '</div></div>';
  }

  function getLedgerWorkflowFilterForMode(mode) {
    const value = String(state.ledgerFilterWorkflow || 'all');
    const allowed = mode === 'design'
      ? ['all', 'not-generated', 'generated-not-finalized']
      : (mode === 'finalized' ? ['all', 'box-pending', 'label-pending', 'image-pack-pending', 'any-file-pending'] : ['all']);
    return allowed.includes(value) ? value : 'all';
  }

  function ledgerWorkflowFilterHtml(mode) {
    if (mode === 'trash') return '';
    const selected = getLedgerWorkflowFilterForMode(mode);
    const options = mode === 'design'
      ? [
        ['all', '全部待定稿'],
        ['not-generated', '未出图'],
        ['generated-not-finalized', '出图未定稿'],
      ]
      : [
        ['image-pack-pending', '图包未做'],
        ['all', '全部已定稿'],
        ['box-pending', '纸盒未做'],
        ['label-pending', '标签未做'],
        ['any-file-pending', '任一文件未做'],
      ];
    return '<select class="pfh-ledger-filter-workflow" aria-label="' + escapeHtml(mode === 'design' ? '出图流程筛选' : '文件制作筛选') + '">' + options.map(([value, label]) => '<option value="' + escapeHtml(value) + '"' + (selected === value ? ' selected' : '') + '>' + escapeHtml(label) + '</option>').join('') + '</select>';
  }

  function isLedgerFilePending(value, doneFallback) {
    return normalizeLedgerFileState(value, doneFallback) === 'pending';
  }

  function matchesLedgerWorkflowFilter(record, mode, filter) {
    if (filter === 'all') return true;
    if (mode === 'design') {
      const imageGenerated = Boolean(record && record.imageGeneratedAt);
      return filter === 'not-generated' ? !imageGenerated : (filter === 'generated-not-finalized' ? imageGenerated : true);
    }
    if (mode !== 'finalized') return true;
    if (filter === 'box-pending') return isLedgerFilePending(record && record.boxFileState, record && record.boxFileDone);
    if (filter === 'label-pending') return isLedgerFilePending(record && record.labelFileState, record && record.labelFileDone);
    if (filter === 'image-pack-pending') return isLedgerFilePending(record && record.imagePackState, record && record.imagePackDone);
    if (filter === 'any-file-pending') return [['boxFileState', 'boxFileDone'], ['labelFileState', 'labelFileDone'], ['imagePackState', 'imagePackDone']].some(([field, doneField]) => isLedgerFilePending(record && record[field], record && record[doneField]));
    return true;
  }

  function getLedgerStatusFilterForMode(mode) {
    const value = String(state.ledgerFilterStatus || 'all');
    const allowed = mode === 'design'
      ? ['all', '待出图', '待定稿', '异常', 'ai-error']
      : (mode === 'finalized' ? ['all', '已定稿', '已完成', '作废', '异常', 'ai-error'] : ['all', '异常', 'ai-error']);
    return allowed.includes(value) ? value : 'all';
  }

  function ledgerStatusFilterHtml(mode) {
    const selected = getLedgerStatusFilterForMode(mode);
    const options = mode === 'design'
      ? [['all', '全部状态'], ['待出图', '待出图'], ['待定稿', '待定稿'], ['异常', '异常'], ['ai-error', 'AI 异常']]
      : (mode === 'finalized'
        ? [['all', '全部状态'], ['已定稿', '已定稿'], ['已完成', '已完成'], ['作废', '作废'], ['异常', '异常'], ['ai-error', 'AI 异常']]
        : [['all', '全部状态'], ['待出图', '待出图'], ['待定稿', '待定稿'], ['已定稿', '已定稿'], ['已完成', '已完成'], ['异常', '异常'], ['ai-error', 'AI 异常']]);
    return '<select class="pfh-ledger-filter-status" aria-label="状态筛选">' + options.map(([value, label]) => '<option value="' + escapeHtml(value) + '"' + (selected === value ? ' selected' : '') + '>' + escapeHtml(label) + '</option>').join('') + '</select>';
  }

  function filterLedgerWorkbenchRecords(records, mode) {
    const query = String(state.ledgerFilterQuery || '').trim().toLowerCase();
    const tokens = parseSearchTokens(query);
    const statusFilter = getLedgerStatusFilterForMode(mode);
    const imageFilter = String(state.ledgerFilterImage || 'all');
    const workflowFilter = getLedgerWorkflowFilterForMode(mode);
    return (records || []).filter((record) => {
      if (tokens.length) {
        const haystack = [record.sku, record.brand, record.name, record.designType, record.artPriority, record.packageCode, record.printCode, record.developerName].filter(Boolean).join(' ').toLowerCase();
        if (!tokens.every((token) => haystack.includes(token))) return false;
      }
      const finalized = isLedgerFinalizedRecord(record);
      const imageGenerated = Boolean(record.imageGeneratedAt);
      const workflow = /^(?:作废|已完成|异常)$/.test(record.status || '') ? record.status : (finalized ? '已定稿' : (imageGenerated ? '待定稿' : '待出图'));
      if (statusFilter !== 'all') {
        if (statusFilter === 'ai-error') {
          if (!/^(?:error|needs-|task-error|result-missing)/.test(normalizeLedgerAiImageStatus(record.aiImageStatus, record.aiImageMessage))) return false;
        } else if (workflow !== statusFilter) return false;
      }
      if (!matchesLedgerWorkflowFilter(record, mode, workflowFilter)) return false;
      const preferredImage = mode === 'design' ? record.benchmarkImageUrl : record.skuImageUrl;
      if (imageFilter === 'benchmark' && !record.benchmarkImageUrl) return false;
      if (imageFilter === 'effect' && !record.skuImageUrl) return false;
      if (imageFilter === 'missing' && preferredImage) return false;
      return true;
    });
  }

  function ledgerTableRowsHtml(records, mode) {
    if (!records.length) return '<div class="pfh-ledger-empty">当前筛选条件下没有记录。</div>';
    const rows = records.map((record) => {
      const finalized = isLedgerFinalizedRecord(record);
      const workflow = /^(?:作废|已完成|异常)$/.test(record.status || '') ? record.status : (finalized ? '已定稿' : (record.imageGeneratedAt ? '待定稿' : '待出图'));
      const ai = getLedgerAiImageStatusMeta(record).label;
      const date = mode === 'finalized' ? getLedgerFinalizedDate(record) : getLedgerDesignDate(record);
      return '<tr><td class="pfh-ledger-table-sku-cell"><button type="button" class="pfh-ledger-table-sku" data-action="ledger-copy-sku" data-ledger-table-sku="' + escapeHtml(record.sku) + '" data-sku="' + escapeHtml(record.sku) + '" title="单击复制；按住并向下拖可连续复制编码">' + escapeHtml(record.sku) + '</button></td><td>' + escapeHtml([record.brand, record.name].filter(Boolean).join(' ')) + '</td><td>' + escapeHtml(record.designType || '') + '</td><td>' + escapeHtml(record.artPriority || '') + '</td><td>' + escapeHtml(workflow) + '</td><td>' + escapeHtml(date || '') + '</td><td>' + escapeHtml(record.purchasePrice || '') + '</td><td>' + escapeHtml(ledgerFileStateLabel(record.boxFileState)) + '</td><td>' + escapeHtml(ledgerFileStateLabel(record.labelFileState)) + '</td><td>' + escapeHtml(ledgerFileStateLabel(record.imagePackState)) + '</td><td>' + escapeHtml(ai) + '</td></tr>';
    }).join('');
    return '<div class="pfh-ledger-table-wrap"><table class="pfh-ledger-table"><thead><tr><th>SKU</th><th>产品</th><th>设计类型</th><th>优先级</th><th>状态</th><th>日期</th><th>价格</th><th>纸盒</th><th>标签</th><th>图包</th><th>AI 生图</th></tr></thead><tbody>' + rows + '</tbody></table></div>';
  }

  function getVisibleLedgerWorkbenchRecords() {
    const mode = state.ledgerView === 'trash' ? 'trash' : (state.ledgerView === 'finalized' ? 'finalized' : 'design');
    return filterLedgerWorkbenchRecords(getLedgerRecordsForMonth(state.ledgerView, getCurrentLedgerMonth()), mode);
  }

  function copyLedgerWorkbenchTable(asTsv) {
    const records = getVisibleLedgerWorkbenchRecords();
    const text = asTsv
      ? ['SKU\t产品\t设计类型\t优先级\t状态\t日期\t价格\t纸盒\t标签\t图包\tAI生图'].concat(records.map((record) => [record.sku, [record.brand, record.name].filter(Boolean).join(' '), record.designType || '', record.artPriority || '', record.status || '', state.ledgerView === 'finalized' ? getLedgerFinalizedDate(record) : getLedgerDesignDate(record), record.purchasePrice || '', ledgerFileStateLabel(record.boxFileState), ledgerFileStateLabel(record.labelFileState), ledgerFileStateLabel(record.imagePackState), getLedgerAiImageStatusMeta(record).label].join('\t'))).join('\n')
      : records.map((record) => record.sku).filter(Boolean).join('\n');
    copyText(text);
    showToast('已复制 ' + records.length + ' 条' + (asTsv ? '表格' : '编码'));
  }

  let ledgerTableSkuDragSession = null;

  function getLedgerTableSkuButtonAtPoint(clientX, clientY, wrapper) {
    const hit = document.elementFromPoint(clientX, clientY);
    const row = hit && hit.closest && hit.closest('.pfh-ledger-table tbody tr');
    const button = row && row.querySelector('.pfh-ledger-table-sku[data-ledger-table-sku]');
    return button && wrapper && wrapper.contains(button) ? button : null;
  }

  function ensureLedgerTableSkuDragTip(panel) {
    let tip = panel && panel.querySelector('.pfh-ledger-drag-copy-tip');
    if (!tip && panel) {
      tip = document.createElement('div');
      tip.className = 'pfh-ledger-drag-copy-tip';
      tip.setAttribute('aria-hidden', 'true');
      (panel.querySelector('.pfh-full') || panel).appendChild(tip);
    }
    return tip;
  }

  function updateLedgerTableSkuDragSelection(button, clientX, clientY) {
    const session = ledgerTableSkuDragSession;
    if (!session || !button) return;
    const currentIndex = session.buttons.indexOf(button);
    if (currentIndex < 0) return;
    const distance = Math.hypot(clientX - session.startX, clientY - session.startY);
    if (currentIndex !== session.startIndex || distance >= 6) session.active = true;
    if (!session.active) return;
    const lower = Math.min(session.startIndex, currentIndex);
    const upper = Math.max(session.startIndex, currentIndex);
    session.selectedButtons = session.buttons.slice(lower, upper + 1);
    session.buttons.forEach((item, index) => item.classList.toggle('is-drag-selected', index >= lower && index <= upper));
    session.panel.classList.add('is-ledger-sku-dragging');
    const tip = ensureLedgerTableSkuDragTip(session.panel);
    if (tip) {
      tip.textContent = '松开复制 ' + session.selectedButtons.length + ' 个编码';
      tip.style.left = Math.min(window.innerWidth - 142, clientX + 14) + 'px';
      tip.style.top = Math.min(window.innerHeight - 36, clientY + 14) + 'px';
      tip.classList.add('is-visible');
    }
  }

  function runLedgerTableSkuAutoScroll() {
    const session = ledgerTableSkuDragSession;
    if (!session || !session.autoScrollSpeed) return;
    session.wrapper.scrollTop += session.autoScrollSpeed;
    const button = getLedgerTableSkuButtonAtPoint(session.clientX, session.clientY, session.wrapper);
    if (button) updateLedgerTableSkuDragSelection(button, session.clientX, session.clientY);
    session.autoScrollFrame = window.requestAnimationFrame(runLedgerTableSkuAutoScroll);
  }

  function handleLedgerTableSkuPointerDown(event) {
    if (state.view !== 'ledger' || state.ledgerDisplayMode !== 'table' || event.button !== 0) return;
    const button = event.target && event.target.closest && event.target.closest('.pfh-ledger-table-sku[data-ledger-table-sku]');
    const wrapper = button && button.closest('.pfh-ledger-table-wrap');
    if (!button || !wrapper) return;
    const buttons = Array.from(wrapper.querySelectorAll('.pfh-ledger-table-sku[data-ledger-table-sku]'));
    const startIndex = buttons.indexOf(button);
    if (startIndex < 0) return;
    resetLedgerTableSkuDrag(false);
    ledgerTableSkuDragSession = {
      pointerId: event.pointerId,
      panel: event.currentTarget,
      wrapper,
      button,
      buttons,
      startIndex,
      startX: event.clientX,
      startY: event.clientY,
      clientX: event.clientX,
      clientY: event.clientY,
      selectedButtons: [button],
      active: false,
      autoScrollSpeed: 0,
      autoScrollFrame: 0,
    };
    try { button.setPointerCapture(event.pointerId); } catch (_) {}
  }

  function handleLedgerTableSkuPointerMove(event) {
    const session = ledgerTableSkuDragSession;
    if (!session || event.pointerId !== session.pointerId) return;
    session.clientX = event.clientX;
    session.clientY = event.clientY;
    const button = getLedgerTableSkuButtonAtPoint(event.clientX, event.clientY, session.wrapper);
    if (button) updateLedgerTableSkuDragSelection(button, event.clientX, event.clientY);
    const rect = session.wrapper.getBoundingClientRect();
    const edge = 42;
    session.autoScrollSpeed = event.clientY > rect.bottom - edge ? Math.min(18, Math.max(4, (event.clientY - rect.bottom + edge) * 0.45))
      : (event.clientY < rect.top + edge ? -Math.min(18, Math.max(4, (rect.top + edge - event.clientY) * 0.45)) : 0);
    if (session.autoScrollSpeed && !session.autoScrollFrame) session.autoScrollFrame = window.requestAnimationFrame(runLedgerTableSkuAutoScroll);
    if (!session.autoScrollSpeed && session.autoScrollFrame) {
      window.cancelAnimationFrame(session.autoScrollFrame);
      session.autoScrollFrame = 0;
    }
    if (session.active) event.preventDefault();
  }

  function handleLedgerTableSkuPointerEnd(event) {
    const session = ledgerTableSkuDragSession;
    if (!session || event.pointerId !== session.pointerId) return;
    const active = session.active && session.selectedButtons.length > 1;
    const skus = active ? session.selectedButtons.map((button) => button.getAttribute('data-ledger-table-sku') || '').filter(Boolean) : [];
    try { session.button.releasePointerCapture(event.pointerId); } catch (_) {}
    resetLedgerTableSkuDrag(false);
    if (!active || !skus.length) return;
    event.preventDefault();
    state.ledgerSkuDragSuppressClickUntil = Date.now() + 700;
    copyText(skus.join('\n'));
    showToast('已连续复制 ' + skus.length + ' 个编码');
  }

  function resetLedgerTableSkuDrag(clearSuppressClick) {
    const session = ledgerTableSkuDragSession;
    if (session && session.autoScrollFrame) window.cancelAnimationFrame(session.autoScrollFrame);
    ledgerTableSkuDragSession = null;
    const panel = document.getElementById(PANEL_ID);
    if (panel) {
      panel.classList.remove('is-ledger-sku-dragging');
      panel.querySelectorAll('.pfh-ledger-table-sku.is-drag-selected').forEach((button) => button.classList.remove('is-drag-selected'));
      const tip = panel.querySelector('.pfh-ledger-drag-copy-tip');
      if (tip) tip.remove();
    }
    if (clearSuppressClick) state.ledgerSkuDragSuppressClickUntil = 0;
  }

  let ledgerCardSelectionDragSession = null;

  function getLedgerCardSelectionKey(card) {
    if (!card) return '';
    return getLedgerSelectionKey({
      sku: card.getAttribute('data-ledger-sku') || '',
      date: normalizeLedgerDate(card.getAttribute('data-ledger-date') || ''),
    });
  }

  function getLedgerCardAtPoint(clientX, clientY, wrapper) {
    const hit = document.elementFromPoint(clientX, clientY);
    const card = hit && hit.closest && hit.closest('.pfh-ledger-item.is-clickable[data-ledger-sku]');
    return card && wrapper && wrapper.contains(card) ? card : null;
  }

  function syncLedgerCardSelectionClasses(panel) {
    if (!panel) return;
    const selected = new Set(state.ledgerSelectedKeys || []);
    panel.querySelectorAll('.pfh-ledger-item.is-clickable[data-ledger-sku]').forEach((card) => {
      const isSelected = selected.has(getLedgerCardSelectionKey(card));
      card.classList.toggle('is-selected', isSelected);
      card.setAttribute('aria-pressed', isSelected ? 'true' : 'false');
    });
  }

  function updateLedgerCardSelectionRange(card, clientX, clientY) {
    const session = ledgerCardSelectionDragSession;
    if (!session || !card) return;
    const currentIndex = session.cards.indexOf(card);
    if (currentIndex < 0) return;
    const distance = Math.hypot(clientX - session.startX, clientY - session.startY);
    if (currentIndex !== session.startIndex || distance >= 6) session.active = true;
    if (!session.active) return;
    const lower = Math.min(session.startIndex, currentIndex);
    const upper = Math.max(session.startIndex, currentIndex);
    const selected = new Set(session.baseSelectedKeys);
    session.cards.slice(lower, upper + 1).forEach((item) => {
      const key = getLedgerCardSelectionKey(item);
      if (key) selected.add(key);
      if (key && session.selectionMode === 'remove') selected.delete(key);
    });
    state.ledgerSelectedKeys = Array.from(selected);
    syncLedgerCardSelectionClasses(session.panel);
    session.panel.classList.add('is-ledger-card-dragging');
  }

  function handleLedgerCardSelectionPointerDown(event) {
    if (state.view !== 'ledger' || state.ledgerDisplayMode !== 'cards' || state.ledgerView === 'trash' || event.button !== 0) return;
    const card = event.target && event.target.closest && event.target.closest('.pfh-ledger-item.is-clickable[data-ledger-sku]');
    const interactive = event.target && event.target.closest && event.target.closest('button,a,input,textarea,select,label,[contenteditable="true"]');
    const wrapper = card && card.closest('.pfh-ledger-list');
    if (!card || interactive || !wrapper) return;
    const cards = Array.from(wrapper.querySelectorAll('.pfh-ledger-item.is-clickable[data-ledger-sku]'));
    const startIndex = cards.indexOf(card);
    if (startIndex < 0) return;
    resetLedgerCardSelectionDrag();
    ledgerCardSelectionDragSession = {
      pointerId: event.pointerId,
      panel: event.currentTarget,
      wrapper,
      card,
      cards,
      startIndex,
      startX: event.clientX,
      startY: event.clientY,
      baseSelectedKeys: new Set(state.ledgerSelectedKeys || []),
      selectionMode: (state.ledgerSelectedKeys || []).includes(getLedgerCardSelectionKey(card)) ? 'remove' : 'add',
      active: false,
    };
    try { card.setPointerCapture(event.pointerId); } catch (_) {}
  }

  function handleLedgerCardSelectionPointerMove(event) {
    const session = ledgerCardSelectionDragSession;
    if (!session || event.pointerId !== session.pointerId) return;
    const card = getLedgerCardAtPoint(event.clientX, event.clientY, session.wrapper);
    if (card) updateLedgerCardSelectionRange(card, event.clientX, event.clientY);
    if (session.active) event.preventDefault();
  }

  function handleLedgerCardSelectionPointerEnd(event) {
    const session = ledgerCardSelectionDragSession;
    if (!session || event.pointerId !== session.pointerId) return;
    const active = session.active;
    try { session.card.releasePointerCapture(event.pointerId); } catch (_) {}
    resetLedgerCardSelectionDrag();
    if (!active) return;
    event.preventDefault();
    state.ledgerSkuDragSuppressClickUntil = Date.now() + 700;
    refreshLedgerPerformanceMergeButton();
  }

  function resetLedgerCardSelectionDrag() {
    const session = ledgerCardSelectionDragSession;
    ledgerCardSelectionDragSession = null;
    const panel = session && session.panel || document.getElementById(PANEL_ID);
    if (panel) panel.classList.remove('is-ledger-card-dragging');
  }

  function getLedgerThumbnailUrl(url) {
    const source = String(url || '').trim();
    if (!source) return '';
    try {
      const parsed = new URL(source, window.location.origin);
      const hostname = String(parsed.hostname || '').toLowerCase();
      const isOssHost = hostname === 'oss-pro.plm.westmonth.cn'
        || hostname === 'oss-cn-shenzhen.aliyuncs.com'
        || hostname.endsWith('.oss-cn-shenzhen.aliyuncs.com');
      if (!/^https?:$/.test(parsed.protocol) || !isOssHost) return source;
      if (/(?:^|&)(?:ossaccesskeyid|signature|expires|x-oss-signature|x-oss-credential|x-oss-security-token)=/i.test(parsed.search.slice(1))) return source;
      parsed.searchParams.delete('x-oss-process');
      parsed.searchParams.set('x-oss-process', 'image/resize,w_240/quality,q_80');
      return parsed.href;
    } catch (_) {
      return source;
    }
  }

  function ledgerSelectionToolbarHtml(records, selectedKeys) {
    const selected = selectedKeys instanceof Set ? selectedKeys : new Set(selectedKeys || []);
    const visibleRecords = Array.isArray(records) ? records : [];
    const selectedCount = visibleRecords.filter((record) => selected.has(getLedgerSelectionKey(record))).length;
    const total = visibleRecords.length;
    return '<span class="pfh-ledger-selection-count" aria-live="polite" title="选中多个产品后，点击任一卡片的纸盒、标签或图包按钮，会同步对应状态">已选 ' + escapeHtml(String(selectedCount)) + ' / ' + escapeHtml(String(total)) + '</span>' +
      '<button type="button" data-action="ledger-select-all"' + (total ? '' : ' disabled') + '>全选</button>' +
      '<button type="button" data-action="ledger-clear-selection"' + (selected.size ? '' : ' disabled') + '>取消全选</button>';
  }

  function ledgerViewContentHtml(records) {
    const mode = state.ledgerView === 'trash' ? 'trash' : (state.ledgerView === 'finalized' ? 'finalized' : 'design');
    const filteredRecords = filterLedgerWorkbenchRecords(records, mode);
    const groups = groupLedgerRecordsByDate(filteredRecords, mode === 'trash' ? 'design' : mode);
    const performanceSummary = mode === 'finalized' ? summarizeLedgerPerformance(filteredRecords) : null;
    const performanceHtml = performanceSummary ? ledgerPerformanceHtml(performanceSummary, getLedgerTodayPerformanceSummary()) : '';
    const performanceGroupMaps = getLedgerPerformanceGroupMaps(performanceSummary);
    const selectedKeys = new Set(state.ledgerSelectedKeys || []);
    const mergePerformanceHtml = mode === 'finalized' ? ledgerPerformanceMergeButtonHtml(records, selectedKeys) : '';
    const selectionToolbarHtml = mode === 'finalized' ? ledgerSelectionToolbarHtml(filteredRecords, selectedKeys) : '';
    const rows = groups.length ? groups.map((group) => {
      const allSelected = mode === 'finalized' && group.items.length && group.items.every((record) => selectedKeys.has(getLedgerSelectionKey(record)));
      const daySelect = mode === 'finalized' ? '<button type="button" class="pfh-ledger-day-select' + (allSelected ? ' is-selected' : '') + '" data-action="ledger-select-date" data-date="' + escapeHtml(group.date) + '">' + (allSelected ? '取消当天' : '选择当天') + '</button>' : '';
      return '<section class="pfh-ledger-day"><h4><span class="pfh-ledger-day-date">' + escapeHtml(formatLedgerDateLabel(group.date)) + '</span><span class="pfh-ledger-day-count">' + escapeHtml(String(group.items.length)) + ' 条</span>' + daySelect + '</h4>' + group.items.map((record) => mode === 'trash' ? ledgerTrashRowHtml(record) : ledgerRowHtml(record, mode, performanceGroupMaps.labels, performanceGroupMaps.recordGroupIds)).join('') + '</section>';
    }).join('') : '<div class="pfh-ledger-empty">' + escapeHtml(records.length ? '当前筛选条件下没有记录。' : (mode === 'trash' ? '本月垃圾篓是空的。' : (mode === 'finalized' ? '本月还没有已定稿记录。' : '本月还没有出图记录。打开设计分配在本月的 PLM 详情后会自动加入。'))) + '</div>';
    const month = getCurrentLedgerMonth();
    const ledgerScrollContext = ['ledger', mode, month].join('|');
    const toolsCollapsed = Boolean(state.ledgerToolsCollapsed);
    const toolsTitle = performanceHtml ? '绩效与筛选' : '筛选与操作';
    return '<section class="pfh-ledger-tools-panel' + (toolsCollapsed ? ' is-collapsed' : '') + '">' +
      '<button type="button" class="pfh-ledger-tools-toggle" data-action="ledger-toggle-tools" aria-expanded="' + (toolsCollapsed ? 'false' : 'true') + '"><span class="pfh-ledger-tools-toggle-copy"><strong>' + toolsTitle + '</strong><small>收起后列表会展示更多产品</small></span><span class="pfh-ledger-tools-toggle-state" data-ledger-tools-state>' + (toolsCollapsed ? '展开' : '收起') + '</span><span class="pfh-ledger-tools-toggle-chevron" aria-hidden="true">⌄</span></button>' +
      '<div class="pfh-ledger-tools-body">' +
      performanceHtml +
      '<div class="pfh-ledger-controlbar"><div class="pfh-ledger-toolbar">' +
        '<button type="button" class="pfh-ledger-month" data-action="ledger-prev-month" title="上个月">‹</button>' +
        '<button type="button" class="pfh-ledger-month-label" data-action="ledger-today">' + escapeHtml(formatLedgerMonthLabel(month)) + '</button>' +
        '<button type="button" class="pfh-ledger-month" data-action="ledger-next-month" title="下个月">›</button>' +
        '<button type="button" data-action="ledger-today">本月</button>' +
        (mode === 'trash'
          ? '<button type="button" data-action="ledger-trash-empty"' + (records.length ? '' : ' disabled') + '>清空本月垃圾篓</button>'
          : mergePerformanceHtml +
            selectionToolbarHtml +
            '<button type="button" data-action="ledger-copy" title="导出已定稿内容到登记表">导出到登记</button>' +
            '<button type="button" data-action="ledger-copy-selected" title="复制当前勾选的产品编码">复制选中编码</button>' +
            '<button type="button" data-action="ledger-copy-video" title="复制选中产品的视频申请内容">制作视频</button>') +
      '</div>' +
      '<div class="pfh-ledger-filterbar"><input type="search" class="pfh-ledger-filter-query" value="' + escapeHtml(state.ledgerFilterQuery || '') + '" placeholder="筛选 SKU / 品牌 / 品名 / 编码">' + ledgerStatusFilterHtml(mode) + ledgerWorkflowFilterHtml(mode) + '<select class="pfh-ledger-filter-image"><option value="all">全部图片</option><option value="benchmark"' + (state.ledgerFilterImage === 'benchmark' ? ' selected' : '') + '>有对标图</option><option value="effect"' + (state.ledgerFilterImage === 'effect' ? ' selected' : '') + '>有效果图</option><option value="missing"' + (state.ledgerFilterImage === 'missing' ? ' selected' : '') + '>缺当前图</option></select><button type="button" data-action="ledger-copy-filtered-skus">复制当前编码</button><button type="button" data-action="ledger-copy-filtered-table">复制当前表格</button><div class="pfh-ledger-view-switch"><button type="button" data-action="ledger-display-mode" data-mode="cards" class="' + (state.ledgerDisplayMode === 'cards' ? 'is-active' : '') + '">卡片</button><button type="button" data-action="ledger-display-mode" data-mode="table" class="' + (state.ledgerDisplayMode === 'table' ? 'is-active' : '') + '">表格</button></div></div></div>' +
      '</div></section>' +
      (state.ledgerDisplayMode === 'table' ? ledgerTableRowsHtml(filteredRecords, mode) : '<div class="pfh-ledger-list" data-scroll-context="' + escapeHtml(ledgerScrollContext) + '">' + rows + '</div>') +
      ledgerTimeEditorHtml() +
      ledgerPerformanceGroupModalHtml();
  }

  function ledgerViewHtml(records) {
    const mode = state.ledgerView === 'trash' ? 'trash' : (state.ledgerView === 'finalized' ? 'finalized' : 'design');
    const month = getCurrentLedgerMonth();
    const ledgerScrollContext = ['ledger', mode, month].join('|');
    return '<div class="pfh-detail-scroll" data-scroll-context="' + escapeHtml(ledgerScrollContext) + '"><section class="pfh-ledger-page">' +
      '<div class="pfh-ledger-hero"><button type="button" class="pfh-upload-back pfh-ledger-back" data-action="home-back" aria-label="返回主页">' + iconHtml('backArrow') + '</button><div class="pfh-ledger-hero-copy"><h3>今日工作台</h3><p data-ledger-hero-note>' + escapeHtml(mode === 'trash' ? '移除记录会阻止 PLM 再次自动加入，恢复后才解除拦截。' : (mode === 'finalized' ? '默认只显示图包未完成；选中多个产品后，点击纸盒、标签或图包会同步选中产品，图包完成后自动收纳。' : '按设计分配日期整理出图，定稿后继续跟纸盒、标签和图包。')) + '</p></div><div class="pfh-ledger-hero-actions"><span data-ledger-record-count>' + escapeHtml(records.length + ' 条 / ' + month) + '</span><button type="button" class="pfh-ledger-fullscreen-toggle" data-action="ledger-fullscreen-toggle" aria-pressed="' + (state.ledgerFullscreen ? 'true' : 'false') + '" title="' + (state.ledgerFullscreen ? '返回悬浮窗' : '打开专注工作区') + '">' + (state.ledgerFullscreen ? '退出工作区' : '全屏工作区') + '</button></div><div class="pfh-ledger-hero-tabs"><div class="pfh-ledger-tabs-shell">' +
           '<div class="pfh-ledger-tabs-main"><div class="pfh-ledger-tabs" data-active-tab="' + mode + '">' +
             '<span class="pfh-ledger-tab-indicator" aria-hidden="true"></span>' +
             '<button type="button" class="' + (mode === 'design' ? 'is-active active' : '') + '" data-action="ledger-view-design">待定稿</button>' +
             '<button type="button" class="' + (mode === 'finalized' ? 'is-active active' : '') + '" data-action="ledger-view-finalized">已定稿</button>' +
           '</div></div>' +
           '<button type="button" class="pfh-ledger-trash-entry' + (mode === 'trash' ? ' is-active' : '') + '" data-action="ledger-view-trash" aria-current="' + (mode === 'trash' ? 'page' : 'false') + '"><span>垃圾篓</span><small>低频入口</small></button>' +
         '</div></div></div>' +
       '<div class="pfh-ledger-workbench-shell"><div class="pfh-ledger-content-anchor">' +
           ledgerViewContentHtml(records) +
         '</div>' +
       '</div>' +
       '</section></div>';
  }

  function ledgerRowHtml(record, mode, performanceGroupLabels, performanceRecordGroupIds) {
    const sku = record.sku || '';
    const title = [record.brand, record.name].filter(Boolean).join(' ') || sku;
    const thumbUrl = record.skuImageUrl || record.benchmarkImageUrl;
    const thumbnailUrl = getLedgerThumbnailUrl(thumbUrl);
    const thumb = thumbUrl
      ? '<span class="pfh-ledger-thumb-frame"><img src="' + escapeHtml(thumbnailUrl || thumbUrl) + '" alt="" loading="lazy" decoding="async"></span>'
      : '<span class="pfh-ledger-thumb-empty">' + iconHtml('image') + '</span>';
    const imageGenerated = Boolean(record.imageGeneratedAt);
    const workDate = mode === 'finalized' ? getLedgerFinalizedDate(record) : getLedgerDesignDate(record);
    const designType = record.designType || '未分类';
    const artPriority = record.artPriority || '';
    const priorityClass = /^P0.*(?:紧急|urgent)/i.test(artPriority) ? ' is-p0-urgent' : (/^P0.*(?:当日|当天|today)/i.test(artPriority) ? ' is-p0-today' : (/^P0/i.test(artPriority) ? ' is-p0-urgent' : (/^P1/i.test(artPriority) ? ' is-p1' : '')));
    const packageCode = record.packageCode || '';
    const printCode = record.printCode || '';
    const purchasePrice = String(record.purchasePrice || '').trim();
    const dateAttr = escapeHtml(record.date || workDate);
    const selected = (state.ledgerSelectedKeys || []).includes(getLedgerSelectionKey(record));
    const effectivePerformanceGroupId = (performanceRecordGroupIds && performanceRecordGroupIds.get(getLedgerSelectionKey(record))) || record.performanceGroupId || '';
    const dateText = mode === 'finalized'
      ? ((record.status === '作废' ? '作废 ' : '定稿 ') + (record.finalizedAt ? formatLedgerMinuteLabel(record.finalizedAt, workDate) : formatLedgerDateLabel(workDate)))
      : ('分配 ' + formatLedgerMinuteLabel(record.designAssignedAt || workDate, workDate));
    const tagHtml = '<div class="pfh-ledger-tags">' +
      '<button type="button" class="is-sku" data-action="ledger-copy-sku" data-sku="' + escapeHtml(sku) + '" title="点击复制产品编码">' + escapeHtml(sku) + '</button>' +
      '<span class="is-design-type" title="设计类型">' + escapeHtml(designType) + '</span>' +
      (artPriority ? '<span class="is-priority' + priorityClass + '" title="美工处理优先级">' + escapeHtml(artPriority) + '</span>' : '') +
      (record.performanceType === 'extension' ? '<span class="is-extension" title="绩效按 0.3 分计算">延伸 · 0.3</span>' : '') +
      (isLedgerSeriesExcluded(record) ? '<span class="is-series-excluded" title="已手动剔除自动系列">已剔除系列</span>' : '') +
      (performanceGroupLabels && performanceGroupLabels.get(effectivePerformanceGroupId) ? '<span class="is-performance-group" title="此编码已纳入绩效分组">' + escapeHtml(performanceGroupLabels.get(effectivePerformanceGroupId)) + '</span>' : '') +
      '</div>';
    const assignmentHtml = '<div class="pfh-ledger-assignment">' + escapeHtml(dateText) +
      (mode === 'finalized' ? '<button type="button" class="pfh-ledger-edit-time" data-action="ledger-edit-finalized-time" data-sku="' + escapeHtml(sku) + '" data-date="' + dateAttr + '">改时间</button>' : '') +
      '</div>';
    const stageClass = record.finalizedAt || mode === 'finalized'
      ? ' is-stage-finalized'
      : (imageGenerated ? ' is-stage-generated' : ' is-stage-pending');
    const menuHtml = ledgerOverflowMenuHtml(record, sku, dateAttr, imageGenerated);
    const menuOpen = state.ledgerMenuSku === sku && state.ledgerMenuDate === normalizeLedgerDate(record.date || workDate);
    const moreButton = '<div class="pfh-ledger-more"><button type="button" data-action="ledger-more" data-sku="' + escapeHtml(sku) + '" data-date="' + dateAttr + '" aria-label="更多操作" aria-expanded="' + (menuOpen ? 'true' : 'false') + '"><span class="pfh-more-dots"><i></i><i></i><i></i></span></button>' + menuHtml + '</div>';
    const actions = mode === 'finalized'
      ? '<div class="pfh-ledger-file-actions">' +
        ledgerArtworkStateButtonHtml(record, sku, dateAttr) +
        ledgerFileButtonHtml('ledger-toggle-box-file', sku, dateAttr, '纸盒', packageCode, record.boxFileState, record.boxFileDone) +
        ledgerFileButtonHtml('ledger-toggle-label-file', sku, dateAttr, '标签', printCode, record.labelFileState, record.labelFileDone) +
        ledgerFileButtonHtml('ledger-toggle-image-pack', sku, dateAttr, '图包', '', record.imagePackState, record.imagePackDone) +
        moreButton +
      '</div>'
      : '<div class="pfh-ledger-actions">' +
        (!imageGenerated ? '<button type="button" class="is-primary is-generate" data-action="ledger-image-generated" data-sku="' + escapeHtml(sku) + '" data-date="' + dateAttr + '"><span>出图</span></button>' : (record.finalizedAt ? '<span class="pfh-ledger-complete">已定稿</span>' : '<label class="pfh-ledger-price' + (state.ledgerFlowTransitionSku === sku ? ' is-flow-transition' : '') + '"><span>¥</span><input type="text" inputmode="decimal" value="' + escapeHtml(purchasePrice) + '" placeholder="价格" aria-label="产品价格"></label><button type="button" class="is-primary is-finalize' + (state.ledgerFlowTransitionSku === sku ? ' is-flow-transition' : '') + '" data-action="ledger-finalize" data-sku="' + escapeHtml(sku) + '" data-date="' + dateAttr + '">' + ledgerFinalizeCheckIconHtml() + '<span>定稿</span><em>已出图</em></button>')) +
        moreButton +
      '</div>';
    return '<article class="pfh-ledger-item is-clickable is-' + escapeHtml(mode) + stageClass + (selected ? ' is-selected' : '') + (menuOpen ? ' is-menu-open' : '') + '" data-ledger-stage="' + escapeHtml(record.finalizedAt || mode === 'finalized' ? 'finalized' : (imageGenerated ? 'generated' : 'pending')) + '" data-ledger-sku="' + escapeHtml(sku) + '" data-ledger-date="' + dateAttr + '" data-performance-group-id="' + escapeHtml(effectivePerformanceGroupId) + '" role="button" aria-pressed="' + (selected ? 'true' : 'false') + '" tabindex="0" title="点击卡片选择产品">' +
      '<button type="button" class="pfh-ledger-thumb" data-action="ledger-open-sku" data-sku="' + escapeHtml(sku) + '">' + thumb + '</button>' +
      '<div class="pfh-ledger-main">' +
        '<div class="pfh-ledger-title-row"><button type="button" class="pfh-ledger-title" data-action="ledger-open-sku" data-sku="' + escapeHtml(sku) + '"><b>' + escapeHtml(title) + '</b></button></div>' +
        tagHtml +
        assignmentHtml +
      '</div>' +
      '<div class="pfh-ledger-bottom">' + actions + '</div>' +
    '</article>';
  }

  function refreshLedgerCard(record) {
    if (!record || state.view !== 'ledger') {
      renderShell();
      return;
    }
    const mode = state.ledgerView === 'finalized' ? 'finalized' : 'design';
    const panel = ensurePanel();
    const card = Array.from(panel.querySelectorAll('.pfh-ledger-item')).find((item) => item.getAttribute('data-ledger-sku') === record.sku && normalizeLedgerDate(item.getAttribute('data-ledger-date')) === normalizeLedgerDate(record.date));
    const finalized = isLedgerFinalizedRecord(record);
    if ((mode === 'finalized' && !finalized) || (mode === 'design' && finalized)) {
      if (card) card.remove();
      else renderShell();
      return;
    }
    if (!filterLedgerWorkbenchRecords([record], mode).length) {
      if (!renderLedgerTabContent(panel)) renderShell();
      return;
    }
    if (!card) {
      renderShell();
      return;
    }
    const performanceGroupMaps = mode === 'finalized'
      ? getLedgerPerformanceGroupMaps(summarizeLedgerPerformance(getLedgerRecordsForMonth('finalized', getCurrentLedgerMonth())))
      : { labels: null, recordGroupIds: null };
    card.outerHTML = ledgerRowHtml(record, mode, performanceGroupMaps.labels, performanceGroupMaps.recordGroupIds);
    if (state.ledgerMenuSku === record.sku && state.ledgerMenuDate === normalizeLedgerDate(record.date)) {
      const nextButton = Array.from(panel.querySelectorAll('[data-action="ledger-more"]')).find((button) => button.getAttribute('data-sku') === record.sku && normalizeLedgerDate(button.getAttribute('data-date')) === normalizeLedgerDate(record.date));
      if (nextButton) positionRenderedLedgerMenu(panel, nextButton);
    }
  }

  function ledgerTrashRowHtml(record) {
    const sku = record.sku || '';
    const title = [record.brand, record.name].filter(Boolean).join(' ') || sku;
    const thumbUrl = record.skuImageUrl || record.benchmarkImageUrl || '';
    const thumb = thumbUrl ? '<img src="' + escapeHtml(thumbUrl) + '" alt="">' : '<span class="pfh-ledger-thumb-empty">' + iconHtml('image') + '</span>';
    const dateAttr = escapeHtml(record.date || '');
    const removedAt = record.removedAt ? '移除 ' + formatLedgerMinuteLabel(record.removedAt, record.date) : '已从工作台移除';
    return '<article class="pfh-ledger-item is-trash" data-ledger-sku="' + escapeHtml(sku) + '" data-ledger-date="' + dateAttr + '">' +
      '<div class="pfh-ledger-thumb">' + thumb + '</div>' +
      '<div class="pfh-ledger-main"><div class="pfh-ledger-title-row"><b>' + escapeHtml(title) + '</b><span class="pfh-ledger-status is-skip">垃圾篓</span></div>' +
      '<div class="pfh-ledger-tags"><button type="button" class="is-sku" data-action="ledger-copy-sku" data-sku="' + escapeHtml(sku) + '">' + escapeHtml(sku) + '</button><span class="is-design-type">' + escapeHtml(record.designType || '未分类') + '</span></div>' +
      '<div class="pfh-ledger-bottom"><div class="pfh-ledger-assignment">' + escapeHtml(removedAt) + '</div><div class="pfh-ledger-trash-actions"><button type="button" class="is-restore" data-action="ledger-trash-restore" data-sku="' + escapeHtml(sku) + '" data-date="' + dateAttr + '">恢复</button><button type="button" class="is-delete" data-action="ledger-trash-delete" data-sku="' + escapeHtml(sku) + '" data-date="' + dateAttr + '">清除</button></div></div></div>' +
      '</article>';
  }

  function closeRenderedLedgerMenus(panel, keepCard) {
    if (!panel) return;
    panel.querySelectorAll('.pfh-ledger-item.is-menu-open').forEach((card) => {
      if (keepCard && card === keepCard) return;
      card.classList.remove('is-menu-open');
      const button = card.querySelector('[data-action="ledger-more"]');
      if (button) button.setAttribute('aria-expanded', 'false');
    });
    panel.querySelectorAll('.pfh-ledger-overflow-menu').forEach((menu) => menu.remove());
  }

  function positionRenderedLedgerMenu(panel, button) {
    if (!panel || !button || !button.isConnected) return;
    const card = button.closest('.pfh-ledger-item');
    const menu = card && card.querySelector('.pfh-ledger-overflow-menu');
    const host = panel.querySelector('.pfh-full') || panel;
    if (!menu || !host) return;
    menu.setAttribute('data-ledger-menu-sku', button.getAttribute('data-sku') || '');
    menu.setAttribute('data-ledger-menu-date', button.getAttribute('data-date') || '');
    host.appendChild(menu);
    // The cloud stylesheet still has an older absolute-position rule. Pin the
    // live menu inline so it cannot fall back to the bottom of the panel.
    menu.style.setProperty('position', 'fixed', 'important');
    menu.style.setProperty('right', 'auto', 'important');
    menu.style.setProperty('bottom', 'auto', 'important');
    menu.style.setProperty('display', 'grid', 'important');
    menu.style.setProperty('z-index', '2147483646', 'important');
    menu.style.setProperty('pointer-events', 'auto', 'important');
    menu.style.visibility = 'hidden';
    window.requestAnimationFrame(() => {
      if (!menu.isConnected || !button.isConnected) return;
      const buttonRect = button.getBoundingClientRect();
      const panelRect = panel.getBoundingClientRect();
      const sideInset = 10;
      const topBoundary = Math.max(8, panelRect.top + sideInset);
      const bottomBoundary = Math.min(window.innerHeight - 8, panelRect.bottom - sideInset);
      const leftBoundary = Math.max(8, panelRect.left + sideInset);
      const rightBoundary = Math.min(window.innerWidth - 8, panelRect.right - sideInset);
      menu.style.maxHeight = Math.max(120, bottomBoundary - topBoundary) + 'px';
      const menuRect = menu.getBoundingClientRect();
      const left = Math.max(leftBoundary, Math.min(rightBoundary - menuRect.width, buttonRect.right - menuRect.width));
      const spaceBelow = bottomBoundary - buttonRect.bottom - 7;
      const spaceAbove = buttonRect.top - topBoundary - 7;
      const openBelow = spaceBelow >= Math.min(menuRect.height, 240) || spaceBelow >= spaceAbove;
      const top = openBelow
        ? Math.min(bottomBoundary - menuRect.height, buttonRect.bottom + 7)
        : Math.max(topBoundary, buttonRect.top - menuRect.height - 7);
      // The hosted stylesheet still declares `top` with `!important`; write
      // both computed axes at the same priority so the menu stays in view.
      menu.style.setProperty('left', Math.round(left) + 'px', 'important');
      menu.style.setProperty('top', Math.round(top) + 'px', 'important');
      menu.style.setProperty('--pfh-menu-origin', openBelow ? 'right top' : 'right bottom');
      menu.style.visibility = 'visible';
    });
  }

  function handleLedgerMenuScroll(event) {
    if (!state.ledgerMenuSku || state.view !== 'ledger') return;
    if (event.target && event.target.closest && event.target.closest('.pfh-ledger-overflow-menu')) return;
    const panel = event.currentTarget;
    window.cancelAnimationFrame(state.ledgerMenuPositionFrame || 0);
    state.ledgerMenuPositionFrame = window.requestAnimationFrame(() => {
      state.ledgerMenuPositionFrame = 0;
      const button = Array.from(panel.querySelectorAll('[data-action="ledger-more"][aria-expanded="true"]')).find((item) => item.getAttribute('data-sku') === state.ledgerMenuSku && normalizeLedgerDate(item.getAttribute('data-date')) === state.ledgerMenuDate);
      const menu = panel.querySelector('.pfh-ledger-overflow-menu');
      if (!button || !menu) return;
      const card = button.closest('.pfh-ledger-item');
      if (card) card.appendChild(menu);
      positionRenderedLedgerMenu(panel, button);
    });
  }

  function ledgerOverflowMenuHtml(record, sku, dateAttr, imageGenerated) {
    if (state.ledgerMenuSku !== sku || state.ledgerMenuDate !== normalizeLedgerDate(dateAttr)) return '';
    const rollback = record.status === '作废'
      ? '<button type="button" data-action="ledger-unfinalize" data-sku="' + escapeHtml(sku) + '" data-date="' + dateAttr + '">撤回作废</button>'
      : record.finalizedAt
      ? '<button type="button" data-action="ledger-unfinalize" data-sku="' + escapeHtml(sku) + '" data-date="' + dateAttr + '">撤回定稿</button>'
      : (imageGenerated ? '<button type="button" data-action="ledger-unmark-image-generated" data-sku="' + escapeHtml(sku) + '" data-date="' + dateAttr + '">撤回出图</button>' : '');
    const seriesAction = isLedgerSeriesExcluded(record) ? '恢复自动系列' : '剔除自动系列';
    const artworkState = normalizeLedgerArtworkState(record.artworkState);
    const artworkLabel = artworkState === 'doing' ? '生图中' : (artworkState === 'done' ? '完成生图' : '待生图');
    const searchUsesBenchmark = state.ledgerView === 'design' || !record.skuImageUrl;
    const searchImageUrl = searchUsesBenchmark ? (record.benchmarkImageUrl || '') : record.skuImageUrl;
    const searchImageLabel = searchUsesBenchmark ? '对标图' : '效果图';
    const searchActions = searchImageUrl
      ? '<button type="button" data-action="reverse-image-search" data-engine="1688" data-image-url="' + escapeHtml(searchImageUrl) + '">1688 搜' + searchImageLabel + '</button><button type="button" data-action="reverse-image-search" data-engine="google" data-image-url="' + escapeHtml(searchImageUrl) + '">Google 搜' + searchImageLabel + '</button><button type="button" data-action="reverse-image-search" data-engine="yandex" data-image-url="' + escapeHtml(searchImageUrl) + '">Yandex 搜' + searchImageLabel + '</button>'
      : '';
    return '<div class="pfh-ledger-overflow-menu">' + rollback +
      searchActions +
      '<button type="button" data-action="ledger-cycle-artwork-state" data-sku="' + escapeHtml(sku) + '" data-date="' + dateAttr + '">手动切换生图标记（当前：' + artworkLabel + '）</button>' +
      '<button type="button" class="' + (record.performanceType === 'extension' ? 'is-active' : '') + '" data-action="ledger-extension" data-sku="' + escapeHtml(sku) + '" data-date="' + dateAttr + '">' + (record.performanceType === 'extension' ? '取消延伸（当前 0.3）' : '延伸（绩效 0.3）') + '</button>' +
      '<button type="button" class="' + (isLedgerSeriesExcluded(record) ? 'is-active' : '') + '" data-action="ledger-series-exclude" data-sku="' + escapeHtml(sku) + '" data-date="' + dateAttr + '">' + seriesAction + '</button>' +
      '<button type="button" data-action="ledger-void" data-sku="' + escapeHtml(sku) + '" data-date="' + dateAttr + '">作废</button>' +
      '<button type="button" data-action="ledger-done" data-sku="' + escapeHtml(sku) + '" data-date="' + dateAttr + '">完成</button>' +
      '<button type="button" data-action="ledger-remove" data-sku="' + escapeHtml(sku) + '" data-date="' + dateAttr + '">移除</button>' +
      '</div>';
  }

  function ledgerFileButtonHtml(action, sku, dateAttr, label, code, stateValue, doneFallback) {
    const value = normalizeLedgerFileState(stateValue, doneFallback);
    const title = label + '\uff1a' + ledgerFileStateLabel(value) + (code ? ' \u00b7 ' + code : '');
    const displayLabel = value === 'skip' ? String.fromCharCode(0x65e0, 0x9700) + label : label;
    return '<button type="button" class="is-' + escapeHtml(value) + '" data-action="' + action + '" data-sku="' + escapeHtml(sku) + '" data-date="' + dateAttr + '" title="' + escapeHtml(title) + '"><span>' + escapeHtml(displayLabel) + '</span>' + (value !== 'skip' && code ? '<small>' + escapeHtml(code) + '</small>' : '') + '</button>';
  }

  function ledgerFinalizeCheckIconHtml() {
    return '<svg class="pfh-ledger-finalize-check" viewBox="0 0 1024 1024" aria-hidden="true"><path d="M511.93 64.07C264.54 64.07 64 264.62 64 512s200.54 447.93 447.93 447.93c58.83 0.07 117.09-11.5 171.43-34.04 167.5-69.32 276.7-232.76 276.64-414.03-0.08-247.39-200.69-447.87-448.07-447.79z m0.41 831.87c-212.04 0.11-384.03-171.69-384.14-383.73-0.11-212.04 171.69-384.03 383.73-384.14 50.5 0 100.51 9.93 147.18 29.24C802.49 216.72 895.99 356.6 896.08 511.8c0.11 212.04-171.7 384.02-383.74 384.14z"></path><path d="M431.85 660.55l-121.19-121.2c-12.49-12.49-12.49-32.75 0-45.24 12.49-12.49 32.75-12.49 45.24 0l92.11 92.11L668.1 366.13c12.49-12.49 32.75-12.49 45.24 0 12.49 12.49 12.49 32.75 0 45.24L464.17 660.55c-8.92 8.92-23.39 8.92-32.32 0z"></path></svg>';
  }

  function ledgerTimeEditorHtml() {
    const editor = state.ledgerTimeEditor;
    if (!editor) return '';
    const date = new Date(editor.timeMs || Date.now());
    const dateValue = [date.getFullYear(), String(date.getMonth() + 1).padStart(2, '0'), String(date.getDate()).padStart(2, '0')].join('-');
    const hour = String(date.getHours()).padStart(2, '0');
    const minute = String(date.getMinutes()).padStart(2, '0');
    return '<div class="pfh-ledger-time-modal" role="dialog" aria-modal="true" aria-label="修改定稿时间">' +
      '<div class="pfh-ledger-time-card">' +
        '<div class="pfh-ledger-time-head"><div><b>修改定稿时间</b><span>' + escapeHtml(editor.sku) + '</span></div><button type="button" data-action="ledger-time-close" aria-label="关闭">×</button></div>' +
        '<div class="pfh-ledger-time-fields"><label>日期<input class="pfh-ledger-time-date" type="text" inputmode="numeric" value="' + escapeHtml(dateValue) + '" placeholder="2026-07-10"></label><label>时间<span class="pfh-ledger-time-clock"><input class="pfh-ledger-time-hour" type="text" inputmode="numeric" maxlength="2" value="' + hour + '"><i>:</i><input class="pfh-ledger-time-minute" type="text" inputmode="numeric" maxlength="2" value="' + minute + '"></span></label></div>' +
        '<div class="pfh-ledger-time-presets"><button type="button" data-action="ledger-time-today">今天</button><button type="button" data-action="ledger-time-yesterday">昨天</button><button type="button" data-action="ledger-time-day-before">前天</button></div>' +
        '<div class="pfh-ledger-time-actions"><button type="button" data-action="ledger-time-close">取消</button><button type="button" class="is-primary" data-action="ledger-time-save">保存时间</button></div>' +
      '</div></div>';
  }

  function formatLedgerMonthLabel(month) {
    const match = String(month || '').match(/^(\d{4})-(\d{2})$/);
    return match ? (match[1] + ' 年 ' + Number(match[2]) + ' 月') : String(month || '本月');
  }

  function productThumbHtml(data) {
    const src = getSkuListImageUrl(data);
    if (!src) return '<span class="pfh-product-thumb is-empty">' + iconHtml('image') + '</span>';
    return '<button type="button" class="pfh-product-thumb" title="悬浮放大预览">' +
      '<span class="pfh-thumb-frame"><img src="' + escapeHtml(src) + '" alt=""></span>' +
      '<span class="pfh-thumb-preview"><img src="' + escapeHtml(src) + '" alt=""></span>' +
      '</button>';
  }

  function formatSkuDetailPriority(value) {
    const text = cleanName(value || '').replace(/\s+/g, '');
    if (!text) return '';
    const match = text.match(/^(P\d+)[\-\uFF0D\u2013\u2014·•|/:：]?(.*)$/i);
    if (!match) return text;
    const level = match[1].toUpperCase();
    const detail = String(match[2] || '').replace(/^[\-\uFF0D\u2013\u2014·•|/:：]+/, '');
    return detail ? level + '-' + detail : level;
  }

  function formatSkuDetailLinkLabel(value) {
    const source = String(value || '').trim();
    if (!source) return '';
    let label = source;
    try {
      if (/^https?:\/\//i.test(source)) {
        const url = new URL(source);
        label = url.hostname + (url.pathname || '').replace(/\/$/, '');
      }
    } catch (error) {
      label = source;
    }
    return label.length > 30 ? label.slice(0, 29) + '\u2026' : label;
  }

  function updateProductThumbInPlace(data) {
    if (!data || !data.sku || state.view !== 'detail' || !state.data || state.data.sku !== data.sku) return false;
    const panel = ensurePanel();
    const current = panel.querySelector('.pfh-product-hero .pfh-product-thumb');
    if (!current) return false;
    const src = getSkuListImageUrl(data);
    if (!src) return false;
    if (current.matches('button')) {
      current.querySelectorAll('img').forEach((image) => {
        if (image.getAttribute('src') !== src) image.setAttribute('src', src);
      });
    } else {
      current.outerHTML = productThumbHtml(data);
    }
    return true;
  }

  function updateInsightRecommendationInPlace(sku) {
    if (!sku || state.view !== 'detail' || !state.data || state.data.sku !== sku) return false;
    if (state.skuEditMode) return true;
    const panel = ensurePanel();
    const section = panel.querySelector('.pfh-graphic-section');
    if (!section) return false;
    const current = section.querySelector('.pfh-smart-recommend');
    const html = insightRecommendationHtml(state.data);
    if (current && html) current.outerHTML = html;
    else if (current) current.remove();
    else if (html) section.insertAdjacentHTML('beforeend', html);
    return true;
  }

  function formatPrintSizeDisplay(data) {
    if (!data) return '';
    return [data.printSizeText || '', data.tubeSegmentText || ''].filter(Boolean).join('\n');
  }

  function renderStatusHtml(statusText) {
    const openingDetail = state.openingProjectDetail || statusText === L.openingDetail;
    if (openingDetail || state.scanRunning || statusText === L.scanning || statusText === L.checkingMaterial) {
      const tip = getCurrentLoadingTip();
      return '<div class="pfh-status pfh-loading-tip"><i class="pfh-loading-ring" aria-hidden="true"></i><span>' + (openingDetail ? '\u52a0\u8f7d\u4e2d' : '\u8bc6\u522b\u4e2d') + '</span><strong>' + escapeHtml(tip) + '</strong></div>';
    }
    return '';
  }

  function isLoadingTipVisible() {
    const panel = document.getElementById(PANEL_ID);
    return Boolean(panel && panel.querySelector('.pfh-detail.is-loading .pfh-loading-tip'));
  }

  function getCurrentLoadingTip() {
    const tips = normalizeLoadingTips(state.loadingTips);
    const seed = state.scanTargetSku || state.selectedSku || state.sku || String(Date.now());
    if (!state.loadingTipText || !tips.includes(state.loadingTipText)) lockLoadingTip(seed);
    return state.loadingTipText || DEFAULT_LOADING_TIPS[0];
  }

  function lockLoadingTip(seed) {
    const stableSeed = String(seed || state.scanTargetSku || state.selectedSku || state.sku || Date.now());
    if (state.loadingTipSeed === stableSeed && state.loadingTipText) return;
    const picked = pickLoadingTipItem(state.loadingTips, stableSeed);
    state.loadingTipText = picked.text;
    state.loadingTipId = picked.tipId || '';
    state.loadingTipSeed = stableSeed;
    recordLoadingTipImpression(picked);
  }

  function pickLoadingTipItem(tips, seed) {
    const items = normalizeLoadingTipItems(tips);
    let hash = 0;
    String(seed || '').split('').forEach((char) => {
      hash = ((hash << 5) - hash + char.charCodeAt(0)) | 0;
    });
    const total = items.reduce((sum, item) => sum + item.weight, 0) || 1;
    let target = Math.abs(hash) % total;
    for (const item of items) {
      target -= item.weight;
      if (target < 0) return item;
    }
    return items[0] || { text: DEFAULT_LOADING_TIPS[0], tipId: '', weight: 1 };
  }

  function normalizeLoadingTips(tips) {
    return normalizeLoadingTipItems(tips).map((item) => item.text);
  }

  function normalizeLoadingTipItems(tips) {
    const seen = new Set();
    const list = (Array.isArray(tips) ? tips : []).map((item) => ({
      text: String(typeof item === 'string' ? item : (item && item.text) || '').trim(),
      tipId: String(item && typeof item === 'object' ? item.tipId || '' : ''),
      weight: Math.max(1, Math.min(20, Number(item && typeof item === 'object' ? item.weight : 1) || 1)),
    })).filter((item) => item.text && !seen.has(item.text) && seen.add(item.text));
    return list.length ? list.slice(0, 80) : DEFAULT_LOADING_TIPS.map((text) => ({ text, tipId: '', weight: 1 }));
  }

  function insightRecommendationHtml(data) {
    if (!data || !data.sku) return '';
    const recommendation = state.insightRecommendationSku === data.sku ? state.insightRecommendation : null;
    const categoryEditor = state.skuEditMode
      ? '<input type="text" class="pfh-smart-category-input" data-sku-edit-key="manualCategory" value="' + escapeHtml(getDisplayedProductCategory(data, true)) + '" placeholder="例如：玩具" autocomplete="off" spellcheck="false">'
      : '';
    if (state.insightRecommendationLoading && state.insightRecommendationSku === data.sku && !state.skuEditMode) {
      return '<div class="pfh-smart-recommend is-loading"><strong>\u667a\u80fd\u8865\u5168</strong><span>\u6b63\u5728\u5339\u914d\u5386\u53f2\u4ef7\u683c\u548c\u5546\u54c1\u7c7b\u578b...</span></div>';
    }
    if (!recommendation || !recommendation.recommendedPrice) {
      return state.skuEditMode
        ? '<div class="pfh-smart-recommend"><strong>\u667a\u80fd\u8865\u5168</strong><span>产品分类 / ' + categoryEditor + '</span></div>'
        : '';
    }
    const type = recommendation.effectiveProductType || recommendation.recommendedProductType || recommendation.productType || '';
    const confidence = recommendation.priceConfidence || recommendation.recommendationConfidence || '';
    const stats = formatRecommendationPriceStats(recommendation.priceStats);
    const reason = recommendation.recommendationReason || buildLocalRecommendationReason(recommendation, type);
    const samples = formatRecommendationSamples(recommendation.priceSamples);
    return '<div class="pfh-smart-recommend"><strong>\u667a\u80fd\u8865\u5168</strong>' +
      '<span>\u63a8\u8350\u4ef7\u683c <b>' + escapeHtml(String(recommendation.recommendedPrice)) + '</b>' + (state.skuEditMode ? ' / ' + categoryEditor : (type ? ' / ' + escapeHtml(type) : '')) + (confidence ? ' / \u7f6e\u4fe1\u5ea6' + escapeHtml(confidence) : '') + '</span>' +
      (stats || reason ? '<small>' + escapeHtml([stats, reason].filter(Boolean).join(' / ')) + '</small>' : '') +
      (samples ? '<em>\u6837\u672c\u4f9d\u636e\uff1a' + escapeHtml(samples) + '</em>' : '') +
      '</div>';
  }

  function formatRecommendationSamples(samples) {
    if (!Array.isArray(samples) || !samples.length) return '';
    return samples.slice(0, 3).map((item) => {
      const sku = item && item.sku ? String(item.sku) : '';
      const price = item && item.price ? String(item.price) : '';
      const type = item && item.productType ? String(item.productType) : '';
      const packQty = item && item.packQty ? '\u88c5' + String(item.packQty) : '';
      return [sku, price ? '\uffe5' + price : '', type, packQty].filter(Boolean).join(' ');
    }).filter(Boolean).join('；');
  }

  function scheduleInsightRecommendation(data) {
    const sku = data && data.sku;
    if (!sku || state.insightRecommendationLoading || state.insightRecommendationSku === sku) return;
    state.insightRecommendationSku = sku;
    state.insightRecommendation = null;
    state.insightRecommendationLoading = true;
    window.setTimeout(() => loadInsightRecommendationForDetail(sku).catch((error) => {
      addLog('warn', '\u667a\u80fd\u8865\u5168\u5efa\u8bae\u83b7\u53d6\u5931\u8d25', sku + ' ' + formatErrorMessage(error));
    }).finally(() => {
      if (state.insightRecommendationSku === sku) {
        state.insightRecommendationLoading = false;
        if (!updateInsightRecommendationInPlace(sku)) renderShell();
      }
    }), 120);
  }

  async function loadInsightRecommendationForDetail(sku) {
    const data = normalizeData(loadData(sku) || (state.data && state.data.sku === sku ? state.data : null));
    if (!data || !data.sku) return;
    const productType = getProductTypeForInsight(data, null);
    const cloudRecommendation = await fetchInsightRecommendation(data, productType).catch(() => null);
    const recommendedType = cloudRecommendation && cloudRecommendation.recommendedProductType && cloudRecommendation.recommendedProductType !== productType ? cloudRecommendation.recommendedProductType : '';
    const effectiveProductType = recommendedType || (cloudRecommendation && cloudRecommendation.effectiveProductType) || productType;
    const recommendation = cloudRecommendation && cloudRecommendation.recommendedPrice ? cloudRecommendation : getLocalPriceRecommendation(data, effectiveProductType);
    if (!recommendation || !recommendation.recommendedPrice || state.insightRecommendationSku !== sku) return;
    state.insightRecommendation = {
      ...recommendation,
      productType,
      effectiveProductType,
      recommendedProductType: recommendation.recommendedProductType || recommendedType || '',
      recommendationReason: recommendation.recommendationReason || buildLocalRecommendationReason(recommendation, effectiveProductType),
    };
    syncInsightEvent('recommendation', {
      sku: data.sku || '',
      brand: data.brand || '',
      name: data.name || '',
      productType: effectiveProductType || productType || '',
      price: String(recommendation.recommendedPrice || ''),
      recommendedPrice: String(recommendation.recommendedPrice || ''),
      source: recommendation.source || 'detail-recommendation',
      reason: state.insightRecommendation.recommendationReason || '',
      recommendationReason: state.insightRecommendation.recommendationReason || '',
      productTypeSource: recommendation.productTypeSource || '',
      productTypeScore: recommendation.productTypeScore || '',
      typeSampleCount: recommendation.typeSampleCount || '',
      recommendedProductType: state.insightRecommendation.recommendedProductType || '',
      effectiveProductType,
      priceConfidence: recommendation.priceConfidence || recommendation.recommendationConfidence || '',
      recommendationConfidence: recommendation.priceConfidence || recommendation.recommendationConfidence || '',
      priceStats: recommendation.priceStats || null,
    });
  }

  function getProductThumbUrl(data) {
    if (!data) return '';
    return /^(?:effectImage|productListImage)$/.test(data.skuImageSource || '') ? (data.skuImageUrl || data.skuImageFallbackUrl || '') : '';
  }

  function getSkuEditableFields() {
    return ['packageCode', 'printCode', 'packageSizeText', 'printSizeText', 'packageLength', 'packageWidth', 'packageHeight', 'productLength', 'productWidth', 'productHeight', 'netContent', 'grossWeight'];
  }

  function isSkuEditableField(key) {
    return getSkuEditableFields().includes(key);
  }

  function getSkuEditInputValue(data, key) {
    const rawValue = data && data[key] != null ? data[key] : '';
    if (!/^(?:package|product)(?:Length|Width|Height)$/.test(key)) return rawValue;
    const cmValue = extractCmValue(rawValue);
    return Number.isFinite(Number(cmValue)) && Number(cmValue) > 0 ? trimNumber(Number(cmValue)) : '';
  }

  function getSkuDataFieldLabel(key) {
    const labels = {
      brand: '品牌',
      name: '商品名称',
      manualCategory: '产品分类',
      packageCode: L.packageCode,
      printCode: L.printCode,
      packageSizeText: L.packageSize,
      printSizeText: L.printSize,
      packageLength: L.cartonLength,
      packageWidth: L.cartonWidth,
      packageHeight: L.cartonHeight,
      productLength: L.productLength,
      productWidth: L.productWidth,
      productHeight: L.productHeight,
      netContent: L.netContent,
      grossWeight: L.grossWeight,
      englishName: '英文产品名',
      ingredientChinese: '中文成分',
      ingredientEnglish: '英文成分',
      referenceUrl: '对标链接',
      infringementImageUrls: '侵权图',
      infringementCopywriting: '侵权图文案',
    };
    return labels[key] || key;
  }

  function getStoredDataChanges(data) {
    return Array.isArray(data && data.recentFieldChanges)
      ? data.recentFieldChanges.filter((item) => item && item.key && !trackedDataValuesEqual(item.key, item.before, item.after)).slice(0, 20)
      : [];
  }

  function getDataChangeSignature(changes) {
    const normalized = (Array.isArray(changes) ? changes : [])
      .filter((item) => item && item.key && !trackedDataValuesEqual(item.key, item.before, item.after))
      .map((item) => [
        String(item.key),
        normalizeTrackedDataValue(item.key, item.before),
        normalizeTrackedDataValue(item.key, item.after),
      ])
      .sort((left, right) => {
        const leftText = JSON.stringify(left);
        const rightText = JSON.stringify(right);
        return leftText < rightText ? -1 : (leftText > rightText ? 1 : 0);
      });
    return normalized.length ? JSON.stringify(normalized) : '';
  }

  function getVisibleStoredDataChanges(data) {
    const changes = getStoredDataChanges(data);
    const acknowledged = String(data && data.recentFieldChangesAcknowledgedSignature || '').trim();
    return acknowledged && getDataChangeSignature(changes) === acknowledged ? [] : changes;
  }

  function getStoredDataUpdateLogs(data) {
    const logs = normalizeDataUpdateLog(data && data.dataUpdateLog);
    if (logs.length) return logs;
    const changes = getStoredDataChanges(data);
    return changes.length
      ? [{ id: 'recent-data-changes', changedAt: changes[0].changedAt || String(data && data.updatedAt || ''), changedAtMs: Number(data && data.updatedAtMs || 0) || 0, source: changes[0].source || '自动获取', changes }]
      : [];
  }

  function saveSkuManualEdits() {
    const data = normalizeData(state.data || (state.selectedSku ? loadData(state.selectedSku) : null));
    if (!data || !data.sku) return;
    const panel = ensurePanel();
    const values = {};
    Array.from(panel.querySelectorAll('[data-sku-edit-key]')).forEach((input) => {
      values[input.getAttribute('data-sku-edit-key')] = String(input.value || '').trim();
    });
    const next = { ...data };
    const manualFieldOverrides = { ...normalizeManualFieldOverrides(data) };
    const rememberManualValue = (key, value) => {
      if (isManualOverrideField(key)) manualFieldOverrides[key] = value == null ? '' : String(value).trim();
    };
    if (Object.prototype.hasOwnProperty.call(values, 'manualCategory')) {
      next.manualCategory = normalizeManualProductCategory(values.manualCategory);
      next.manualCategoryUpdatedAt = next.manualCategory ? new Date().toLocaleString() : '';
      if (compactText(next.manualCategory) !== compactText(data.manualCategory)) rememberManualValue('manualCategory', next.manualCategory);
    }
    ['packageCode', 'printCode', 'packageSizeText', 'printSizeText', 'netContent', 'grossWeight'].forEach((key) => {
      if (Object.prototype.hasOwnProperty.call(values, key)) {
        next[key] = values[key];
        if (compactText(values[key]) !== compactText(data[key])) rememberManualValue(key, values[key]);
      }
    });

    const packageKeys = ['packageLength', 'packageWidth', 'packageHeight'];
    // Dimension inputs use plain centimetre numbers, while stored fields include
    // the formatted cm/inch text. Compare the same input representation so that
    // editing packageSizeText alone is not overwritten by the old dimensions.
    const packageChanged = packageKeys.some((key) => compactText(values[key]) !== compactText(getSkuEditInputValue(data, key)));
    if (packageChanged) {
      const packageNums = packageKeys.map((key) => firstNumber(values[key]));
      if (!packageNums.every((value) => Number.isFinite(value) && value > 0)) {
        showToast('纸盒长、宽、高需要填写完整的有效数字');
        return;
      }
      next.packageNums = packageNums;
      next.packageSizeText = packageNums.map(trimNumber).join('x') + 'cm';
      packageKeys.forEach((key) => rememberManualValue(key, values[key]));
      rememberManualValue('packageSizeText', next.packageSizeText);
    } else if (Object.prototype.hasOwnProperty.call(values, 'packageSizeText') && compactText(values.packageSizeText) !== compactText(data.packageSizeText)) {
      next.packageNums = null;
      delete manualFieldOverrides.packageLength;
      delete manualFieldOverrides.packageWidth;
      delete manualFieldOverrides.packageHeight;
      rememberManualValue('packageSizeText', values.packageSizeText);
    }

    const productKeys = ['productLength', 'productWidth', 'productHeight'];
    const productChanged = productKeys.some((key) => compactText(values[key]) !== compactText(getSkuEditInputValue(data, key)));
    if (productChanged) {
      const productNums = productKeys.map((key) => firstNumber(values[key]));
      if (!productNums.every((value) => Number.isFinite(value) && value > 0)) {
        showToast('产品长、宽、高需要填写完整的有效数字');
        return;
      }
      next.plmProductNums = productNums;
      next.productNums = productNums;
      if (data.isTubePrint) {
        next.tailSealLengthValue = formatSingleDimension(productNums[0]);
        next.tubeTailSealLengthValue = next.tailSealLengthValue;
      }
      productKeys.forEach((key) => rememberManualValue(key, values[key]));
    }
    const correctedUnitIssues = normalizeMaterialDimensionUnitIssues(data.materialDimensionUnitIssues, data);
    if (Object.prototype.hasOwnProperty.call(values, 'packageSizeText')) {
      correctedUnitIssues.package = detectMaterialDimensionUnitIssue(next.packageSizeText)
        || (extractDimensionString(next.packageSizeText) ? null : correctedUnitIssues.package);
    }
    if (Object.prototype.hasOwnProperty.call(values, 'printSizeText')) {
      correctedUnitIssues.print = detectMaterialDimensionUnitIssue(next.printSizeText)
        || (extractDimensionString(next.printSizeText) ? null : correctedUnitIssues.print);
    }
    next.materialDimensionUnitIssues = correctedUnitIssues;
    next.manualFieldOverrides = manualFieldOverrides;
    next.updatedAt = new Date().toLocaleString();
    next.updatedAtMs = Date.now();
    const categoryChanged = compactText(next.manualCategory) !== compactText(data.manualCategory);
    saveData(data.sku, next, { changeSource: '手动校准', trackEmptyChanges: true });
    state.skuEditMode = false;
    if (categoryChanged) {
      state.insightRecommendationSku = '';
      state.insightRecommendation = null;
      state.toyCopywritingErrorSku = '';
      state.toyCopywritingError = '';
    }
    resetExcelState();
    renderShell();
    addLog('success', 'SKU 数据手动校准已保存', data.sku);
    showToast('校准数据已保存');
  }

  function acknowledgeSkuDataChanges() {
    const data = normalizeData(state.data || (state.selectedSku ? loadData(state.selectedSku) : null));
    if (!data || !data.sku) return;
    const next = {
      ...data,
      recentFieldChanges: [],
      recentFieldChangesAcknowledgedSignature: getDataChangeSignature(getStoredDataChanges(data)),
    };
    saveData(data.sku, next, { suppressChangeTracking: true });
    renderShell();
    showToast('已确认本次数据更新');
  }

  function rowHtml(key, title, value, options) {
    const shown = value || L.unknown;
    const colorClass = /^package(Length|Width|Height)$/.test(key) ? ' is-carton-dim' : (/^product(Length|Width|Height)$/.test(key) ? ' is-product-dim' : '');
    const skuEditing = state.skuEditMode && isSkuEditableField(key);
    const editButton = !skuEditing && options && options.editable ? '<button type="button" data-edit-key="' + escapeHtml(key) + '">' + escapeHtml(L.edit) + '</button>' : '';
    const namingHint = /^(?:packageSizeText|printSizeText)$/.test(key) ? '左键复制尺寸，右键查看命名与历史编码' : L.copyHint;
    const copyAttr = skuEditing || options && options.noCopy ? '' : ' data-copy-key="' + escapeHtml(key) + '" title="' + escapeHtml(namingHint) + '"';
    const rawEditValue = getSkuEditInputValue(state.data, key);
    const dimensionPlaceholder = /^(?:package|product)(?:Length|Width|Height)$/.test(key) ? 'cm（自动换算 inch）' : '';
    const inputHtml = skuEditing ? '<input type="text" class="pfh-sku-edit-input" data-sku-edit-key="' + escapeHtml(key) + '" value="' + escapeHtml(rawEditValue) + '" placeholder="' + escapeHtml(dimensionPlaceholder) + '" autocomplete="off" spellcheck="false">' : '';
    return '<div class="pfh-row' + colorClass + (skuEditing ? ' is-sku-editing' : '') + '"' + copyAttr + ' data-key="' + escapeHtml(key) + '">' +
      '<span class="pfh-label"><span>' + escapeHtml(title) + '</span></span>' +
      '<span class="pfh-value">' + escapeHtml(shown).replace(/\n/g, '<br>') + '</span>' +
      inputHtml +
      '<span class="pfh-row-actions">' + editButton +
      '</span>' +
      '</div>';
  }

  function excelTriggerHtml() {
    return '<div class="pfh-excel-controls"><button type="button" data-action="excel-prepare">' + iconHtml('download') + '<span>' + escapeHtml(L.excel) + '</span></button></div>';
  }

  function excelOptionsHtml() {
    if (!state.excelPanelOpen) {
      return '';
    }
    const status = state.excelStatus || formatExcelMissingStatus(state.excelMissing);
    const statusClass = state.excelMissing.length || !state.excelExtra ? ' is-bad' : ' is-good';
    const priceValue = state.excelPurchasePrice === '' ? '6' : state.excelPurchasePrice;
    const exportLabel = state.exportType === 'toy-label' ? L.exportTypeToyLabel : L.exportTypeExcel;
    return '<div class="pfh-excel-form is-open">' +
      '<div class="pfh-export-menu' + (state.exportMenuOpen ? ' is-open' : '') + '">' +
        '<button type="button" class="pfh-export-menu-button" data-action="export-menu-toggle" aria-expanded="' + (state.exportMenuOpen ? 'true' : 'false') + '">' +
          '<span>' + escapeHtml(exportLabel) + '</span><i></i>' +
        '</button>' +
        '<div class="pfh-export-menu-list">' +
          '<button type="button" data-action="export-type" data-export-type="excel" class="' + (state.exportType === 'excel' ? 'is-active' : '') + '">' + escapeHtml(L.exportTypeExcel) + '</button>' +
          '<button type="button" data-action="export-type" data-export-type="toy-label" class="' + (state.exportType === 'toy-label' ? 'is-active' : '') + '">' + escapeHtml(L.exportTypeToyLabel) + '</button>' +
        '</div>' +
      '</div>' +
      '<input type="number" min="0" step="1" class="pfh-excel-price" placeholder="' + escapeHtml(L.excelPurchasePrice) + '" value="' + escapeHtml(priceValue) + '">' +
      '<button type="button" data-action="excel-prepare" title="' + escapeHtml(L.excelRefresh) + '">' + iconHtml('refresh') + '</button>' +
      '<button type="button" data-action="excel-generate">' + escapeHtml(L.excel) + '</button>' +
      '<span class="pfh-excel-status' + statusClass + '">' + escapeHtml(status) + '</span>' +
      '</div>';
  }

  function namingLogoKey(data) {
    return compactText((data && (data.logoText || data.brand)) || '').toUpperCase().replace(/[^A-Z0-9\u3400-\u9fff]/g, '');
  }

  function namingProductText(data) {
    const brand = cleanName((data && data.brand) || '');
    const name = cleanName((data && data.name) || '');
    return brand && name.toUpperCase().startsWith(brand.toUpperCase()) ? name : brand + name;
  }

  function namingSizeText(values) {
    return values.map((value) => trimNumber(Number(value))).join('x') + 'cm';
  }

  function namingCodes(value) {
    const matches = String(value || '').match(/\bMTL\d+\b/gi);
    return matches ? matches.map((code) => code.toUpperCase()) : [];
  }

  function packagingNamingEntries(data, key) {
    if (!data) return [];
    if (key === 'packageSizeText') {
      const printedBag = isPrintedBagPackageDimensionData(data);
      const printedBagValues = printedBag ? getPrintedBagFlatDimensionPair(data) : null;
      if (printedBag && (!printedBagValues || printedBagValues.length < 2)) return [];
      const values = printedBagValues || (Array.isArray(data.packageNums) ? data.packageNums.slice(0, 3).map(Number) : parseDimension(data.packageSizeText, 3));
      const requiredCount = printedBag ? 2 : 3;
      if (!values || values.length < requiredCount || values.slice(0, requiredCount).some((value) => !Number.isFinite(value))) return [];
      const codes = namingCodes(data.packageCode);
      return [{
        type: printedBag ? 'printed-bag' : 'package',
        label: compactText(data.packageSizeLabel || (printedBag ? '印刷自立袋' : '纸盒')),
        values: printedBag ? printedBagValues : values.slice(0, 3),
        size: namingSizeText(printedBag ? printedBagValues : values.slice(0, 3)),
        code: codes[0] || compactText(data.packageCode || ''),
      }];
    }
    if (key !== 'printSizeText') return [];
    return getLabelSizeImageSpecs(data).map((spec) => ({
      type: 'print',
      label: compactText(spec.labelText || (spec.kind === 'label' ? '标签' : '印刷')),
      values: [Number(spec.width), Number(spec.height)],
      size: namingSizeText([spec.width, spec.height]),
      code: compactText(spec.code || ''),
    }));
  }

  function namingLine(entry, data) {
    const codeAndName = [entry.code, namingProductText(data)].filter(Boolean).join(' ');
    return entry.label + (/[）)]$/.test(entry.label) ? ' ' : '') + '（' + entry.size + '）' + codeAndName;
  }

  function namingDimensionDistance(left, right) {
    if (!left || !right || left.length !== right.length) return null;
    const distances = left.map((value, index) => Math.abs(Number(value) - Number(right[index])));
    if (left.length === 2) {
      const rotated = [Math.abs(Number(left[0]) - Number(right[1])), Math.abs(Number(left[1]) - Number(right[0]))];
      if (Math.max(...rotated) < Math.max(...distances)) distances.splice(0, distances.length, ...rotated);
    }
    if (distances.some((value) => !Number.isFinite(value) || value > 0.5 + 1e-8)) return null;
    return { max: Math.max(...distances), total: distances.reduce((sum, value) => sum + value, 0) };
  }

  function historicalNamingRecommendations(data, key, entries) {
    const currentSku = String((data && data.sku) || '');
    const currentLogo = namingLogoKey(data);
    const currentCodes = new Set(entries.map((entry) => entry.code).filter(Boolean));
    const recommendations = [];
    (state.index || []).forEach((item) => {
      if (!item || !item.sku || item.sku === currentSku) return;
      const history = normalizeData(loadData(item.sku) || item);
      packagingNamingEntries(history, key).forEach((candidate) => {
        if (!candidate.code || currentCodes.has(candidate.code)) return;
        let best = null;
        entries.forEach((entry) => {
          const distance = namingDimensionDistance(entry.values, candidate.values);
          if (distance && (!best || distance.max < best.max || (distance.max === best.max && distance.total < best.total))) best = distance;
        });
        if (!best) return;
        recommendations.push({
          code: candidate.code,
          size: candidate.size,
          label: candidate.label,
          brandName: namingProductText(history),
          sameLogo: Boolean(currentLogo && namingLogoKey(history) === currentLogo),
          exact: best.max < 0.01,
          max: best.max,
          total: best.total,
          updatedAtMs: Number(history.updatedAtMs || item.updatedAtMs || 0),
        });
      });
    });
    const deduped = new Map();
    recommendations.forEach((item) => {
      const old = deduped.get(item.code);
      if (!old || item.max < old.max || (item.max === old.max && item.sameLogo && !old.sameLogo)) deduped.set(item.code, item);
    });
    return Array.from(deduped.values()).sort((left, right) =>
      Number(right.sameLogo) - Number(left.sameLogo) || left.max - right.max || left.total - right.total || right.updatedAtMs - left.updatedAtMs || left.code.localeCompare(right.code)
    ).slice(0, 5);
  }

  function closePackagingNamingCard(panel) {
    const card = (panel || document).querySelector && (panel || document).querySelector('.pfh-packaging-naming-card');
    if (card) card.remove();
  }

  function showPackagingNamingCard(row, key, event) {
    const panel = row && row.closest('#' + PANEL_ID);
    const data = normalizeData(state.data || (state.selectedSku ? loadData(state.selectedSku) : null));
    if (!panel || !data) return;
    const entries = packagingNamingEntries(data, key);
    if (!entries.length) {
      showToast('当前尺寸无法生成命名', { quiet: true });
      return;
    }
    closePackagingNamingCard(panel);
    const recommendations = historicalNamingRecommendations(data, key, entries);
    const entryHtml = entries.map((entry) => {
      const line = namingLine(entry, data);
      return '<button type="button" class="pfh-packaging-naming-current" data-naming-copy="' + escapeHtml(line) + '"><span>' + escapeHtml(line) + '</span></button>';
    }).join('');
    const recommendationHtml = recommendations.length ? recommendations.map((item) =>
      '<button type="button" class="pfh-packaging-naming-history" data-naming-copy="' + escapeHtml(item.code) + '">' +
        '<span><b>' + escapeHtml(item.code) + '</b><i>' + escapeHtml(item.exact ? '同尺寸' : '相近') + '</i>' + (item.sameLogo ? '<i class="is-logo">同 Logo</i>' : '') + '</span>' +
        '<small>' + escapeHtml(item.label + (/[）)]$/.test(item.label) ? ' ' : '') + '（' + item.size + '）' + (item.brandName ? ' ' + item.brandName : '')) + '</small>' +
      '</button>'
    ).join('') : '<p class="pfh-packaging-naming-empty">暂无同尺寸或偏差 0.5cm 以内的历史文件</p>';
    const card = document.createElement('section');
    card.className = 'pfh-packaging-naming-card';
    card.setAttribute('role', 'dialog');
    card.setAttribute('aria-label', '包材命名与历史编码');
    const namingTitle = key === 'packageSizeText' && entries.some((entry) => entry.type === 'printed-bag') ? '印刷自立袋命名' : (key === 'packageSizeText' ? '纸盒命名' : '标签 / 印刷命名');
    card.innerHTML = '<header><div><b>' + namingTitle + '</b><span>点击内容即可复制</span></div><button type="button" data-naming-close aria-label="关闭">×</button></header>' +
      '<div class="pfh-packaging-naming-current-list">' + entryHtml + '</div>' +
      '<div class="pfh-packaging-naming-subtitle"><b>历史相近文件编码</b><span>同 Logo 优先 · 偏差 ≤ 0.5cm</span></div>' +
      '<div class="pfh-packaging-naming-history-list">' + recommendationHtml + '</div>';
    panel.appendChild(card);
    const panelRect = panel.getBoundingClientRect();
    const cardRect = card.getBoundingClientRect();
    card.style.left = Math.max(8, Math.min(event.clientX - panelRect.left, panelRect.width - cardRect.width - 8)) + 'px';
    card.style.top = Math.max(8, Math.min(event.clientY - panelRect.top, panelRect.height - cardRect.height - 8)) + 'px';
  }

  function handlePanelContextMenu(event) {
    const detailLink = event.target && event.target.closest && event.target.closest('.pfh-detail-link-value[data-reference-url]');
    if (detailLink) {
      event.preventDefault();
      event.stopPropagation();
      copyText(detailLink.getAttribute('data-reference-url') || '');
      detailLink.classList.add('is-copied');
      window.setTimeout(() => detailLink.classList.remove('is-copied'), 650);
      showToast('链接已复制');
      return;
    }
    const skuCard = event.target && event.target.closest && event.target.closest('.pfh-sku-waterfall-card[data-sku], .pfh-sku[data-sku]');
    if (skuCard) {
      event.preventDefault();
      event.stopPropagation();
      closePackagingNamingCard(ensurePanel());
      showSkuWaterfallContextMenu(skuCard.getAttribute('data-sku'), event, { allowCache: true, includeSearch: false });
      return;
    }
    const row = event.target && event.target.closest && event.target.closest('.pfh-row[data-key="packageSizeText"], .pfh-row[data-key="printSizeText"]');
    if (!row) return;
    event.preventDefault();
    event.stopPropagation();
    showPackagingNamingCard(row, row.getAttribute('data-key'), event);
  }

  function encodeSkuCode128B(value) {
    const text = String(value || '').trim();
    if (!text) throw new Error('SKU 不能为空');
    if (!/^[\x20-\x7e]+$/.test(text)) throw new Error('SKU 含有 Code 128 不支持的字符');
    const values = [104];
    let checksum = 104;
    for (let index = 0; index < text.length; index += 1) {
      const code = text.charCodeAt(index) - 32;
      values.push(code);
      checksum += code * (index + 1);
    }
    values.push(checksum % 103);
    return { value: text, pattern: values.map((code) => CODE128_PATTERNS[code]).concat(CODE128_PATTERNS[106]).join('') };
  }

  function buildSkuBarcodeSvg(value) {
    const encoded = encodeSkuCode128B(value);
    const format = (number) => Number(number.toFixed(4));
    const moduleWidth = 1.13;
    const barReduction = 0.13;
    const barStartX = 11.268;
    const barY = 9.8218;
    const barHeight = 36.01;
    let moduleOffset = 0;
    let isBar = true;
    const bars = [];
    for (const token of encoded.pattern) {
      const modules = Number(token);
      if (isBar) {
        bars.push('<rect x="' + format(barStartX + moduleOffset * moduleWidth) + '" y="' + barY + '" width="' + format(modules * moduleWidth - barReduction) + '" height="' + barHeight + '"></rect>');
      }
      moduleOffset += modules;
      isBar = !isBar;
    }
    return '<?xml version="1.0" encoding="UTF-8"?>' +
      '<svg xmlns="http://www.w3.org/2000/svg" width="198.463pt" height="60.4398pt" viewBox="0 0 198.463 60.4398">' +
      '<rect width="198.463" height="60.4398" fill="#fff"></rect>' +
      '<rect x="11.203" y="9.8218" width="176.28" height="45.01" fill="#fff"></rect>' +
      '<g fill="#000">' + bars.join('') + '</g>' +
      '<rect x="77.343" y="46.8318" width="44" height="8" fill="#fff"></rect>' +
      '<text x="77.3433" y="54.0306" fill="#000" font-family="SimSun, Songti SC, serif" font-size="8pt" font-weight="400" textLength="44" lengthAdjust="spacingAndGlyphs">' + escapeHtml(encoded.value) + '</text>' +
      '</svg>';
  }

  function downloadSkuBarcode(sku, productName) {
    const value = String(sku || '').trim();
    const name = cleanFileNamePart(productName);
    const filename = [value, name].filter(Boolean).join(' ') + '.svg';
    const svg = buildSkuBarcodeSvg(value);
    downloadBlob(new Blob([svg], { type: 'image/svg+xml;charset=utf-8' }), filename);
    addLog('success', '已生成 SKU 条码', value + ' / Code 128-B');
    showToast(value + ' 条码已下载');
  }

  function closeSkuWaterfallContextMenu(panel) {
    const menu = panel && panel.querySelector('.pfh-sku-context-menu');
    if (menu) menu.remove();
    if (panel) panel.querySelectorAll('[data-action="sku-detail-more"]').forEach((button) => button.setAttribute('aria-expanded', 'false'));
    state.skuContextMenuSku = '';
  }

  function getSkuContextSearchSources(data) {
    const source = data && typeof data === 'object' ? data : {};
    const firstImage = (values) => values
      .map((value) => String(value || '').trim())
      .find((value) => value && !/^data:image\//i.test(value)) || '';
    return {
      effect: firstImage([
        source.skuImageUrl,
        source.skuImageFallbackUrl,
        source.effectImage,
        source.productListImageUrl,
        source.productListImageFallbackUrl,
        source.productListImage,
      ]),
      benchmark: firstImage([
        source.benchmarkImageUrl,
        source.benchmarkImageFallbackUrl,
        source.benchmarkImage,
      ]),
    };
  }

  function skuContextReverseSearchGroupHtml(label, imageUrl) {
    const url = String(imageUrl || '').trim();
    if (!url) return '';
    const encodedUrl = escapeHtml(url);
    return '<div class="pfh-sku-context-search-group"><strong>' + escapeHtml(label) + '</strong><div class="pfh-sku-context-search-actions">' +
      '<button type="button" data-action="reverse-image-search" data-engine="1688" data-image-url="' + encodedUrl + '" title="1688 搜' + escapeHtml(label) + '">1688</button>' +
      '<button type="button" data-action="reverse-image-search" data-engine="google" data-image-url="' + encodedUrl + '" title="Google 搜' + escapeHtml(label) + '">Google</button>' +
      '<button type="button" data-action="reverse-image-search" data-engine="yandex" data-image-url="' + encodedUrl + '" title="Yandex 搜' + escapeHtml(label) + '">Yandex</button>' +
      '</div></div>';
  }

  function showSkuWaterfallContextMenu(sku, event, options) {
    const opts = options || {};
    const panel = ensurePanel();
    closeSkuWaterfallContextMenu(panel);
    const item = state.index.find((entry) => entry.sku === sku) || (state.data && state.data.sku === sku ? state.data : null);
    if (!item) return;
    const sourceData = opts.includeSearch
      ? normalizeData(loadData(sku) || (state.data && state.data.sku === sku ? state.data : item))
      : item;
    const searchSources = opts.includeSearch ? getSkuContextSearchSources(sourceData) : { effect: '', benchmark: '' };
    const searchHtml = opts.includeSearch
      ? skuContextReverseSearchGroupHtml('搜 SKU 效果图', searchSources.effect) + skuContextReverseSearchGroupHtml('搜对标图', searchSources.benchmark)
      : '';
    const cacheHtml = opts.allowCache === false
      ? ''
      : '<button type="button" data-action="sku-context-cache" data-sku="' + escapeHtml(sku) + '">完整缓存信息</button>';
    const menu = document.createElement('div');
    menu.className = 'pfh-sku-context-menu';
    menu.setAttribute('role', 'menu');
    menu.innerHTML = searchHtml + cacheHtml +
      '<button type="button" data-action="sku-context-barcode" data-sku="' + escapeHtml(sku) + '">生成条码</button>';
    panel.appendChild(menu);
    state.skuContextMenuSku = sku;
    panel.querySelectorAll('[data-action="sku-detail-more"]').forEach((button) => {
      if (button.getAttribute('data-sku') === sku) button.setAttribute('aria-expanded', 'true');
    });
    const panelRect = panel.getBoundingClientRect();
    const menuRect = menu.getBoundingClientRect();
    menu.style.left = Math.max(8, Math.min(event.clientX - panelRect.left, panelRect.width - menuRect.width - 8)) + 'px';
    menu.style.top = Math.max(8, Math.min(event.clientY - panelRect.top, panelRect.height - menuRect.height - 8)) + 'px';
  }

  function closeSkuCacheEditor() {
    const panel = document.getElementById(PANEL_ID);
    const layer = panel && panel.querySelector('.pfh-cache-editor-layer');
    if (layer) layer.remove();
    state.skuCacheEditorSku = '';
  }

  const SKU_CACHE_EDITOR_LABELS = Object.freeze({
    sku: 'SKU 编码',
    name: '产品名称',
    productName: '产品名称',
    brand: '品牌',
    brandName: '品牌',
    categoryName: '产品分类',
    productType: '产品类型',
    developerName: '开发人员',
    packageCode: '纸盒编码',
    printCode: '印刷编码',
    packageSizeText: '纸盒尺寸',
    printSizeText: '印刷尺寸',
    productSizeText: '产品尺寸',
    purchasePrice: '采购价格',
    ingredientEnglish: '英文成分',
    ingredientChinese: '中文成分',
    copywriting: '产品文案',
    benchmarkImageUrl: '对标图片',
    effectImage: '效果图片',
    productListImage: '列表图片',
    manualFieldOverrides: '手动覆盖字段',
    recentFieldChanges: '近期字段变更',
    updatedAt: '更新时间',
    updatedAtMs: '更新时间戳',
    createdAt: '创建时间',
  });

  function getSkuCacheEditorValueType(value) {
    if (value === null) return 'null';
    if (Array.isArray(value)) return 'array';
    if (value && typeof value === 'object') return 'object';
    if (typeof value === 'number') return 'number';
    if (typeof value === 'boolean') return 'boolean';
    return 'string';
  }

  function getSkuCacheEditorFieldLabel(key, isArrayItem) {
    if (isArrayItem) return '第 ' + (Number(key) + 1) + ' 项';
    return SKU_CACHE_EDITOR_LABELS[key] || String(key || '未命名字段');
  }

  function encodeSkuCacheEditorPath(path) {
    return encodeURIComponent(JSON.stringify(path || []));
  }

  function decodeSkuCacheEditorPath(value) {
    const parsed = JSON.parse(decodeURIComponent(String(value || '')));
    if (!Array.isArray(parsed)) throw new Error('字段路径无效');
    return parsed;
  }

  function collectSkuCacheEditorSearchText(key, value, seen) {
    const parts = [String(key || ''), getSkuCacheEditorFieldLabel(key, false)];
    const visited = seen || new WeakSet();
    if (value && typeof value === 'object') {
      if (visited.has(value)) return parts.join(' ');
      visited.add(value);
      Object.keys(value).forEach((childKey) => parts.push(collectSkuCacheEditorSearchText(childKey, value[childKey], visited)));
    } else {
      parts.push(String(value === null ? 'null' : (value === undefined ? 'undefined' : value)));
    }
    return parts.join(' ').replace(/\s+/g, ' ').slice(0, 12000);
  }

  function renderSkuCacheEditorScalar(key, value, path, depth, isArrayItem) {
    const type = getSkuCacheEditorValueType(value);
    const label = getSkuCacheEditorFieldLabel(key, isArrayItem);
    const technicalKey = isArrayItem ? '[' + key + ']' : String(key || '');
    const pathText = path.map((part) => typeof part === 'number' ? '[' + part + ']' : String(part)).join('.').replace('.[', '[');
    const encodedPath = encodeSkuCacheEditorPath(path);
    const valueText = type === 'null' ? '' : String(value);
    const longText = type === 'string' && (valueText.length > 88 || /[\r\n]/.test(valueText));
    const isSku = path.length === 1 && path[0] === 'sku';
    const options = ['string', 'number', 'boolean', 'null'].map((candidate) => '<option value="' + candidate + '"' + (candidate === type ? ' selected' : '') + '>' + ({ string: '文本', number: '数字', boolean: '布尔', null: '空值' }[candidate]) + '</option>').join('');
    const control = type === 'boolean'
      ? '<select class="pfh-cache-value-input" data-cache-role="value"><option value="true"' + (value ? ' selected' : '') + '>是 / true</option><option value="false"' + (!value ? ' selected' : '') + '>否 / false</option></select>'
      : (longText
        ? '<textarea class="pfh-cache-value-input" data-cache-role="value"' + (type === 'null' ? ' disabled' : '') + (isSku ? ' readonly' : '') + '>' + escapeHtml(valueText) + '</textarea>'
        : '<input class="pfh-cache-value-input" data-cache-role="value" value="' + escapeHtml(valueText) + '"' + (type === 'null' ? ' disabled' : '') + (isSku ? ' readonly' : '') + '>');
    return '<div class="pfh-cache-field pfh-cache-scalar" data-cache-path="' + escapeHtml(encodedPath) + '" data-cache-search="' + escapeHtml(collectSkuCacheEditorSearchText(key, value)) + '">' +
      '<div class="pfh-cache-field-head"><div class="pfh-cache-field-key"><strong>' + escapeHtml(label) + '</strong><code title="' + escapeHtml(pathText) + '">' + escapeHtml(technicalKey) + '</code></div>' +
      '<div class="pfh-cache-field-control"><select class="pfh-cache-value-type" data-cache-role="type"' + (isSku ? ' disabled' : '') + '>' + options + '</select>' + control + '</div></div></div>';
  }

  function renderSkuCacheEditorField(key, value, path, depth, isArrayItem) {
    const type = getSkuCacheEditorValueType(value);
    if (type !== 'object' && type !== 'array') return renderSkuCacheEditorScalar(key, value, path, depth, isArrayItem);
    const entries = Object.entries(value);
    const label = getSkuCacheEditorFieldLabel(key, isArrayItem);
    const technicalKey = isArrayItem ? '[' + key + ']' : String(key || '');
    const children = entries.length
      ? entries.map(([childKey, childValue]) => renderSkuCacheEditorField(type === 'array' ? Number(childKey) : childKey, childValue, path.concat(type === 'array' ? Number(childKey) : childKey), depth + 1, type === 'array')).join('')
      : '<div class="pfh-cache-empty">' + (type === 'array' ? '空数组' : '空对象') + '</div>';
    return '<details class="pfh-cache-field pfh-cache-container" data-cache-search="' + escapeHtml(collectSkuCacheEditorSearchText(key, value)) + '"' + (depth < 2 ? ' open' : '') + '>' +
      '<summary><span class="pfh-cache-container-title"><strong>' + escapeHtml(label) + '</strong><code>' + escapeHtml(technicalKey) + '</code></span><span class="pfh-cache-container-count">' + escapeHtml((type === 'array' ? '数组 ' : '对象 ') + entries.length + ' 项') + '</span></summary>' +
      '<div class="pfh-cache-children">' + children + '</div></details>';
  }

  function getSkuCacheEditorGroup(key) {
    const text = String(key || '');
    if (/copy|ingredient|direction|description|selling|efficacy|benefit|warning|claim|文案|成分/i.test(text)) return 'copy';
    if (/image|img|photo|picture|pic|thumbnail|url|file|attachment|asset|图片|文件/i.test(text)) return 'asset';
    if (/package|print|material|size|length|width|height|weight|volume|dimension|纸盒|印刷|尺寸|包材/i.test(text)) return 'material';
    if (/status|state|task|ledger|upload|seen|error|sync|source|history|record|log|time|date|created|updated|状态|记录/i.test(text)) return 'workflow';
    if (/^(?:sku|name|productName|brand|brandName|category|categoryName|productType|developer|developerName|purchasePrice|price)$/i.test(text)) return 'basic';
    return 'other';
  }

  function renderSkuCacheEditorGroups(raw) {
    const definitions = [
      ['basic', '基础信息'],
      ['material', '包材与尺寸'],
      ['asset', '图片与文件'],
      ['copy', '文案与成分'],
      ['workflow', '流程与记录'],
      ['other', '其他缓存'],
    ];
    const groups = Object.fromEntries(definitions.map(([key]) => [key, []]));
    Object.entries(raw).forEach(([key, value]) => groups[getSkuCacheEditorGroup(key)].push([key, value]));
    return definitions.map(([groupKey, label]) => {
      const entries = groups[groupKey];
      if (!entries.length) return '';
      const fields = entries.map(([key, value]) => '<div class="pfh-cache-top-field" data-cache-search="' + escapeHtml(collectSkuCacheEditorSearchText(key, value)) + '">' + renderSkuCacheEditorField(key, value, [key], 0, false) + '</div>').join('');
      return '<section class="pfh-cache-group" data-cache-group="' + groupKey + '"><header><strong>' + label + '</strong><span>' + entries.length + ' 个顶层字段</span></header><div class="pfh-cache-group-fields">' + fields + '</div></section>';
    }).join('');
  }

  function setSkuCacheEditorPathValue(target, path, value) {
    let cursor = target;
    for (let index = 0; index < path.length - 1; index += 1) {
      if (!cursor || typeof cursor !== 'object') throw new Error('字段路径不存在：' + path.join('.'));
      cursor = cursor[path[index]];
    }
    cursor[path[path.length - 1]] = value;
  }

  function parseSkuCacheEditorScalar(type, rawValue, label) {
    const text = String(rawValue == null ? '' : rawValue);
    if (type === 'null') return null;
    if (type === 'string') return text;
    if (type === 'number') {
      if (!text.trim()) throw new Error(label + ' 不能为空数字');
      const number = Number(text.trim());
      if (!Number.isFinite(number)) throw new Error(label + ' 不是有效数字');
      return number;
    }
    if (type === 'boolean') {
      if (/^(?:true|1|yes|是)$/i.test(text.trim())) return true;
      if (/^(?:false|0|no|否)$/i.test(text.trim())) return false;
      throw new Error(label + ' 的布尔值请填写 true 或 false');
    }
    return text;
  }

  function updateSkuCacheEditorValueControl(typeControl) {
    const field = typeControl && typeControl.closest('.pfh-cache-scalar');
    const current = field && field.querySelector('[data-cache-role="value"]');
    if (!field || !current) return;
    const type = typeControl.value;
    if (type === 'boolean' && current.tagName !== 'SELECT') {
      const select = document.createElement('select');
      select.className = 'pfh-cache-value-input';
      select.setAttribute('data-cache-role', 'value');
      const truthy = /^(?:true|1|yes|是)$/i.test(String(current.value || '').trim());
      select.innerHTML = '<option value="true"' + (truthy ? ' selected' : '') + '>是 / true</option><option value="false"' + (!truthy ? ' selected' : '') + '>否 / false</option>';
      current.replaceWith(select);
      return;
    }
    if (type !== 'boolean' && current.tagName === 'SELECT') {
      const input = document.createElement('input');
      input.className = 'pfh-cache-value-input';
      input.setAttribute('data-cache-role', 'value');
      input.value = current.value;
      current.replaceWith(input);
      input.disabled = type === 'null';
      input.placeholder = type === 'number' ? '请输入数字' : '请输入内容';
      return;
    }
    current.disabled = type === 'null';
    current.placeholder = type === 'number' ? '请输入数字' : '请输入内容';
  }

  function filterSkuCacheEditorFields(query) {
    const layer = document.querySelector('#' + PANEL_ID + ' .pfh-cache-editor-layer');
    if (!layer) return;
    const needle = String(query || '').trim().toLowerCase();
    layer.querySelectorAll('.pfh-cache-top-field').forEach((field) => {
      field.classList.toggle('is-hidden', Boolean(needle && !String(field.getAttribute('data-cache-search') || '').toLowerCase().includes(needle)));
    });
    layer.querySelectorAll('.pfh-cache-group').forEach((group) => {
      group.hidden = !Array.from(group.querySelectorAll(':scope .pfh-cache-top-field')).some((field) => !field.classList.contains('is-hidden'));
    });
  }

  function toggleSkuCacheEditorDetails(open) {
    const layer = document.querySelector('#' + PANEL_ID + ' .pfh-cache-editor-layer');
    if (!layer) return;
    layer.querySelectorAll('details.pfh-cache-field').forEach((item) => { item.open = Boolean(open); });
  }

  function showSkuCacheEditor(sku) {
    const normalizedSku = String(sku || '').trim();
    const raw = loadData(normalizedSku);
    if (!normalizedSku || !raw || typeof raw !== 'object' || Array.isArray(raw)) {
      showToast('没有找到 ' + (normalizedSku || '当前 SKU') + ' 的完整缓存');
      return;
    }
    const panel = ensurePanel();
    closeSkuCacheEditor();
    const layer = document.createElement('div');
    layer.className = 'pfh-cache-editor-layer';
    layer.setAttribute('data-action', 'sku-cache-editor-close');
    layer.innerHTML = '<section class="pfh-cache-editor" role="dialog" aria-modal="true" aria-label="SKU 完整缓存信息">' +
      '<header><div><h3>完整缓存信息 · ' + escapeHtml(normalizedSku) + '</h3><p>全部缓存已按用途整理；对象和数组可展开后逐项修改。</p></div><button type="button" data-action="sku-cache-editor-close" aria-label="关闭">×</button></header>' +
      '<div class="pfh-cache-editor-summary"><span>' + escapeHtml(Object.keys(raw).length + ' 个顶层字段') + '</span><input type="search" class="pfh-cache-editor-search" placeholder="搜索字段名或内容"><button type="button" data-action="sku-cache-editor-expand">全部展开</button><button type="button" data-action="sku-cache-editor-collapse">全部折叠</button></div>' +
      '<div class="pfh-cache-editor-body">' + renderSkuCacheEditorGroups(raw) + '</div>' +
      '<p class="pfh-cache-editor-error" aria-live="polite"></p>' +
      '<footer><span>SKU 键不可修改；尺寸等派生字段保存时会按现有兼容规则重新计算。</span><div><button type="button" data-action="sku-cache-editor-close">取消</button><button type="button" class="is-primary" data-action="sku-cache-editor-save">保存修改</button></div></footer>' +
      '</section>';
    panel.appendChild(layer);
    layer.style.setProperty('z-index', '360', 'important');
    layer._pfhCacheOriginal = JSON.parse(JSON.stringify(raw));
    state.skuCacheEditorSku = normalizedSku;
    const search = layer.querySelector('.pfh-cache-editor-search');
    if (search) search.focus();
  }

  function saveSkuCacheEditor() {
    const panel = document.getElementById(PANEL_ID);
    const layer = panel && panel.querySelector('.pfh-cache-editor-layer');
    const errorNode = layer && layer.querySelector('.pfh-cache-editor-error');
    const sku = String(state.skuCacheEditorSku || '').trim();
    if (!sku || !layer || !layer._pfhCacheOriginal) return;
    try {
      const edited = JSON.parse(JSON.stringify(layer._pfhCacheOriginal));
      layer.querySelectorAll('.pfh-cache-scalar[data-cache-path]').forEach((field) => {
        const path = decodeSkuCacheEditorPath(field.getAttribute('data-cache-path'));
        const typeControl = field.querySelector('[data-cache-role="type"]');
        const valueControl = field.querySelector('[data-cache-role="value"]');
        const label = field.querySelector('.pfh-cache-field-key strong');
        const value = parseSkuCacheEditorScalar(typeControl && typeControl.value || 'string', valueControl && valueControl.value || '', label && label.textContent || path.join('.'));
        setSkuCacheEditorPathValue(edited, path, value);
      });
      const previous = normalizeData(loadData(sku) || { sku });
      edited.sku = sku;
      const overrides = { ...(edited.manualFieldOverrides && typeof edited.manualFieldOverrides === 'object' ? edited.manualFieldOverrides : {}) };
      MANUAL_OVERRIDE_FIELDS.forEach((key) => {
        if (!trackedDataValuesEqual(key, previous[key], edited[key])) overrides[key] = edited[key] == null ? '' : String(edited[key]).trim();
      });
      edited.manualFieldOverrides = overrides;
      saveData(sku, edited, { changeSource: '完整信息编辑', trackEmptyChanges: true });
      closeSkuCacheEditor();
      renderShell();
      showToast(sku + ' 完整缓存已保存');
    } catch (error) {
      if (errorNode) errorNode.textContent = '无法保存：' + (formatErrorMessage(error) || '字段格式错误');
    }
  }

  async function tryHydrateCopywritingFromApi(sku, options) {
    const opts = options || {};
    const normalizedSku = String(sku || '').trim();
    if (!normalizedSku) return { handled: false };
    const updateStatus = (message) => {
      if (typeof opts.onStatus === 'function') opts.onStatus(message);
    };
    const workingData = normalizeData(opts.data || loadData(normalizedSku) || { sku: normalizedSku });
    const cached = normalizeCopywritingRecord(workingData.copywriting);
    let file;
    try {
      updateStatus('正在通过 PLM API 定位产品文案 Word...');
      file = await fetchApiCopywritingFile(workingData, { force: Boolean(opts.force) });
    } catch (error) {
      addLog('warn', '产品文案：定位失败，改用页面下载', normalizedSku + ' | ' + formatErrorMessage(error));
      return { handled: false, error };
    }
    if (!file || !file.found) return { handled: false, noFile: true };
    const fileName = file.fileName;
    const fileTimestamp = file.fileTimestamp || '';
    const sameFile = Boolean(cached && cached.fullText
      && cached.parserVersion === COPYWRITING_PARSER_VERSION
      && compactText(cached.fileName).toLowerCase() === compactText(fileName).toLowerCase());
    if (!opts.force && sameFile) {
      const next = markCopywritingCheckedAt(workingData, cached, Date.now());
      addLog('info', '产品文案：命中历史缓存', normalizedSku + ' | ' + fileName);
      return { handled: true, skipped: true, data: next, file };
    }
    if (!opts.force && cached && cached.fileTimestamp && fileTimestamp && fileTimestamp < cached.fileTimestamp) {
      const next = markCopywritingCheckedAt(workingData, cached, Date.now());
      addLog('warn', '产品文案：当前 Word 早于缓存，保留较新文案', normalizedSku + ' | ' + fileName + ' < ' + cached.fileName);
      return { handled: true, skipped: true, older: true, data: next, file };
    }
    try {
      updateStatus('正在通过 API 下载 Word ' + fileName);
      const arrayBuffer = await withCopywritingTimeout(downloadCopywritingDocument(file.url), 18000, 'API Word 文件读取');
      if (!isCopywritingDocxBuffer(arrayBuffer)) throw new Error('后台返回内容不是有效 Word 文件');
      updateStatus('正在解析 API Word 表格...');
      addLog('info', '产品文案：开始解析 Word', normalizedSku + ' | ' + fileName + ' | ' + arrayBuffer.byteLength + 'B');
      const fileHash = await hashCopywritingBuffer(arrayBuffer);
      const parsedDocument = await withCopywritingTimeout(parseCopywritingDocxRows(arrayBuffer), 20000, 'API Word 表格解析');
      const built = buildMainstreamCopywriting(parsedDocument, workingData);
      if (!built.sections.length) throw new Error('后台 Word 中未识别到主流版文案字段');
      const nextRecord = buildCopywritingRecord(fileName, fileTimestamp, fileHash, built, cached);
      const next = mergeCopywritingCacheIntoData(workingData, nextRecord);
      saveData(normalizedSku, next);
      const updated = Boolean(cached && cached.fullText && nextRecord.updatePending && (
        nextRecord.fileHash !== cached.fileHash
        || nextRecord.fileName !== cached.fileName
        || nextRecord.fullText !== cached.fullText
      ));
      addLog('info', updated ? '产品文案：检测到更新' : '产品文案：读取成功', normalizedSku + ' | ' + fileName + ' | ' + built.sections.length + '段');
      return { handled: true, data: next, updated, file };
    } catch (error) {
      addLog('warn', '产品文案：Word 读取失败，改用页面下载', normalizedSku + ' | ' + formatErrorMessage(error));
      return { handled: false, error, file };
    }
  }

  async function openCopywritingFromCurrent(force) {
    const data = normalizeData(state.data || (state.selectedSku ? loadData(state.selectedSku) : null));
    if (!data || !data.sku) {
      showToast('请先选择一个产品');
      return;
    }
    const sku = data.sku;
    const currentCached = normalizeCopywritingRecord(data.copywriting);
    const hasImmediateCopywriting = Boolean(currentCached && currentCached.fullText);
    if (!state.copywritingMode) state.copywritingView = 'file';
    state.copywritingMode = true;
    state.copywritingLoading = !hasImmediateCopywriting;
    state.copywritingChecking = true;
    state.copywritingError = '';
    state.copywritingStatus = hasImmediateCopywriting ? '正在检查新文案...' : '正在读取本地缓存...';
    stopScan();
    stopMaterialWatch();
    cancelDrawerTabFlow();
    expandPanel();
    await wait(COPYWRITING_CACHE_DEBOUNCE_MS);
    const storedData = hasImmediateCopywriting ? data : normalizeData(loadData(sku) || data);
    const storedCached = normalizeCopywritingRecord(storedData.copywriting);
    const initialCached = (currentCached && currentCached.fullText ? currentCached : null)
      || (storedCached && storedCached.fullText ? storedCached : null)
      || currentCached
      || storedCached;
    const hasCachedCopywriting = Boolean(initialCached && initialCached.fullText);
    const skipRecentCopywritingCheck = !force && hasCachedCopywriting
      && initialCached.parserVersion === COPYWRITING_PARSER_VERSION
      && isCopywritingCheckFresh(initialCached);
    if (initialCached && initialCached.fullText && !hasImmediateCopywriting) {
      state.data = normalizeData({ ...state.data, copywriting: initialCached });
    }
    if (skipRecentCopywritingCheck) {
      state.copywritingLoading = false;
      state.copywritingChecking = false;
      state.copywritingStatus = '';
      state.copywritingError = '';
      addLog('info', '产品文案：30分钟内已检查，跳过重复检查', sku);
      renderShell();
      return;
    }
    if (initialCached && initialCached.fullText && !hasImmediateCopywriting) {
      state.copywritingLoading = false;
      state.copywritingStatus = '正在检查新文案...';
      state.copywritingChecking = true;
      renderShell();
    }
    addLog('info', '产品文案：开始读取', sku + (force ? ' 重新获取' : ''));
    try {
      const apiResult = await tryHydrateCopywritingFromApi(sku, {
        force: Boolean(force),
        data: normalizeData(loadData(sku) || state.data || data),
        onStatus: (message) => {
          state.copywritingStatus = message;
          renderShell();
        },
      });
      if (apiResult && apiResult.handled) {
        state.data = normalizeData(apiResult.data || loadData(sku) || data);
        state.copywritingStatus = '';
        state.copywritingError = '';
        if (!apiResult.skipped) showToast(apiResult.updated ? '文案已更新，差异已高亮' : '文案读取成功');
        renderShell();
        return;
      }
      if (apiResult && apiResult.noFile) {
        state.data = normalizeData(loadData(sku) || state.data || data);
        state.copywritingLoading = false;
        state.copywritingChecking = false;
        state.copywritingStatus = '';
        state.copywritingError = '';
        addLog('info', '产品文案：未找到 Word，不再读取页面附件', sku);
        renderShell();
        return;
      }
      let drawer = getProjectDrawerForSku(sku);
      if (!drawer) {
        await openSelectedProjectDetail({ preserveCopywriting: hasCachedCopywriting });
        drawer = await waitFor(() => getProjectDrawerForSku(sku), 6000, 150);
      }
      if (!drawer) throw new Error('未打开当前编码的项目详情');
      stopScan();
      state.copywritingStatus = '正在定位产品信息里的产品文案...';
      renderShell();
      await switchDrawerTab(drawer, L.productTab);
      const productReady = await waitFor(() => {
        const tab = findTabButton(drawer, L.productTab);
        return tab && isActiveTab(tab);
      }, 5000, 120);
      if (!productReady) throw new Error('无法切换到产品信息');
      const item = await waitFor(() => findProductCopywritingItem(drawer), 5000, 160);
      if (!item) throw new Error('产品信息中未找到“产品文案”字段');
      const file = findProductCopywritingFile(item, sku);
      if (!file) throw new Error('产品文案字段中未找到当前编码的 Word 文件');
      let workingData = normalizeData(loadData(sku) || state.data || data);
      let cached = normalizeCopywritingRecord(workingData.copywriting);
      if (cached && cached.fullText) {
        workingData = markCopywritingCheckedAt(workingData, cached, Date.now());
        cached = normalizeCopywritingRecord(workingData.copywriting);
      }
      const fileTimestamp = extractCopywritingFileTimestamp(file.fileName);
      if (!force && cached && cached.fullText && cached.parserVersion === COPYWRITING_PARSER_VERSION && compactText(cached.fileName).toLowerCase() === compactText(file.fileName).toLowerCase()) {
        state.data = workingData;
        state.copywritingStatus = '';
        state.copywritingError = '';
        addLog('info', '产品文案：命中历史缓存', file.fileName);
        return;
      }
      if (!force && cached && cached.fileTimestamp && fileTimestamp && fileTimestamp < cached.fileTimestamp) {
        state.copywritingError = '页面中的 Word 版本早于缓存，已保留较新的文案';
        addLog('warn', '产品文案：检测到旧附件', file.fileName + ' < ' + cached.fileName);
        return;
      }
      if (!hasCachedCopywriting) state.copywritingLoading = true;
      state.copywritingStatus = '正在触发 Word 下载 ' + file.fileName;
      renderShell();
      let source = await withCopywritingTimeout(resolveCopywritingDocumentSource(file.card, file.fileName), 12000, 'Word 下载监听');
      if (!source || (!source.url && !source.arrayBuffer)) throw new Error('未读取到 Word 文件内容');
      addLog('info', '产品文案：已取得文件内容', source.arrayBuffer ? '内存 Word 数据' : String(source.url || '').replace(/\?.*$/, '?...'));
      let arrayBuffer;
      try {
        state.copywritingStatus = source.arrayBuffer ? '正在校验 Word 文件...' : '正在读取 Word 文件...';
        renderShell();
        arrayBuffer = source.arrayBuffer || await withCopywritingTimeout(downloadCopywritingDocument(source.url), 18000, 'Word 文件读取');
        if (!isCopywritingDocxBuffer(arrayBuffer)) throw new Error('读取到的内容不是有效 Word 文件');
      } catch (error) {
        if (source.kind === 'captured') throw error;
        addLog('warn', '产品文案：组件地址不可直接读取，改用下载监听', formatErrorMessage(error));
        state.copywritingStatus = '正在重新监听 Word 下载...';
        renderShell();
        source = { ...(await withCopywritingTimeout(captureCopywritingDownloadSource(file.card, file.fileName), 12000, '备用下载监听')), kind: 'captured' };
        if (!source.url && !source.arrayBuffer) throw error;
        state.copywritingStatus = source.arrayBuffer ? '正在校验 Word 文件...' : '正在读取 Word 文件...';
        renderShell();
        arrayBuffer = source.arrayBuffer || await withCopywritingTimeout(downloadCopywritingDocument(source.url), 18000, '备用 Word 文件读取');
        if (!isCopywritingDocxBuffer(arrayBuffer)) throw new Error('下载监听取得的内容不是有效 Word 文件');
      }
      const fileHash = await hashCopywritingBuffer(arrayBuffer);
      state.copywritingStatus = '正在解析 Word 表格...';
      renderShell();
      addLog('info', '产品文案：开始解析 Word', file.fileName + ' | ' + arrayBuffer.byteLength + 'B');
      const parsedDocument = await withCopywritingTimeout(parseCopywritingDocxRows(arrayBuffer), 20000, 'Word 表格解析');
      const built = buildMainstreamCopywriting(parsedDocument, workingData);
      if (!built.sections.length) throw new Error('Word 中未识别到主流版文案字段');
      const next = buildCopywritingRecord(file.fileName, fileTimestamp, fileHash, built, cached);
      saveData(sku, mergeCopywritingCacheIntoData(workingData, next));
      state.copywritingStatus = '';
      state.copywritingError = '';
      const updated = Boolean(cached && cached.fullText && next.updatePending && (
        next.fileHash !== cached.fileHash
        || next.fileName !== cached.fileName
        || next.fullText !== cached.fullText
      ));
      addLog('info', updated ? '产品文案：检测到更新' : '产品文案：读取成功', file.fileName + ' ' + built.sections.length + '段');
      showToast(updated ? '文案已更新，差异已高亮' : '文案读取成功');
    } catch (error) {
      state.copywritingError = formatErrorMessage(error) || '产品文案读取失败';
      addLog('error', '产品文案读取失败', sku + ' ' + state.copywritingError);
      showToast('产品文案读取失败');
    } finally {
      state.copywritingLoading = false;
      state.copywritingChecking = false;
      renderShell();
    }
  }

  function switchDetailViewTab(nextView) {
    const target = normalizeDetailViewTab(nextView);
    const current = getCurrentDetailViewTab();
    if (target === 'sizeImage' && !state.sizeImageAccessEnabled) {
      showToast(state.sizeImageAccessLoading ? '正在准备功能' : '该功能暂未开放，敬请期待');
      return;
    }
    if (target === 'parameterImage' && !state.parameterImageAccessEnabled) {
      showToast(state.parameterImageAccessLoading ? '正在准备功能' : '该功能暂未开放，敬请期待');
      scheduleParameterImageAccessRefresh(0);
      return;
    }
    if (target === current) return;
    const data = normalizeData(state.data || (state.selectedSku ? loadData(state.selectedSku) : null));
    if (!data || !data.sku) {
      showToast('请先从左侧选择 SKU');
      return;
    }
    state.detailViewPreviousTab = current;
    state.selectedSku = data.sku;
    state.data = data;
    if (target === 'copywriting') {
      state.view = 'detail';
      state.copywritingMode = false;
      openCopywritingFromCurrent(false);
      return;
    }
    state.copywritingMode = false;
    state.view = target;
    if (target === 'parameterImage') parameterImageFeature.loadRules();
    expandPanel();
  }

  function acknowledgeCopywritingUpdate() {
    const data = normalizeData(state.data || (state.selectedSku ? loadData(state.selectedSku) : null));
    const record = normalizeCopywritingRecord(data && data.copywriting);
    if (!data || !data.sku || !record) return;
    const next = {
      ...record,
      updatePending: false,
      changedSectionKeys: [],
      removedSections: [],
      previousSections: [],
    };
    saveData(data.sku, { ...data, copywriting: next });
    showToast('已标记为查看');
    renderShell();
  }

  async function hydrateCopywritingForSku(sku, options) {
    const opts = options || {};
    const resultGeneration = Number(state.skuResultGeneration[sku] || 0);
    if (!sku || state.copywritingHydratingSkus.has(sku)) return normalizeData(loadData(sku) || {});
    const failedAt = Number(state.copywritingHydrateFailedAt[sku] || 0);
    if (!opts.force && failedAt && Date.now() - failedAt < 10 * 60 * 1000) return normalizeData(loadData(sku) || {});
    const recentData = normalizeData(loadData(sku) || {});
    const recentRecord = normalizeCopywritingRecord(recentData.copywriting);
    if (!opts.force && recentRecord && recentRecord.parserVersion === COPYWRITING_PARSER_VERSION && isCopywritingCheckFresh(recentRecord)) return recentData;
    state.copywritingHydratingSkus.add(sku);
    let drawer = null;
    let originalTab = '';
    try {
      if (state.ingredientHydratingSkus.has(sku)) await waitFor(() => !state.ingredientHydratingSkus.has(sku), 65000, 250);
      const apiResult = await tryHydrateCopywritingFromApi(sku, {
        force: Boolean(opts.force),
        data: recentData,
        onStatus: !opts.silent ? (message) => {
          state.copywritingStatus = message;
          renderShell();
        } : null,
      });
      if (apiResult && apiResult.handled) {
        delete state.copywritingHydrateFailedAt[sku];
        return normalizeData(apiResult.data || loadData(sku) || recentData);
      }
      if (apiResult && apiResult.noFile) return recentData;
      drawer = opts.drawer || getProjectDrawerForSku(sku);
      if (!drawer || drawer !== getProjectDrawerForSku(sku)) return normalizeData(loadData(sku) || {});
      originalTab = getActiveTabText(drawer);
      if (opts.silent && !opts.file && getActiveTabText(drawer) !== L.productTab && !(apiResult && apiResult.error)) return normalizeData(loadData(sku) || {});
      if (!opts.file) await switchDrawerTab(drawer, L.productTab);
      if (!opts.file) await waitFor(() => findProductCopywritingItem(drawer), 5000, 160);
      const item = opts.file ? null : findProductCopywritingItem(drawer);
      if (!opts.file && !item) return normalizeData(loadData(sku) || {});
      const file = opts.file || findProductCopywritingFile(item, sku);
      if (!file) return normalizeData(loadData(sku) || {});
      const cached = normalizeData(loadData(sku) || (state.data && state.data.sku === sku ? state.data : { sku }));
      const oldRecord = normalizeCopywritingRecord(cached.copywriting);
      const sameFile = oldRecord && oldRecord.fullText
        && oldRecord.parserVersion === COPYWRITING_PARSER_VERSION
        && compactText(oldRecord.fileName).toLowerCase() === compactText(file.fileName).toLowerCase();
      if (!opts.force && isCopywritingCheckFresh(oldRecord)) return cached;
      const fileTimestamp = extractCopywritingFileTimestamp(file.fileName);
      if (!opts.force && sameFile) return markCopywritingCheckedAt(cached, oldRecord, Date.now());
      if (!opts.force && oldRecord && oldRecord.fileTimestamp && fileTimestamp && fileTimestamp < oldRecord.fileTimestamp) return markCopywritingCheckedAt(cached, oldRecord, Date.now());

      let source = await withCopywritingTimeout(resolveCopywritingDocumentSource(file.card, file.fileName), 12000, '\u4ea7\u54c1\u6587\u6848 Word \u4e0b\u8f7d\u76d1\u542c');
      if (!source || (!source.url && !source.arrayBuffer)) throw new Error('\u672a\u8bfb\u53d6\u5230\u4ea7\u54c1\u6587\u6848 Word');
      let arrayBuffer;
      try {
        arrayBuffer = source.arrayBuffer || await withCopywritingTimeout(downloadCopywritingDocument(source.url), 18000, '\u4ea7\u54c1\u6587\u6848 Word \u8bfb\u53d6');
        if (!isCopywritingDocxBuffer(arrayBuffer)) throw new Error('\u8bfb\u53d6\u5230\u7684\u5185\u5bb9\u4e0d\u662f\u6709\u6548 Word \u6587\u4ef6');
      } catch (error) {
        if (source.kind === 'captured') throw error;
        source = { ...(await withCopywritingTimeout(captureCopywritingDownloadSource(file.card, file.fileName), 12000, '\u5907\u7528\u4ea7\u54c1\u6587\u6848 Word \u4e0b\u8f7d\u76d1\u542c')), kind: 'captured' };
        arrayBuffer = source.arrayBuffer || (source.url ? await withCopywritingTimeout(downloadCopywritingDocument(source.url), 18000, '\u5907\u7528\u4ea7\u54c1\u6587\u6848 Word \u8bfb\u53d6') : null);
        if (!isCopywritingDocxBuffer(arrayBuffer)) throw error;
      }
      const fileHash = await hashCopywritingBuffer(arrayBuffer);
      const parsedDocument = await withCopywritingTimeout(parseCopywritingDocxRows(arrayBuffer), 20000, '\u4ea7\u54c1\u6587\u6848 Word \u8868\u683c\u89e3\u6790');
      const built = buildMainstreamCopywriting(parsedDocument, cached);
      if (!built.sections.length) throw new Error('Word \u4e2d\u672a\u8bc6\u522b\u5230\u4e3b\u6d41\u7248\u6587\u6848\u5b57\u6bb5');
      const nextRecord = buildCopywritingRecord(file.fileName, fileTimestamp, fileHash, built, oldRecord);
      const next = mergeCopywritingCacheIntoData(cached, nextRecord);
      if (drawer !== getProjectDrawerForSku(sku) || Number(state.skuResultGeneration[sku] || 0) !== resultGeneration) return normalizeData(loadData(sku) || {});
      saveData(sku, next);
      delete state.copywritingHydrateFailedAt[sku];
      addLog('success', '\u4ea7\u54c1\u6587\u6848\u9759\u9ed8\u7f13\u5b58\u5b8c\u6210', sku + ' | ' + file.fileName);
      return next;
    } catch (error) {
      if (Number(state.skuResultGeneration[sku] || 0) === resultGeneration) {
        state.copywritingHydrateFailedAt[sku] = Date.now();
        addLog('warn', '\u4ea7\u54c1\u6587\u6848\u9759\u9ed8\u8bfb\u53d6\u5931\u8d25', sku + ' | ' + formatErrorMessage(error));
      }
      return normalizeData(loadData(sku) || {});
    } finally {
      if (Number(state.skuResultGeneration[sku] || 0) === resultGeneration) state.copywritingHydratingSkus.delete(sku);
      const currentDrawer = getProjectDrawerForSku(sku);
      if (!opts.silent && currentDrawer && originalTab && getActiveTabText(currentDrawer) !== originalTab) await switchDrawerTab(currentDrawer, originalTab);
    }
  }

  async function hydrateIngredientPdfFromApi(sku, options) {
    const opts = options || {};
    let file = opts.apiFile || null;
    try {
      if (!file) file = await fetchApiIngredientPdfFile({ sku }, { force: Boolean(opts.force) });
    } catch (error) {
      addLog('warn', '成分表：定位失败，改用页面附件', sku + ' | ' + formatErrorMessage(error));
      return { handled: false, error };
    }
    if (!file || !file.found) return { handled: false, noFile: true };
    if (!file.url) throw new Error('成分表附件缺少下载地址');
    const cached = normalizeData(loadData(sku) || (state.data && state.data.sku === sku ? state.data : { sku }));
    const fileName = String(file.fileName || ('ingredient-' + sku + '.pdf')).trim();
    if (!opts.force && cached.ingredientNormalizerVersion === INGREDIENT_NORMALIZER_VERSION && cached.ingredientPdfFileName === fileName && cached.ingredientEnglish && cached.ingredientChinese) {
      addLog('info', '成分表：命中历史缓存', sku + ' | ' + fileName);
      return { handled: true, skipped: true, data: cached, file };
    }
    try {
      const arrayBuffer = await withCopywritingTimeout(downloadCopywritingDocument(file.url), 18000, 'API 成分表 PDF 读取');
      if (!isPdfBuffer(arrayBuffer)) throw new Error('后台返回内容不是有效 PDF');
      const fileHash = await hashCopywritingBuffer(arrayBuffer);
      if (!opts.force && cached.ingredientNormalizerVersion === INGREDIENT_NORMALIZER_VERSION && cached.ingredientPdfHash === fileHash && cached.ingredientEnglish && cached.ingredientChinese) {
        const next = cached.ingredientPdfFileName === fileName ? cached : normalizeData({ ...cached, ingredientPdfFileName: fileName, ingredientSource: 'ingredientPdfApi' });
        saveData(sku, next, { suppressDataQuality: true });
        return { handled: true, skipped: true, data: next, file };
      }
      let rawText = '';
      try {
        rawText = await withCopywritingTimeout(extractIngredientPdfText(arrayBuffer), 20000, 'API 成分表 PDF 解析');
      } catch (error) {
        addLog('warn', '成分表：PDF 文本层不可用', sku + ' | 将转为图片交给 AI | ' + formatErrorMessage(error));
      }
      const requestBody = { sku, fileName, rawText };
      if (!rawText || rawText.length < 20) {
        try {
          requestBody.pageImages = await withCopywritingTimeout(renderIngredientPdfImages(arrayBuffer), 25000, 'API 成分表 PDF 转图片');
        } catch (error) {
          addLog('warn', '成分表：PDF 转图片失败，改用 AI 直接读取 PDF', sku + ' | ' + formatErrorMessage(error));
        }
        requestBody.pdfBase64 = arrayBufferToBase64(arrayBuffer);
      }
      const response = await cloudRequest('/ingredients/normalize', { method: 'POST', timeoutMs: 90000, body: requestBody });
      if (!response || !response.ok || !response.english || !response.chinese) throw new Error(response && response.error ? response.error : 'AI 未返回有效成分');
      const next = normalizeData({
        ...cached,
        ingredientEnglish: String(response.english || '').slice(0, 8000),
        ingredientChinese: String(response.chinese || '').slice(0, 8000),
        ingredientItems: Array.isArray(response.items) ? response.items.slice(0, 100) : [],
        ingredientPdfFileName: fileName,
        ingredientPdfHash: fileHash,
        ingredientPdfModel: String(response.model || ''),
        ingredientPdfUpdatedAt: new Date().toLocaleString(),
        ingredientNormalizerVersion: String(response.normalizerVersion || INGREDIENT_NORMALIZER_VERSION),
        ingredientSource: 'ingredientPdfApi',
      });
      const drawer = opts.drawer || getProjectDrawerForSku(sku);
      if (opts.drawer && (drawer !== getProjectDrawerForSku(sku) || Number(state.skuResultGeneration[sku] || 0) !== Number(opts.resultGeneration || state.skuResultGeneration[sku] || 0))) return { handled: true, data: normalizeData(loadData(sku) || {}) };
      saveData(sku, next, { suppressDataQuality: true });
      const clearedCopywritingError = state.toyCopywritingErrorSku === sku && state.toyCopywritingErrorKind === 'ingredient-cache' && Boolean(state.toyCopywritingError);
      if (clearedCopywritingError) {
        clearToyCopywritingError(sku);
        if (state.selectedSku === sku) renderShell();
        showToast('成分表缓存已获取，现在可以重试智能补充食品文案');
      }
      delete state.ingredientHydrateFailedAt[sku];
      addLog('success', '成分表缓存完成', sku + ' | ' + next.ingredientEnglish);
      return { handled: true, data: next, file };
    } catch (error) {
      addLog('warn', '成分表：读取失败，改用页面附件', sku + ' | ' + formatErrorMessage(error));
      return { handled: false, error, file };
    }
  }

  async function hydrateIngredientPdfForSku(sku, options) {
    const opts = options || {};
    const resultGeneration = Number(state.skuResultGeneration[sku] || 0);
    if (!sku || state.ingredientHydratingSkus.has(sku)) return normalizeData(loadData(sku) || {});
    const failedAt = Number(state.ingredientHydrateFailedAt[sku] || 0);
    if (!opts.force && failedAt && Date.now() - failedAt < 10 * 60 * 1000) return normalizeData(loadData(sku) || {});
    const drawer = opts.drawer || getProjectDrawerForSku(sku);
    if (!drawer && opts.preferApi === false) return normalizeData(loadData(sku) || {});
    if (drawer && drawer !== getProjectDrawerForSku(sku) && opts.preferApi === false) return normalizeData(loadData(sku) || {});
    state.ingredientHydratingSkus.add(sku);
    const originalTab = drawer ? getActiveTabText(drawer) : '';
    try {
      let apiResult = null;
      if (opts.preferApi !== false) {
        apiResult = await hydrateIngredientPdfFromApi(sku, { ...opts, drawer, resultGeneration, apiFile: opts.apiFile || null });
        if (apiResult && apiResult.handled) return apiResult.data || normalizeData(loadData(sku) || {});
        if (apiResult && apiResult.noFile) return normalizeData(loadData(sku) || {});
      }
      if (!drawer || drawer !== getProjectDrawerForSku(sku)) return normalizeData(loadData(sku) || {});
      if (opts.silent && !opts.file && getActiveTabText(drawer) !== L.productTab && !(apiResult && apiResult.error)) return normalizeData(loadData(sku) || {});
      if (!opts.file) await switchDrawerTab(drawer, L.productTab);
      if (!opts.file) await waitFor(() => findIngredientPdfItem(drawer), 3500, 140);
      const item = opts.file ? null : findIngredientPdfItem(drawer);
      if (!opts.file && !item) return normalizeData(loadData(sku) || {});
      const file = opts.file || findIngredientPdfFile(item);
      if (!file) return normalizeData(loadData(sku) || {});
      const cached = normalizeData(loadData(sku) || (state.data && state.data.sku === sku ? state.data : { sku }));
      if (!opts.force && cached.ingredientNormalizerVersion === INGREDIENT_NORMALIZER_VERSION && cached.ingredientPdfFileName === file.fileName && cached.ingredientEnglish && cached.ingredientChinese) return cached;

      let source = await withCopywritingTimeout(resolveCopywritingDocumentSource(file.card, file.fileName), 12000, '成分表 PDF 下载监听');
      if (!source || (!source.url && !source.arrayBuffer)) throw new Error('未读取到成分表 PDF');
      let arrayBuffer = source.arrayBuffer || await withCopywritingTimeout(downloadCopywritingDocument(source.url), 18000, '成分表 PDF 读取');
      if (!isPdfBuffer(arrayBuffer) && source.kind !== 'captured') {
        source = { ...(await withCopywritingTimeout(captureCopywritingDownloadSource(file.card, file.fileName), 12000, '备用成分表 PDF 下载监听')), kind: 'captured' };
        arrayBuffer = source.arrayBuffer || (source.url ? await withCopywritingTimeout(downloadCopywritingDocument(source.url), 18000, '备用成分表 PDF 读取') : null);
      }
      if (!isPdfBuffer(arrayBuffer)) throw new Error('读取到的内容不是有效 PDF');
      const fileHash = await hashCopywritingBuffer(arrayBuffer);
      if (!opts.force && cached.ingredientNormalizerVersion === INGREDIENT_NORMALIZER_VERSION && cached.ingredientPdfHash === fileHash && cached.ingredientEnglish && cached.ingredientChinese) {
        if (cached.ingredientPdfFileName !== file.fileName && drawer === getProjectDrawerForSku(sku) && Number(state.skuResultGeneration[sku] || 0) === resultGeneration) saveData(sku, { ...cached, ingredientPdfFileName: file.fileName });
        return cached;
      }
      let rawText = '';
      try {
        rawText = await withCopywritingTimeout(extractIngredientPdfText(arrayBuffer), 20000, '成分表 PDF 解析');
      } catch (error) {
        addLog('warn', '成分表 PDF 文本层不可用', sku + ' | 将转为图片交给魔搭读取 | ' + formatErrorMessage(error));
      }
      const requestBody = { sku, fileName: file.fileName, rawText };
      if (!rawText || rawText.length < 20) {
        try {
          requestBody.pageImages = await withCopywritingTimeout(renderIngredientPdfImages(arrayBuffer), 25000, '成分表 PDF 转图片');
        } catch (error) {
          addLog('warn', '成分表 PDF 转图片失败', sku + ' | 将回退 Gemini 直接读取 PDF | ' + formatErrorMessage(error));
        }
        requestBody.pdfBase64 = arrayBufferToBase64(arrayBuffer);
      }
      const response = await cloudRequest('/ingredients/normalize', {
        method: 'POST',
        timeoutMs: 90000,
        body: requestBody,
      });
      if (!response || !response.ok || !response.english || !response.chinese) throw new Error(response && response.error ? response.error : 'AI 未返回有效成分');
      const next = normalizeData({
        ...cached,
        ingredientEnglish: String(response.english || '').slice(0, 8000),
        ingredientChinese: String(response.chinese || '').slice(0, 8000),
        ingredientItems: Array.isArray(response.items) ? response.items.slice(0, 100) : [],
        ingredientPdfFileName: file.fileName,
        ingredientPdfHash: fileHash,
        ingredientPdfModel: String(response.model || ''),
        ingredientPdfUpdatedAt: new Date().toLocaleString(),
        ingredientNormalizerVersion: String(response.normalizerVersion || INGREDIENT_NORMALIZER_VERSION),
        ingredientSource: 'ingredientPdf',
      });
      if (drawer !== getProjectDrawerForSku(sku) || Number(state.skuResultGeneration[sku] || 0) !== resultGeneration) return normalizeData(loadData(sku) || {});
      saveData(sku, next);
      const clearedCopywritingError = state.toyCopywritingErrorSku === sku && state.toyCopywritingErrorKind === 'ingredient-cache' && Boolean(state.toyCopywritingError);
      if (clearedCopywritingError) {
        clearToyCopywritingError(sku);
        if (state.selectedSku === sku) renderShell();
        showToast('\u6210\u5206\u8868\u7f13\u5b58\u5df2\u83b7\u53d6\uff0c\u73b0\u5728\u53ef\u4ee5\u91cd\u8bd5\u667a\u80fd\u8865\u5145\u98df\u54c1\u6587\u6848');
      }
      delete state.ingredientHydrateFailedAt[sku];
      addLog('success', '成分表静默缓存完成', sku + ' | ' + next.ingredientEnglish);
      return next;
    } catch (error) {
      if (Number(state.skuResultGeneration[sku] || 0) === resultGeneration) {
        state.ingredientHydrateFailedAt[sku] = Date.now();
        addLog('warn', '成分表静默读取失败', sku + ' | ' + formatErrorMessage(error));
      }
      return normalizeData(loadData(sku) || {});
    } finally {
      if (Number(state.skuResultGeneration[sku] || 0) === resultGeneration) state.ingredientHydratingSkus.delete(sku);
      const currentDrawer = getProjectDrawerForSku(sku);
      if (!opts.silent && currentDrawer && originalTab && getActiveTabText(currentDrawer) !== originalTab) await switchDrawerTab(currentDrawer, originalTab);
    }
  }

  function findIngredientPdfItem(drawer) {
    if (!drawer) return null;
    return Array.from(drawer.querySelectorAll('.ant-form-item'))
      .filter(isVisibleElement)
      .find((item) => {
        const label = item.querySelector('.ant-form-item-label');
        return /^(?:成份表|成分表)$/.test(compactText(label && (label.innerText || label.textContent)).replace(/[：:*]/g, ''));
      }) || null;
  }

  function findIngredientPdfFile(item) {
    const cards = Array.from(item.querySelectorAll('.filePreviewMainBox, .filePreviewCard, .removeOtherContent'))
      .filter(isVisibleElement)
      .map((card) => ({ card, fileName: extractPdfFileName(card) }))
      .filter((entry) => /\.pdf$/i.test(entry.fileName));
    const unique = cards.filter((entry, index) => cards.findIndex((candidate) => candidate.fileName === entry.fileName) === index);
    return unique[0] || null;
  }

  function isPdfBuffer(arrayBuffer) {
    if (!arrayBuffer || arrayBuffer.byteLength < 4) return false;
    const bytes = new Uint8Array(arrayBuffer, 0, 4);
    return bytes[0] === 0x25 && bytes[1] === 0x50 && bytes[2] === 0x44 && bytes[3] === 0x46;
  }

  function arrayBufferToBase64(arrayBuffer) {
    const bytes = new Uint8Array(arrayBuffer || new ArrayBuffer(0));
    let binary = '';
    for (let offset = 0; offset < bytes.length; offset += 0x8000) {
      binary += String.fromCharCode.apply(null, bytes.subarray(offset, Math.min(offset + 0x8000, bytes.length)));
    }
    return btoa(binary);
  }

  async function extractIngredientPdfText(arrayBuffer) {
    const Pdf = (typeof pdfjsLib !== 'undefined' && pdfjsLib) || (typeof unsafeWindow !== 'undefined' && unsafeWindow.pdfjsLib);
    if (!Pdf || typeof Pdf.getDocument !== 'function') throw new Error('PDF 解析组件未加载');
    if (Pdf.GlobalWorkerOptions && !Pdf.GlobalWorkerOptions.workerSrc) {
      Pdf.GlobalWorkerOptions.workerSrc = 'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.worker.min.js';
    }
    const task = Pdf.getDocument({ data: new Uint8Array(arrayBuffer.slice(0)) });
    const documentHandle = await task.promise;
    const pages = [];
    try {
      const pageCount = Math.min(Number(documentHandle.numPages) || 0, 12);
      for (let pageNumber = 1; pageNumber <= pageCount; pageNumber += 1) {
        const page = await documentHandle.getPage(pageNumber);
        const content = await page.getTextContent();
        let line = '';
        const lines = [];
        (content.items || []).forEach((item) => {
          const value = String(item && item.str || '').trim();
          if (value) line += (line ? ' ' : '') + value;
          if (item && item.hasEOL && line) {
            lines.push(line);
            line = '';
          }
        });
        if (line) lines.push(line);
        pages.push(lines.join('\n'));
      }
    } finally {
      if (documentHandle && typeof documentHandle.destroy === 'function') await documentHandle.destroy();
    }
    return pages.join('\n\n').replace(/[ \t]+/g, ' ').trim().slice(0, 30000);
  }

  async function renderIngredientPdfImages(arrayBuffer) {
    const Pdf = (typeof pdfjsLib !== 'undefined' && pdfjsLib) || (typeof unsafeWindow !== 'undefined' && unsafeWindow.pdfjsLib);
    if (!Pdf || typeof Pdf.getDocument !== 'function') throw new Error('PDF 解析组件未加载');
    if (Pdf.GlobalWorkerOptions && !Pdf.GlobalWorkerOptions.workerSrc) {
      Pdf.GlobalWorkerOptions.workerSrc = 'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.worker.min.js';
    }
    const task = Pdf.getDocument({ data: new Uint8Array(arrayBuffer.slice(0)) });
    const documentHandle = await task.promise;
    const images = [];
    let totalLength = 0;
    try {
      const pageCount = Math.min(Number(documentHandle.numPages) || 0, 6);
      for (let pageNumber = 1; pageNumber <= pageCount; pageNumber += 1) {
        const page = await documentHandle.getPage(pageNumber);
        const baseViewport = page.getViewport({ scale: 1 });
        const scale = Math.min(2, 1800 / Math.max(1, baseViewport.width), 2400 / Math.max(1, baseViewport.height));
        const viewport = page.getViewport({ scale: Math.max(0.1, scale) });
        const canvas = document.createElement('canvas');
        canvas.width = Math.max(1, Math.round(viewport.width));
        canvas.height = Math.max(1, Math.round(viewport.height));
        const context = canvas.getContext('2d', { alpha: false });
        if (!context) throw new Error('无法创建 PDF 图片画布');
        context.fillStyle = '#fff';
        context.fillRect(0, 0, canvas.width, canvas.height);
        await page.render({ canvasContext: context, viewport }).promise;
        const image = canvas.toDataURL('image/jpeg', 0.82);
        canvas.width = 1;
        canvas.height = 1;
        if (typeof page.cleanup === 'function') page.cleanup();
        if (image.length > 4500000 || (images.length && totalLength + image.length > 12000000)) break;
        images.push(image);
        totalLength += image.length;
      }
    } finally {
      if (documentHandle && typeof documentHandle.destroy === 'function') await documentHandle.destroy();
    }
    if (!images.length) throw new Error('PDF 页面未生成图片');
    return images;
  }

  function findProductCopywritingItem(drawer) {
    if (!drawer) return null;
    return Array.from(drawer.querySelectorAll('.ant-form-item'))
      .filter(isVisibleElement)
      .find((item) => {
        const label = item.querySelector('.ant-form-item-label');
        return compactText(label && (label.innerText || label.textContent)).replace(/[：:*]/g, '') === '产品文案';
      }) || null;
  }

  function findProductCopywritingFile(item, sku) {
    const cards = Array.from(item.querySelectorAll('.filePreviewMainBox, .filePreviewCard, .removeOtherContent'))
      .filter(isVisibleElement)
      .map((card) => ({ card, fileName: extractCopywritingFileName(card) }))
      .filter((entry) => /\.docx$/i.test(entry.fileName));
    const unique = cards.filter((entry, index) => cards.findIndex((candidate) => candidate.fileName === entry.fileName) === index);
    if (!unique.length) return null;
    const skuMatches = unique.filter((entry) => !sku || new RegExp(escapeRegExp(sku), 'i').test(entry.fileName));
    const pool = skuMatches.length ? skuMatches : (unique.length === 1 ? unique : []);
    if (!pool.length) return null;
    return pool.sort((a, b) => extractCopywritingFileTimestamp(b.fileName).localeCompare(extractCopywritingFileTimestamp(a.fileName)))[0];
  }

  function extractCopywritingFileName(card) {
    if (!card) return '';
    const titleSpans = Array.from(card.querySelectorAll('.title span, [class*="title"] span'))
      .map((el) => compactText(el.innerText || el.textContent))
      .filter((text) => /\.docx$/i.test(text));
    if (titleSpans.length) return titleSpans[titleSpans.length - 1];
    return ((compactText(card.innerText || card.textContent).match(/[^\n\\/:*?"<>|]+\.docx\b/i) || [])[0] || '').trim();
  }

  function extractPdfFileName(card) {
    if (!card) return '';
    const titleSpans = Array.from(card.querySelectorAll('.title span, [class*="title"] span'))
      .map((el) => compactText(el.innerText || el.textContent))
      .filter((text) => /\.pdf$/i.test(text));
    if (titleSpans.length) return titleSpans[titleSpans.length - 1];
    return ((compactText(card.innerText || card.textContent).match(/[^\n\\/:*?"<>|]+\.pdf\b/i) || [])[0] || '').trim();
  }

  function extractCopywritingFileTimestamp(fileName) {
    return ((String(fileName || '').match(/_(\d{14,17})(?=\.docx$)/i) || [])[1] || '');
  }

  async function resolveCopywritingDocumentSource(card, fileName) {
    const attachmentLabel = /\.pdf$/i.test(String(fileName || '')) ? '成分表' : '产品文案';
    const direct = findCopywritingUrlInCard(card);
    if (direct) {
      addLog('info', attachmentLabel + '：命中卡片地址', fileName + ' | ' + redactCopywritingUrl(direct));
      return { url: direct, arrayBuffer: null, kind: 'direct' };
    }
    addLog('info', attachmentLabel + '：未发现静态地址，直接监听下载动作', fileName);
    return { ...(await captureCopywritingDownloadSource(card, fileName)), kind: 'captured' };
  }

  function withCopywritingTimeout(promise, timeout, stage) {
    let timer = null;
    const limit = new Promise((resolve, reject) => {
      timer = setTimeout(() => reject(new Error((stage || '产品文案处理') + '超时')), Math.max(1000, Number(timeout) || 12000));
    });
    return Promise.race([Promise.resolve(promise), limit]).finally(() => {
      if (timer) clearTimeout(timer);
    });
  }

  function redactCopywritingUrl(value) {
    return String(value || '').replace(/\?.*$/, '?...').slice(0, 500);
  }

  function findCopywritingUrlInCard(card) {
    if (!card) return '';
    const attrs = ['href', 'src', 'data-url', 'data-src', 'data-file-url', 'data-download-url', 'download-url'];
    const nodes = [card].concat(Array.from(card.querySelectorAll('*')));
    for (const node of nodes) {
      for (const name of attrs) {
        const value = node.getAttribute && node.getAttribute(name);
        const url = normalizeCopywritingUrl(value);
        if (url && isUsableCopywritingUrl(url)) return url;
      }
    }
    const html = String(card.outerHTML || '').replace(/&amp;/g, '&');
    const urls = html.match(/https?:\/\/[^"'<>\s]+/g) || [];
    return urls.map(normalizeCopywritingUrl).find(isUsableCopywritingUrl) || '';
  }

  function normalizeCopywritingUrl(value) {
    const text = String(value || '').trim().replace(/&amp;/g, '&').replace(/\\\//g, '/');
    if (!text || /^(?:data:|javascript:)/i.test(text) || /filePic\/word\.png/i.test(text)) return '';
    if (/^(?:https?:|blob:)/i.test(text)) return text;
    if (/^\/\//.test(text)) return location.protocol + text;
    if (/^\//.test(text)) return location.origin + text;
    return '';
  }

  function isUsableCopywritingUrl(url) {
    const text = String(url || '');
    return /^blob:/i.test(text) || (/^https?:/i.test(text) && /(?:\.(?:docx|pdf)(?:\?|$)|download|attachment)/i.test(text));
  }

  function scoreCopywritingUrl(url, fileName) {
    const text = String(url || '').toLowerCase();
    if (!text || /filepic\/word\.png|data:image/i.test(text)) return -100;
    let score = /^(?:https?:|blob:)/i.test(text) ? 1 : 0;
    if (/^blob:/i.test(text)) score += 100;
    if (/\.docx(?:\?|$)/i.test(text)) score += 90;
    if (/\.pdf(?:\?|$)/i.test(text)) score += 90;
    if (/download|attachment/i.test(text)) score += 45;
    if (/file(?:\/|=|\?|_)/i.test(text)) score += 18;
    if (/oss|object|storage/i.test(text)) score += 10;
    const normalizedName = String(fileName || '').toLowerCase();
    if (normalizedName && (text.includes(normalizedName) || text.includes(encodeURIComponent(normalizedName).toLowerCase()))) score += 80;
    return score;
  }

  function findCopywritingUrlInVueState(card, fileName) {
    if (!card) return '';
    const roots = [];
    let element = card;
    for (let level = 0; element && level < 6; level += 1, element = element.parentElement) {
      try {
        Object.getOwnPropertyNames(element).filter((key) => /^__vue/i.test(key)).forEach((key) => roots.push(element[key]));
      } catch (error) { /* no-op */ }
    }
    const queue = [];
    roots.forEach((instance) => {
      if (!instance || typeof instance !== 'object') return;
      ['props', 'setupState', 'data', 'ctx', 'attrs'].forEach((key) => {
        try { if (instance[key]) queue.push({ value: instance[key], depth: 0, key }); } catch (error) { /* no-op */ }
      });
      try { if (instance.vnode && instance.vnode.props) queue.push({ value: instance.vnode.props, depth: 0, key: 'vnode.props' }); } catch (error) { /* no-op */ }
    });
    const seen = new Set();
    const candidates = [];
    let inspected = 0;
    const addCandidate = (value, key, sameFileObject) => {
      const raw = String(value || '').replace(/\\u002f/gi, '/').replace(/\\\//g, '/');
      const values = [raw].concat(raw.match(/https?:\/\/[^"'<>\s]+/gi) || []);
      values.forEach((candidate) => {
        const url = normalizeCopywritingUrl(candidate);
        if (!url) return;
        const baseScore = scoreCopywritingUrl(url, fileName);
        const score = baseScore + (/url|path|download|file/i.test(String(key || '')) ? 20 : 0) + (sameFileObject ? 40 : 0);
        if (baseScore > 20 || sameFileObject) candidates.push({ url, score });
      });
    };
    while (queue.length && inspected < 700) {
      const entry = queue.shift();
      const value = entry.value;
      inspected += 1;
      if (typeof value === 'string') {
        addCandidate(value, entry.key, false);
        continue;
      }
      if (!value || typeof value !== 'object' || entry.depth >= 5 || seen.has(value)) continue;
      if (value.nodeType || value === window || value === document) continue;
      seen.add(value);
      let keys = [];
      try { keys = Object.keys(value).slice(0, 80); } catch (error) { continue; }
      const normalizedName = String(fileName || '').toLowerCase();
      const sameFileObject = Boolean(normalizedName && keys.some((key) => {
        try { return typeof value[key] === 'string' && String(value[key]).toLowerCase().includes(normalizedName); } catch (error) { return false; }
      }));
      keys.forEach((key) => {
        if (/^(?:parent|root|appContext|subTree|component|el|proxy|provides)$/i.test(key)) return;
        let child;
        try { child = value[key]; } catch (error) { return; }
        if (typeof child === 'string') addCandidate(child, key, sameFileObject);
        else if (child && typeof child === 'object') queue.push({ value: child, depth: entry.depth + 1, key });
      });
    }
    return candidates.sort((a, b) => b.score - a.score)[0]?.url || '';
  }

  async function captureCopywritingDownloadSource(card, fileName) {
    const wantsPdf = /\.pdf$/i.test(String(fileName || ''));
    const attachmentLogLabel = wantsPdf ? '成分表' : '产品文案';
    if (!card) {
      addLog('error', attachmentLogLabel + '：下载监听失败', '附件卡片不存在');
      return { url: '', arrayBuffer: null };
    }
    // PLM only reveals this control on hover, but HTMLElement.click() works while it is hidden.
    const control = card.querySelector('.delBtn .anticon-vertical-align-bottom, .delBtn [aria-label="vertical-align-bottom"], .anticon-vertical-align-bottom, [aria-label="vertical-align-bottom"], [class*="download" i]');
    const clickable = control && (control.closest('.delBtn, button, a, [role="button"]') || control);
    if (!clickable) {
      addLog('error', attachmentLogLabel + '：下载监听失败', fileName + ' | 未找到下载图标，卡片类名：' + String(card.className || ''));
      return { url: '', arrayBuffer: null };
    }
    let captured = '';
    let capturedScore = -100;
    let capturedAt = 0;
    let capturedReady = false;
    let capturedBuffer = null;
    const root = typeof unsafeWindow !== 'undefined' ? unsafeWindow : window;
    const restores = [];
    const trace = [];
    const capture = (value, bonus, ready) => {
      const url = normalizeCopywritingUrl(value);
      const score = scoreCopywritingUrl(url, fileName) + Number(bonus || 0);
      if (!url || (score < 25 && !ready)) return false;
      if (url && score > capturedScore) {
        captured = url;
        capturedScore = score;
        capturedAt = Date.now();
        capturedReady = Boolean(ready);
        trace.push('地址:' + redactCopywritingUrl(url));
      }
      return Boolean(url);
    };
    const captureBuffer = (value) => {
      if (!value) return;
      const convert = Object.prototype.toString.call(value) === '[object ArrayBuffer]'
        ? Promise.resolve(value)
        : (typeof value.arrayBuffer === 'function' ? value.arrayBuffer() : Promise.resolve(null));
      convert.then((buffer) => {
        if (!buffer || !buffer.byteLength) return;
        const bytes = new Uint8Array(buffer, 0, Math.min(4, buffer.byteLength));
        const isPdf = bytes[0] === 0x25 && bytes[1] === 0x50 && bytes[2] === 0x44 && bytes[3] === 0x46;
        const isDocx = bytes[0] === 0x50 && bytes[1] === 0x4b;
        if ((wantsPdf && isPdf) || (!wantsPdf && isDocx)) {
          capturedBuffer = buffer;
          trace.push('内存' + (wantsPdf ? 'PDF:' : 'Word:') + buffer.byteLength + 'B');
        } else trace.push('非目标文件响应:' + buffer.byteLength + 'B');
      }).catch(() => {});
    };
    try {
      const anchorProto = root.HTMLAnchorElement && root.HTMLAnchorElement.prototype;
      if (anchorProto && anchorProto.click) {
        const originalAnchorClick = anchorProto.click;
        anchorProto.click = function () {
          const url = this.href || this.getAttribute('href') || '';
          if (capture(url, 70, true)) return;
          return originalAnchorClick.apply(this, arguments);
        };
        restores.push(() => { anchorProto.click = originalAnchorClick; });
      }
      if (typeof root.open === 'function') {
        const originalOpen = root.open;
        root.open = function (url) {
          if (capture(url, 70, true)) return null;
          return originalOpen.apply(this, arguments);
        };
        restores.push(() => { root.open = originalOpen; });
      }
      if (root.URL && typeof root.URL.createObjectURL === 'function') {
        const originalCreate = root.URL.createObjectURL;
        root.URL.createObjectURL = function () {
          const url = originalCreate.apply(this, arguments);
          captureBuffer(arguments[0]);
          capture(url, 100, true);
          return url;
        };
        restores.push(() => { root.URL.createObjectURL = originalCreate; });
      }
      if (root.URL && typeof root.URL.revokeObjectURL === 'function') {
        const originalRevoke = root.URL.revokeObjectURL;
        root.URL.revokeObjectURL = function (url) {
          if (captured && String(url || '') === captured) return;
          return originalRevoke.apply(this, arguments);
        };
        restores.push(() => { root.URL.revokeObjectURL = originalRevoke; });
      }
      if (typeof root.fetch === 'function') {
        const originalFetch = root.fetch;
        root.fetch = function (input) {
          const requestUrl = typeof input === 'string' ? input : (input && input.url) || '';
          capture(requestUrl, 15, false);
          const result = originalFetch.apply(this, arguments);
          result.then((response) => {
            const disposition = response.headers && response.headers.get ? (response.headers.get('content-disposition') || '') : '';
            const contentType = response.headers && response.headers.get ? (response.headers.get('content-type') || '') : '';
            capture(response.url || requestUrl, 25, false);
            if (/docx|pdf|officedocument|octet-stream|attachment/i.test(disposition + ' ' + contentType + ' ' + requestUrl)) {
              try { captureBuffer(response.clone()); } catch (error) { /* no-op */ }
            }
          }).catch(() => {});
          return result;
        };
        restores.push(() => { root.fetch = originalFetch; });
      }
      const xhrProto = root.XMLHttpRequest && root.XMLHttpRequest.prototype;
      if (xhrProto && xhrProto.open && xhrProto.send) {
        const originalXhrOpen = xhrProto.open;
        const originalXhrSend = xhrProto.send;
        xhrProto.open = function (method, url) {
          this.__pfhCopywritingUrl = String(url || '');
          capture(url, 15, false);
          return originalXhrOpen.apply(this, arguments);
        };
        xhrProto.send = function () {
          const xhr = this;
          const requestUrl = xhr.__pfhCopywritingUrl || '';
          xhr.addEventListener('load', () => {
            let disposition = '';
            let contentType = '';
            try {
              disposition = xhr.getResponseHeader('content-disposition') || '';
              contentType = xhr.getResponseHeader('content-type') || '';
            } catch (error) { /* no-op */ }
            capture(xhr.responseURL || requestUrl, 25, false);
            if (/docx|pdf|officedocument|octet-stream|attachment/i.test(disposition + ' ' + contentType + ' ' + requestUrl)) captureBuffer(xhr.response);
          }, { once: true });
          return originalXhrSend.apply(this, arguments);
        };
        restores.push(() => {
          xhrProto.open = originalXhrOpen;
          xhrProto.send = originalXhrSend;
        });
      }
    } catch (error) {
      addLog('warn', attachmentLogLabel + '：下载地址监听受限', formatErrorMessage(error));
    }
    const before = new Set((performance.getEntriesByType && performance.getEntriesByType('resource') || []).map((entry) => entry.name));
    const observer = new MutationObserver((mutations) => {
      mutations.forEach((mutation) => Array.from(mutation.addedNodes || []).forEach((node) => {
        if (!node || node.nodeType !== 1) return;
        capture(node.href || (node.getAttribute && (node.getAttribute('href') || node.getAttribute('src'))) || '', 45, true);
        if (!captured && node.querySelectorAll) {
          Array.from(node.querySelectorAll('a[href], [src]')).some((el) => capture(el.href || el.src || '', 45, true));
        }
      }));
    });
    observer.observe(document.documentElement, { childList: true, subtree: true });
    try {
      clickElement(clickable);
      trace.push('已点击:' + String(clickable.className || clickable.getAttribute('aria-label') || clickable.tagName));
      const observed = await waitUntil(() => {
        if (capturedBuffer) return 'buffer';
        if (captured && capturedReady) return 'url';
        const resources = (performance.getEntriesByType && performance.getEntriesByType('resource') || [])
          .map((entry) => entry.name)
          .filter((name) => !before.has(name));
        resources.forEach((url) => capture(url, 20, false));
        if (captured && capturedAt && Date.now() - capturedAt > 6500) return 'url';
        return '';
      }, 9000, 100);
      if (!observed && captured) capturedReady = true;
    } finally {
      observer.disconnect();
      restores.reverse().forEach((restore) => {
        try { restore(); } catch (error) { /* no-op */ }
      });
    }
    if (capturedBuffer) addLog('info', attachmentLogLabel + '：下载监听成功', fileName + ' | 内存 ' + (wantsPdf ? 'PDF ' : 'Word ') + capturedBuffer.byteLength + 'B');
    else if (captured) addLog('info', attachmentLogLabel + '：下载监听捕获地址', fileName + ' | ' + redactCopywritingUrl(captured));
    else addLog('error', attachmentLogLabel + '：下载监听未取得文件', fileName + ' | ' + (trace.join('；') || '点击后未发现下载地址、Blob 或目标文件响应'));
    return { url: captured, arrayBuffer: capturedBuffer };
  }

  function downloadCopywritingDocument(url) {
    if (/^blob:/i.test(url)) {
      return fetch(url).then((response) => {
        if (!response.ok) throw new Error('Word 下载失败：' + response.status);
        return response.arrayBuffer();
      }).finally(() => {
        try { URL.revokeObjectURL(url); } catch (error) { /* no-op */ }
      });
    }
    return new Promise((resolve, reject) => {
      if (typeof GM_xmlhttpRequest !== 'function') {
        fetch(url).then((response) => {
          if (!response.ok) throw new Error('Word 下载失败：' + response.status);
          return response.arrayBuffer();
        }).then(resolve, reject);
        return;
      }
      GM_xmlhttpRequest({
        method: 'GET',
        url,
        responseType: 'arraybuffer',
        timeout: 20000,
        onload: (response) => {
          if (response.status < 200 || response.status >= 300) {
            reject(new Error('Word 下载失败：HTTP ' + response.status));
            return;
          }
          if (response.response instanceof ArrayBuffer) resolve(response.response);
          else if (response.response && response.response.arrayBuffer) response.response.arrayBuffer().then(resolve, reject);
          else reject(new Error('Word 下载内容为空'));
        },
        onerror: () => reject(new Error('Word 下载请求失败')),
        ontimeout: () => reject(new Error('Word 下载超时')),
      });
    });
  }

  function isCopywritingDocxBuffer(arrayBuffer) {
    if (!arrayBuffer || arrayBuffer.byteLength < 4) return false;
    const bytes = new Uint8Array(arrayBuffer, 0, 4);
    return bytes[0] === 0x50 && bytes[1] === 0x4b;
  }

  async function parseCopywritingDocxRows(arrayBuffer) {
    let xmlText = '';
    try {
      xmlText = await readDocxDocumentXmlNative(arrayBuffer);
      addLog('info', '产品文案：Word 原生解压成功', xmlText.length + ' 字符');
    } catch (nativeError) {
      addLog('warn', '产品文案：原生解压不可用，尝试 JSZip', formatErrorMessage(nativeError));
      const Zip = (typeof JSZip !== 'undefined' && JSZip) || (typeof unsafeWindow !== 'undefined' && unsafeWindow.JSZip);
      if (!Zip) throw new Error('Word 解析组件未加载，且原生解压失败：' + formatErrorMessage(nativeError));
      const zip = await Zip.loadAsync(arrayBuffer, { checkCRC32: false, createFolders: false });
      const documentFile = zip.file('word/document.xml');
      if (!documentFile) throw new Error('Word 文件结构不完整');
      xmlText = await documentFile.async('string');
      addLog('info', '产品文案：JSZip 解压成功', xmlText.length + ' 字符');
    }
    const xml = new DOMParser().parseFromString(xmlText, 'application/xml');
    if (xml.querySelector('parsererror')) throw new Error('Word XML 解析失败');
    const rows = [];
    Array.from(xml.getElementsByTagNameNS('*', 'tr')).forEach((row) => {
      const cells = Array.from(row.children || []).filter((node) => node.localName === 'tc').map(copywritingCellLines);
      if (cells.length >= 2) rows.push(cells);
    });
    const fullText = rows
      .filter((cells) => !/^内容说明$/.test(cleanCopywritingLine((cells[0] || []).join('')).replace(/\s+/g, '')))
      .map((cells) => [
        (cells[1] || []).map(cleanCopywritingLine).filter(Boolean).join('\n'),
        (cells[2] || []).map(cleanCopywritingLine).filter(Boolean).join('\n'),
      ].filter(Boolean).join('\n'))
      .filter(Boolean)
      .join('\n');
    return { rows, fullText: fullText.slice(0, 50000) };
  }

  async function readDocxDocumentXmlNative(arrayBuffer) {
    if (typeof DecompressionStream !== 'function') throw new Error('浏览器不支持原生 ZIP 解压');
    const bytes = new Uint8Array(arrayBuffer);
    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    const readU16 = (offset) => view.getUint16(offset, true);
    const readU32 = (offset) => view.getUint32(offset, true);
    let eocd = -1;
    const start = Math.max(0, bytes.length - 65557);
    for (let offset = bytes.length - 22; offset >= start; offset -= 1) {
      if (readU32(offset) === 0x06054b50) {
        eocd = offset;
        break;
      }
    }
    if (eocd < 0) throw new Error('未找到 Word ZIP 目录');
    const entryCount = readU16(eocd + 10);
    let offset = readU32(eocd + 16);
    const decoder = new TextDecoder('utf-8');
    for (let index = 0; index < entryCount; index += 1) {
      if (offset + 46 > bytes.length || readU32(offset) !== 0x02014b50) throw new Error('Word ZIP 目录损坏');
      const compression = readU16(offset + 10);
      const compressedSize = readU32(offset + 20);
      const nameLength = readU16(offset + 28);
      const extraLength = readU16(offset + 30);
      const commentLength = readU16(offset + 32);
      const localOffset = readU32(offset + 42);
      const name = decoder.decode(bytes.subarray(offset + 46, offset + 46 + nameLength));
      offset += 46 + nameLength + extraLength + commentLength;
      if (name !== 'word/document.xml') continue;
      if (localOffset + 30 > bytes.length || readU32(localOffset) !== 0x04034b50) throw new Error('Word 正文位置无效');
      const localNameLength = readU16(localOffset + 26);
      const localExtraLength = readU16(localOffset + 28);
      const dataStart = localOffset + 30 + localNameLength + localExtraLength;
      const compressed = bytes.slice(dataStart, dataStart + compressedSize);
      if (compression === 0) return decoder.decode(compressed);
      if (compression !== 8) throw new Error('Word 使用了不支持的压缩方式：' + compression);
      const stream = new Blob([compressed]).stream().pipeThrough(new DecompressionStream('deflate-raw'));
      const inflated = await new Response(stream).arrayBuffer();
      return decoder.decode(new Uint8Array(inflated));
    }
    throw new Error('Word 中没有正文 XML');
  }

  function copywritingCellLines(cell) {
    const numbering = {};
    let previousNumberingKey = '';
    let previousWasNumbered = false;
    return Array.from(cell.getElementsByTagNameNS('*', 'p'))
      .map((paragraph) => {
        const text = Array.from(paragraph.querySelectorAll('*'))
          .filter((node) => ['t', 'noBreakHyphen', 'softHyphen', 'tab', 'br', 'cr'].includes(node.localName))
          .map((node) => {
            if (node.localName === 'noBreakHyphen' || node.localName === 'softHyphen') return '-';
            if (node.localName === 'tab') return '\t';
            if (node.localName === 'br' || node.localName === 'cr') return '\n';
            return node.textContent || '';
          })
          .join('');
        const numPr = Array.from(paragraph.children || []).find((node) => node.localName === 'pPr')
          && Array.from(Array.from(paragraph.children || []).find((node) => node.localName === 'pPr').children || [])
            .find((node) => node.localName === 'numPr');
        const numIdNode = numPr && Array.from(numPr.children || []).find((node) => node.localName === 'numId');
        const ilvlNode = numPr && Array.from(numPr.children || []).find((node) => node.localName === 'ilvl');
        const numId = numIdNode && numIdNode.getAttribute('w:val') || numIdNode && numIdNode.getAttributeNS('http://schemas.openxmlformats.org/wordprocessingml/2006/main', 'val') || '';
        const ilvl = ilvlNode && ilvlNode.getAttribute('w:val') || ilvlNode && ilvlNode.getAttributeNS('http://schemas.openxmlformats.org/wordprocessingml/2006/main', 'val') || '0';
        const numberingKey = numId && numId !== '0' ? numId + ':' + ilvl : '';
        let marker = '';
        if (numberingKey) {
          if (numberingKey !== previousNumberingKey || !previousWasNumbered) numbering[numberingKey] = 0;
          numbering[numberingKey] = (numbering[numberingKey] || 0) + 1;
          marker = /^\s*\d+[.)、]\s*/.test(text) ? '' : numbering[numberingKey] + '. ';
        }
        previousNumberingKey = numberingKey;
        previousWasNumbered = Boolean(numberingKey);
        return marker + text;
      })
      .map(cleanCopywritingLine)
      .filter(Boolean);
  }

  function normalizeCopywritingCompatibilityCharacters(value) {
    return String(value || '').replace(/[\u2010\u2011]/g, '-');
  }

  function cleanCopywritingLine(value) {
    return normalizeCopywritingCompatibilityCharacters(value).replace(/[\u00a0\u2000-\u200b\u202f\u205f\u3000]/g, ' ').replace(/[ \t]+/g, ' ').trim();
  }

  function normalizeIngredientLocantHyphens(value) {
    return String(value || '').replace(/\b(\d+(?:\s*[,、]\s*\d+)+)\s*(?=[A-Za-z])/g, (_match, locants) => locants.replace(/\s*[,、]\s*/g, ',') + '-');
  }

  function splitCopywritingIngredientItems(value) {
    const text = String(value || '');
    const items = [];
    let current = '';
    for (let index = 0; index < text.length; index += 1) {
      const character = text[index];
      let separator = /[\n、，;；]/.test(character);
      if (character === ',') {
        let before = index - 1;
        let after = index + 1;
        while (before >= 0 && /\s/.test(text[before])) before -= 1;
        while (after < text.length && /\s/.test(text[after])) after += 1;
        const isNumericLocant = before >= 0 && after < text.length
          && /\d/.test(text[before]) && /\d/.test(text[after]);
        separator = !isNumericLocant;
      }
      if (separator) {
        items.push(current);
        current = '';
      } else {
        current += character;
      }
    }
    items.push(current);
    return items;
  }

  function cleanCopywritingIngredientValue(lines, language) {
    let text = (lines || []).map(cleanCopywritingLine).filter(Boolean).join('\n').trim();
    if (!text) return '';
    if (language === 'chinese') {
      text = text.replace(/(?:非活性成分|活性成分|(?:中文)?成[分份]表|(?:中文)?成[分份])\s*[:：]?/gi, '、');
    } else {
      text = text.replace(/\b(?:(?:INACTIVE|ACTIVE)\s+)?INGREDIENTS?\s*[:：]?/gi, '、');
    }
    return splitCopywritingIngredientItems(text)
      .map((item) => normalizeIngredientLocantHyphens(cleanCopywritingLine(item).replace(/^[\s:：.。]+|[\s:：.。]+$/g, '')))
      .filter(Boolean)
      .join('、')
      .slice(0, 8000);
  }

  function hasSplitCopywritingIngredients(englishLines, chineseLines) {
    const english = (englishLines || []).map(cleanCopywritingLine).join('\n');
    const chinese = (chineseLines || []).map(cleanCopywritingLine).join('\n');
    return (/\bACTIVE\s+INGREDIENTS?\s*[:：]?/i.test(english) && /\bINACTIVE\s+INGREDIENTS?\s*[:：]?/i.test(english))
      || (/(?:^|\n)\s*活性成分\s*[:：]?/.test(chinese) && /(?:^|\n)\s*非活性成分\s*[:：]?/.test(chinese));
  }

  function buildMainstreamCopywriting(parsedDocument, data) {
    const rows = Array.isArray(parsedDocument) ? parsedDocument : (parsedDocument && parsedDocument.rows || []);
    const wordFullText = Array.isArray(parsedDocument) ? '' : String(parsedDocument && parsedDocument.fullText || '').trim();
    const rowMap = {};
    (rows || []).forEach((cells) => {
      const label = cleanCopywritingLine((cells[0] || []).join('')).replace(/\s+/g, '');
      if (label && !rowMap[label]) rowMap[label] = { english: cells[1] || [], chinese: cells[2] || [] };
    });
    const find = (pattern, language) => {
      const key = Object.keys(rowMap).find((label) => pattern.test(label));
      const entry = key ? rowMap[key] : null;
      return entry ? (entry[language === 'chinese' ? 'chinese' : 'english'] || []).slice() : [];
    };
    const sections = [];
    const missingSections = [];
    const add = (key, label, text, required) => {
      const value = String(text || '').trim();
      if (value) sections.push({ key, label, text: value.slice(0, 12000) });
      else if (required !== false) missingSections.push(label);
    };
    const productSection = preserveCopywritingHeading(find(/^产品名称$/), /^PRODUCT\s+NAME\s*[:：]?$/i, 'PRODUCT NAME:');
    add('productName', '产品名称', joinCopywritingSection(productSection.heading, productSection.lines));
    const functionsHeading = find(/^24国语言功效标题/).join('').trim();
    add('functionsHeading', '24国语言功效标题', functionsHeading, false);
    const functionLines = find(/^24国语言功效内容/).map((line) => line.replace(/;\s*$/, '').trim()).filter(Boolean);
    add('functions', '24国语言功效内容', functionLines.join(';  '), false);
    const ingredientLines = find(/^(?:成分表|成分活性非活性成分)/);
    const ingredientChineseLines = find(/^(?:成分表|成分活性非活性成分)/, 'chinese');
    const ingredientEnglish = cleanCopywritingIngredientValue(ingredientLines, 'english');
    const ingredientChinese = cleanCopywritingIngredientValue(ingredientChineseLines, 'chinese');
    const ingredientSplit = hasSplitCopywritingIngredients(ingredientLines, ingredientChineseLines);
    const activeIngredients = extractLabeledCopywritingSection(ingredientLines, /\bACTIVE\s+INGREDIENTS?\s*[:：]?/i, /\bINACTIVE\s+INGREDIENTS?\s*[:：]?/i, 'ACTIVE INGREDIENTS:');
    const inactiveIngredients = extractLabeledCopywritingSection(ingredientLines, /\bINACTIVE\s+INGREDIENTS?\s*[:：]?/i, null, 'INACTIVE INGREDIENTS:');
    if (activeIngredients.lines.length || inactiveIngredients.lines.length) {
      add('activeIngredients', 'ACTIVE INGREDIENTS', joinCopywritingSection(activeIngredients.heading, activeIngredients.lines));
      add('inactiveIngredients', 'INACTIVE INGREDIENTS', joinCopywritingSection(inactiveIngredients.heading, inactiveIngredients.lines));
    } else {
      const ingredientSection = preserveCopywritingHeading(ingredientLines, /^INGREDIENTS?\s*[:：]?$/i, 'INGREDIENTS:');
      add('ingredients', '成分表', joinCopywritingSection(ingredientSection.heading, ingredientSection.lines));
    }
    const materialEnglish = find(/^(?:材质|材料)$/);
    const materialChinese = find(/^(?:材质|材料)$/, 'chinese');
    // The file view is used for the English artwork copy.  Do not append the
    // Chinese material cell here; it remains available in the raw full-text view.
    add('material', '材质', materialEnglish.join('\n'), false);
    const directionSection = preserveCopywritingHeading(find(/^(?:[AB][.．、]?\s*)?(?:建议使用方法|使用方法|食用方法)/i), /^DIRECTIONS(?:\s+OF\s+SAFE\s+USE)?\s*[:：]?$/i, 'DIRECTIONS:');
    add('directions', '建议使用方法', joinCopywritingSection(directionSection.heading, directionSection.lines));
    add('directionsChinese', '中文使用方法', find(/^(?:[AB][.．、]?\s*)?(?:建议使用方法|使用方法|食用方法)/i, 'chinese').join('\n'));
    const warningSection = preserveCopywritingHeading(find(/^警告语$/), /^WARNINGS?\s*[:：]?$/i, 'WARNINGS:');
    add('warning', '警告语', joinCopywritingSection(warningSection.heading, warningSection.lines));
    const emailLines = find(/^美国不良事故联系人邮箱$/);
    const emailSection = preserveCopywritingHeading(emailLines, /^E-?MAIL\s*[:：]?$/i, 'e-mail:');
    add('email', '联系邮箱', joinCopywritingSection(emailSection.heading, emailSection.lines), false);
    // Some Word templates place the actual package contents in a separate
    // “包含 / INCLUDING” row instead of the product net-content field.  Keep
    // that complete English statement in the net-content card and do not
    // reduce it to the first numeric quantity (the foaming net is an accessory).
    const includingLines = find(/^(?:包含|包括|内含|INCLUDING)[:：]?$/i);
    const includingSection = preserveCopywritingHeading(includingLines, /^INCLUDING\s*[:：]?$/i, 'INCLUDING:');
    const includingText = joinCopywritingSection(includingSection.heading, includingSection.lines);
    const net = formatCopywritingNetContent(data && data.netContent);
    if (!includingText && net.warning && net.text) missingSections.push(net.warning);
    add('netContent', '净含量', includingText || net.text);
    const originLines = find(/^原产国$/);
    add('origin', '原产国', originLines.join('\n'));
    const shelfLines = find(/^保质期$/);
    add('shelfLife', '保质期', shelfLines.join('\n'));
    formatBrandComplianceSections(data).forEach((section) => add(section.key, section.label, section.text));
    return {
      sections,
      fullText: (wordFullText || sections.map((section) => section.text).join('\n')).slice(0, 50000),
      missingSections,
      ingredientEnglish,
      ingredientChinese,
      ingredientSplit,
    };
  }

  function findBrandCompliance(data) {
    const brand = String(data && data.brand || '').replace(/[\u00a0\u2000-\u200b\u202f\u205f\u3000]/g, ' ').replace(/\s+/g, ' ').trim().toUpperCase();
    if (!brand) return null;
    return BRAND_COMPLIANCE_DATA.find((item) => {
      const names = [item && item.brand].concat(Array.isArray(item && item.aliases) ? item.aliases : []);
      return names.some((name) => String(name || '').replace(/[\u00a0\u2000-\u200b\u202f\u205f\u3000]/g, ' ').replace(/\s+/g, ' ').trim().toUpperCase() === brand);
    }) || null;
  }

  function cleanComplianceValue(value) {
    return String(value || '').replace(/\u00a0/g, ' ').replace(/\r/g, '').split('\n').map((line) => line.trim()).filter(Boolean).join('\n').trim();
  }

  function formatBrandComplianceSections(data) {
    const info = findBrandCompliance(data);
    if (!info) return [];
    const distributedBy = cleanComplianceValue(info.distributed_by);
    const address = cleanComplianceValue(info.address);
    if (!distributedBy && !address) return [];
    const sections = [];
    if (distributedBy) sections.push({ key: 'distributedBy', label: 'DISTRIBUTED BY', text: 'DISTRIBUTED BY: ' + distributedBy });
    if (address) sections.push({ key: 'address', label: 'ADDRESS', text: 'ADDRESS: ' + address });
    [['EU REP', 'euRep', info.eu_rep], ['UK REP', 'ukRep', info.uk_rep], ['US REP', 'usRep', info.us_rep]].forEach(([label, key, rep]) => {
      if (!rep || !cleanComplianceValue(rep.company)) return;
      const lines = [cleanComplianceValue(rep.company), cleanComplianceValue(rep.address), cleanComplianceValue(rep.contact), cleanComplianceValue(rep.phone), cleanComplianceValue(rep.postal_code)].filter(Boolean);
      if (lines.length) sections.push({ key, label, text: label + '\n' + lines.join('\n') });
    });
    return sections;
  }

  function getCopywritingDisplayRecord(data) {
    const record = normalizeCopywritingRecord(data && data.copywriting);
    if (!record) return null;
    const existingKeys = new Set(record.sections.map((section) => section.key));
    const complianceSections = formatBrandComplianceSections(data)
      .filter((section) => section && section.key && !existingKeys.has(section.key));
    if (!complianceSections.length) return record;
    const complianceText = complianceSections.map((section) => section.text).filter(Boolean).join('\n');
    return normalizeCopywritingRecord({
      ...record,
      sections: record.sections.concat(complianceSections),
      fullText: [record.fullText, complianceText].filter(Boolean).join('\n'),
    });
  }

  function extractLabeledCopywritingSection(lines, headingPattern, nextHeadingPattern, fallbackHeading) {
    const text = (lines || []).map(cleanCopywritingLine).filter(Boolean).join('\n');
    const match = text.match(headingPattern);
    if (!match) return { heading: fallbackHeading, lines: [] };
    const start = Number(match.index) || 0;
    const heading = String(match[0] || '').trim() || fallbackHeading;
    let value = text.slice(start + match[0].length).replace(/^\s*[:：]\s*/, '');
    if (nextHeadingPattern) {
      const next = value.search(nextHeadingPattern);
      if (next >= 0) value = value.slice(0, next);
    }
    return { heading, lines: value.split(/\r?\n/).map(cleanCopywritingLine).filter(Boolean) };
  }

  function preserveCopywritingHeading(lines, headingPattern, fallbackHeading) {
    const result = (lines || []).map(cleanCopywritingLine).filter(Boolean);
    if (!result.length) return { heading: fallbackHeading, lines: [] };
    const first = result[0];
    const colonIndex = first.search(/[:：]/);
    const prefix = colonIndex >= 0 ? first.slice(0, colonIndex + 1).trim() : first.trim();
    const hasExpectedHeading = headingPattern.test(first) || (colonIndex >= 0 && headingPattern.test(prefix));
    const hasSourceHeading = colonIndex >= 0 && /^[A-Z][A-Z0-9 /().&-]*[:：]$/.test(prefix);
    if (!hasExpectedHeading && !hasSourceHeading) {
      return { heading: fallbackHeading, lines: result };
    }
    const body = colonIndex >= 0 ? first.slice(colonIndex + 1).trim() : '';
    result.shift();
    if (body) result.unshift(body);
    return { heading: prefix || fallbackHeading, lines: result };
  }

  function joinCopywritingSection(heading, lines) {
    const body = (lines || []).map(cleanCopywritingLine).filter(Boolean);
    return body.length ? [heading].concat(body).join('\n') : '';
  }

  function formatCopywritingNetContent(value) {
    const text = cleanCopywritingLine(value);
    if (!text || text === '--' || text === L.unknown) return { text: '', warning: '净含量' };
    if (/^\d+(?:\.\d+)?(?:CAPSULES|GUMMIES|TABLETS|PAIR|PAIRS|PCS?|PC)$/i.test(text)) return { text: text.toUpperCase(), warning: '' };
    const match = text.match(/(\d+(?:\.\d+)?)\s*(g|ml)\b/i);
    if (!match) return { text, warning: '净含量单位无法换算' };
    const amount = Number(match[1]);
    const unit = match[2].toUpperCase();
    if (!Number.isFinite(amount)) return { text, warning: '净含量单位无法换算' };
    const imperial = unit === 'G' ? amount / 28.349523125 : amount / 29.5735295625;
    return { text: trimNumber(amount) + unit + '/ ' + imperial.toFixed(2) + (unit === 'G' ? ' OZ' : ' FL OZ'), warning: '' };
  }

  async function hashCopywritingBuffer(arrayBuffer) {
    try {
      const digest = await crypto.subtle.digest('SHA-256', arrayBuffer.slice(0));
      return Array.from(new Uint8Array(digest)).map((byte) => byte.toString(16).padStart(2, '0')).join('');
    } catch (error) {
      const bytes = new Uint8Array(arrayBuffer);
      let hash = 2166136261;
      for (let index = 0; index < bytes.length; index += 1) hash = Math.imul(hash ^ bytes[index], 16777619);
      return (hash >>> 0).toString(16);
    }
  }

  function normalizeCopywritingComparisonText(value) {
    return String(value || '')
      .replace(/[\u00a0\u2000-\u200b\u202f\u205f\u3000]/g, ' ')
      .replace(/[ \t]+/g, ' ')
      .replace(/(\d+(?:\.\d+)?)\s*(fl\s*oz|mcg|mg|kg|g|ml|l|oz|lbs?|cm|mm|in(?:ches?)?|ft|pcs?|capsules?|tablets?|gummies?|pairs?)(?=\b)/gi, (_, amount, unit) => amount + unit.replace(/\s+/g, '').toLowerCase())
      .trim();
  }

  function areCopywritingSectionsEquivalent(previousSections, nextSections) {
    if (!Array.isArray(previousSections) || !Array.isArray(nextSections) || previousSections.length !== nextSections.length) return false;
    const nextMap = new Map(nextSections.map((section) => [section.key, section]));
    return previousSections.every((section) => {
      const next = nextMap.get(section.key);
      return Boolean(next) && normalizeCopywritingComparisonText(section.text) === normalizeCopywritingComparisonText(next.text);
    });
  }

  function buildCopywritingRecord(fileName, fileTimestamp, fileHash, built, cached) {
    const now = new Date().toLocaleString();
    const old = normalizeCopywritingRecord(cached);
    const oldMap = new Map((old && old.sections || []).map((section) => [section.key, section]));
    const nextMap = new Map((built.sections || []).map((section) => [section.key, section]));
    const contentChangedSectionKeys = built.sections
      .filter((section) => !oldMap.has(section.key) || normalizeCopywritingComparisonText(oldMap.get(section.key).text) !== normalizeCopywritingComparisonText(section.text))
      .map((section) => section.key);
    const contentRemovedSections = (old && old.sections || [])
      .filter((section) => !nextMap.has(section.key))
      .map((section) => section.label || section.key);
    const changedFile = Boolean(old && old.fullText && (
      old.fileName !== fileName
      || normalizeCopywritingComparisonText(old.fullText) !== normalizeCopywritingComparisonText(built.fullText)
      || contentChangedSectionKeys.length
      || contentRemovedSections.length
    ));
    const changedSectionKeys = changedFile
      ? contentChangedSectionKeys
      : (old && old.updatePending ? old.changedSectionKeys.slice() : []);
    const removedSections = changedFile
      ? contentRemovedSections
      : (old && old.updatePending ? old.removedSections.slice() : []);
    return normalizeCopywritingRecord({
      fileName,
      parserVersion: COPYWRITING_PARSER_VERSION,
      fileTimestamp,
      fileHash,
      fetchedAt: now,
      lastCheckedAtMs: Date.now(),
      sections: built.sections,
      fullText: built.fullText,
      ingredientEnglish: built.ingredientEnglish,
      ingredientChinese: built.ingredientChinese,
      cleanedIngredientEnglish: built.ingredientEnglish,
      cleanedIngredientChinese: built.ingredientChinese,
      ingredientSplit: Boolean(built.ingredientSplit),
      missingSections: built.missingSections,
      updatePending: changedFile || Boolean(old && old.updatePending),
      changedSectionKeys,
      removedSections,
      previousSections: changedFile ? old.sections : (old && old.updatePending ? old.previousSections : []),
      copiedSectionKeys: changedFile ? [] : (old && old.copiedSectionKeys || []),
      copiedFullText: changedFile ? false : Boolean(old && old.copiedFullText),
    });
  }

  function normalizeCopywritingRecord(record) {
    if (!record || typeof record !== 'object') return null;
    const normalizeSections = (items) => (Array.isArray(items) ? items : []).slice(0, 80).map((section) => ({
      key: String(section && section.key || '').slice(0, 60),
      label: normalizeCopywritingCompatibilityCharacters(String(section && section.label || '')).slice(0, 100),
      text: normalizeCopywritingCompatibilityCharacters(String(section && section.text || '')).slice(0, 12000),
    })).filter((section) => section.key && section.text);
    const sections = normalizeSections(record.sections).map((section) => ({
      ...section,
      text: /ingredient/i.test(section.key) ? normalizeIngredientLocantHyphens(section.text) : section.text,
    }));
    const previousSections = normalizeSections(record.previousSections);
    const updatePending = Boolean(record.updatePending) && (!previousSections.length || !areCopywritingSectionsEquivalent(previousSections, sections));
    return {
      fileName: String(record.fileName || '').slice(0, 300),
      parserVersion: String(record.parserVersion || '').slice(0, 20),
      fileTimestamp: String(record.fileTimestamp || '').slice(0, 20),
      fileHash: String(record.fileHash || '').slice(0, 128),
      fetchedAt: String(record.fetchedAt || '').slice(0, 80),
      lastCheckedAtMs: Math.max(0, Number(record.lastCheckedAtMs) || 0),
      sections,
      fullText: normalizeIngredientLocantHyphens(normalizeCopywritingCompatibilityCharacters(String(record.fullText || '')).slice(0, 50000)),
      ingredientEnglish: normalizeIngredientLocantHyphens(normalizeCopywritingCompatibilityCharacters(String(record.ingredientEnglish || '').trim())).slice(0, 8000),
      ingredientChinese: String(record.ingredientChinese || '').trim().slice(0, 8000),
      cleanedIngredientEnglish: normalizeIngredientLocantHyphens(normalizeCopywritingCompatibilityCharacters(String(record.cleanedIngredientEnglish || record.ingredientEnglish || '').trim())).slice(0, 8000),
      cleanedIngredientChinese: String(record.cleanedIngredientChinese || record.ingredientChinese || '').trim().slice(0, 8000),
      ingredientSplit: Boolean(record.ingredientSplit),
      missingSections: (Array.isArray(record.missingSections) ? record.missingSections : []).map((item) => String(item || '').slice(0, 100)).filter(Boolean).slice(0, 16),
      updatePending,
      changedSectionKeys: updatePending ? (Array.isArray(record.changedSectionKeys) ? record.changedSectionKeys : []).map((item) => String(item || '').slice(0, 60)).filter(Boolean).slice(0, 16) : [],
      removedSections: updatePending ? (Array.isArray(record.removedSections) ? record.removedSections : []).map((item) => String(item || '').slice(0, 100)).filter(Boolean).slice(0, 16) : [],
      previousSections: updatePending ? previousSections : [],
      copiedSectionKeys: (Array.isArray(record.copiedSectionKeys) ? record.copiedSectionKeys : []).map((item) => String(item || '').slice(0, 60)).filter(Boolean).slice(0, 80),
      copiedFullText: Boolean(record.copiedFullText),
    };
  }

  function isCopywritingCheckFresh(record, now) {
    const checkedAtMs = Number(record && record.lastCheckedAtMs) || 0;
    const currentTime = Number(now) || Date.now();
    return checkedAtMs > 0 && currentTime >= checkedAtMs && currentTime - checkedAtMs < COPYWRITING_CHECK_WINDOW_MS;
  }

  function markCopywritingCheckedAt(data, record, checkedAtMs) {
    const cached = normalizeCopywritingRecord(record);
    if (!data || !data.sku || !cached || !cached.fullText) return normalizeData(data || {});
    const checkedAt = Number(checkedAtMs) || Date.now();
    if (cached.lastCheckedAtMs && checkedAt - cached.lastCheckedAtMs < 1000) return normalizeData(data);
    const nextRecord = normalizeCopywritingRecord({ ...cached, lastCheckedAtMs: checkedAt });
    const next = mergeCopywritingCacheIntoData(data, nextRecord);
    saveData(data.sku, next, { suppressChangeTracking: true });
    return next;
  }

  function mergeCopywritingCacheIntoData(data, record) {
    const cached = normalizeCopywritingRecord(record);
    const english = String(cached && cached.cleanedIngredientEnglish || '').trim();
    const chinese = String(cached && cached.cleanedIngredientChinese || '').trim();
    const hasExistingIngredients = Boolean(data && (data.ingredientEnglish || data.ingredientChinese));
    return normalizeData({
      ...(data || {}),
      copywriting: cached,
      copywritingIngredientEnglish: english,
      copywritingIngredientChinese: chinese,
      copywritingIngredientSplit: Boolean(cached && cached.ingredientSplit),
      ingredientEnglish: data && data.ingredientEnglish || english,
      ingredientChinese: data && data.ingredientChinese || chinese,
      ingredientSource: hasExistingIngredients ? (data && data.ingredientSource || '') : (english || chinese ? 'copywritingWord' : data && data.ingredientSource || ''),
      ingredientWordFileName: english || chinese ? cached.fileName : data && data.ingredientWordFileName || '',
      ingredientWordHash: english || chinese ? cached.fileHash : data && data.ingredientWordHash || '',
      ingredientWordUpdatedAt: english || chinese ? cached.fetchedAt : data && data.ingredientWordUpdatedAt || '',
    });
  }

  function uploadPanelHtml() {
    state.uploadExpanded = true;
    const uploadMode = normalizeUploadMode(state.uploadMode);
    state.uploadMode = uploadMode;
    state.uploadWorkerMode = uploadMode;
    state.uploadRunning = loadUploadWorkerRunning(uploadMode);
    moveCompletedUploadsToHistory(uploadMode);
    normalizeRunningUploadsInQueue();
    state.uploadQueue = loadUploadQueue();
    state.uploadHistory = loadUploadHistory();
    const viewingHistory = state.uploadView === 'history';
    const history = (state.uploadHistory || []).filter((item) => getUploadItemMode(item) === uploadMode);
    const successfulHistory = history.filter(isUploadHistorySuccess);
    const queue = (state.uploadQueue || []).filter((item) => getUploadItemMode(item) === uploadMode && !/\u6210\u529f/.test(item.status || ''));
    const allItems = viewingHistory ? history : queue;
    const pageSize = 10;
    const pageKey = viewingHistory ? 'uploadHistoryPage' : 'uploadPage';
    const totalPages = Math.max(1, Math.ceil(allItems.length / pageSize));
    state[pageKey] = clamp(state[pageKey] || 1, 1, totalPages);
    const pageItems = allItems.slice((state[pageKey] - 1) * pageSize, state[pageKey] * pageSize);
    const currentSku = state.data && state.data.sku ? state.data.sku : '';
    const currentUpload = state.uploadRunning ? getCurrentRunningUpload(queue, uploadMode) : null;
    const statusText = (state.uploadRunning ? '\u8fd0\u884c\u4e2d' : '\u5df2\u6682\u505c') + (currentUpload ? ' | ' + currentUpload.sku : '');
    const visibleIdSet = new Set(allItems.map((item) => item.id));
    const selectedIds = new Set((state.uploadSelectedIds || []).filter((id) => visibleIdSet.has(id)));
    const rows = pageItems.length ? pageItems.map((item) => {
      const active = currentSku && item.sku === currentSku ? ' is-current' : '';
      const isToyLabel = item.kind === 'toy-label';
      const isToyEffect = item.kind === 'toy-effect';
      const isCopyright = item.kind === 'copyright';
      const ready = isUploadItemReady(item);
      const historyStatus = isToyLabel && (!item.status || item.status === L.uploadSuccess)
        ? '\u6807\u7b7e\u4e0a\u4f20\u6210\u529f'
        : (isToyEffect && (!item.status || item.status === L.uploadSuccess)
          ? '\u6548\u679c\u56fe\u4e0a\u4f20\u6210\u529f'
          : (isCopyright && (!item.status || item.status === L.uploadSuccess) ? '\u7248\u6743\u56fe\u4e0a\u4f20\u6210\u529f' : (item.status || L.uploadSuccess)));
      const defaultStatus = isToyLabel ? '\u5f85\u751f\u6210\u73a9\u5177\u6807\u7b7e' : (isToyEffect ? '\u5f85\u4e0a\u4f20\u6548\u679c\u56fe' : '\u5f85\u4e0a\u4f20');
      const status = viewingHistory ? historyStatus : (ready ? (item.status || defaultStatus) : '\u7f3a\u6587\u4ef6');
      const statusClass = /\u6210\u529f/.test(status) ? 'is-success' : (!ready || /\u5931\u8d25|\u8df3\u8fc7|\u5df2\u6709\u5185\u5bb9/.test(status) ? 'is-missing' : 'is-ready');
      const copyrightFiles = getCopyrightUploadEntries(item);
      const toyEffectFiles = getToyEffectUploadEntries(item);
      const files = isToyLabel
        ? '\u73a9\u5177\u6807\u7b7e\uff1a\u751f\u6210 / \u4e0a\u4f20 BOM / \u4e0b\u8f7d PSD \u4e0e\u56fe\u7247'
        : (isToyEffect
          ? '\u6548\u679c\u56fe\uff1a' + (toyEffectFiles.length ? toyEffectFiles.map((entry) => entry.name).join(' / ') : '\u7f3a\u5c11\u56fe\u7247')
        : (isCopyright
          ? '\u7248\u6743\u56fe\uff1a' + (copyrightFiles.length ? copyrightFiles.map((entry) => entry.name).join(' / ') : '\u7f3a\u5c11\u56fe\u7247')
          : [
            item.xlsxName ? 'XLSX \u5df2\u6709 ' + item.xlsxName : 'XLSX \u7f3a\u5c11',
            item.zipName ? 'ZIP \u5df2\u6709 ' + item.zipName : 'ZIP \u7f3a\u5c11',
          ].join(' | ')));
      const previousUpload = viewingHistory ? null : findPreviousSuccessfulUpload(item, successfulHistory);
      const previousUploadText = previousUpload ? '\u4e0a\u6b21\u4e0a\u4f20\uff1a' + (previousUpload.completedAt || previousUpload.updatedAt || '') : '';
      const progressText = viewingHistory ? (item.completedAt || item.updatedAt || '') : [previousUploadText, item.step || files].filter(Boolean).join(' \u00b7 ');
      const progressTitle = viewingHistory ? (item.step || item.skipReason || '') : [previousUploadText, files].filter(Boolean).join('\n');
      const uploadName = getUploadDisplayName(item);
      const selectAction = viewingHistory ? 'upload-history-select' : 'upload-queue-select';
      const selectHtml = '<button type="button" class="pfh-upload-check' + (selectedIds.has(item.id) ? ' is-checked' : '') + '" data-action="' + selectAction + '" data-upload-id="' + escapeHtml(item.id) + '" title="\u9009\u4e2d"></button>';
      const actionHtml = selectHtml;
      return '<div class="pfh-upload-item' + active + (viewingHistory ? ' is-history' : '') + '" data-upload-id="' + escapeHtml(item.id) + '">' +
        '<div><b>' + escapeHtml(item.sku) + '</b><small>' + escapeHtml(uploadName) + '</small></div>' +
        '<span class="' + statusClass + '">' + escapeHtml(status) + '</span>' +
        '<em title="' + escapeHtml(progressTitle) + '">' + escapeHtml(progressText) + '</em>' +
        actionHtml +
        '</div>';
    }).join('') : '<div class="pfh-empty">' + escapeHtml(viewingHistory ? L.uploadHistoryEmpty : L.uploadQueueEmpty) + '</div>';
    const historyHeadActions = '<span class="pfh-upload-head-project"><b>\u9879\u76ee</b></span>';
    const tableHead = '<div class="pfh-upload-table-head' + (viewingHistory ? ' is-history' : '') + '">' + historyHeadActions + '<span>\u72b6\u6001</span><span>' + escapeHtml(viewingHistory ? '\u65f6\u95f4' : '\u6587\u4ef6/\u8fdb\u5ea6') + '</span><span>\u9009\u62e9</span></div>';
    const pagerAction = viewingHistory ? 'upload-history-page' : 'upload-page';
    const pager = '<div class="pfh-upload-pager"><span>\u5171 ' + allItems.length + ' \u6761</span><div><button type="button" data-action="' + pagerAction + '-prev"' + (state[pageKey] <= 1 ? ' disabled' : '') + '>\u2039</button>' + renderCompactPager(pagerAction, state[pageKey], totalPages) + '<button type="button" data-action="' + pagerAction + '-next"' + (state[pageKey] >= totalPages ? ' disabled' : '') + '>\u203a</button></div></div>';
    const selectedActionHtml = '<button type="button" data-action="upload-clear-list">' + escapeHtml(L.uploadClearList) + '</button><button type="button" data-action="upload-selected-delete"' + (!selectedIds.size ? ' disabled' : '') + '>' + escapeHtml(L.uploadDelete) + '</button><button type="button" data-action="upload-selected-retry"' + (!selectedIds.size ? ' disabled' : '') + '>' + escapeHtml(L.uploadRetry) + '</button>';
    const backAction = viewingHistory ? 'upload-history-toggle' : 'home-back';
    const backLabel = viewingHistory ? '\u8fd4\u56de\u63d0\u5ba1\u4e0a\u4f20' : '\u8fd4\u56de\u4e3b\u9875';
    const uploadModeTabs = !viewingHistory ? '<div class="pfh-upload-mode-tabs is-four' + (uploadMode === 'toy-label' ? ' is-toy-label' : '') + (uploadMode === 'toy-effect' ? ' is-toy-effect' : '') + (uploadMode === 'copyright' ? ' is-copyright' : '') + '" data-active-mode="' + escapeHtml(uploadMode) + '" style="--pfh-upload-mode-count:4;grid-template-columns:repeat(4,minmax(68px,1fr));width:min(100%,360px)"><i class="pfh-upload-mode-indicator" aria-hidden="true"></i><button type="button" data-action="upload-mode" data-upload-mode="standard" class="' + (uploadMode === 'standard' ? 'is-active' : '') + '">\u56fe\u5305\u8868\u683c</button><button type="button" data-action="upload-mode" data-upload-mode="toy-label" class="' + (uploadMode === 'toy-label' ? 'is-active' : '') + '">\u73a9\u5177\u6807\u7b7e</button><button type="button" data-action="upload-mode" data-upload-mode="toy-effect" class="' + (uploadMode === 'toy-effect' ? 'is-active' : '') + '">\u73a9\u5177\u6548\u679c\u56fe</button><button type="button" data-action="upload-mode" data-upload-mode="copyright" class="' + (uploadMode === 'copyright' ? 'is-active' : '') + '">\u7248\u6743\u56fe</button></div>' : '';
    const copyrightPendingFiles = Array.isArray(state.copyrightPendingFiles) ? state.copyrightPendingFiles : [];
    const queueControl = state.uploadRunning ? '<button type="button" data-action="upload-pause">' + escapeHtml(L.uploadPauseQueue) + '</button>' : '<button type="button" data-action="upload-start">' + escapeHtml(L.uploadStartQueue) + '</button>';
    const uploadSkuDropHtml = isUploadSkuPickerMode(uploadMode) ? '<div class="pfh-upload-sku-drop-target" data-upload-sku-drop="true" tabindex="0" role="button">\u62d6\u52a8\u4e0a\u65b9 SKU \u5361\u7247\u5230\u8fd9\u91cc\u6dfb\u52a0\u4efb\u52a1</div>' : '';
    const uploadSkuPickerHtml = !viewingHistory && isUploadSkuPickerMode(uploadMode) ? '<div class="pfh-upload-sku-picker" data-upload-sku-picker="true"></div>' : '';
    const copyrightModeHtml = '<textarea class="pfh-toy-label-sku-input pfh-copyright-sku-input" placeholder="\u7c98\u8d34\u4e00\u4e2a\u6216\u591a\u4e2a SKU \u7f16\u7801">' + escapeHtml(state.copyrightSkuInput || '') + '</textarea>' +
      '<div class="pfh-upload-drop pfh-copyright-drop" data-action="upload-pick" data-upload-drop="copyright" tabindex="0" role="button" aria-label="\u7c98\u8d34\u6216\u62d6\u5165\u7248\u6743\u56fe">\u7c98\u8d34\u6216\u62d6\u5165\u7248\u6743\u56fe\uff08JPG / PNG\uff09' + (copyrightPendingFiles.length ? '<small>\u5df2\u9009 ' + copyrightPendingFiles.length + ' \u5f20\uff1a' + escapeHtml(copyrightPendingFiles.slice(0, 6).map((file) => file.name).join(' / ') + (copyrightPendingFiles.length > 6 ? ' ...' : '')) + '</small>' : '') + '</div>' +
      '<input class="pfh-upload-file" data-upload-kind="copyright" type="file" multiple accept=".jpg,.jpeg,.png,image/jpeg,image/png">' +
      '<div class="pfh-upload-actions"><button type="button" data-action="copyright-queue-add"' + (!(state.copyrightSkuInput || '').trim() || !copyrightPendingFiles.length ? ' disabled' : '') + '>\u52a0\u5165\u7248\u6743\u56fe\u4efb\u52a1</button>' + (copyrightPendingFiles.length ? '<button type="button" data-action="copyright-pending-clear">\u6e05\u7a7a\u5df2\u9009</button>' : '') + queueControl + '</div>';
    const toyEffectModeHtml = '<div class="pfh-upload-drop pfh-toy-effect-drop" data-action="upload-pick" data-upload-drop="toy-effect" tabindex="0" role="button" aria-label="\u62d6\u5165\u73a9\u5177\u6548\u679c\u56fe">\u62d6\u5165\u73a9\u5177\u6548\u679c\u56fe\uff08JPG / PNG\uff09<small>\u6309\u6587\u4ef6\u540d\u4e2d\u7684\u4ea7\u54c1\u540d\u5339\u914d SKU\uff0c\u4e0a\u4f20\u5230\u5bf9\u5e94 BOM \u7684\u6548\u679c\u56fe</small></div>' +
      (state.toyEffectMatchStatus ? '<div class="pfh-upload-match-status is-error">' + escapeHtml(state.toyEffectMatchStatus) + '</div>' : '') +
      '<input class="pfh-upload-file" data-upload-kind="toy-effect" type="file" multiple accept=".jpg,.jpeg,.png,image/jpeg,image/png">' +
      '<div class="pfh-upload-actions"><button type="button" data-action="upload-pick" data-upload-kind="toy-effect">\u9009\u62e9\u6548\u679c\u56fe</button>' + queueControl + '</div>';
    const historyBottomButton = '<button type="button" data-action="upload-history-toggle">' + escapeHtml(viewingHistory ? '\u8fd4\u56de\u63d0\u5ba1\u4e0a\u4f20' : '\u5386\u53f2\u8bb0\u5f55') + '</button>';
    return '<div class="pfh-detail-scroll pfh-upload-scroll"><section class="pfh-section pfh-upload-section is-open' + (viewingHistory ? ' is-history-view' : '') + '">' +
      '<div class="pfh-section-title pfh-upload-title"><button type="button" class="pfh-upload-back" data-action="' + backAction + '" aria-label="' + backLabel + '">' + iconHtml('backArrow') + '</button><h3>' + escapeHtml(L.uploadSection) + '</h3>' + uploadModeTabs +
      '<span class="pfh-upload-status">' + escapeHtml(statusText) + '</span>' +
      '<button type="button" class="pfh-upload-guide-button" data-action="upload-guide" title="\u4f7f\u7528\u8bf4\u660e" aria-label="\u4f7f\u7528\u8bf4\u660e">' + uploadGuideIconHtml() + '</button>' +
      '</div>' + uploadSkuPickerHtml +
      '<div class="pfh-upload-body">' +
        (viewingHistory ? '' : (uploadMode === 'toy-label'
          ? uploadSkuDropHtml + '<textarea class="pfh-toy-label-sku-input" placeholder="\u7c98\u8d34\u591a\u4e2a SKU \u7f16\u7801\uff0c\u6bcf\u884c\u4e00\u4e2a\u6216\u7528\u7a7a\u683c/\u9017\u53f7\u5206\u9694">' + escapeHtml(state.toyLabelSkuInput || '') + '</textarea><div class="pfh-upload-actions"><button type="button" data-action="toy-label-queue-add">\u52a0\u5165\u73a9\u5177\u6807\u7b7e\u4efb\u52a1</button>' + queueControl + '</div>'
          : (uploadMode === 'toy-effect' ? toyEffectModeHtml : (uploadMode === 'copyright' ? uploadSkuDropHtml + copyrightModeHtml : '<div class="pfh-upload-drop" data-action="upload-pick" data-upload-drop="any" tabindex="0" role="button" aria-label="' + escapeHtml(L.uploadDropHint) + '">' + escapeHtml(L.uploadDropHint) + '</div>' +
        '<input class="pfh-upload-file" data-upload-kind="any" type="file" multiple accept=".xls,.xlsx,.zip,.rar">' +
        '<div class="pfh-upload-actions"><button type="button" data-action="upload-pick" data-upload-kind="any">\u9009\u62e9\u6587\u4ef6</button>' + queueControl + '</div>'))) ) +
        tableHead + '<div class="pfh-upload-list">' + rows + '</div>' +
      '</div>' +
      '</section></div>' +
      '<div class="pfh-upload-bottom"><div class="pfh-upload-bottom-line">' + pager + '<div class="pfh-upload-bottom-actions">' + historyBottomButton + selectedActionHtml + '</div></div></div>' +
      uploadGuideModalHtml() + uploadClearConfirmModalHtml();
  }

  function uploadGuideIconHtml() {
    return '<svg viewBox="0 0 1024 1024" aria-hidden="true"><path d="M512 85.3c235.3 0 426.7 191.4 426.7 426.7 0 235.3-191.4 426.7-426.7 426.7S85.3 747.3 85.3 512C85.3 276.7 276.7 85.3 512 85.3m0-64C241 21.3 21.3 241 21.3 512S241 1002.7 512 1002.7 1002.7 783 1002.7 512 783 21.3 512 21.3z"></path><path d="M512 277.3m-64 0a64 64 0 1 0 128 0 64 64 0 1 0-128 0Z"></path><path d="M512 810.7c-35.3 0-64-28.7-64-64v-256c0-35.3 28.7-64 64-64s64 28.7 64 64v256c0 35.3-28.7 64-64 64z"></path></svg>';
  }

  function uploadGuideModalHtml() {
    if (!state.uploadGuideOpen) return '';
    return '<div class="pfh-upload-guide-modal" data-action="upload-guide-close"><section role="dialog" aria-modal="true" aria-label="\u4f7f\u7528\u8bf4\u660e"><header><h3>\u4f7f\u7528\u8bf4\u660e</h3><button type="button" data-action="upload-guide-close" aria-label="\u5173\u95ed">\u00d7</button></header><article><b>\u56fe\u5305\u8868\u683c</b><p>\u628a XLSX \u548c ZIP \u4e00\u8d77\u62d6\u5165\uff0c\u811a\u672c\u6309\u6587\u4ef6\u540d\u4e2d\u7684 SKU \u81ea\u52a8\u5339\u914d\u5e76\u52a0\u5165\u4efb\u52a1\u680f\u3002</p><b>\u73a9\u5177\u6807\u7b7e</b><p>\u7c98\u8d34\u591a\u4e2a SKU \u540e\u52a0\u5165\u4efb\u52a1\uff1b\u961f\u5217\u4f1a\u9010\u4e2a\u751f\u6210\u6807\u7b7e\u3001\u4e0a\u4f20 BOM\uff0c\u5e76\u5728\u7ed3\u675f\u540e\u4e0b\u8f7d\u4e00\u4e2a ZIP \u538b\u7f29\u5305\u3002</p><b>\u7248\u6743\u56fe</b><p>\u8f93\u5165 SKU \u540e\u7c98\u8d34\u6216\u62d6\u5165 JPG/PNG\uff1b\u961f\u5217\u4f1a\u4e0a\u4f20\u5230\u300c\u8bbe\u8ba1\u6587\u4ef6 - \u7248\u6743\u56fe\u300d\uff0c\u4fdd\u5b58\u8349\u7a3f\u540e\u63d0\u5ba1\u3002\u591a SKU \u53ef\u6309\u6587\u4ef6\u540d\u4e2d\u7684 SKU \u5339\u914d\uff0c\u6216\u6309\u56fe\u7247\u987a\u5e8f\u4e00\u5bf9\u4e00\u5206\u914d\u3002</p><p class="pfh-upload-guide-tip">\u8bf7\u5148\u4fdd\u8bc1 SKU \u5df2\u6709\u672c\u5730\u7f13\u5b58\uff0c\u4ee5\u907f\u514d\u4efb\u52a1\u65e0\u6cd5\u83b7\u53d6\u5236\u4f5c\u6570\u636e\u3002</p></article></section></div>';
  }

  function uploadClearConfirmModalHtml() {
    if (!state.uploadClearConfirmOpen) return '';
    const history = state.uploadView === 'history';
    return '<div class="pfh-upload-guide-modal pfh-upload-clear-modal"><section role="dialog" aria-modal="true" aria-label="确认清空"><header><h3>确认清空</h3><button type="button" data-action="upload-clear-cancel" aria-label="关闭">×</button></header><article><b>' + (history ? '清空全部历史记录？' : '清空当前提审队列？') + '</b><p>' + (history ? '清空后将无法在历史记录中查看已上传或报错的产品。' : '队列中的待上传文件会被移除，这项操作无法撤销。') + '</p><footer><button type="button" data-action="upload-clear-cancel">取消</button><button type="button" class="is-danger" data-action="upload-clear-confirm">确认清空</button></footer></article></section></div>';
  }

  function renderCompactPager(actionPrefix, currentPage, totalPages) {
    const pages = buildCompactPages(currentPage, totalPages);
    return pages.map((page) => {
      if (page === '...') return '<span class="pfh-pager-ellipsis">\u2026</span>';
      const active = page === currentPage;
      return active
        ? '<b>' + page + '</b>'
        : '<button type="button" class="pfh-pager-page" data-action="' + actionPrefix + '-goto" data-page="' + page + '">' + page + '</button>';
    }).join('');
  }

  function buildCompactPages(currentPage, totalPages) {
    if (totalPages <= 1) return [1];
    if (totalPages <= 5) return Array.from({ length: totalPages }, (_, index) => index + 1);
    const pages = new Set([1, totalPages, currentPage]);
    if (currentPage <= 3) {
      [2, 3, 4].forEach((page) => pages.add(page));
    } else if (currentPage >= totalPages - 2) {
      [totalPages - 3, totalPages - 2, totalPages - 1].forEach((page) => pages.add(page));
    } else {
      [currentPage - 1, currentPage + 1].forEach((page) => pages.add(page));
    }
    const sorted = Array.from(pages).filter((page) => page >= 1 && page <= totalPages).sort((a, b) => a - b);
    return sorted.reduce((result, page) => {
      const previous = result[result.length - 1];
      if (typeof previous === 'number' && page - previous > 1) result.push('...');
      result.push(page);
      return result;
    }, []);
  }

  function handleLedgerMoreAction(button) {
    if (!button || button.disabled) return;
    const sku = String(button.getAttribute('data-sku') || '').trim();
    const date = normalizeLedgerDate(button.getAttribute('data-date')) || normalizeLedgerDate(state.ledgerDate) || getTodayKey();
    if (!sku) return;
    const panel = ensurePanel();
    const card = button.closest('.pfh-ledger-item');
    const record = findLedgerRecord(sku, date) || (state.ledgerRecords || []).find((item) => getLedgerSkuKey(item.sku) === getLedgerSkuKey(sku));
    if (!record || !card) return;
    state.ledgerFlowTransitionSku = '';
    const opening = state.ledgerMenuSku !== sku || state.ledgerMenuDate !== date;
    state.ledgerMenuSku = opening ? sku : '';
    state.ledgerMenuDate = opening ? date : '';
    closeRenderedLedgerMenus(panel, opening ? card : null);
    card.classList.toggle('is-menu-open', opening);
    button.setAttribute('aria-expanded', opening ? 'true' : 'false');
    if (!opening) return;
    card.insertAdjacentHTML('beforeend', ledgerOverflowMenuHtml(record, sku, escapeHtml(date), Boolean(record.imageGeneratedAt)));
    const nextButton = card.querySelector('[data-action="ledger-more"]');
    if (nextButton) positionRenderedLedgerMenu(panel, nextButton);
  }

  function handleLedgerMoreClickCapture(event) {
    if (!event || state.view !== 'ledger') return;
    const target = event.target;
    const button = target && typeof target.closest === 'function'
      ? target.closest('[data-action="ledger-more"]')
      : null;
    if (!button || button.disabled) return;
    event.preventDefault();
    // The panel also has a normal bubble listener. Stop sibling listeners here
    // so one click cannot open the menu and immediately toggle it closed again.
    event.stopImmediatePropagation();
    handleLedgerMoreAction(button);
  }

  // <magic-upload-actions-module>
  function handleMagicUploadPanelAction(event, actionTarget, action) {
    if (action === 'magic-upload-pick') {
      const input = ensurePanel().querySelector('.pfh-magic-upload-file');
      if (input) input.click();
      return true;
    }
    if (action === 'magic-upload-mode') {
      const nextMagicMode = actionTarget.getAttribute('data-magic-mode');
      state.magicUploadMode = nextMagicMode === 'effect' || nextMagicMode === 'toy-label' ? nextMagicMode : 'package';
      if (!renderMagicUploadModeContent(ensurePanel())) renderShell();
      return true;
    }
    if (action === 'magic-toy-label-add') {
      addMagicToyLabelTasks(state.magicToyLabelInput);
      return true;
    }
    if (action === 'magic-toy-label-start') {
      startMagicToyLabelQueue();
      return true;
    }
    if (action === 'magic-toy-label-pause') {
      state.magicToyLabelRunning = false;
      state.magicToyLabelStatus = '队列已暂停';
      saveMagicToyLabelQueue(state.magicToyLabelQueue);
      refreshMagicToyLabelPage();
      return true;
    }
    if (action === 'magic-toy-label-remove') {
      removeMagicToyLabelTask(actionTarget.getAttribute('data-magic-toy-label-id') || '');
      return true;
    }
    if (action === 'magic-toy-label-retry') {
      retryMagicToyLabelTask(actionTarget.getAttribute('data-magic-toy-label-id') || '');
      return true;
    }
    if (action === 'magic-toy-label-clear') {
      clearMagicToyLabelQueue();
      return true;
    }
    if (action === 'magic-toy-label-history-toggle') {
      state.magicToyLabelHistoryOpen = !state.magicToyLabelHistoryOpen;
      refreshMagicToyLabelPage();
      return true;
    }
    if (action === 'magic-toy-label-history-close') {
      if (actionTarget.classList && actionTarget.classList.contains('pfh-magic-history-modal') && event.target !== actionTarget) return true;
      state.magicToyLabelHistoryOpen = false;
      refreshMagicToyLabelPage();
      return true;
    }
    if (action === 'magic-toy-label-history-retry') {
      retryMagicToyLabelHistory(actionTarget.getAttribute('data-magic-toy-label-history-id') || '');
      return true;
    }
    if (action === 'magic-effect-start') {
      startMagicEffectQueueInline();
      return true;
    }
    if (action === 'magic-effect-pause') {
      state.uploadMode = 'toy-effect';
      pauseUploadQueue();
      return true;
    }
    if (action === 'magic-upload-replace') {
      state.magicUploadReplaceId = actionTarget.getAttribute('data-magic-id') || '';
      const input = ensurePanel().querySelector('.pfh-magic-upload-file');
      if (input) input.click();
      return true;
    }
    if (action === 'magic-upload-toggle-task') {
      toggleMagicUploadTask(actionTarget.getAttribute('data-magic-id') || '');
      return true;
    }
    if (action === 'magic-upload-file-up' || action === 'magic-upload-file-down') {
      moveMagicUploadFile(actionTarget.getAttribute('data-magic-id') || '', actionTarget.getAttribute('data-magic-file-index') || '', action === 'magic-upload-file-up' ? -1 : 1);
      return true;
    }
    if (action === 'magic-upload-history-toggle') {
      state.magicUploadHistoryOpen = !state.magicUploadHistoryOpen;
      renderShell();
      return true;
    }
    if (action === 'magic-upload-history-close') {
      if (actionTarget.classList && actionTarget.classList.contains('pfh-magic-history-modal') && event.target !== actionTarget) return true;
      state.magicUploadHistoryOpen = false;
      renderShell();
      return true;
    }
    if (action === 'magic-effect-history-toggle') {
      state.magicEffectHistoryOpen = !state.magicEffectHistoryOpen;
      renderShell();
      return true;
    }
    if (action === 'magic-effect-history-close') {
      if (actionTarget.classList && actionTarget.classList.contains('pfh-magic-history-modal') && event.target !== actionTarget) return true;
      state.magicEffectHistoryOpen = false;
      renderShell();
      return true;
    }
    if (action === 'magic-upload-history-retry') {
      retryMagicUploadHistory(actionTarget.getAttribute('data-magic-history-id') || '');
      return true;
    }
    if (action === 'magic-upload-start') {
      startMagicUploadQueue();
      return true;
    }
    if (action === 'magic-upload-pause') {
      state.magicUploadRunning = false;
      saveMagicUploadQueue(state.magicUploadQueue);
      renderShell();
      return true;
    }
    if (action === 'magic-upload-remove') {
      removeMagicUploadTask(actionTarget.getAttribute('data-magic-id') || '');
      return true;
    }
    if (action === 'magic-upload-clear') {
      clearMagicUploadQueue();
      return true;
    }
    if (action === 'magic-effect-clear') {
      clearMagicEffectQueue();
      return true;
    }
    if (action === 'magic-upload-retry') {
      retryMagicUploadTask(actionTarget.getAttribute('data-magic-id') || '');
      return true;
    }
    if (action === 'magic-upload-save-task') {
      saveMagicUploadTaskEdits(actionTarget.getAttribute('data-magic-id') || '');
      return true;
    }
    if (action === 'home-magic-upload') {
      if (!state.magicUploadAccessEnabled) {
        showToast(state.magicUploadAccessLoading ? '正在准备功能' : '魔法上传暂未开放，敬请期待');
        scheduleMagicUploadAccessRefresh(0);
        return true;
      }
      state.view = 'magicUpload';
      state.uploadReturnView = '';
      state.magicUploadMode = state.magicUploadMode === 'effect' || state.magicUploadMode === 'toy-label' ? state.magicUploadMode : 'package';
      expandPanel();
      renderShell();
      return true;
    }
    return false;
  }
